window.CFA_DEEP_QUANT = [{"version":"2026.11.22-quant3-reconstruction-01","module_id":"CFA26-01-03","module_title":"Statistical Measures of Asset Returns","language":"vi explanation / en questions","qa_status":"SOURCE_MAPPED_AND_INDEPENDENT_EXAMPLE_CHECK_PENDING_FULL_ACADEMIC_QA","disclaimer_vi":"Bài học tự biên soạn trên cơ sở đối chiếu phạm vi CFAI Curriculum 2026, Kaplan Book 1 và slide Quant. Không sao chép nguyên văn các bài tập có bản quyền. Hồ sơ kiểm toán nguồn chi tiết được lưu riêng; không đánh dấu toàn bộ 4 LOS là fully approved.","los":[{"id":"CFA26-01-03-LOS01","letter":"3.a","title_en":"Measures of Central Tendency and Location","outcome_en":"Calculate, interpret and assess measures of central tendency and location for investment decisions.","overview_vi":"Chọn phép đo “giá trị điển hình” phù hợp với câu hỏi đầu tư, loại dữ liệu và tính chất ngoại lệ. Không có một chỉ tiêu trung bình tốt nhất trong mọi tình huống.","source":[{"id":"CFAI Quant 2026","pages":"95–107 (PDF physical pages)"},{"id":"Kaplan SchweserNotes Book 1 (2026)","pages":"44–50 (PDF physical pages)"},{"id":"SAPP Quant Slide Notes 2026","pages":"143–153 (LOS 3.a; PDF physical pages); 114–142 = prerequisite content"}],"sections":[{"heading":"1. Xác định đúng dữ liệu và câu hỏi đầu tư","body":"Một mẫu (sample) gồm những quan sát thực tế đã thu thập; tổng thể (population) bao gồm toàn bộ quan sát mục tiêu. Các return theo thời gian và dữ liệu cắt ngang không nhất thiết cần cùng loại thước đo. Trước khi tính, xác định đơn vị (% hay decimal), dữ liệu có trọng số không, kỳ đầu tư giống nhau không, và có outlier hoặc thiếu dữ liệu không.","trap":"Nếu một con số là “trung bình của giá cổ phiếu”, nó không tự động là “trung bình của lợi suất” hay “tốc độ tăng trưởng kép”."},{"heading":"2. Arithmetic mean — kỳ vọng một kỳ và trung bình mẫu","body":"Arithmetic mean lấy tổng tất cả quan sát chia số quan sát. Khi các kỳ có độ dài bằng nhau, đây là mô tả trung bình lịch sử một kỳ và thường dùng trong mô hình kỳ vọng một kỳ. Với n=5, return 2%, 4%, −3%, 7%, 5% thì mean=(2+4−3+7+5)/5=3%. Phần tử cực lớn hoặc cực nhỏ ảnh hưởng trực tiếp đến mean.","trap":"Không dùng arithmetic mean làm compounded growth thực tế qua nhiều kỳ biến động."},{"heading":"3. Weighted mean — trọng số gắn với mục đích","body":"Weighted mean gán cho mỗi quan sát một trọng số wᵢ, tổng trọng số bằng 1. Trọng số có thể là tỷ lệ vốn đầu tư, xác suất hoặc tần suất: mỗi trường hợp có diễn giải khác nhau. Nếu khối lượng vốn lần lượt 20%, 50%, 30% với return 2%, 7%, −4%, portfolio return cùng kỳ là 2.7%. Không đảo lẫn weight của tài sản và weight của khoảng thời gian.","trap":"Nếu đề cho lượng vốn tại ngày đầu kỳ thì trọng số là giá trị đầu kỳ; việc nộp/rút vốn giữa kỳ đòi hỏi phương pháp xử lý khác."},{"heading":"4. Median — trung vị bền hơn trước outlier","body":"Sắp xếp dữ liệu tăng dần. Nếu n lẻ, median ở vị trí (n+1)/2; nếu n chẵn, median là trung bình hai quan sát giữa. Ví dụ [2,3,4,100] có median 3.5 nhưng mean 27.25. Median chỉ sử dụng vị trí tương đối của dữ liệu chứ không phản ánh độ lớn mọi quan sát.","trap":"Không được chọn median theo dữ liệu chưa sắp xếp. Median thường bền hơn mean, nhưng vẫn có thể thay đổi khi thứ hạng hoặc số lượng quan sát thay đổi."},{"heading":"5. Mode — giá trị xuất hiện phổ biến","body":"Mode là giá trị (hoặc nhóm/bin) có tần suất xuất hiện cao nhất. Dữ liệu có thể unimodal, bimodal, multimodal hoặc không có mode rõ rệt. Mode phù hợp với các loại dữ liệu định tính, tần suất hoặc histogram. Khi dữ liệu liên tục, mode của histogram phụ thuộc vào cách chia bins, nên phải đọc nhãn và độ rộng khoảng.","trap":"Mode không nhất thiết bằng mean và không thể suy ra một “giá trị phổ biến” nếu mọi quan sát chỉ xuất hiện một lần."},{"heading":"6. Geometric mean — tăng trưởng kép của các return liên tiếp","body":"Đổi từng return Rᵢ thành gross return 1+Rᵢ, nhân lại, lấy căn bậc n và trừ 1. Đây là tốc độ tăng trưởng kép bình quân mỗi kỳ của cùng một khoản vốn, trước giả định tái đầu tư. Ví dụ +10% rồi −10% tạo tổng tài sản bằng 0.99 lần đầu kỳ, tức geometric mean ≈−0.5013% mỗi kỳ mặc dù arithmetic mean bằng 0.","trap":"Không được lấy geometric mean trực tiếp trên các signed percentage returns có giá trị âm; phải dùng 1+Rᵢ dương. Kỳ −100% làm tài sản về 0 và geometric return =−100%."},{"heading":"7. Harmonic mean — bình quân tỷ số với mẫu số đúng","body":"Harmonic mean của các đại lượng dương là nghịch đảo của trung bình các nghịch đảo. Có ích khi tính giá mua bình quân với số tiền đầu tư bằng nhau ở nhiều mức giá khác nhau, hoặc khi bình quân các ratios theo mẫu số phù hợp. Khi áp dụng cho return, sử dụng gross returns 1+Rᵢ rồi trừ 1; không lấy nghịch đảo trực tiếp của một số return âm.","trap":"Dù harmonic mean ≤ geometric mean ≤ arithmetic mean đối với dữ liệu dương cùng trọng số, điều này không có nghĩa harmonic là luôn tốt nhất cho phân tích return."},{"heading":"8. Trimmed và winsorized mean — xử lý outlier có chủ đích","body":"Trimmed mean loại bỏ một tỷ lệ quan sát ở cả hai đuôi rồi tính arithmetic mean của các điểm còn lại. Winsorized mean không xóa quan sát mà thay các giá trị vượt ngưỡng bằng giá trị biên tương ứng rồi lấy trung bình. Cả hai giúp giảm tác động ngoại lệ, nhưng làm mất/giảm thông tin ở đuôi. Phải ghi rõ tỷ lệ loại/thay, quy tắc percentiles và mẫu sử dụng.","trap":"Trong CFAI, “5% trimmed” nghĩa là loại tổng 5%: 2.5% ở mỗi phía. “95% winsorized” giữ 95% trung tâm và đưa mỗi 2.5% đuôi về ngưỡng tương ứng."},{"heading":"9. Outlier: dữ liệu lỗi khác tail risk thực tế","body":"Một return −60% có thể do nhập nhầm dấu hoặc là cú sốc thị trường có thật. Xác minh nguồn trước khi xóa, thay thế hoặc winsorize. Giữ outlier hợp lệ nếu nghiên cứu quan tâm tới rủi ro cực đoan; sử dụng median/trimmed mean nếu mục tiêu là xu hướng trung tâm ít nhạy với ngoại lệ. Luôn so sánh các phép đo và nêu lý do lựa chọn.","trap":""},{"heading":"10. Measures of location — quantiles, quartiles, quintiles, deciles, percentiles","body":"Quantiles chia các quan sát đã sắp xếp thành các nhóm theo tỷ lệ. Quartiles: 4 nhóm 25%; quintiles: 5 nhóm 20%; deciles: 10 nhóm 10%; percentile: 100 nhóm 1%. Ví dụ 80th percentile xấp xỉ mức mà 80% quan sát không vượt quá. Với grouped data, xác định bin chứa vị trí thích hợp thông qua cumulative frequency. Các thư viện thống kê có nhiều quy tắc interpolation khác nhau cho dữ liệu thô.","trap":""},{"heading":"11. Đọc percentile cho hiệu quả quỹ","body":"Nếu một quỹ nằm trong 10th percentile theo hiệu quả từ thấp đến cao thì chỉ khoảng 10% quỹ có return thấp hơn/không vượt mức ấy. Khi bảng hạng 1 là tốt nhất thì quy ước ranking lại đảo chiều, nên phải đọc hướng sắp xếp. Không đồng nhất percentile rank với return bằng 10%.","trap":"Một quỹ ở “top decile” thường có hiệu quả cao nếu ranking xếp từ tốt đến xấu, nhưng percentile số 90 theo phân phối tăng dần là ngưỡng cao; hai cách diễn đạt khác nhau."},{"heading":"12. Chọn thước đo cho từng bài toán","body":"Dùng arithmetic mean cho dự báo một kỳ lịch sử; weighted mean cho danh mục với weights; geometric mean cho tăng trưởng nhiều kỳ; harmonic mean cho rate/ratio với trọng số mẫu số phù hợp; median cho dữ liệu nhiều ngoại lệ; trimmed/winsorized khi có quy tắc xử lý outlier; mode cho kết quả xuất hiện thường xuyên; quantiles để đánh giá vị trí tương đối. Tránh kết luận từ một chỉ tiêu duy nhất.","trap":""}],"formulas":[{"name":"Arithmetic/sample mean","expr":"x̄ = Σᵢ xᵢ / n","meaning":"n = số quan sát; xᵢ = giá trị quan sát thứ i.","conditions":"Đơn vị giữ nguyên đơn vị x; nhạy với outlier."},{"name":"Weighted mean","expr":"x̄w = Σᵢ wᵢ xᵢ","meaning":"wᵢ ≥ 0 với Σwᵢ=1 nếu weight là tỷ trọng danh mục dài hạn không đòn bẩy.","conditions":"Phải đảm bảo weights tương ứng cùng kỳ và cùng metric."},{"name":"Geometric return","expr":"G = [Πᵢ(1 + Rᵢ)]^(1/n) − 1","meaning":"Rᵢ = simple holding-period return mỗi kỳ; Π là tích.","conditions":"Các kỳ tương đương về độ dài; 1+Rᵢ ≥ 0."},{"name":"Harmonic mean","expr":"H = n / Σᵢ(1/xᵢ)","meaning":"xᵢ dương, cùng trọng số.","conditions":"Muốn bình quân gross returns đặt xᵢ=1+Rᵢ rồi lấy H−1."},{"name":"Median positions","expr":"odd n: position (n+1)/2; even n: average of positions n/2 and (n+2)/2","meaning":"Sắp xếp trước khi xác định vị trí.","conditions":"Không áp dụng trực tiếp vị trí nếu dữ liệu đang ở dạng bins tổng hợp."},{"name":"Quartiles / interquartile range","expr":"IQR = Q3 − Q1","meaning":"Q1=25th percentile; Q3=75th percentile.","conditions":"Thuật toán nội suy quartile phụ thuộc quy ước dataset/software."}],"examples":[{"question_en":"A sample contains 2, 3, 4, and 100. Calculate the arithmetic mean and median.","steps_vi":["Mean = (2+3+4+100)/4 = 109/4 = 27.25.","Dữ liệu đã xếp; median là (3+4)/2 = 3.5.","Mean cao bất thường vì outlier 100; median phản ánh giá trị thường gặp tốt hơn trong bối cảnh này."],"answer":"Mean = 27.25; median = 3.50.","check":""},{"question_en":"A portfolio earns +10% in Year 1 and −10% in Year 2. Compute the two-year cumulative return and annual geometric mean.","steps_vi":["Tích gross return = 1.10 × 0.90 = 0.99.","Cumulative = 0.99−1=−1%.","Annual geometric = sqrt(0.99)−1≈−0.5013%; arithmetic mean=0%."],"answer":"Cumulative −1.00%; geometric mean ≈ −0.5013% per year.","check":""},{"question_en":"An investor puts $1,000 into a stock at $10 per share and another $1,000 at $20. What is the average acquisition price per share?","steps_vi":["Lần 1 mua 100 shares; lần 2 mua 50 shares.","Total shares=150; total cost=$2,000.","Average cost=$2,000/150=$13.333; equals harmonic mean 2/(1/10+1/20)."],"answer":"$13.33 per share.","check":""},{"question_en":"An equally weighted dataset consists of 1, 2, 3, 4, and 100. Remove the smallest and largest observations. Calculate the trimmed mean and a winsorized mean using adjacent observations as boundaries.","steps_vi":["Trimmed sample = [2,3,4]; arithmetic mean=3.","Winsorize 1→2 and 100→4; dataset [2,2,3,4,4].","Winsorized mean=15/5=3. Lưu ý đây là xử lý một quan sát ở mỗi đuôi, không phải quy ước 5%."],"answer":"Trimmed mean = 3.00; winsorized mean = 3.00.","check":""},{"question_en":"Asset weights are 20%, 50%, and 30% with matching returns 2%, 7%, and −4%. Compute the portfolio return.","steps_vi":["Weighted return=0.2×0.02+0.5×0.07+0.3×(−0.04).","=0.004+0.035−0.012=0.027.","Các khoản return cùng kỳ và weights tại đầu kỳ."],"answer":"2.70%.","check":""},{"question_en":"In a sample of 100 observations sorted into 20 equal-size bins, which bin contains the 75th percentile?","steps_vi":["Each bin holds 5 observations =5%.","The 75th percentile is the end of the lowest 75 observations.","Bin 15 covers cumulative 70–75%."],"answer":"Bin 15 (boundary convention may matter exactly at the endpoint).","check":""},{"question_en":"Returns are −10% and +20%. Compare arithmetic, geometric and harmonic means of gross returns.","steps_vi":["Arithmetic return=(−10%+20%)/2=5%.","Geometric=sqrt(0.9×1.2)−1≈3.923%.","Harmonic gross=2/(1/0.9+1/1.2)=1.028571; harmonic return≈2.857%."],"answer":"Arithmetic 5.000%; geometric 3.923%; harmonic 2.857%.","check":""},{"question_en":"Five daily returns are 1%, 2%, 2%, 3%, and 9%. What is the mode and median?","steps_vi":["Dữ liệu đã sắp tăng; mode=2% (xuất hiện hai lần).","n=5 nên median là quan sát thứ ba, cũng bằng 2%.","Arithmetic mean=17%/5=3.4% vì return 9% kéo mean lên."],"answer":"Mode = 2%; median = 2%; mean = 3.4%.","check":""}],"questions":[{"stem_en":"Which measure is generally least sensitive to a single extremely large observation?","options":["Arithmetic mean","Median","Weighted mean with a large weight on that observation"],"correct":1,"why_vi":"Median dựa trên thứ tự, vì thế thường ít nhạy với outlier cực lớn hơn mean.","trap_vi":""},{"stem_en":"A stock returns +25% and −20% in consecutive years. Its two-year geometric mean annual return is closest to:","options":["0.00%","2.50%","−2.50%"],"correct":0,"why_vi":"1.25×0.80=1.00, nên CAGR hai kỳ =0%.","trap_vi":""},{"stem_en":"Which measure should be used to compute the average purchase price when equal dollar amounts are invested at different share prices?","options":["Harmonic mean","Arithmetic mean","Median"],"correct":0,"why_vi":"Tổng USD/tổng số cổ phiếu = harmonic mean các price khi số tiền mỗi lần giống nhau.","trap_vi":""},{"stem_en":"The main distinction between a trimmed mean and a winsorized mean is that a winsorized mean:","options":["Discards the middle observations","Replaces extreme observations with boundary values","Ignores all observations with negative values"],"correct":1,"why_vi":"Winsorize giữ số lượng quan sát, thay các giá trị đuôi bằng ngưỡng.","trap_vi":""},{"stem_en":"A dataset contains 8, 2, 5, 5, and 10. The mode is:","options":["5","6","8"],"correct":0,"why_vi":"5 xuất hiện hai lần, còn những giá trị khác chỉ một lần.","trap_vi":""},{"stem_en":"An investment has annual returns of +40% and −40%. The arithmetic mean return is:","options":["0%","−8%","−16%"],"correct":0,"why_vi":"Mean=(40−40)/2=0%; geometric âm vì compounding.","trap_vi":""},{"stem_en":"A measure of location that divides a distribution into ten equal groups is a:","options":["Quartile","Decile","Quintile"],"correct":1,"why_vi":"Deciles chia 10 nhóm, mỗi nhóm 10% quan sát.","trap_vi":""},{"stem_en":"Which measure directly incorporates portfolio weights and individual asset returns measured over the same period?","options":["Weighted arithmetic mean","Sample median","Sample mode"],"correct":0,"why_vi":"Weighted arithmetic là tổng wᵢRᵢ theo weights thích hợp.","trap_vi":""},{"stem_en":"A 5% trimmed mean computed symmetrically removes approximately what fraction from each tail?","options":["5.0%","2.5%","10.0%"],"correct":1,"why_vi":"Quy ước trimmed 5% là tổng 5%, tức 2.5% mỗi đuôi.","trap_vi":""},{"stem_en":"Which statement about the mode is most accurate?","options":["It always equals the median","A dataset may have multiple modes","It cannot be used for categorical data"],"correct":1,"why_vi":"Dữ liệu có thể nhiều mode; các biến định tính cũng có thể có mode.","trap_vi":""},{"stem_en":"The geometric mean return of +10% followed by −10% is closest to:","options":["−0.50%","0.00%","−1.00%"],"correct":0,"why_vi":"sqrt(0.99)−1≈−0.5013%/kỳ; −1% là cumulative total.","trap_vi":""},{"stem_en":"An analyst wants to describe the middle value of an odd-sized sorted sample. Which measure is appropriate?","options":["Median","Standard deviation","Kurtosis"],"correct":0,"why_vi":"Median là giá trị đứng giữa danh sách đã xếp.","trap_vi":""},{"stem_en":"A fund ranks at the 90th percentile on a return distribution sorted from lowest to highest. Which statement is best?","options":["Its return is necessarily 90%","Its return is near a threshold exceeded by roughly 10% of observations","It is in the bottom 10%"],"correct":1,"why_vi":"90th percentile là ngưỡng vị trí, không phải 90% suất sinh lời.","trap_vi":""},{"stem_en":"For strictly positive observations with equal weights, which relationship is generally correct?","options":["Harmonic ≤ Geometric ≤ Arithmetic","Arithmetic ≤ Harmonic ≤ Geometric","All three must be identical"],"correct":0,"why_vi":"Bất đẳng thức trung bình áp dụng cho các giá trị dương; các giá trị không đồng nhất tạo phân biệt.","trap_vi":""},{"stem_en":"When a large negative return is a genuine market event, removing it without disclosure would most likely:","options":["Improve transparency","Potentially hide downside risk","Leave the distribution unchanged"],"correct":1,"why_vi":"Loại một outlier có thật có thể che mất tail risk, nhất là khi học mục tiêu risk.","trap_vi":""}],"cards":[{"front_en":"When is the arithmetic mean useful?","back_vi":"Mô tả trung bình lịch sử một kỳ hoặc input kỳ vọng một kỳ; nhạy với outlier."},{"front_en":"What is the correct geometric mean return formula?","back_vi":"[Π(1+Rᵢ)]^(1/n)−1, với gross returns dương."},{"front_en":"Why can arithmetic return be zero while geometric return is negative?","back_vi":"Biến động lãi/lỗ có hiệu ứng nhân và volatility drag."},{"front_en":"Define median for an even sample.","back_vi":"Sắp xếp rồi lấy trung bình hai quan sát ở giữa."},{"front_en":"Can a distribution have two modes?","back_vi":"Có, bimodal; cũng có thể không có mode rõ."},{"front_en":"Why use the harmonic mean for average share purchase price?","back_vi":"Nếu mỗi lần chi số tiền như nhau thì số shares mua tỷ lệ nghịch với price."},{"front_en":"What is a trimmed mean?","back_vi":"Loại một tỷ lệ quan sát ở hai đuôi rồi tính mean của phần còn lại."},{"front_en":"What is a winsorized mean?","back_vi":"Thay extreme values bằng boundary values thay vì xóa."},{"front_en":"Which quantile splits a distribution into five groups?","back_vi":"Quintile: năm nhóm, mỗi nhóm 20%."},{"front_en":"What does a 90th percentile mean?","back_vi":"Ngưỡng mà khoảng 90% số quan sát nằm tại hoặc bên dưới theo quy ước phân phối tăng."},{"front_en":"What is the IQR?","back_vi":"Q3−Q1, độ trải rộng 50% dữ liệu ở giữa."},{"front_en":"What must be checked before discarding an outlier?","back_vi":"Xác minh đó là lỗi nhập dữ liệu hay observation hợp lệ phản ánh tail risk."}]},{"id":"CFA26-01-03-LOS02","letter":"3.b","title_en":"Measures of Dispersion","outcome_en":"Calculate, interpret and assess dispersion measures in investment analysis.","overview_vi":"Một giá trị trung bình giống nhau không bảo đảm mức rủi ro giống nhau. Dispersion đo mức độ phân tán quanh tâm hoặc quanh một ngưỡng yêu cầu, gồm absolute và relative dispersion.","source":[{"id":"CFAI Quant 2026","pages":"108–117"},{"id":"Kaplan SchweserNotes Book 1 (2026)","pages":"47–51"},{"id":"SAPP Quant Slide Notes 2026","pages":"154–164 (LOS 3.b; PDF physical pages)"}],"sections":[{"heading":"1. Dispersion trả lời câu hỏi gì?","body":"Khi hai quỹ đều có mean return 7%, quỹ A thường biến động quanh mức 7% ít hơn quỹ B có thể có nhiều kỳ lãi/lỗ cực đoan. Trung bình chỉ phản ánh vị trí, không cho biết sự bất định của từng kết quả. Dispersion bổ sung risk perspective; tuy nhiên standard deviation đối xử với cả upside và downside như biến động.","trap":""},{"heading":"2. Range — nhanh nhưng rất dễ bị outlier chi phối","body":"Range=max−min. Ưu điểm là tính nhanh, trực quan và dễ so sánh trong cùng thang đo. Nhược điểm: chỉ dùng hai quan sát cực trị, không sử dụng các điểm còn lại và tăng theo kích thước mẫu. Ví dụ 1,2,3,4,100 có range=99, không cho biết đa số quan sát tập trung gần 1–4.","trap":""},{"heading":"3. Interquartile range — độ rộng của 50% giữa","body":"IQR=Q3−Q1, quan tâm giữa phân phối, thường vững hơn range trước outliers. Dùng khi muốn so sánh sự trải rộng của các quan sát điển hình; không thay thế đánh giá tail risk, vì có thể bỏ qua nhiều thông tin về hai đuôi. Cách xác định Q1,Q3 trên dữ liệu rất ít điểm cần theo đúng quy tắc bài toán/phần mềm.","trap":""},{"heading":"4. Mean absolute deviation (MAD)","body":"Đầu tiên xác định mean, sau đó tính |xᵢ−mean| cho mỗi điểm và chia cho n. Dùng toàn bộ mẫu; không triệt tiêu dấu dương và âm. So với standard deviation, MAD không phóng đại các sai lệch lớn bằng bình phương, nhưng kém thuận tiện cho biến đổi toán học. MAD ở đây là mean absolute deviation chứ không phải median absolute deviation.","trap":""},{"heading":"5. Population variance và sample variance","body":"Phương sai tổng thể dùng μ và chia N. Phương sai mẫu dùng x̄ và chia n−1 để hiệu chỉnh bậc tự do khi ước tính phương sai tổng thể. Không chia n−1 khi đề nói rõ đang tính population variance của toàn bộ dữ liệu. Var đo đơn vị bình phương (ví dụ %²), gây khó diễn giải trực tiếp.","trap":"Một số máy tính hoặc thư viện trả cả population SD và sample SD; phải chọn đúng theo đề."},{"heading":"6. Standard deviation — mức phân tán về đơn vị gốc","body":"Standard deviation là căn bậc hai của variance, đo cùng đơn vị với dữ liệu. Nếu return là % thì standard deviation cũng biểu diễn bằng percentage points. Giá trị cao thường hàm ý biến động rộng hơn, nhưng riêng SD không phản ánh chiều lệch của tail, shape, thanh khoản hay rủi ro phi tuyến.","trap":""},{"heading":"7. Target downside deviation / target semideviation","body":"Chọn target B (ví dụ zero, minimum acceptable return hoặc benchmark). Với mỗi quan sát Rᵢ, lấy min(0,Rᵢ−B), bình phương, cộng tất cả và dùng mẫu số n−1 theo công thức sample trong CFAI 2026; lấy căn. Quan sát trên target đóng góp 0 nhưng vẫn nằm trong tổng n của mẫu, không chỉ chia cho số kỳ thất bại.","trap":"Không thay B bằng sample mean nếu đề yêu cầu minimum acceptable return; hai mục tiêu này khác nhau."},{"heading":"8. Tăng target làm thay đổi downside deviation thế nào?","body":"Với cùng tập return, nếu target tăng, mọi điểm từng nằm dưới ngưỡng vẫn ở dưới và độ thiếu hụt ít nhất không nhỏ hơn; thêm một số quan sát có thể chuyển sang dưới target. Vì vậy target downside deviation không giảm khi target tăng, giữ nguyên dữ liệu và công thức. Quan sát cao hơn target không làm giảm các squared shortfalls.","trap":""},{"heading":"9. Coefficient of variation (CV)","body":"CV=standard deviation/mean, thể hiện biến động trên mỗi đơn vị return trung bình khi mean dương, có ý nghĩa. Khi hai danh mục kỳ vọng return khác nhau, CV hỗ trợ so sánh biến động tương đối. CV không đáng tin khi mean rất gần 0, bằng 0 hoặc âm; khi đó ratio có thể rất lớn, vô hạn hoặc đổi dấu khiến diễn giải “risk per return” vô nghĩa.","trap":""},{"heading":"10. So sánh measures hợp với bài toán","body":"Range/IQR cho vị trí cực trị/trung tâm, MAD cho khoảng lệch trung bình, SD cho total dispersion, target semideviation cho downside relative target, CV cho relative dispersion nếu mean dương. Chọn theo câu hỏi quản trị rủi ro và kiểm tra thang đo/trọng số, độ dài kỳ tính return.","trap":""},{"heading":"11. Geometric vs arithmetic khi biến động tăng","body":"Nếu hai khoản đầu tư có mean arithmetic giống nhau, khoản biến động cao hơn thường có geometric mean thấp hơn khi điều kiện so sánh thích hợp; chênh lệch do compounding. Nhưng từ SD riêng lẻ không tính chính xác geometric mean nếu thiếu phân phối hoặc các return thực tế.","trap":""},{"heading":"12. Chebyshev — kiến thức mở rộng không nhầm với LOS bắt buộc","body":"Chebyshev inequality đưa ra chặn tối thiểu số quan sát nằm trong k độ lệch chuẩn của mean với k>1 mà không cần giả định phân phối normal. Kiến thức này có thể gặp trong prerequisite hoặc phần thống kê tổng quát, nhưng không được đánh dấu là trọng tâm bắt buộc của chính LOS 3.b khi chưa đối chiếu nguồn 2026.","trap":""}],"formulas":[{"name":"Range","expr":"Range = max(xᵢ) − min(xᵢ)","meaning":"Độ rộng toàn bộ sample.","conditions":"Nhạy với outliers."},{"name":"Interquartile range","expr":"IQR = Q3 − Q1","meaning":"Q3=75th percentile; Q1=25th percentile.","conditions":"Có nhiều percentile conventions trên mẫu nhỏ."},{"name":"Mean absolute deviation","expr":"MAD = Σ |xᵢ−x̄| / n","meaning":"x̄ là sample mean; độ lệch tuyệt đối từng phần tử.","conditions":"MAD ≠ median absolute deviation."},{"name":"Population variance","expr":"σ² = Σ(xᵢ−μ)² / N","meaning":"μ là population mean, N population count.","conditions":"Khi mẫu đại diện toàn population."},{"name":"Sample variance and SD","expr":"s² = Σ(xᵢ−x̄)² / (n−1); s = √s²","meaning":"s là sample standard deviation.","conditions":"n>1; dùng n−1 khi tính sample variance."},{"name":"Target downside deviation (sample)","expr":"s_target = √[Σ min(0, Rᵢ−B)² / (n−1)]","meaning":"B là minimum acceptable return; các kỳ không underperform đóng góp 0.","conditions":"CFAI LM3 sample convention; n là tất cả quan sát."},{"name":"Coefficient of variation","expr":"CV = s / x̄","meaning":"SD chia sample mean trong cùng đơn vị.","conditions":"Chủ yếu có ý nghĩa khi x̄>0 và không quá gần 0."}],"examples":[{"question_en":"For the sample 2, 4, 6, calculate range, mean absolute deviation, sample variance and sample standard deviation.","steps_vi":["Mean=4; range=6−2=4.","MAD=(|2−4|+|4−4|+|6−4|)/3=4/3≈1.333.","Sum squared deviations=4+0+4=8.","Sample s²=8/(3−1)=4; sample s=2."],"answer":"Range 4; MAD 1.333; sample variance 4; sample SD 2.","check":""},{"question_en":"For the population 2, 4, 6, calculate population variance and population standard deviation.","steps_vi":["μ=4, squared deviation sum =8.","Population variance=8/3≈2.6667, not divide by n−1.","Population SD=√(8/3)≈1.633."],"answer":"Variance ≈2.667; SD ≈1.633.","check":""},{"question_en":"Four monthly returns are 8%, 0%, −4%, and 6%. Calculate sample target downside deviation using a 2% target.","steps_vi":["Relative deviations to 2% are +6, −2, −6, +4 percentage points.","Negative-only squared deviations=0+4+36+0=40 squared-percentage-points.","Sample target downside deviation = √(40/3)=3.6515%."],"answer":"≈3.65% per month.","check":""},{"question_en":"Portfolio A has mean return 8% and standard deviation 12%; Portfolio B has mean 12% and standard deviation 12%. Which has lower CV?","steps_vi":["CV A=12/8=1.5.","CV B=12/12=1.0.","B có cùng SD nhưng mean cao hơn, nên relative dispersion thấp hơn."],"answer":"Portfolio B: CV 1.0 (versus 1.5 for A).","check":""},{"question_en":"A return series is −20% and +30%. Calculate arithmetic and geometric means.","steps_vi":["Arithmetic mean=(−20%+30%)/2=5%.","Geometric mean = √(0.8×1.3)−1=√1.04−1≈1.9804%.","Khoảng cách phản ánh ảnh hưởng compounded volatility."],"answer":"Arithmetic 5%; geometric ≈1.98%.","check":""},{"question_en":"For 1, 2, 3, 4, 5, calculate mean absolute deviation from the arithmetic mean.","steps_vi":["Mean=3.","Absolute deviations=2,1,0,1,2; total=6.","MAD=6/5=1.2."],"answer":"1.20.","check":""},{"question_en":"Returns of −1%, 3%, 6%, 8% are evaluated against a 0% target. What is sample target downside deviation?","steps_vi":["Only −1% is below zero; squared shortfall=1 percentage-point squared.","There are four observations, so sample denominator n−1=3.","Root(1/3)≈0.5774%."],"answer":"≈0.577%.","check":""},{"question_en":"A portfolio has a mean return of 0% and standard deviation of 10%. Is the CV a useful relative-risk statistic?","steps_vi":["CV=10/0 không xác định.","Với mean xấp xỉ 0, CV có thể tăng vô lý khi mẫu thay đổi nhỏ.","Phải trình bày mean và SD riêng hoặc chọn thước đo phù hợp khác."],"answer":"No. CV is undefined.","check":""}],"questions":[{"stem_en":"For the sample 2, 4, and 6, the sample variance is:","options":["2.67","4.00","8.00"],"correct":1,"why_vi":"Sum squared deviations 8; divide by n−1=2 →4.","trap_vi":""},{"stem_en":"For the population 2, 4, and 6, the population variance is closest to:","options":["2.67","4.00","1.63"],"correct":0,"why_vi":"Population variance=8/3≈2.667; 1.633 là population SD.","trap_vi":""},{"stem_en":"Which measure uses only the highest and lowest values?","options":["Interquartile range","Range","Mean absolute deviation"],"correct":1,"why_vi":"Range=max−min, bỏ qua các quan sát nằm giữa.","trap_vi":""},{"stem_en":"A sample contains five values. For sample variance, the appropriate denominator is:","options":["4","5","6"],"correct":0,"why_vi":"n−1=4 do estimated sample mean.","trap_vi":""},{"stem_en":"Which statistic measures dispersion in the same units as the original observations?","options":["Variance","Standard deviation","Squared deviation"],"correct":1,"why_vi":"SD là căn phương sai nên cùng đơn vị gốc.","trap_vi":""},{"stem_en":"Which risk measure focuses on observations below a specified minimum acceptable return?","options":["Coefficient of variation","Target downside deviation","Range"],"correct":1,"why_vi":"Target downside deviation chỉ tính các hụt mức so với target.","trap_vi":""},{"stem_en":"For a sample of four returns, sample target downside deviation divides the sum of squared shortfalls by:","options":["The number of observations below target","Four","Three"],"correct":2,"why_vi":"Trong CFAI sample formula, mẫu số n−1=3, kể cả kỳ trên target đóng góp 0.","trap_vi":""},{"stem_en":"If the target return rises while observed returns stay unchanged, target downside deviation will most likely:","options":["Decrease","Stay the same or increase","Become negative"],"correct":1,"why_vi":"Các negative shortfalls không giảm và có thể thêm kỳ dưới ngưỡng.","trap_vi":""},{"stem_en":"The coefficient of variation is most informative when the sample mean is:","options":["A meaningful positive value","Exactly zero","A large negative value"],"correct":0,"why_vi":"CV=s/mean tốt nhất khi mean dương, có thể diễn giải risk per expected return.","trap_vi":""},{"stem_en":"A return sample has a minimum of −12% and a maximum of 24%. Its range is:","options":["12 percentage points","24 percentage points","36 percentage points"],"correct":2,"why_vi":"24−(−12)=36 percentage points.","trap_vi":""},{"stem_en":"Which measure is the difference between the 75th and 25th percentiles?","options":["IQR","MAD","CV"],"correct":0,"why_vi":"IQR=Q3−Q1.","trap_vi":""},{"stem_en":"For the sample 1, 2, 3, 4, 5, mean absolute deviation is:","options":["1.20","1.50","2.00"],"correct":0,"why_vi":"Mean 3; sum absolute deviations 6; MAD=6/5=1.2.","trap_vi":""},{"stem_en":"An analyst reports a negative standard deviation. This value is:","options":["Possible when returns are negative","Not possible","Equal to variance"],"correct":1,"why_vi":"Variance và SD không âm.","trap_vi":""},{"stem_en":"Relative to variance, standard deviation is generally easier to interpret because it:","options":["Always ignores outliers","Has the original data units","Does not depend on sample size"],"correct":1,"why_vi":"Variance dùng đơn vị bình phương còn SD dùng đơn vị gốc.","trap_vi":""},{"stem_en":"Two investments have equal arithmetic mean returns. All else equal, a more volatile path will generally have a:","options":["Higher compounded geometric mean","Lower compounded geometric mean","Guaranteed equal geometric mean"],"correct":1,"why_vi":"Volatility drag tác động làm thấp geometric growth; không thể tính chính xác chỉ từ SD.","trap_vi":""}],"cards":[{"front_en":"Population variance denominator?","back_vi":"N, với μ là population mean."},{"front_en":"Sample variance denominator?","back_vi":"n−1, với x̄ là sample mean."},{"front_en":"What does standard deviation measure?","back_vi":"Độ phân tán quanh mean, cùng đơn vị với dữ liệu."},{"front_en":"Range formula?","back_vi":"Max−min; chỉ dùng hai extreme values."},{"front_en":"What is the IQR?","back_vi":"Q3−Q1, khoảng 50% dữ liệu trung tâm."},{"front_en":"MAD formula?","back_vi":"Σ|xᵢ−x̄|/n; không phải median absolute deviation."},{"front_en":"Which observations enter sample target downside deviation?","back_vi":"Tất cả n quan sát trong denominator n−1; các quan sát R≥B có numerator contribution=0."},{"front_en":"What happens when the target return rises?","back_vi":"Target semideviation không giảm khi giữ nguyên data."},{"front_en":"What is the coefficient of variation?","back_vi":"s / x̄; risk dispersion per unit mean khi mean dương."},{"front_en":"When should CV not be trusted?","back_vi":"Mean zero, rất gần 0 hoặc âm."},{"front_en":"What is the main weakness of standard deviation?","back_vi":"Phạt biến động lãi và lỗ đối xứng, không thể hiện skew/tail shape."},{"front_en":"What is Chebyshev’s inequality in this module?","back_vi":"Kiến thức mở rộng/tiền đề, không tự động là yêu cầu core LOS 3.b."}]},{"id":"CFA26-01-03-LOS03","letter":"3.c","title_en":"Skewness and Kurtosis","outcome_en":"Interpret and evaluate skewness and kurtosis in investment-return distributions.","overview_vi":"Mean và variance không đủ để biết phía lãi/lỗ nào có cực trị, hoặc hai đuôi của phân phối có nặng hơn normal hay không. Skewness và kurtosis bổ sung góc nhìn về hình dạng và tail risk.","source":[{"id":"CFAI Quant 2026","pages":"118–124"},{"id":"Kaplan SchweserNotes Book 1 (2026)","pages":"51–57"},{"id":"SAPP Quant Slide Notes 2026","pages":"165–169 (LOS 3.c; PDF physical pages)"}],"sections":[{"heading":"1. Tại sao phải kiểm tra shape của return distribution?","body":"Hai tài sản có mean 8% và SD 12% giống nhau vẫn có thể khác về tần suất những khoản lỗ thảm họa hoặc những khoản lãi hiếm gặp. Mean đo center, SD đo tổng độ phân tán; skewness phân biệt bất đối xứng trái-phải, kurtosis bổ sung thông tin về trọng lượng các đuôi. Không suy ra tính normal chỉ vì mean và median bằng nhau.","trap":""},{"heading":"2. Symmetry và normal distribution","body":"Normal distribution có dạng đối xứng, mean=median=mode và được mô tả bằng mean/variance; skewness bằng 0 và kurtosis bằng 3 (excess 0). Nhưng một phân phối có skewness 0 không nhất thiết normal; vẫn có thể heavy tails hoặc nhiều đỉnh. Cần kiểm chứng shape bằng histogram/quantiles khi dữ liệu cho phép.","trap":""},{"heading":"3. Positive skew — đuôi dài phía lợi nhuận lớn","body":"Phân phối positively skewed/right-skewed có các khoản lãi rất lớn nhưng hiếm xảy ra; còn nhiều quan sát ở mức tương đối nhỏ. Trong trường hợp unimodal liên tục điển hình, mean > median > mode, nhưng không dùng như định lý cho mọi dữ liệu. Positive skew được coi là hấp dẫn trong một số hoàn cảnh vì upside tail; không đồng nghĩa luôn rủi ro thấp.","trap":""},{"heading":"4. Negative skew — đuôi dài phía thua lỗ","body":"Phân phối negatively skewed/left-skewed có nhiều lợi nhuận nhỏ nhưng thỉnh thoảng thua lỗ lớn. Trong mẫu unimodal liên tục điển hình: mean < median < mode. Người học cần nhận ra rằng chiến lược nhận premium nhỏ đều đặn có thể ẩn tail loss; không đánh giá an toàn chỉ bằng tỷ lệ thắng cao.","trap":"Số âm của skewness cho biết hướng bất đối xứng, không phải xác suất xảy ra lỗ chính xác."},{"heading":"5. Skewness là normalized third central moment","body":"Trực giác: tính sai lệch từng observation so với mean, nâng lũy thừa bậc 3 nên giữ dấu, trung bình và chuẩn hóa bằng SD³. Giá trị dương khi đuôi phải mạnh hơn; âm khi đuôi trái mạnh hơn. CFAI nêu công thức mẫu gần đúng khi n lớn (khoảng 100+); công thức có bias correction trong Excel/phần mềm có thể cho số khác nhau trên mẫu nhỏ.","trap":"LOS 3.c thiên về interpret/evaluate; không ép người học tính tay sample skewness phức tạp nếu đề không yêu cầu."},{"heading":"6. Kurtosis đo trọng lượng hai đuôi","body":"Kurtosis chuẩn hóa moment bậc 4 nên không giữ dấu âm/dương; đo mức xuất hiện tương đối của extreme tails (và liên quan hình dạng phân phối), không đo hướng thua lỗ. Với so sánh normal, kurtosis cao hơn 3 là fat-tailed/leptokurtic; thấp hơn 3 là thin-tailed/platykurtic. Đỉnh cao hay thấp riêng rẽ không đủ để khẳng định kurtosis.","trap":""},{"heading":"7. Excess kurtosis — phải trừ 3","body":"Excess kurtosis = kurtosis−3. Normal distribution có excess 0; >0 là fat-tailed tương đối normal; <0 là thin-tailed. Đề có thể cho trực tiếp excess kurtosis 1.2, không cần trừ thêm 3. Khi đề cho ordinary kurtosis 4.2 mới đổi sang excess 1.2.","trap":""},{"heading":"8. Leptokurtic, mesokurtic và platykurtic","body":"Leptokurtic có excess kurtosis dương (fat tails), mesokurtic excess 0 theo benchmark normal, platykurtic excess âm (thin tails). Trong thực nghiệm, sampling noise có thể khiến kurtosis estimate thay đổi đáng kể; không kết luận tài sản luôn giữ nguyên shape qua các chế độ thị trường.","trap":""},{"heading":"9. Skewness khác kurtosis trong quản lý rủi ro","body":"Negative skew nói tail nặng về phía mất tiền, còn positive excess kurtosis cho biết hai phía tail tổng hợp có thể xảy ra extreme events nhiều hơn normal. Một phân phối có thể vừa negatively skewed vừa leptokurtic. Các thước đo riêng lẻ không đưa ra đầy đủ xác suất tail có điều kiện.","trap":""},{"heading":"10. Normal assumptions có thể đánh giá thấp extreme risk","body":"Mô hình giả định normal thường underestimate extreme losses nếu return thực tế có fat left tail. Cần dùng stress tests, downside measures, kiểm tra dữ liệu lịch sử, scenario analysis hoặc mô hình phân phối phù hợp khi phân tích rủi ro. Không lấy dấu skewness đơn lẻ để suy ra VaR/ES bằng con số cụ thể.","trap":""},{"heading":"11. Không nhầm mean–median ordering với dấu chắc chắn","body":"Quy tắc mean>median>mode có ích cho right-skewed unimodal điển hình, nhưng có ngoại lệ với mẫu finite, multi-modal hoặc đuôi phức tạp. Giá trị zero skew không khẳng định normal, và tail kurtosis dương cũng không khẳng định negative skew.","trap":""},{"heading":"12. Đọc đề thi theo từ khóa","body":"“Occasional extreme gains” gợi positive skew; “rare catastrophic losses” gợi negative skew; “more frequent extremes on both sides relative to normal” gợi positive excess kurtosis; “normal kurtosis =?” →3; “normal excess kurtosis =?” →0. Kiểm tra đề ghi kurtosis hay excess kurtosis.","trap":""}],"formulas":[{"name":"Conceptual skewness (large-sample approximation)","expr":"Skew ≈ [(1/n)Σ(xᵢ−x̄)³] / s³","meaning":"Số mũ lẻ giữ dấu; s>0.","conditions":"CFAI 2026 sử dụng large-sample approximation; sample estimator có corrections khác nhau."},{"name":"Conceptual kurtosis (large-sample approximation)","expr":"Kurtosis ≈ [(1/n)Σ(xᵢ−x̄)⁴] / s⁴","meaning":"Số mũ chẵn đo combined tails.","conditions":"Có multiple sample conventions; không coi gần đúng là exact small-n unbiased formula."},{"name":"Excess kurtosis","expr":"Excess kurtosis = kurtosis − 3","meaning":"Normal benchmark kurtosis 3.","conditions":"Excess >0 fat-tailed; <0 thin-tailed (relative to normal)."}],"examples":[{"question_en":"A distribution has an excess kurtosis of +1.8. How is it classified relative to a normal distribution?","steps_vi":["Excess >0 cho biết fat tails so với normal.","Ordinary kurtosis = 1.8+3=4.8.","Không thể suy ra skewness từ excess kurtosis."],"answer":"Leptokurtic (fat-tailed); kurtosis = 4.8.","check":""},{"question_en":"A return distribution has kurtosis of 2.4. Calculate excess kurtosis and interpret.","steps_vi":["Excess=2.4−3=−0.6.","Negative excess → thin tails relative to normal."],"answer":"Excess kurtosis = −0.6; platykurtic.","check":""},{"question_en":"A strategy earns +2%, +3%, and +4% in most years but occasionally loses −35%. Which skew is of greatest concern?","steps_vi":["Các quan sát thường xuyên nhỏ dương; đôi khi có lỗ lớn âm.","Đuôi trái rất dài, negative skew.","Khi đánh giá cần xét tail risk chứ không chỉ hit rate."],"answer":"Negative skewness.","check":""},{"question_en":"A strategy usually loses 1% but sometimes gains 25%. Which direction of skew is most likely?","steps_vi":["Những mức lỗ nhỏ xuất hiện thường xuyên.","Khoản lãi hiếm có độ lớn cao tạo đuôi phải."],"answer":"Positive skewness.","check":""},{"question_en":"A data analyst reports skewness = 0 and excess kurtosis = +2.0. Is normality established?","steps_vi":["Zero skewness chỉ nói không có third-moment asymmetry theo định nghĩa.","Excess kurtosis +2.0 nêu combined tails nặng hơn normal.","Normal distribution đòi hỏi nhiều thuộc tính khác; dữ liệu này không phù hợp normal theo kurtosis."],"answer":"No: the distribution is approximately symmetric but fat-tailed.","check":""},{"question_en":"The sample analyst reports ordinary kurtosis of 3.0 and skewness of −1.1. Can this distribution be assumed normal?","steps_vi":["Kurtosis 3 tương đương excess 0.","Skewness −1.1 ≠0 cho thấy bất đối xứng trái.","Do đó không thể gọi là normal."],"answer":"No; the nonzero negative skew is inconsistent with normality.","check":""},{"question_en":"A return series has mean 6% and SD 12%. Can these two statistics alone reveal the presence of rare extreme losses?","steps_vi":["Mean và SD chưa nêu dấu tail or shape.","Cần quan sát skewness, kurtosis và empirical quantiles/scenarios."],"answer":"No.","check":""},{"question_en":"A distribution has a longer right tail but a large number of small returns. Is it necessarily leptokurtic?","steps_vi":["Right tail dài gợi positive skewness.","Kurtosis phụ thuộc combined tails, không tự suy ra từ độ dài một phía."],"answer":"No; skewness and kurtosis are distinct.","check":""}],"questions":[{"stem_en":"A portfolio strategy frequently earns small positive returns but rarely experiences very large losses. Its return distribution is most likely:","options":["Positively skewed","Negatively skewed","Perfectly symmetric"],"correct":1,"why_vi":"Rare large losses kéo đuôi trái dài → negative skew.","trap_vi":""},{"stem_en":"The kurtosis of a normal distribution is:","options":["0","3","−3"],"correct":1,"why_vi":"Ordinary kurtosis của normal là 3, excess kurtosis bằng 0.","trap_vi":""},{"stem_en":"A distribution with excess kurtosis of +2.0 is:","options":["Platykurtic","Mesokurtic","Leptokurtic"],"correct":2,"why_vi":"Excess>0 là fat-tailed/leptokurtic.","trap_vi":""},{"stem_en":"A distribution has kurtosis of 2.2. Its excess kurtosis equals:","options":["−0.8","+0.8","+2.2"],"correct":0,"why_vi":"Excess=2.2−3=−0.8.","trap_vi":""},{"stem_en":"Which statistic indicates the direction of asymmetry in returns?","options":["Skewness","Kurtosis","Variance"],"correct":0,"why_vi":"Skewness có dấu âm/dương để chỉ hướng tail.","trap_vi":""},{"stem_en":"A positive skew typically reflects:","options":["Rare extreme gains","Rare extreme losses","No extreme observations"],"correct":0,"why_vi":"Right skew=long right tail với upside extreme.","trap_vi":""},{"stem_en":"For a typical continuous unimodal distribution with positive skew, the ordering is most likely:","options":["Mean > Median > Mode","Mode > Median > Mean","Mean = Median = Mode"],"correct":0,"why_vi":"Đuôi phải kéo mean lớn hơn median, mode trong trường hợp lý tưởng unimodal.","trap_vi":""},{"stem_en":"Which statement about zero skewness is most accurate?","options":["It guarantees normality","It does not guarantee normality","It guarantees zero variance"],"correct":1,"why_vi":"Zero skewness không nói hết kurtosis, multimodality, tail shapes.","trap_vi":""},{"stem_en":"Positive excess kurtosis is most directly associated with:","options":["Thinner tails than the normal distribution","Greater combined tail weight than the normal distribution","A negative arithmetic mean"],"correct":1,"why_vi":"Kurtosis đo độ nặng tail so normal, không cho biết dấu mean.","trap_vi":""},{"stem_en":"A distribution with excess kurtosis below zero is called:","options":["Platykurtic","Leptokurtic","Mesokurtic"],"correct":0,"why_vi":"Excess âm tương ứng thin-tailed relative normal.","trap_vi":""},{"stem_en":"Which combination raises particular concern about extreme downside outcomes?","options":["Positive skew, negative excess kurtosis","Negative skew, positive excess kurtosis","Zero skew, zero excess kurtosis"],"correct":1,"why_vi":"Negative skew có left tail, excess kurtosis dương có heavier combined tail risk.","trap_vi":""},{"stem_en":"An investment has kurtosis equal to 4.5. Its excess kurtosis is:","options":["1.5","4.5","7.5"],"correct":0,"why_vi":"4.5−3=1.5.","trap_vi":""},{"stem_en":"The third central moment is particularly relevant for measuring:","options":["Skewness","Variance","Kurtosis"],"correct":0,"why_vi":"Bậc 3 giữ dấu âm dương, đo bất đối xứng.","trap_vi":""},{"stem_en":"The fourth standardized central moment is most relevant for measuring:","options":["Mean","Kurtosis","Median"],"correct":1,"why_vi":"Bậc 4 đo combined tails và normalized kurtosis.","trap_vi":""},{"stem_en":"Which statement is least accurate?","options":["Positive skew implies rare extreme gains","Kurtosis alone reveals the direction of tail risk","Negative skew implies potential large downside outcomes"],"correct":1,"why_vi":"Kurtosis là fourth moment nên không chỉ ra đuôi âm hay dương.","trap_vi":""}],"cards":[{"front_en":"What does positive skewness indicate?","back_vi":"Right tail: khả năng rare extreme gains; trường hợp unimodal điển hình mean>median>mode."},{"front_en":"What does negative skewness indicate?","back_vi":"Left tail: có thể xuất hiện large losses dù nhiều small gains."},{"front_en":"Skewness of a normal distribution?","back_vi":"0."},{"front_en":"Kurtosis of a normal distribution?","back_vi":"3."},{"front_en":"Excess kurtosis of a normal distribution?","back_vi":"0."},{"front_en":"What does excess kurtosis > 0 mean?","back_vi":"Fat-tailed/leptokurtic relative normal."},{"front_en":"What does excess kurtosis < 0 mean?","back_vi":"Thin-tailed/platykurtic relative normal."},{"front_en":"Can a zero-skew distribution be nonnormal?","back_vi":"Có, ví dụ symmetric heavy-tail hoặc multimodal."},{"front_en":"Can skewness and kurtosis replace stress tests?","back_vi":"Không: chúng tóm tắt shape, không mô tả hết mọi extreme event."},{"front_en":"What is the key arithmetic trap for kurtosis?","back_vi":"Kurtosis và excess kurtosis khác nhau 3 đơn vị."},{"front_en":"What moment does skewness use?","back_vi":"Third standardized central moment."},{"front_en":"What moment does kurtosis use?","back_vi":"Fourth standardized central moment."}]},{"id":"CFA26-01-03-LOS04","letter":"3.d","title_en":"Covariance and Correlation","outcome_en":"Interpret relationships between two variables through covariance, scatter plots and correlation.","overview_vi":"Correlation mô tả mức độ liên hệ tuyến tính, không phải quan hệ nhân quả. Phải xem scatter plot, outliers, phương sai và bối cảnh dữ liệu trước khi đưa ra kết luận đầu tư.","source":[{"id":"CFAI Quant 2026","pages":"125–133"},{"id":"Kaplan SchweserNotes Book 1 (2026)","pages":"54–59"},{"id":"SAPP Quant Slide Notes 2026","pages":"170–173 (LOS 3.d; PDF physical pages)"}],"sections":[{"heading":"1. Scatter plot — kiểm tra trước khi tóm tắt bằng một số","body":"Vẽ điểm (X,Y) tương ứng ở mỗi thời điểm/quan sát. Những điểm tụ sát đường tăng → positive linear association; sát đường giảm → negative; hình chữ U → nonlinear association, Pearson r có thể gần 0 dù quan hệ chặt; vài điểm cô lập cho biết khả năng outliers. Đọc trục, đơn vị, time alignment và liệu cùng thời kỳ quan sát không.","trap":""},{"heading":"2. Covariance: hai biến đổi cùng nhau thế nào?","body":"Covariance là bình quân tích sai lệch quanh mean của từng biến. Nếu các điểm X cao hơn mean cũng thường Y cao hơn mean thì covariance dương; nếu X cao hơn mean nhưng Y thấp hơn mean thì âm. Đơn vị covariance là tích đơn vị X với Y (ví dụ percentage points squared), nên khó so sánh trực tiếp giữa các cặp với volatility khác nhau.","trap":""},{"heading":"3. Sample covariance chia n−1","body":"Đối với paired observations (xᵢ,yᵢ), sample covariance = Σ(xᵢ−x̄)(yᵢ−ȳ)/(n−1). Phải ghép đúng thời điểm giữa hai chuỗi; lệch dữ liệu một ngày có thể phá nghĩa kinh tế. Nếu sample mean của một biến constant và SD=0, correlation không xác định.","trap":"Không áp dụng sample formula với n<2 hoặc chia n khi đề yêu cầu sample covariance."},{"heading":"4. Correlation chuẩn hóa covariance về [−1,+1]","body":"Pearson/product-moment correlation = covariance/(SD_X×SD_Y); coefficient nằm từ −1 đến +1 nếu SD dương. +1 biểu thị perfect positive LINEAR, −1 perfect negative LINEAR, 0 không có LINEAR association. Dấu r giống dấu covariance. Thay đổi thang đo dương của một biến không đổi r, đổi dấu biến sẽ đảo dấu r.","trap":""},{"heading":"5. Strength ≠ slope ≠ causality","body":"Tăng độ dốc của line không làm tương quan mạnh hơn nếu các điểm vẫn nằm hoàn toàn trên đường thẳng. X=1,2,3 và Y=2,4,6 có r=+1, giống X=1,2,3 và Y=10,20,30. Correlation là mức clustering quanh đường thẳng; không cho biết X gây Y thay đổi. Dữ liệu đồng biến có thể vì common factor hoặc coincidence.","trap":""},{"heading":"6. Zero correlation có thể tồn tại khi quan hệ phi tuyến mạnh","body":"Với X=[−1,0,1] và Y=X²=[1,0,1], Y được xác định hoàn toàn bởi X nhưng covariance bằng 0, nên r=0. Vì thế r=0 không cho phép khẳng định hai biến độc lập hoặc không liên quan theo mọi dạng. Xem scatter plot trước.","trap":""},{"heading":"7. Outliers có thể bóp méo hoặc tạo correlation giả","body":"Một vài điểm cực đoan có thể kéo r gần +1/−1 dù phần lớn dữ liệu không theo xu hướng, hoặc làm giảm r của một đám mây vốn có quan hệ rõ. Kiểm tra nguồn, data entry, chế độ thị trường và có nên phân tích robust correlations/nhóm dữ liệu riêng hay không. Tránh xóa outlier thực để làm r đẹp hơn.","trap":""},{"heading":"8. Spurious correlation và confounding","body":"Hai chuỗi cùng tăng theo thời gian có thể tương quan cao chỉ vì trend hoặc một yếu tố thứ ba; không chứng minh tác động trực tiếp. Cân nhắc giả thuyết kinh tế, mốc công bố, overlapping samples, regime, biến bị bỏ sót và khả năng data snooping. Correlation không thay thế causal identification.","trap":""},{"heading":"9. Ứng dụng diversification của correlation","body":"Với hai tài sản có SD dương, correlation càng thấp thì thông thường lợi ích diversification càng lớn (giữ weights và SD không đổi). Nếu r=−1, có thể tạo tổ hợp loại bỏ biến động hoàn toàn trong điều kiện weighting thích hợp và mô hình đơn giản; r=+1 không có giảm volatility do imperfect correlation. Tuy vậy correlations có thể tăng trong stress regimes.","trap":""},{"heading":"10. Tính correlation từ covariance và standard deviations","body":"Nếu Cov(X,Y)=0.0048, SD_X=0.08 và SD_Y=0.12 (returns đo decimal), r=0.0048/(0.08×0.12)=0.50. Đừng nhân nhầm 0.08 và 0.12 khi covariance ghi theo %²: quy đổi cùng hệ đơn vị trước khi tính. Nếu r tính ra 1.4, ít nhất một đầu vào hoặc phép đổi đơn vị có lỗi.","trap":""},{"heading":"11. Pearson so với Spearman — mở rộng, không thay đổi phạm vi nguồn","body":"Rank correlation (Spearman) đo monotonic association của thứ hạng, có thể hữu ích khi dữ liệu có outliers/non-normality. Nhưng phần này là mở rộng liên quan; CFAI LM3 hiện hành trong nguồn đã kiểm tập trung scatter plot, sample covariance và linear correlation. Không xếp tính Spearman vào core LOS 3.d nếu chưa có bằng chứng nguồn chính.","trap":""},{"heading":"12. Các câu hỏi định tính thường gặp","body":"“Correlation = −0.8” → strong negative linear relation, không phải xác suất thua lỗ 80%. “Correlation = 0” → no linear relation, không bảo đảm independence. “Covariance positive” → correlation positive (assuming both SD>0). “Correlation >1” → data error. “Correlation high” → không đủ xác định causality.","trap":""}],"formulas":[{"name":"Sample covariance","expr":"sXY = Σ(xᵢ−x̄)(yᵢ−ȳ) / (n−1)","meaning":"Đo joint variation trong sample n paired observations.","conditions":"Đơn vị X×Y, dễ bị outliers chi phối."},{"name":"Sample correlation","expr":"rXY = sXY / (sX sY)","meaning":"sX,sY là sample standard deviations >0.","conditions":"r∈[−1,1]; không xác định khi sX hoặc sY=0."},{"name":"Two-asset portfolio variance (applied preview)","expr":"σp² = wA²σA² + wB²σB² + 2wAwBσAσBρAB","meaning":"Ứng dụng liên hệ correlation với diversification; full derivation ở Portfolio Mathematics.","conditions":"Weights và returns theo cùng kỳ, linear return combination."}],"examples":[{"question_en":"For X = [1, 2, 3] and Y = [2, 4, 6], calculate sample covariance and correlation.","steps_vi":["Means: x̄=2, ȳ=4.","Cross-products=(−1)(−2)+0+(1)(2)=4.","Sample covariance=4/(3−1)=2.","Sample SDs=1 and 2; r=2/(1×2)=+1."],"answer":"Sample covariance = 2; correlation = +1.","check":""},{"question_en":"For X = [1, 2, 3] and Y = [6, 4, 2], calculate correlation.","steps_vi":["X tăng đều trong khi Y giảm đều theo đường thẳng.","x̄=2, ȳ=4; sample covariance=(−1)(2)+(1)(−2) divided 2 =−2.","SDs 1 and 2; r=−2/(1×2)=−1."],"answer":"Correlation = −1.","check":""},{"question_en":"Covariance of two decimal return series is 0.0048; their standard deviations are 8% and 12%. Compute correlation.","steps_vi":["Đổi SD thành 0.08 và 0.12 để hợp với decimal covariance.","r=0.0048/(0.08×0.12)=0.0048/0.0096=0.5."],"answer":"+0.50.","check":""},{"question_en":"X = [−1, 0, 1] and Y = [1, 0, 1]. Does zero correlation imply no relationship?","steps_vi":["ȳ=2/3; x̄=0.","Cross deviations: −1×(1−2/3) + 0 + 1×(1−2/3)=0.","Covariance=0, r=0; song Y=X² nên có quan hệ phi tuyến hoàn toàn."],"answer":"No. Correlation = 0 despite a deterministic nonlinear relationship.","check":""},{"question_en":"Two assets each have 50% weights. Their standard deviations are 20% and 10%, and correlation is −0.25. Find portfolio standard deviation.","steps_vi":["wA²σA²=0.25×0.04=0.01.","wB²σB²=0.25×0.01=0.0025.","Covariance term=2×0.5×0.5×0.2×0.1×(−0.25)=−0.0025.","Variance=0.01+0.0025−0.0025=0.01; SD=10%."],"answer":"Portfolio SD = 10%.","check":""},{"question_en":"A covariance of −18 is calculated for two variables with positive standard deviations. What can be said about correlation?","steps_vi":["Correlation = covariance/(positive SD product).","Its sign must equal covariance sign, regardless of whether the variables have positive or negative means."],"answer":"Correlation must be negative.","check":""},{"question_en":"A stock’s correlation with an index is 1.25 according to a spreadsheet. What should the analyst do?","steps_vi":["A valid Pearson correlation cannot exceed 1 in magnitude.","Review alignment of dates, covariance units, SD formulae, missing data and data ranges."],"answer":"Treat 1.25 as a calculation/data error.","check":""},{"question_en":"Two variables have correlation +0.95. Is it correct to conclude that X causes Y?","steps_vi":["+0.95 nói strong positive linear association trong sample.","Không loại trừ variable thứ ba, reverse causality, common trend hoặc spurious relationship."],"answer":"No; correlation alone does not establish causation.","check":""}],"questions":[{"stem_en":"A correlation coefficient of −0.75 indicates:","options":["A strong negative linear relationship","A 75% probability of loss","That X causes Y"],"correct":0,"why_vi":"r âm và độ lớn cao cho thấy tuyến tính ngược chiều, không phải xác suất.","trap_vi":""},{"stem_en":"The valid range of a Pearson correlation coefficient is:","options":["0 to 1","−1 to +1","−∞ to +∞"],"correct":1,"why_vi":"Tương quan được chuẩn hóa và nằm trong [−1,+1].","trap_vi":""},{"stem_en":"A positive covariance between two variables with nonzero standard deviations implies a correlation that is:","options":["Negative","Positive","Exactly zero"],"correct":1,"why_vi":"Correlation sign giống covariance khi mẫu số SD product dương.","trap_vi":""},{"stem_en":"Which statement about zero Pearson correlation is most accurate?","options":["The two variables must be independent","No linear association is detected","The two variables must be constant"],"correct":1,"why_vi":"r=0 không loại trừ nonlinear relationship hoặc phụ thuộc.","trap_vi":""},{"stem_en":"If all points lie on a downward-sloping straight line, the correlation is:","options":["−1","0","+1"],"correct":0,"why_vi":"Perfect negative linear relationship.","trap_vi":""},{"stem_en":"Two variables exhibit a strong U-shaped relationship. Their Pearson correlation may be:","options":["Near zero","Greater than +1","Always exactly +1"],"correct":0,"why_vi":"r đo tuyến tính nên có thể gần 0 ngay cả khi phi tuyến rõ rệt.","trap_vi":""},{"stem_en":"For X = [1, 2, 3] and Y = [2, 4, 6], sample covariance is:","options":["1","2","4"],"correct":1,"why_vi":"Sample cross products sum=4, divide n−1=2 →2.","trap_vi":""},{"stem_en":"If covariance equals 0.0048, σX=8%, and σY=12%, correlation is:","options":["0.25","0.50","1.25"],"correct":1,"why_vi":"r=.0048/(.08×.12)=.5.","trap_vi":""},{"stem_en":"Correlation is most accurately described as a measure of:","options":["Linear association","Causation","Expected return"],"correct":0,"why_vi":"Định nghĩa linear association; causation cần riêng chứng cứ.","trap_vi":""},{"stem_en":"Which feature can make a sample correlation misleading?","options":["Outliers","Spurious relationships","Both A and B"],"correct":2,"why_vi":"Outliers và spurious correlations đều có thể làm r gây hiểu nhầm.","trap_vi":""},{"stem_en":"A correlation coefficient changes when both variables are multiplied by positive constants. This statement is:","options":["True","False","True only for negative correlation"],"correct":1,"why_vi":"Positive rescaling không đổi r (nếu SD dương).","trap_vi":""},{"stem_en":"If one variable has a standard deviation of zero, its correlation with another variable is:","options":["+1","0","Undefined"],"correct":2,"why_vi":"Mẫu số sX sY=0 nên r không xác định.","trap_vi":""},{"stem_en":"All else equal, reducing the correlation between two risky assets will generally:","options":["Improve diversification potential","Guarantee higher expected returns","Increase the correlation coefficient"],"correct":0,"why_vi":"Độ tương quan giảm thường giảm portfolio variance nếu weights và SD giữ nguyên.","trap_vi":""},{"stem_en":"For two returns measured in decimal units, covariance is in:","options":["Decimal-return squared units","Pure probability units","Percentile ranks"],"correct":0,"why_vi":"Covariance là tích hai độ lệch; với return decimals thì units squared.","trap_vi":""},{"stem_en":"A strong sample correlation is not proof of causation primarily because:","options":["A third variable may influence both series","Correlation is always zero out of sample","Standard deviations must be equal"],"correct":0,"why_vi":"Confounding/common trend có thể tạo tương quan nhưng không causal.","trap_vi":""}],"cards":[{"front_en":"What is covariance?","back_vi":"Mức độ hai biến cùng biến động quanh mean; dấu biểu thị cùng/khác chiều."},{"front_en":"Sample covariance denominator?","back_vi":"n−1 for n paired observations."},{"front_en":"Correlation formula?","back_vi":"Covariance / (SDx × SDy)."},{"front_en":"Correlation range?","back_vi":"−1 đến +1."},{"front_en":"Does r=0 imply independence?","back_vi":"Không; chỉ không có linear relationship (theo Pearson)."},{"front_en":"Does r=+1 imply a positive regression slope?","back_vi":"Có, perfect positive linear association với SD>0."},{"front_en":"Can r=1.2 occur?","back_vi":"Không; data/formula/unit error."},{"front_en":"Why inspect a scatter plot?","back_vi":"Nhìn pattern, nonlinear shape, clusters, outliers và trục đo."},{"front_en":"Does correlation prove causality?","back_vi":"Không; có thể do confounding, common trend hoặc spurious correlation."},{"front_en":"What changes correlation when one series is multiplied by −1?","back_vi":"Dấu correlation đảo ngược; độ lớn không đổi."},{"front_en":"What happens to diversification when correlation declines?","back_vi":"Thường giảm portfolio variance nếu SD, weights không đổi."},{"front_en":"What is Spearman here?","back_vi":"Kiến thức mở rộng rank correlation; không gắn nhãn core của CFAI LM3 2026 nếu không được xác minh."}]}]},{"version":"2026.11.22-quant4-sourcefirst-01","module_id":"CFA26-01-04","module_title":"Probability Trees and Conditional Expectations","language":"Vietnamese teaching / English assessment","qa_status":"SOURCE_MAPPED_EDITORIAL_DRAFT_WITH_ARITHMETIC_CHECKS_NOT_FULLY_SIGNED_OFF","disclaimer_vi":"Quant LM4: 3 LOS (expected value/variance, probability trees/conditional expectation, Bayes). Tài liệu biên soạn mới theo nguồn 2026; prerequisite slides ở p181–194 không tự được đánh dấu là core 2026. Ví dụ/câu hỏi do dự án tạo; không sao chép nguyên văn ngân hàng đề.","los":[{"id":"CFA26-01-04-LOS01","letter":"4.a","title_en":"Expected Values, Variances and Standard Deviations","outcome_en":"calculate expected values, variances, and standard deviations and demonstrate their application to investment problems","overview_vi":"Một phân phối xác suất (probability distribution) mô tả nhiều kết quả có thể xảy ra trước khi biết kết quả thực tế. Tính E(X), Var(X), σ(X) theo xác suất từng kịch bản; phân biệt hoàn toàn với thống kê mẫu lịch sử của Module 3.","source":[{"id":"CFA Institute Curriculum Level I 2026 — Quantitative Methods LM4","pages":"139–142 (physical PDF; LOS 4.a and expected value/variance section)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 4","pages":"61–63 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026","pages":"195–196 (core 4.a); 181–194 contain prerequisite probability foundations (physical PDF)"}],"sections":[{"heading":"1. Random variable, outcomes, and mutually exclusive scenarios","body":"Random variable X là đại lượng chưa biết chắc tại lúc ra quyết định; có thể biểu diễn bằng EPS, return, giá trị thu hồi hoặc chi phí. Một probability model rời rạc liệt kê từng outcome xᵢ cùng pᵢ. Các trường hợp liệt kê phải bao phủ khả năng xảy ra và không chồng lặp khi cộng xác suất. Mỗi pᵢ thuộc [0,1], tổng pᵢ=1. Nếu bảng chỉ cung cấp ba trạng thái với tổng xác suất bằng 0.90 mà đề không có phần còn lại, không thể tự coi ba trạng thái là toàn bộ phân phối.","trap":"Không nhầm “event” (tập hợp kết quả) với “outcome” (một kết quả); xác suất không phải return."},{"heading":"2. Expected value E(X) là xác suất bình quân, không phải kết quả chắc chắn","body":"E(X)=Σpᵢxᵢ. Trước tiên chuẩn hóa mọi giá trị về cùng đơn vị; nhân return từng trạng thái với probability tương ứng rồi cộng. E(X) có đơn vị của X: nếu X là USD/share thì E(X) cũng USD/share, nếu X là decimal return thì E(X) là decimal return. Ví dụ xác suất thị trường xấu 20% với return −10%, bình thường 50% với +8%, tốt 30% với +20%, kỳ vọng là 8%. 8% không có nghĩa có một trạng thái chắc chắn trả 8%.","trap":"Không lấy trung bình không trọng số của các outcome nếu pᵢ không bằng nhau."},{"heading":"3. Expected return khác historical arithmetic sample mean","body":"Module 3 dùng arithmetic mean của dữ liệu đã xảy ra; ở Module 4, E(R) dựa trên kịch bản dự báo, xác suất chủ quan/ước lượng từ dữ liệu hoặc mô hình. Dù cả hai đều là weighted averages, chúng trả lời hai câu hỏi khác: “quan sát đã trả bao nhiêu bình quân” và “mô hình dự kiến trả bao nhiêu”. Nếu sample mean lịch sử dùng để thiết lập prior trong mô hình, nguồn bất định và giả định dự báo vẫn phải được nhận diện.","trap":""},{"heading":"4. Variance đo độ phân tán quanh E(X)","body":"Variance = Σpᵢ[xᵢ−E(X)]². Trừ mean dự báo cho từng outcome, bình phương sai lệch, nhân với xác suất, cộng. Việc bình phương làm variance không âm; variance bằng 0 khi mọi outcome có xác suất dương đều có cùng giá trị. Số đo này xét khả năng vượt kỳ vọng và dưới kỳ vọng đối xứng về độ lệch bình phương; nó không chuyên biệt đo downside risk.","trap":"Variance có đơn vị bình phương của X, ví dụ return², không được trình bày là %. "},{"heading":"5. Standard deviation bằng căn bậc hai variance","body":"σ(X)=sqrt(Var(X)), không âm và cùng đơn vị với X. Nếu var=0.0108 đối với decimal return, σ=sqrt(0.0108)=0.103923 tức khoảng 10.39%, tuyệt đối không phải 1.08% hay 0.0108%. Trong ví dụ xác suất 20%,50%,30% và return −10%,+8%,+20%, mean 8% và σ≈10.39%.","trap":"Luôn kiểm tra dữ liệu là decimal hay phần trăm trước khi lấy căn và trình bày."},{"heading":"6. Đừng dùng công thức chia n−1 cho toàn bộ phân phối xác suất","body":"Trong một probability distribution rời rạc mà pᵢ đã được định nghĩa để biểu diễn toàn bộ kịch bản, variance là Σpᵢ(xᵢ−μ)². Công thức sample variance Σ(xᵢ−x̄)²/(n−1) thuộc việc ước lượng từ n historical observations và không phù hợp để thay thế vào bảng xác suất. Khi pᵢ đồng đều 1/n, variance phân phối bằng (1/n)Σ(xᵢ−μ)², vẫn khác sample variance.","trap":""},{"heading":"7. Shortcut E(X²)−[E(X)]²","body":"Nếu bảng có sẵn xᵢ², tính E(X²)=Σpᵢxᵢ² rồi Var(X)=E(X²)−[E(X)]². Hai cách phải cho cùng kết quả; đó là công cụ tự kiểm tra tốt. Nếu chênh lệch nhỏ do rounding, giữ số lẻ đủ trong phép tính trung gian. Nếu ra variance âm đáng kể, xác suất hoặc số học sai vì variance thật không âm.","trap":""},{"heading":"8. Linear transformations của random variable","body":"Với Y=a+bX, E(Y)=a+bE(X), Var(Y)=b²Var(X), σ(Y)=|b|σ(X). Cộng thêm một khoản cố định thay đổi mean nhưng không thay đổi volatility; nhân X lên ba lần làm SD tăng gấp ba và variance gấp chín. Điều này hữu ích khi EPS tính theo USD thay vì cents hoặc chuyển lãi/lỗ thành quy mô vốn cụ thể.","trap":"Đừng cho rằng tăng mean bằng khoản cố định làm variance tăng."},{"heading":"9. So sánh hai khoản đầu tư bằng mean và volatility","body":"Nếu hai tài sản cùng expected return nhưng một tài sản có σ cao hơn, nó có độ phân tán theo mô hình lớn hơn; không tự kết luận tài sản đó bị định giá thấp hay có downside loss probability cao hơn. Với mean khác nhau, chỉ xếp hạng bằng SD là thiếu thông tin; cần xét risk aversion, các outcome xấu, mối liên hệ với danh mục và các giả định dự báo.","trap":""},{"heading":"10. Probability-weighting phải phản ánh đúng thời điểm","body":"Không được trộn return một quý với return một năm nếu chưa điều chỉnh kỳ; cũng không cộng return nominal với EPS bằng USD. Kịch bản “economy good/bad” chỉ là nhánh đầu, xác suất của return cụ thể có thể phải tính qua conditional branches ở 4.b. Kết quả E(X) dựa vào quality of assigned probabilities: probability sai sẽ làm mean và risk estimates sai.","trap":""},{"heading":"11. Expected value vs risk-adjusted decision","body":"Một expected return 12% không tự động tốt hơn 9% nếu variance và mức lỗ cực đoan khác nhau. Variance/σ là các thống kê phân tán quan trọng nhưng không mô tả skew, tail events hoặc liquidity. Vì vậy sử dụng thêm analysis ở các bài sau. Trong bài thi, khi đề chỉ hỏi expected value hoặc probability-weighted σ, không cần đưa risk-free rate vào phép tính trừ khi câu hỏi đòi hỏi excess returns.","trap":""},{"heading":"12. Quy trình làm bài tính an toàn","body":"Bước 1: liệt kê outcomes, pᵢ và kiểm tra tổng p. Bước 2: quy đổi return về cùng decimal. Bước 3: tính μ=Σpx. Bước 4: lập cột deviation và squared deviation. Bước 5: Σp deviation² rồi lấy căn. Bước 6: diễn giải “expected/volatility” đúng đơn vị, không tự gán xác suất chắc chắn cho mean.","trap":"Kiểm tra mean phải nằm trong khoảng min/max outcome nếu mọi pᵢ không âm và cộng thành 1."}],"formulas":[{"name":"Probability normalization","expr":"0 ≤ pᵢ ≤ 1; Σᵢ pᵢ = 1","meaning":"Xác suất của các outcome mutually exclusive và collectively exhaustive.","conditions":"Các probabilities cần bao phủ toàn bộ trạng thái của mô hình."},{"name":"Discrete expected value","expr":"μ = E(X) = Σᵢ pᵢ xᵢ","meaning":"Giá trị trung bình có trọng số xác suất, cùng đơn vị X.","conditions":"Các outcomes và probabilities được ghép đúng cặp."},{"name":"Variance of discrete probability model","expr":"Var(X) = σ² = Σᵢ pᵢ (xᵢ−μ)²","meaning":"Phương sai của phân phối xác suất đã cho.","conditions":"Không chia thêm n−1."},{"name":"Standard deviation","expr":"σ(X) = √Var(X)","meaning":"Volatility đơn vị tương tự X; không âm.","conditions":"Nếu return đầu vào decimal, sau cùng nhân 100 để trình bày %."},{"name":"Variance shortcut","expr":"Var(X) = E(X²) − [E(X)]²; E(X²)=Σᵢpᵢxᵢ²","meaning":"Phương pháp kiểm tra bằng second moment.","conditions":"Không làm tròn quá sớm."},{"name":"Linear transformation","expr":"E(a+bX)=a+bE(X); Var(a+bX)=b²Var(X); σ(a+bX)=|b|σ(X)","meaning":"Cộng số cố định không tăng variance; hệ số b làm variance theo bình phương.","conditions":"a và b là constants, X có finite variance."}],"examples":[{"question_en":"The possible annual returns are −10%, 8%, and 20%, with probabilities 20%, 50%, and 30%. Calculate expected return.","steps_vi":["Kiểm tra 0.20+0.50+0.30=1.","Đổi return sang decimal: −0.10, 0.08, 0.20.","E(R)=0.20(−0.10)+0.50(0.08)+0.30(0.20)=−0.02+0.04+0.06=0.08."],"answer":"8.00%.","check":"Calculated independently: sum of probability-weighted returns = 0.08."},{"question_en":"Using the probabilities and returns in the preceding example, calculate variance and standard deviation.","steps_vi":["Expected return μ=0.08.","Deviations: −0.18,0,+0.12.","Variance=0.20(0.18²)+0.50(0²)+0.30(0.12²)=0.0108.","Standard deviation=sqrt(0.0108)=0.103923."],"answer":"Variance = 0.0108; standard deviation ≈10.39%.","check":"The variance is not 1.08%: its units are decimal-return squared."},{"question_en":"EPS can be USD 1, USD 2, or USD 4 with probabilities 20%, 50%, and 30%. Calculate E(EPS).","steps_vi":["E(EPS)=0.20×1+0.50×2+0.30×4=0.20+1.00+1.20."],"answer":"USD 2.40 per share.","check":""},{"question_en":"For the EPS distribution [1,2,4] with probabilities [0.2,0.5,0.3], compute variance using E(X²)−E(X)².","steps_vi":["E(X)=2.4.","E(X²)=0.2×1²+0.5×2²+0.3×4²=0.2+2.0+4.8=7.0.","Var(X)=7.0−2.4²=1.24.","σ=sqrt(1.24)≈1.114."],"answer":"Variance = 1.24 USD²/share²; SD ≈ USD 1.114 per share.","check":""},{"question_en":"A government payment of 6% is certain in the model. What are its expected return and variance?","steps_vi":["Chỉ có một outcome +6% với probability 1.","E(R)=1×0.06=0.06.","Var(R)=1×(0.06−0.06)²=0."],"answer":"Expected return = 6%; variance = 0; standard deviation = 0.","check":""},{"question_en":"A return forecast takes values −20%, 10%, and 15% with probabilities 10%, 60%, and 30%. Calculate expected return.","steps_vi":["E(R)=0.1×(−0.20)+0.6×0.10+0.3×0.15.","Cộng −0.02+0.06+0.045=0.085."],"answer":"8.50%.","check":""},{"question_en":"A model return X has E(X)=4% and standard deviation 6%. A transformed return Y=2X+1 percentage point is proposed. Calculate E(Y) and SD(Y).","steps_vi":["E(Y)=2×4%+1%=9%.","σ(Y)=|2|×6%=12%.","Variance của Y bằng 4 lần variance X; khoản +1 pp không tác động volatility."],"answer":"Expected return = 9%; SD = 12%.","check":""},{"question_en":"Two assets each have expected return 10%, but model standard deviations are 8% and 15%. Which has greater modeled dispersion?","steps_vi":["Standard deviation đo dispersion theo cùng đơn vị.","15%>8%, nên Asset B có variance lớn hơn và outcomes phân tán rộng hơn quanh mean.","Không kết luận B luôn có loss probability lớn hơn nếu chưa xem shape."],"answer":"Asset B; its modeled volatility is greater.","check":""}],"questions":[{"stem_en":"Three mutually exclusive scenarios have probabilities 0.15, 0.35, and 0.50. What is their total probability?","options":["0.85","1.00","1.15"],"correct":1,"why_vi":"Ba trạng thái mutually exclusive và exhaustive phải có tổng xác suất 1.","trap_vi":""},{"stem_en":"A stock returns −10%, 8%, or 20% with respective probabilities 0.20, 0.50, and 0.30. Its expected return is closest to:","options":["8.0%","9.0%","10.0%"],"correct":0,"why_vi":"−2%+4%+6%=8%.","trap_vi":""},{"stem_en":"Which measure uses a probability-weighted sum of squared deviations from an expected value?","options":["Historical sample mean","Variance of a random variable","Median"],"correct":1,"why_vi":"Đó là Var(X)=Σp(x−E(X))².","trap_vi":""},{"stem_en":"The variance of a known discrete probability distribution is calculated by:","options":["Dividing probability-weighted squared deviations by n−1","Adding scenario returns without weights","Summing probability-weighted squared deviations"],"correct":2,"why_vi":"n−1 thuộc sample variance của historical observations, không phải phân phối xác suất đã xác định.","trap_vi":""},{"stem_en":"The return variance of an asset is 0.0108 when returns are in decimal form. Its standard deviation is closest to:","options":["10.39%","1.08%","0.0108%"],"correct":0,"why_vi":"sqrt(0.0108)=0.103923≈10.39%.","trap_vi":""},{"stem_en":"Which statement about expected return is most accurate?","options":["It must be one of the possible realized returns","It is the probability-weighted mean of possible returns","It is always the historical arithmetic sample mean"],"correct":1,"why_vi":"Expected value có thể không trùng bất kỳ outcome thực tế nào.","trap_vi":""},{"stem_en":"If X is always equal to 7, which property holds?","options":["E(X)=0","Var(X)=7","Var(X)=0"],"correct":2,"why_vi":"Không có độ phân tán quanh mean nếu kết quả chắc chắn 7.","trap_vi":""},{"stem_en":"A distribution has E(X)=3 and E(X²)=13. Its variance is:","options":["4","10","22"],"correct":0,"why_vi":"Var=13−3²=4.","trap_vi":""},{"stem_en":"For Y=5+3X, how does the standard deviation of Y compare with that of X?","options":["It increases by 5","It triples","It increases ninefold"],"correct":1,"why_vi":"σ(a+bX)=|b|σ(X), còn 5 là khoản cố định.","trap_vi":""},{"stem_en":"For Y=2−4X, which statement about variance is correct?","options":["Var(Y)=−4Var(X)","Var(Y)=4Var(X)","Var(Y)=16Var(X)"],"correct":2,"why_vi":"Var(Y)=b²Var(X)=16Var(X).","trap_vi":""},{"stem_en":"A model has outcomes of 1, 2, and 4 with probabilities 0.2, 0.5, and 0.3. What is E(X)?","options":["2.4","2.3","2.0"],"correct":0,"why_vi":"0.2(1)+0.5(2)+0.3(4)=2.4.","trap_vi":""},{"stem_en":"Which of the following can have a negative value?","options":["Variance","Expected return","Standard deviation"],"correct":1,"why_vi":"Expected return có thể âm; variance và SD không âm.","trap_vi":""},{"stem_en":"What does a higher standard deviation most directly describe, holding the model basis constant?","options":["Greater modeled dispersion around expected value","A guaranteed larger loss","A higher expected return"],"correct":0,"why_vi":"SD là độ phân tán, không quy định chiều biến động hoặc kỳ vọng.","trap_vi":""},{"stem_en":"For a distribution of future EPS outcomes, expected EPS should be expressed in:","options":["Squared USD per share","Probability units only","USD per share"],"correct":2,"why_vi":"Expected value giữ nguyên đơn vị của random variable.","trap_vi":""},{"stem_en":"A scenario table has probabilities 0.3, 0.3, and 0.3 and states that these are all possible outcomes. What should the analyst do first?","options":["Assume equal weights and proceed","Identify the missing 0.1 probability or correct the model","Divide variance by n−1"],"correct":1,"why_vi":"Tổng 0.9 không phải một phân phối hoàn chỉnh nếu bảng nói đã bao phủ toàn bộ trường hợp.","trap_vi":""}],"cards":[{"front_en":"What is a discrete random variable?","back_vi":"Đại lượng chỉ có thể lấy những giá trị cụ thể, mỗi giá trị gắn probability trong một phân phối."},{"front_en":"Probability-weighted mean formula?","back_vi":"E(X)=Σpᵢxᵢ; Σpᵢ=1."},{"front_en":"Expected value vs realized return?","back_vi":"E là kỳ vọng trung bình từ kịch bản trước khi sự kiện diễn ra; realized là kết quả đã xảy ra."},{"front_en":"Probability distribution variance?","back_vi":"Var(X)=Σpᵢ(xᵢ−E(X))²; không chia n−1."},{"front_en":"Variance shortcut?","back_vi":"E(X²)−[E(X)]²."},{"front_en":"Standard deviation from variance?","back_vi":"sqrt(variance), cùng đơn vị X."},{"front_en":"Can an expected return be negative?","back_vi":"Có. Nhưng variance và SD không âm."},{"front_en":"Does E(X) need to be a possible outcome?","back_vi":"Không, expected value có thể nằm giữa các outcome mà không xuất hiện trong thực tế."},{"front_en":"Effect of adding a constant a to X?","back_vi":"Mean tăng a; variance và SD không đổi."},{"front_en":"Effect of multiplying X by b?","back_vi":"Mean ×b; variance ×b²; SD ×|b|."},{"front_en":"Historical sample variance denominator?","back_vi":"n−1 dùng với sample estimate; không dùng cho probability-weighted variance của distribution đã cho."},{"front_en":"How do you check scenario probabilities?","back_vi":"Mỗi xác suất từ 0 đến 1, các trường hợp bao phủ hết, tổng bằng 1."}]},{"id":"CFA26-01-04-LOS02","letter":"4.b","title_en":"Probability Trees and Conditional Expectations","outcome_en":"formulate an investment problem as a probability tree and explain the use of conditional expectations in investment application","overview_vi":"Probability tree đặt các sự kiện theo thứ tự thời gian/thông tin. Mỗi nhánh có xác suất điều kiện, mỗi đường đi hoàn chỉnh có xác suất chung bằng tích xác suất nhánh. Từ các nhánh, ta tính xác suất không điều kiện và kỳ vọng return/EPS.","source":[{"id":"CFA Institute Curriculum Level I 2026 — Quantitative Methods LM4","pages":"142–147 (physical PDF; probability trees, conditional outcomes, conditional expectation)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 4","pages":"63–64 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026","pages":"197–198 (core LOS 4.b); 188–194 are preparatory conditional probability rules"}],"sections":[{"heading":"1. Vì sao cần probability tree?","body":"Trong đầu tư, một biến phụ thuộc bối cảnh: ví dụ nền kinh tế tăng trưởng/chậm lại, rồi lợi nhuận doanh nghiệp vượt/không vượt dự báo. Liệt kê outcome return trực tiếp sẽ bỏ lỡ cách các xác suất thay đổi theo trạng thái. Tree thể hiện tất cả đường đi (paths) và mối quan hệ điều kiện, giúp trả lời “xác suất đánh bại EPS khi thị trường suy yếu” hay “expected return khi nền kinh tế đã mở rộng”.","trap":"Không nhất thiết các sự kiện ở các tầng cây độc lập; nhánh hai thường phụ thuộc nhánh một."},{"heading":"2. Phân biệt unconditional và conditional probabilities","body":"P(A) là xác suất không điều kiện trước khi biết trạng thái nào xảy ra. P(A|B) là xác suất của A khi biết B, với P(B)>0. Không được tự động đổi hướng: P(A|B) thường khác P(B|A). Ví dụ 70% công ty thắng dự báo trong nền kinh tế mạnh không có nghĩa 70% công ty thắng dự báo thuộc nền kinh tế mạnh. Chiều đảo được xử lý bằng Bayes ở 4.c.","trap":""},{"heading":"3. Dựng cây với trạng thái đầu và trạng thái tiếp theo","body":"Bắt đầu ở root. Nhánh thứ nhất gồm trạng thái mutually exclusive/exhaustive, ví dụ Expansion 60% và Slowdown 40%. Ở mỗi nhánh, triển khai sự kiện Beat/Miss với xác suất conditional riêng: P(Beat|Expansion)=70%, P(Beat|Slowdown)=25%. Tất cả xác suất con của cùng một parent phải cộng bằng 1. Nếu có 3 tầng, lặp lại phép tương tự ở mỗi tầng.","trap":""},{"heading":"4. Joint probability = product along a path","body":"Quy tắc multiplication cho hai sự kiện: P(A∩B)=P(A)P(B|A). Trong cây ba tầng, joint path probability là P(S1)×P(E2|S1)×P(E3|S1,E2). Ví dụ P(Expansion ∩ Beat)=0.60×0.70=0.42; P(Slowdown ∩ Miss)=0.40×0.75=0.30. Không dùng 0.60+0.70 vì đó không phải phép tính xác suất đồng thời.","trap":""},{"heading":"5. Kiểm tra leaf probabilities cộng bằng 1","body":"Bốn đường đi của ví dụ: Expansion&Beat=.42; Expansion&Miss=.18; Slowdown&Beat=.10; Slowdown&Miss=.30. Tổng đúng 1.00. Nếu tổng không bằng 1 đáng kể, xem lại missing branches, conditional probabilities hoặc nhân cộng. Một leaf là outcome hoàn chỉnh với joint probability, không phải conditional probability ghi trên nhánh cuối.","trap":""},{"heading":"6. Total probability rule — cộng các đường đi dẫn đến một sự kiện","body":"Để tính P(Beat), cộng các leaf Beat: .42+.10=.52. Viết tổng quát P(B)=Σ_s P(B|S=s)P(S=s) khi trạng thái S bao phủ hết không chồng nhau. Kết quả .52 nằm giữa conditional probabilities .25 và .70, là một phép kiểm tra hợp lý vì đó là weighted average. Không cộng các probabilities điều kiện trần mà quên weights.","trap":""},{"heading":"7. Conditional expectation trong từng trạng thái","body":"E(R|S)=Σ_i P(Rᵢ|S)Rᵢ. Nếu ở Expansion, cổ phiếu có +20% khi Beat và −5% khi Miss thì E(R|Expansion)=.70(.20)+.30(−.05)=12.5%. Nếu Slowdown có +8% khi Beat và −12% khi Miss với probabilities .25/.75, E(R|Slowdown)=.25(.08)+.75(−.12)=−7%.","trap":"Đây là expected return given state, không phải unconditional portfolio return."},{"heading":"8. Law of total expectation — lấy trung bình conditional expectations","body":"E(R)=Σ_s P(S=s)E(R|S=s). Trong ví dụ, .60×12.5%+.40×(−7%)=4.7%. Cách khác: áp return ở bốn leaf với joint probability .42×20%+.18×(−5%)+.10×8%+.30×(−12%) = 4.7%. Hai cách phải khớp nếu cây chính xác.","trap":"Không áp dụng weights .70/.25 trực tiếp cho E(R|Expansion) và E(R|Slowdown); weights tại root là .60/.40."},{"heading":"9. Event path với hơn hai tầng","body":"Khi thêm credit upgrade/downgrade sau báo cáo earnings, cần mô hình xác suất điều kiện của tầng ba theo lịch sử nhánh trước. Ví dụ P(Upgrade|Expansion,Beat) khác P(Upgrade|Slowdown,Beat). Joint probability theo đường đi phải dùng đúng conditional information đã ghi. Nếu đề nêu independence ở một tầng, khi đó mới có thể thay P(C|A,B) bằng P(C), không được tự giả định độc lập.","trap":""},{"heading":"10. Conditional events không đồng nghĩa mutually exclusive events","body":"Expansion và Slowdown là các trạng thái loại trừ nhau tại cùng thời điểm; Beat và Expansion có thể đồng thời xảy ra nên joint probability của chúng có thể dương. Hai sự kiện độc lập thỏa P(A|B)=P(A), không phải “không bao giờ xảy ra đồng thời”. Hai sự kiện mutually exclusive với xác suất dương không thể đồng thời independent. Phân biệt này thường là bẫy chọn đáp án.","trap":""},{"heading":"11. Tree là framework để cập nhật dự báo","body":"Nếu nhà phân tích biết trước chính sách hỗ trợ đã được thông qua, có thể chuyển từ unconditional E(R) sang E(R|Policy). Nếu chỉ quan sát một tín hiệu mơ hồ về chính sách, cần posterior probability theo Bayes để cân lại nhánh trước khi tính revised E(R). Vì vậy cây ở 4.b là nền tảng toán học của cập nhật tín hiệu ở 4.c.","trap":""},{"heading":"12. Nguyên tắc dựng cây và kiểm toán","body":"Dựng cây theo thứ tự thông tin hợp lý, đánh nhãn từng root, branch, leaf; ghi đầy đủ conditioning after a vertical bar; kiểm tra sums tại từng nút và tổng leaf; từ leaf cộng ngược để tính P(event) hoặc E(X). Nếu tree xuất phát từ dữ liệu tình huống mang tính ước lượng, uncertainty của probabilities còn tồn tại; mô hình giúp trình bày assumptions chứ không bảo đảm dự báo đúng.","trap":"Conditional probability và posterior probability là những đại lượng khác nhau dù có thể liên hệ qua cùng cây."},{"heading":"13. Conditional variance và conditional standard deviation","body":"Ngoài E(X|S), mỗi nhánh có Var(X|S)=ΣᵢP(xᵢ|S)[xᵢ−E(X|S)]² và σ(X|S)=sqrt[Var(X|S)]. Ví dụ trong expansion, +20% với probability 0.70 và −5% với 0.30 tạo mean 12.5%, Var=0.013125, SD≈11.46%. Trong slowdown với +8% probability .25 và −12% .75, mean −7%, Var=.0075, SD≈8.66%. Nghĩa là risk conditional theo từng trạng thái có thể khác đáng kể; không được cộng hai standard deviations theo xác suất để gọi đó là unconditional SD.","trap":"Đề yêu cầu conditional variance thì phải dùng conditional mean của đúng nhánh, không dùng unconditional mean."},{"heading":"14. Forecast từ mô hình Y=a+bX tại từng leaf","body":"Trong một cây dự báo chi phí hoạt động, số cửa hàng hoặc số chi nhánh X có thể thay đổi theo trạng thái. Nếu dự báo tuyến tính Ŷ=a+bX biểu diễn E(Y|X), thay X của mỗi leaf vào mô hình để có conditional forecast; nhân mỗi leaf forecast với joint probability rồi cộng. Ví dụ Ŷ=10+2X (triệu USD), X=20 với probability .7 và X=10 với probability .3, expected cost=.7×50+.3×30=44 triệu USD. Đây là ứng dụng của conditional expectation, không phải hồi quy ước lượng các hệ số mới từ cây xác suất.","trap":""},{"heading":"15. Phân biệt biến động tổng và biến động có điều kiện","body":"Unconditional variance có thể lớn vì cả rủi ro bên trong từng scenario và chênh lệch giữa conditional means của các scenario. Do đó expected conditional variances và unconditional variance không nhất thiết bằng nhau. Khi câu hỏi chỉ yêu cầu E(X), law of total expectation là đủ; khi hỏi conditional variance, tính từ outcomes trong nhánh riêng. Phân tích decomposition chi tiết của unconditional variance là phần đào sâu, không bắt buộc suy ra từ phép cộng σ đơn giản.","trap":""}],"formulas":[{"name":"Conditional probability","expr":"P(A|B)=P(A∩B)/P(B)","meaning":"Xác suất A biết B đã xảy ra.","conditions":"P(B)>0; A∩B là joint event."},{"name":"Path multiplication rule","expr":"P(A∩B)=P(A)P(B|A)","meaning":"Lấy tích dọc theo nhánh tree; mở rộng tuần tự nếu nhiều tầng.","conditions":"Không cần A,B independent khi dùng conditional B|A."},{"name":"Joint probability for 3-stage path","expr":"P(S∩E∩T)=P(S)P(E|S)P(T|S,E)","meaning":"Tích ba điều kiện dọc một path.","conditions":"Giữ đúng điều kiện của mỗi nhánh."},{"name":"Total probability law","expr":"P(B)=Σ_s P(B|S=s)P(S=s)","meaning":"Tổng xác suất từ mọi root states.","conditions":"States mutually exclusive and exhaustive."},{"name":"Conditional expected value","expr":"E(X|S)=Σᵢ xᵢP(X=xᵢ|S)","meaning":"Weighted expected value sau khi biết scenario S.","conditions":"Các xác suất conditional của X trong scenario S cộng 1."},{"name":"Law of total expectation","expr":"E(X)=Σ_s P(S=s)E(X|S=s)","meaning":"Unconditional mean bằng trung bình của conditional means.","conditions":"States S tạo thành partition hợp lệ."},{"name":"Conditional variance","expr":"Var(X|S)=Σᵢ P(xᵢ|S)[xᵢ−E(X|S)]²","meaning":"Độ phân tán quanh conditional mean trong một nhánh cụ thể.","conditions":"Các probabilities là conditional on exactly the same S."},{"name":"Conditional standard deviation","expr":"σ(X|S)=√Var(X|S)","meaning":"Volatility conditional theo trạng thái, cùng đơn vị với X.","conditions":"Không bình quân cộng các σ theo scenario để tính unconditional σ."}],"examples":[{"question_en":"An economy expands with 60% probability; otherwise it slows. Conditional on expansion, earnings beat estimates with 70% probability; conditional on slowdown, with 25%. Find all four terminal path probabilities.","steps_vi":["Root: P(E)=.60 và P(S)=.40.","P(E,Beat)=.60×.70=.42; P(E,Miss)=.60×.30=.18.","P(S,Beat)=.40×.25=.10; P(S,Miss)=.40×.75=.30.","Kiểm tra tổng .42+.18+.10+.30=1.00."],"answer":"Joint probabilities: 42%, 18%, 10%, 30%.","check":"All terminal probabilities sum to 1."},{"question_en":"Using the preceding economy and earnings tree, find the unconditional probability of beating earnings expectations.","steps_vi":["Chọn hai leaf Beat từ hai nhánh kinh tế.","P(Beat)=P(E,Beat)+P(S,Beat)=.42+.10=.52.","Tương đương .60×.70+.40×.25."],"answer":"52%.","check":""},{"question_en":"Conditional on expansion, a stock earns 20% if earnings beat estimates and −5% if they miss; P(Beat|Expansion)=70%. Find conditional expected return.","steps_vi":["P(Miss|Expansion)=.30.","E(R|Expansion)=.70×.20+.30×(−.05)=.14−.015=.125."],"answer":"12.5%.","check":""},{"question_en":"Conditional on slowdown, return is 8% with 25% probability and −12% with 75%. Find the conditional expected return.","steps_vi":["E(R|Slowdown)=.25×.08+.75×(−.12).","=0.02−0.09=−0.07."],"answer":"−7.0%.","check":""},{"question_en":"Expansion and slowdown have probabilities 60% and 40%; their conditional expected stock returns are 12.5% and −7%. Find unconditional expected return.","steps_vi":["Law of total expectation: E(R)=.60×.125+.40×(−.07).","=0.075−0.028=0.047."],"answer":"4.7%.","check":"Check by four leaves: .42×.20+.18×(−.05)+.10×.08+.30×(−.12)=.047."},{"question_en":"An issuer is rated IG with probability 0.80 and HY with probability 0.20. The downgrade probabilities are 5% and 30% in those categories. Find the unconditional downgrade probability.","steps_vi":["P(Downgrade)=P(D|IG)P(IG)+P(D|HY)P(HY).","=0.05×0.80+0.30×0.20=0.04+0.06."],"answer":"10.0%.","check":""},{"question_en":"Given P(A)=0.4 and P(B|A)=0.3, calculate P(A and B).","steps_vi":["Theo multiplication P(A∩B)=P(A)P(B|A).","=0.4×0.3=0.12."],"answer":"12%.","check":""},{"question_en":"A two-stage tree has P(Up)=0.60, P(Down)=0.40, P(Positive|Up)=0.75, and P(Positive|Down)=0.15. Find P(Positive).","steps_vi":["Positive leaf in Up: .60×.75=.45.","Positive leaf in Down: .40×.15=.06.","P(Positive)=.45+.06=.51."],"answer":"51%.","check":""},{"question_en":"Under expansion, a stock has a 70% chance of +20% and a 30% chance of −5%. Calculate conditional variance and standard deviation.","steps_vi":["Conditional mean=.7×.20+.3×(−.05)=.125.","Variance=.7(.20−.125)²+.3(−.05−.125)²=.7×.005625+.3×.030625=.013125.","Conditional SD=sqrt(.013125)≈.11456."],"answer":"Conditional variance = 0.013125; conditional SD ≈11.46%.","check":""},{"question_en":"Under slowdown, the two possible returns are +8% and −12% with conditional probabilities 25% and 75%. Calculate conditional standard deviation.","steps_vi":["Conditional mean=.25×.08+.75×(−.12)=−.07.","Conditional variance=.25(.08+.07)²+.75(−.12+.07)²=.25×.0225+.75×.0025=.0075.","sqrt(.0075)=.08660."],"answer":"Conditional standard deviation ≈8.66%.","check":""},{"question_en":"An analyst forecasts operating cost (USD millions) using Y=10+2X, where X is the number of units. X is 20 with probability 0.7 and 10 with probability 0.3. Calculate expected operating cost.","steps_vi":["Với X=20, conditional forecast=10+2×20=50 triệu USD.","Với X=10, conditional forecast=10+2×10=30 triệu USD.","E(Y)=.7×50+.3×30=44 triệu USD."],"answer":"USD 44 million.","check":""}],"questions":[{"stem_en":"An economy expands with probability 0.60. Given expansion, an issuer beats earnings forecasts with probability 0.70. Their joint probability is:","options":["42%","70%","130%"],"correct":0,"why_vi":"P(Expand ∩ Beat)=0.60×0.70=0.42.","trap_vi":""},{"stem_en":"If P(A)=0.4 and P(B|A)=0.3, P(A and B) is:","options":["0.7","0.12","0.3"],"correct":1,"why_vi":"0.4×0.3=0.12.","trap_vi":""},{"stem_en":"The probabilities of all mutually exclusive terminal paths in a complete tree must add to:","options":["The expected return","Zero","One"],"correct":2,"why_vi":"Nếu đúng partition toàn bộ outcome, tổng joint path probabilities bằng 1.","trap_vi":""},{"stem_en":"An economy expands with probability 0.6; P(Beat|Expansion)=0.7 and P(Beat|Slowdown)=0.25. P(Beat) equals:","options":["52%","70%","95%"],"correct":0,"why_vi":".6×.7+.4×.25=.52.","trap_vi":""},{"stem_en":"P(A|B) is defined as:","options":["P(A∩B)/P(A)","P(A∩B)/P(B)","P(A)+P(B)"],"correct":1,"why_vi":"Điều kiện biết B xảy ra, nên mẫu số P(B)>0.","trap_vi":""},{"stem_en":"Which statement is least accurate?","options":["Joint probability can be computed by multiplying along a conditional path","A second-stage probability can depend on the first-stage state","All second-stage branch probabilities must be independent of the first-stage state"],"correct":2,"why_vi":"Probability tree thường biểu diễn phụ thuộc; không tự giả định independence.","trap_vi":""},{"stem_en":"Conditional on expansion, a stock gains 20% with 70% probability and loses 5% with 30%. Expected return given expansion equals:","options":["12.5%","15.0%","10.5%"],"correct":0,"why_vi":".70×20%+.30×(−5%)=12.5%.","trap_vi":""},{"stem_en":"Conditional expected return is 12.5% under expansion and −7% under slowdown. The scenario probabilities are 0.6 and 0.4. Unconditional expected return is:","options":["5.5%","4.7%","2.2%"],"correct":1,"why_vi":".6×12.5%+.4×(−7%)=4.7%.","trap_vi":""},{"stem_en":"Two events with positive probabilities cannot be both mutually exclusive and:","options":["Exhaustive","Different","Independent"],"correct":2,"why_vi":"P(A∩B)=0 nếu mutually exclusive; independence đòi P(A∩B)=P(A)P(B)>0.","trap_vi":""},{"stem_en":"To compute the probability of a terminal outcome across several first-stage states, which rule is most useful?","options":["Total probability","Sample variance","Geometric mean"],"correct":0,"why_vi":"Cộng joint probabilities của các paths dẫn tới outcome.","trap_vi":""},{"stem_en":"A tree gives P(Up)=0.60 and P(Positive|Up)=0.75. Which is the joint probability P(Up and Positive)?","options":["0.75","0.45","1.35"],"correct":1,"why_vi":"Joint = .60×.75=.45.","trap_vi":""},{"stem_en":"A parent node has three exhaustive child probabilities of 20%, 25%, and 40%. Which issue is most evident?","options":["Probabilities exceed 1","They must all equal one another","The specified probabilities total only 85%"],"correct":2,"why_vi":"Thiếu xác suất 15% hoặc dữ liệu bị sai.","trap_vi":""},{"stem_en":"A signal is observed but does not reveal the state with certainty. To update the probability of the earlier state, an analyst would most directly use:","options":["Bayes’ formula","n−1 sample variance","A perpetuity formula"],"correct":0,"why_vi":"Cập nhật probability về nguyên nhân/state từ thông tin signal theo Bayes.","trap_vi":""},{"stem_en":"A firm has 80% probability of being IG and 20% of being HY. If downgrade probabilities conditional on category are 5% and 30%, the overall downgrade probability is:","options":["7%","10%","35%"],"correct":1,"why_vi":".80×.05+.20×.30=.04+.06=.10.","trap_vi":""},{"stem_en":"Which notation describes a conditional expectation of return given a recession?","options":["P(Recession)","Var(R)","E(R|Recession)"],"correct":2,"why_vi":"E(R|Recession) là expected return trong trạng thái recession, không phải probability.","trap_vi":""},{"stem_en":"Conditional on expansion, stock returns are +20% with probability 70% and −5% with probability 30%. The conditional standard deviation is closest to:","options":["11.46%","1.31%","12.50%"],"correct":0,"why_vi":"Conditional mean=.125; variance=.013125; sqrt=.11456≈11.46%.","trap_vi":""},{"stem_en":"Which mean must be used when calculating variance of return conditional on recession?","options":["Unconditional mean of all states","The mean return within recession","The previous historical sample mean in all cases"],"correct":1,"why_vi":"Var(R|Recession) đo deviation từ E(R|Recession).","trap_vi":""},{"stem_en":"Costs (USD millions) are forecast by Y=10+2X. X is 20 with probability 0.7 and 10 with probability 0.3. Expected cost is:","options":["USD 40 million","USD 50 million","USD 44 million"],"correct":2,"why_vi":"Cost outcomes 50 và 30; weighted mean .7×50+.3×30=44.","trap_vi":""}],"cards":[{"front_en":"Probability tree: probability of a complete path?","back_vi":"Nhân các xác suất branch điều kiện dọc theo path."},{"front_en":"What is conditional probability?","back_vi":"P(A|B): xác suất A khi B đã xảy ra; =P(A∩B)/P(B)."},{"front_en":"Multiplication rule for joint probability?","back_vi":"P(A∩B)=P(A)P(B|A)."},{"front_en":"Do two tree stages have to be independent?","back_vi":"Không. Có thể P(B|A) khác P(B|not A)."},{"front_en":"Total probability law?","back_vi":"P(B)=Σ_s P(B|S=s)P(S=s) với S là exhaustive/mutually exclusive states."},{"front_en":"Conditional expected value?","back_vi":"E(X|S)=Σ outcomes xᵢP(xᵢ|S)."},{"front_en":"Law of total expectation?","back_vi":"E(X)=Σ_s P(S=s)E(X|S=s)."},{"front_en":"How to verify a probability tree?","back_vi":"Tổng nhánh con mỗi parent=1; tổng xác suất leaf=1."},{"front_en":"What is a leaf probability?","back_vi":"Joint probability của toàn bộ events theo đường đi đến leaf."},{"front_en":"Mutually exclusive vs independent?","back_vi":"Mutually exclusive: không xảy ra đồng thời; independent: biết A không đổi xác suất B."},{"front_en":"P(Beat|Expansion) = P(Expansion|Beat)?","back_vi":"Không nói chung; chiều đảo cần Bayes."},{"front_en":"What happens when all conditional expected returns are weighted by first-stage probabilities?","back_vi":"Thu được unconditional expected return E(R)."},{"front_en":"Formula for conditional variance?","back_vi":"Var(X|S)=ΣᵢP(xᵢ|S)[xᵢ−E(X|S)]²."},{"front_en":"Conditional SD vs unconditional SD?","back_vi":"Conditional SD tính trong từng scenario; không lấy bình quân weighted của SD các scenario để suy ra unconditional SD."}]},{"id":"CFA26-01-04-LOS03","letter":"4.c","title_en":"Bayes’ Formula and Probability Updating","outcome_en":"calculate and interpret an updated probability in an investment setting using Bayes’ formula","overview_vi":"Thông tin mới như tăng hạng tín nhiệm, vượt EPS hoặc tín hiệu cảnh báo làm thay đổi đánh giá xác suất ban đầu. Bayes’ formula chuyển prior probability thành posterior probability bằng cách kết hợp likelihood của tín hiệu với xác suất tổng của tín hiệu.","source":[{"id":"CFA Institute Curriculum Level I 2026 — Quantitative Methods LM4","pages":"147–156 (physical PDF; Bayes formula, frequency tree, stock and credit illustrations)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 4","pages":"64–66 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026","pages":"199–203 (LOS 4.c core); 204–206 are supplementary preparatory counting exercises, not core 4.c"}],"sections":[{"heading":"1. Câu hỏi Bayes đảo chiều điều kiện như thế nào?","body":"Khi thị trường có trạng thái ẩn A (ví dụ một issuer đang khó khăn) và ta quan sát tín hiệu B (cảnh báo credit), mô hình thường biết P(B|A): nếu issuer khó khăn thì khả năng xuất hiện cảnh báo là bao nhiêu. Câu hỏi thực tế muốn P(A|B): khi đã thấy cảnh báo thì xác suất issuer khó khăn là bao nhiêu? Hai xác suất này không giống nhau. Bayes là phép cập nhật có lý do toán học, không phải giả định rằng tín hiệu là nguyên nhân của trạng thái.","trap":""},{"heading":"2. Prior, likelihood, evidence, posterior","body":"Prior P(A) là đánh giá trước khi nhận tín hiệu. Likelihood P(B|A) là độ thường gặp của tín hiệu trong trạng thái A; không phải posterior. Evidence P(B) là xác suất quan sát tín hiệu ở mọi trạng thái có thể. Posterior P(A|B) là xác suất trạng thái A sau khi thấy B. Công thức: P(A|B)=[P(B|A)P(A)]/P(B). Mẫu số làm chuẩn hóa tổng posterior của các trạng thái bằng 1.","trap":"Bẫy: thay prior bằng likelihood hoặc quên denominator khi tính updated probability."},{"heading":"3. Mẫu số dùng total probability rule","body":"Với hai trạng thái A và not A: P(B)=P(B|A)P(A)+P(B|not A)P(not A). Đây là tổng joint probabilities của các nhánh có signal B. Nếu có ba scenarios, tiếp tục cộng ba nhánh. Điều kiện P(B)>0 bắt buộc để posterior có nghĩa. Xác suất tín hiệu tổng thường không bằng likelihood trong một trạng thái cụ thể.","trap":""},{"heading":"4. Ví dụ cảnh báo rủi ro tín dụng","body":"Trước khi nhận tin có 10% xác suất doanh nghiệp distress. Một mô hình phát tín hiệu Flag ở 80% doanh nghiệp distress và 20% doanh nghiệp không distress. P(Flag)=0.8×0.1+0.2×0.9=0.26. Posterior distress khi thấy Flag =0.08/0.26≈30.77%. Tín hiệu khá nhạy nhưng tín hiệu giả ở nhóm lành mạnh làm posterior thấp hơn 80%.","trap":"Không phát biểu “80% flagged companies distressed” vì 80% là P(Flag|Distress), không phải P(Distress|Flag)."},{"heading":"5. Base-rate effect — không thể bỏ qua prior","body":"Một test có sensitivity rất cao vẫn có posterior positive predictive probability không cao nếu sự kiện thực sự hiếm. Ví dụ 5% issuer default, test cảnh báo 90% khi default và cảnh báo nhầm 10% khi không default: trên 1,000 issuer kỳ vọng 45 true flags và 95 false flags. Trong 140 flags, khoảng 32.14% thực sự default. Đây là lý do baseline distress probability quan trọng ngang với signal quality.","trap":""},{"heading":"6. Frequency-tree là cách kiểm tra Bayes trực quan","body":"Chọn quần thể giả định 1,000 hoặc 10,000 đơn vị, chia theo prior thành các nhóm A/not A, rồi phân tiếp bằng likelihood cho tín hiệu B/not B. Đếm tổng B và phần B thuộc A. Chia số trường hợp A∩B cho B để được posterior. Với xác suất có số lẻ, dùng expected counts hoặc quần thể đủ lớn; đừng coi dữ liệu giả định là tần suất thực quan sát.","trap":""},{"heading":"7. Khi quan sát không có tín hiệu (negative evidence)","body":"Bayes cũng áp dụng với not B. Trong mô hình distress P(A)=.10, P(Flag|A)=.8, P(Flag|not A)=.2, khi không có Flag: P(not Flag|A)=.2; P(not Flag|not A)=.8. P(A|not Flag)=.02/(.02+.72)=.02703. Không có cảnh báo làm giảm xác suất khó khăn từ 10% về khoảng 2.7%, nhưng không chứng minh doanh nghiệp không thể distress.","trap":""},{"heading":"8. Posterior cho nhiều trạng thái và chuẩn hóa","body":"Nếu prior của ba regimes A/B/C lần lượt 0.2/0.5/0.3, likelihood của tín hiệu lần lượt 0.8/0.4/0.1, unnormalized weights là 0.16/0.20/0.03. P(Signal)=.39. Posterior là .4103/.5128/.0769 và cộng xấp xỉ 1 (sai số làm tròn). Một tín hiệu không nhất thiết khiến trạng thái có likelihood cao nhất trở thành posterior lớn nhất, vì priors cũng ảnh hưởng mạnh.","trap":""},{"heading":"9. Sequential updating — prior ngày mai có thể là posterior hôm nay","body":"Sau lần quan sát thứ nhất, posterior mới trở thành prior để xử lý lần quan sát kế tiếp. Khi dùng P(B2|A,B1), cần biết cấu trúc phụ thuộc của các signals. Không được nhân likelihoods từ hai signals trừ khi chúng độc lập có điều kiện theo từng trạng thái, hoặc mô hình cung cấp joint likelihood. Nếu xử lý trùng một tín hiệu hai lần, mức tự tin có thể bị phóng đại.","trap":""},{"heading":"10. Posterior odds và likelihood ratio — công cụ bổ sung","body":"Bayes có thể viết posterior odds = prior odds × likelihood ratio, trong đó odds=P(A)/(1−P(A)) và LR=P(B|A)/P(B|not A). Phương pháp này giúp nhìn tác động của tín hiệu: LR>1 tăng odds, LR<1 giảm odds, LR=1 không đổi odds. Đây là cách giải bổ trợ; trọng tâm của 4.c vẫn là tính và diễn giải posterior probability bằng Bayes trên probability tree.","trap":""},{"heading":"11. Biến xác suất thành revised investment expectations","body":"Sau khi có P(Expansion|Good signal)=2/3, nếu expected return của tài sản là +15% khi expansion và −10% khi slowdown, revised E(R|Good signal)=(2/3)(0.15)+(1/3)(−0.10)=6.67%. Không lấy 2/3 làm expected return; đây là xác suất điều kiện dùng làm trọng số của các state-dependent investment returns.","trap":""},{"heading":"12. Kiểm tra giả định và độ bền của tín hiệu","body":"Mọi posterior phụ thuộc prior, likelihood, định nghĩa tín hiệu và độ ổn định giữa các giai đoạn. Backtests có thể sai vì look-ahead, survivorship, small samples hoặc base rate dịch chuyển. Nếu tín hiệu chỉ là một dấu hiệu dự đoán, Bayes không chứng minh nhân quả hay xác nhận model calibration. Trong bài thi, đọc kỹ cụm “given the observed upgrade” để chọn đúng hướng điều kiện.","trap":""},{"heading":"13. Quy trình 6 bước giải bài Bayesian trong đề CFA","body":"(1) Đặt A=state cần hỏi, B=evidence đã quan sát. (2) Ghi prior P(A) cùng P(not A). (3) Ghi likelihood P(B|A) và P(B|not A). (4) Nhân để ra joint weights. (5) Cộng weights để tìm P(B). (6) Posterior=joint(A,B)/P(B); kiểm tra posterior trong [0,1] và các posterior theo state cộng 1. Nếu dùng frequency tree, thực hiện đúng sáu bước bằng số lượng công ty tương ứng.","trap":""}],"formulas":[{"name":"Bayes’ formula","expr":"P(A|B) = P(B|A)P(A) / P(B)","meaning":"Posterior của A sau khi quan sát B.","conditions":"P(B)>0; xác suất có cùng tập kịch bản."},{"name":"Evidence probability for two states","expr":"P(B) = P(B|A)P(A) + P(B|not A)[1−P(A)]","meaning":"Chuẩn hóa posterior của cả A/not A.","conditions":"A và not A là partition exhaustive."},{"name":"Posterior for three or more regimes","expr":"P(Sᵢ|B) = P(B|Sᵢ)P(Sᵢ) / Σⱼ[P(B|Sⱼ)P(Sⱼ)]","meaning":"Cập nhật multiple regimes từ cùng một signal.","conditions":"Các Sᵢ mutually exclusive/exhaustive."},{"name":"Posterior on absence of evidence","expr":"P(A|not B) = P(not B|A)P(A) / P(not B)","meaning":"Negative/no-signal information cũng cập nhật xác suất.","conditions":"P(not B)>0."},{"name":"Odds form (supporting method)","expr":"Posterior odds(A|B) = Prior odds(A) × [P(B|A)/P(B|not A)]","meaning":"Likelihood ratio mô tả tín hiệu làm tăng hay giảm odds của state.","conditions":"Hai trạng thái A/not A, likelihood denominator >0."},{"name":"Updated conditional expected return","expr":"E(R|B) = Σᵢ P(Sᵢ|B) E(R|Sᵢ,B)","meaning":"Dùng posterior state probabilities để cập nhật lợi suất kỳ vọng.","conditions":"Nếu returns trong từng state không đổi khi biết B, có thể dùng E(R|Sᵢ) thay vì E(R|Sᵢ,B)."}],"examples":[{"question_en":"Prior distress probability is 10%. A warning flag appears with 80% probability if distressed and with 20% probability if healthy. After observing a flag, what is the probability of distress?","steps_vi":["P(D)=.10; P(H)=.90.","P(Flag∩D)=.80×.10=.08; P(Flag∩H)=.20×.90=.18.","P(Flag)=.08+.18=.26.","P(D|Flag)=.08/.26≈.307692."],"answer":"30.77%.","check":"Do not confuse 80% sensitivity with 30.77% positive posterior probability."},{"question_en":"Under the preceding distress/flag model, what is the posterior distress probability if NO flag appears?","steps_vi":["P(NoFlag|D)=1−.8=.2; P(NoFlag|H)=1−.2=.8.","Joint distress and no-flag=.10×.20=.02.","P(NoFlag)=.02+.90×.80=.74.","Posterior=.02/.74≈.027027."],"answer":"2.70%.","check":""},{"question_en":"Expansion has a 60% prior; a favorable report occurs with probability 75% if expansion and 30% if slowdown. Find P(Expansion|Favorable report).","steps_vi":["Joint expansion and favorable=.60×.75=.45.","Joint slowdown and favorable=.40×.30=.12.","P(Favorable)=.57; posterior=.45/.57=.7894737."],"answer":"78.95%.","check":""},{"question_en":"Three regimes have priors [0.20,0.50,0.30] and signal likelihoods [0.80,0.40,0.10]. Compute all posterior regime probabilities.","steps_vi":["Unnormalized weights: 0.20×0.80=.16; 0.50×0.40=.20; 0.30×0.10=.03.","Evidence probability=.16+.20+.03=.39.","Posteriors: .16/.39=.41026; .20/.39=.51282; .03/.39=.07692.","Tổng ≈1.00."],"answer":"A=41.03%; B=51.28%; C=7.69%.","check":""},{"question_en":"A default screen is positive for 90% of future defaulters and 10% of non-defaulters; the prior default rate is 5%. Among 1,000 issuers, estimate P(Default|Positive screen).","steps_vi":["Kỳ vọng 50 default và 950 non-default.","Positive default: 50×.90=45; false positive: 950×.10=95.","Total positive=140, default share=45/140=.3214286."],"answer":"32.14%.","check":""},{"question_en":"The prior distress probability is 10%. Two conditionally independent positive signals have true-positive rates of 80% and 90%, and false-positive rates of 20% and 10%. Find P(Distress|both positive).","steps_vi":["Joint weight of D and both positives=.10×.80×.90=.072.","Joint weight healthy and both positives=.90×.20×.10=.018.","Posterior=.072/(.072+.018)=.80.","Conditional independence within each state is essential; without it, cannot multiply the likelihoods."],"answer":"80.0%.","check":""},{"question_en":"The prior expansion probability is 40%. A positive macro signal occurs with probability 75% in expansion and 25% in slowdown. Compute updated expansion probability and expected return if expansion returns +15% and slowdown −10%.","steps_vi":["Prior weights: P(Positive∩Expansion)=.40×.75=.30; P(Positive∩Slowdown)=.60×.25=.15.","P(Expansion|Positive)=.30/.45=2/3; P(Slowdown|Positive)=1/3.","Updated return=(2/3)(.15)+(1/3)(−.10)=.0666667."],"answer":"Posterior expansion = 66.67%; revised expected return = 6.67%.","check":""},{"question_en":"A credit upgrade has a 30% prior probability. A favorable economic indicator is seen in 80% of upgrade cases and 20% of no-upgrade cases. Find the posterior upgrade probability.","steps_vi":["P(Upgrade∩Indicator)=.30×.80=.24.","P(NoUpgrade∩Indicator)=.70×.20=.14.","Posterior=.24/(.24+.14)=.6315789."],"answer":"63.16%.","check":""}],"questions":[{"stem_en":"Prior distress probability is 10%; a warning is observed with probability 80% under distress and 20% under health. P(Distress|Warning) is closest to:","options":["80.00%","30.77%","10.00%"],"correct":1,"why_vi":"Bayes=.8×.1/(.8×.1+.2×.9)=.08/.26=.3077.","trap_vi":""},{"stem_en":"In Bayes’ formula, P(Signal|Distress) is best described as the:","options":["Likelihood","Posterior probability","Evidence probability"],"correct":0,"why_vi":"Likelihood đo xác suất thấy signal nếu đang ở trạng thái distress.","trap_vi":""},{"stem_en":"A positive signal is seen in 75% of expansion states; the prior probability of expansion is 60%. The joint probability of signal and expansion is:","options":["1.35","0.75","0.45"],"correct":2,"why_vi":".75×.60=.45.","trap_vi":""},{"stem_en":"P(Signal)=0.45+0.12=0.57 and P(Expansion and Signal)=0.45. The updated P(Expansion|Signal) is closest to:","options":["45.0%","78.95%","57.0%"],"correct":1,"why_vi":"Posterior=.45/.57=.78947.","trap_vi":""},{"stem_en":"Which probability is the normalizing denominator in P(A|B)=P(B|A)P(A)/P(B)?","options":["P(B)","P(A)","P(A|B)"],"correct":0,"why_vi":"Evidence P(B) là unconditional probability of observed information.","trap_vi":""},{"stem_en":"An event has a very low prior probability. A test has high sensitivity but moderate false-positive rate. What might still be true?","options":["The positive posterior must be above 90%","Prior probability is irrelevant","Many positive test results may be false positives"],"correct":2,"why_vi":"Base-rate effect: số khỏe mạnh nhiều có thể tạo nhiều false positives.","trap_vi":""},{"stem_en":"A test has a 5% event base rate, 90% sensitivity, and 10% false-positive rate. P(Event|Positive) is closest to:","options":["90.0%","32.14%","5.0%"],"correct":1,"why_vi":".05×.9/(.05×.9+.95×.1)=.045/.14=.32143.","trap_vi":""},{"stem_en":"What is the posterior probability of distress if no warning occurs in the model P(D)=0.1, P(Warning|D)=0.8, P(Warning|Healthy)=0.2?","options":["2.70%","20.00%","80.00%"],"correct":0,"why_vi":"No-warning joint=.1×.2=.02; total no-warning=.02+.9×.8=.74; posterior=.0270.","trap_vi":""},{"stem_en":"The prior probabilities of three exhaustive regimes are 0.2, 0.5, 0.3. Their signal likelihoods are 0.8, 0.4, 0.1. What is the unconditional probability of the signal?","options":["0.23","0.45","0.39"],"correct":2,"why_vi":".2×.8+.5×.4+.3×.1=.16+.20+.03=.39.","trap_vi":""},{"stem_en":"In the preceding three-regime model, which regime has the highest posterior probability after observing the signal?","options":["Regime A","Regime B","Regime C"],"correct":1,"why_vi":"B có weight .20/.39≈51.28%, lớn hơn A dù likelihood A cao hơn.","trap_vi":""},{"stem_en":"Bayes’ formula is particularly useful when an analyst needs to:","options":["Reverse conditional information and update probabilities after evidence","Compute a historical sample standard deviation without data","Ensure an event will occur"],"correct":0,"why_vi":"Bayes cập nhật prior theo likelihood và evidence.","trap_vi":""},{"stem_en":"Two conditionally independent positive signals have true-positive rates 80% and 90%. What is the joint likelihood of both signals if the event is true?","options":["0.90","0.08","0.72"],"correct":2,"why_vi":"Nếu independent conditional event: .8×.9=.72.","trap_vi":""},{"stem_en":"A signal is equally likely under distress and health. Assuming positive priors, observing it changes the prior odds by a factor of:","options":["Zero","One","Two"],"correct":1,"why_vi":"Likelihood ratio=1; posterior odds bằng prior odds, không cập nhật.","trap_vi":""},{"stem_en":"After observing evidence, the posterior probability of expansion is 2/3 and conditional returns in expansion and slowdown are +15% and −10%. Revised expected return is closest to:","options":["6.67%","15.00%","−10.00%"],"correct":0,"why_vi":"2/3×.15+1/3×(−.10)=.06667.","trap_vi":""},{"stem_en":"If P(B)=0, which calculation is invalid?","options":["P(A)","P(B|A) for all models","P(A|B) computed by dividing by P(B)"],"correct":2,"why_vi":"Conditional probability given an impossible event has undefined denominator in usual formula.","trap_vi":""}],"cards":[{"front_en":"What is Bayes’ formula?","back_vi":"P(A|B)=P(B|A)P(A)/P(B)."},{"front_en":"What is prior probability?","back_vi":"P(A) trước khi quan sát tín hiệu B."},{"front_en":"What is likelihood?","back_vi":"P(B|A): xác suất signal nếu A đúng; không phải P(A|B)."},{"front_en":"What is evidence probability?","back_vi":"P(B)=Σ_i P(B|Sᵢ)P(Sᵢ); denominator chuẩn hóa posterior."},{"front_en":"What is posterior probability?","back_vi":"P(A|B): xác suất cập nhật của trạng thái A sau khi thấy B."},{"front_en":"P(A|B) vs P(B|A)?","back_vi":"Không nói chung bằng nhau; prior/base rates ảnh hưởng chiều đảo."},{"front_en":"What is a false positive?","back_vi":"Signal dương ở nhóm không có trạng thái/event cần phát hiện."},{"front_en":"Why is the base rate important?","back_vi":"Nếu A hiếm, positive signals có thể chứa nhiều false positives."},{"front_en":"How to use a frequency tree for Bayes?","back_vi":"Từ prior chia counts theo state, nhân likelihood để lấy số signal, rồi lấy joint count/total signal count."},{"front_en":"How is absence of a signal incorporated?","back_vi":"Dùng P(not B|A) và P(not B|not A) để tính P(A|not B)."},{"front_en":"What must posterior probabilities across exhaustive states total?","back_vi":"1 (ngoại trừ sai số làm tròn)."},{"front_en":"When may likelihoods of consecutive signals be multiplied?","back_vi":"Chỉ khi conditional independence được nêu/hợp lý hoặc có joint likelihood."},{"front_en":"What is a likelihood ratio?","back_vi":"P(B|A)/P(B|not A); >1 tăng posterior odds của A."},{"front_en":"How is updated expected return computed?","back_vi":"Dùng posterior probabilities làm trọng số cho state-dependent returns, trong điều kiện phù hợp."}]}]},{"version":"2026.11.22-quant5-sourcefirst-01","module_id":"CFA26-01-05","module_title":"Portfolio Mathematics","language":"Vietnamese concepts / English questions / Vietnamese explanations","qa_status":"SOURCE_MAPPED_SELF_STUDY_DRAFT_PENDING_FULL_INDEPENDENT_ACADEMIC_SIGNOFF","disclaimer_vi":"Bài giảng và câu hỏi mới do dự án tự biên soạn; đối chiếu CFAI Curriculum 2026, Kaplan 2026, Slide Quant; không sao chép nguyên văn QBank/Mock thương mại. Các kiểm tra số học độc lập là kiểm tra từng mẫu, chưa thay thế duyệt học thuật toàn diện.","los":[{"id":"CFA26-01-05-LOS01","letter":"5.a","title_en":"Expected Return, Variance, Covariance and Correlation of Portfolios","outcome_en":"Calculate and interpret the expected value, variance, standard deviation, covariances, and correlations of portfolio returns.","overview_vi":"Portfolio return là tổng các return thành phần có trọng số theo market value. Nhưng portfolio risk KHÔNG phải bình quân có trọng số đơn giản của standard deviations: cần variance của từng tài sản và covariance giữa chúng. Học cả population/probability covariance, sample covariance, dạng hai tài sản, ma trận nhiều tài sản, ràng buộc correlation và diễn giải diversification.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM5","pages":"159–168 (physical PDF; LOS 5.a; overview and portfolio risk calculations)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 5","pages":"67–70 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 5","pages":"215–224 (physical PDF; focus 218–224)"}],"sections":[{"heading":"1. Portfolio weights are based on current market values","body":"Portfolio weight wᵢ = market value của holding i / tổng market value portfolio. Với danh mục long-only, từng wᵢ không âm và Σwᵢ=1. Ví dụ vốn ở A=USD 60,000 và B=USD 40,000 thì wA=0.60, wB=0.40. Sau khi giá biến động, weight thực tế có thể đổi (portfolio drift); khi giải bài đề cần đọc rõ trọng số tại thời điểm nào và giả định có rebalancing hay không.","trap":"Không sử dụng số cổ phiếu như weight nếu giá mỗi cổ phiếu khác nhau."},{"heading":"2. Expected portfolio return obeys linearity of expectation","body":"Return portfolio trong một kỳ Rp=ΣwᵢRi với weights cố định tại đầu kỳ. Do đó E(Rp)=ΣwᵢE(Ri) mà không đòi hỏi các tài sản độc lập: covariance không ảnh hưởng phép cộng kỳ vọng. Trường hợp A 60% có E(RA)=10%, B 40% có E(RB)=4%, E(Rp)=7.6%. Weighted expected return vẫn phải cùng kỳ đo, cùng loại return.","trap":"Không chèn correlation vào expected return."},{"heading":"3. Portfolio variance is not a weighted average of variances","body":"Var(Rp)=Var(ΣwᵢRi)=ΣᵢΣⱼwᵢwⱼCov(Ri,Rj). Vế phải bao gồm các variance terms trên diagonal và covariance terms ngoài diagonal. Bởi vậy volatility của danh mục phụ thuộc cả mức độ dao động từng tài sản lẫn mối quan hệ giữa chúng; không thể suy ra chính xác chỉ từ σA và σB khi chưa biết covariance hoặc correlation.","trap":"Lấy wAσA + wBσB thường sai trừ trường hợp đặc biệt perfect positive correlation với weights không âm."},{"heading":"4. Covariance describes co-movement in returns","body":"Cov(RA,RB)=E[(RA−E(RA))(RB−E(RB))]. Covariance dương khi hai tài sản có xu hướng lệch khỏi kỳ vọng cùng dấu, âm khi thường lệch trái dấu; 0 nghĩa là không có tuyến tính đồng biến rõ trong mô hình, nhưng không chứng minh độc lập trong mọi trường hợp. Covariance có đơn vị return² và không bị chặn bởi [−1,+1].","trap":""},{"heading":"5. Forecast/population versus sample covariance","body":"Khi mô hình có xác suất pₛ cho các trạng thái, covariance = Σₛ pₛ(RA,s−μA)(RB,s−μB), không chia n−1. Khi có n cặp quan sát lịch sử để ước lượng covariance mẫu, dùng [Σₜ(RA,t−meanA)(RB,t−meanB)]/(n−1). Hai đối tượng khác nhau: tính chất phân phối cho trước và estimator từ dữ liệu mẫu.","trap":"Dùng denominator n−1 cho table probabilities sẽ làm sai kết quả."},{"heading":"6. Symmetry, own covariance, covariance matrix","body":"Cov(RA,RB)=Cov(RB,RA); Cov(RA,RA)=Var(RA). Một covariance matrix phải đối xứng, đường chéo là từng variance (không âm). Với n tài sản, có n phần tử variance riêng và n(n−1)/2 cặp covariance khác nhau về mặt thông tin. Trong tổng phương sai danh mục, mọi cặp i≠j xuất hiện hai lần (i,j và j,i).","trap":""},{"heading":"7. Correlation is standardized covariance","body":"ρAB=Cov(RA,RB)/(σAσB) khi σA,σB dương. Correlation nằm từ −1 đến +1, không có đơn vị. Positive là co-movement tuyến tính cùng chiều, negative là ngược chiều; |ρ| lớn là tuyến tính mạnh. Nếu tài sản có zero variance, correlation với nó không được xác định dù covariance bằng 0.","trap":"Correlation +0.20 KHÔNG phải covariance +0.20; cần nhân với σAσB."},{"heading":"8. Two-asset variance and standard deviation","body":"Var(Rp)=wA²σA²+wB²σB²+2wAwBσAσBρAB. Đầu tiên biến % thành decimal, tính ba terms, cộng, rồi lấy căn. Nếu đề đưa covariance thay vì ρ, thay term cuối bằng 2wAwBCovAB. Standard deviation σp=√Var(Rp) cùng đơn vị với returns.","trap":"Hệ số 2 trước cross term là bắt buộc vì CovAB và CovBA đều góp phần."},{"heading":"9. Diversification depends on correlation","body":"Giữ nguyên weights/volatility từng tài sản, hạ correlation giữa hai tài sản làm giảm variance portfolio khi weights đều không âm. ρ=+1 cho mức SD cao nhất với cùng weights và volatilities; ρ<+1 tạo lợi ích diversification theo biến động; ρ=−1 có thể tạo tổ hợp zero variance nếu chọn weights phù hợp và cho phép các giả định hình thức. Correlation không bảo đảm ổn định qua các giai đoạn khủng hoảng.","trap":"Không tự kết luận “ρ=0 nên portfolio risk=0”; phần variance riêng vẫn tồn tại."},{"heading":"10. Perfect positive and perfect negative cases","body":"Khi ρ=+1, σp=|wAσA+wBσB|. Với long-only weights, đó là wAσA+wBσB. Khi ρ=−1, σp=|wAσA−wBσB|. Nếu cả hai tài sản có biến động dương và long-only weights tổng 1, điều kiện zero risk là wAσA=wBσB, suy ra wA=σB/(σA+σB), wB=σA/(σA+σB).","trap":"Chỉ áp dụng công thức tuyệt đối đặc biệt khi |ρ|=1."},{"heading":"11. Diversification is not simply adding more securities","body":"Thêm nhiều tài sản tương quan rất cao có thể không hạ risk nhiều; thay vào đó, kết hợp các dòng returns không cùng chuyển động tạo giảm variance đáng kể. Covariances ngày càng quan trọng ở danh mục nhiều holdings. Tuy vậy việc đa dạng hóa không tự động làm expected return tăng: kỳ vọng vẫn do weights và constituent expected returns quyết định.","trap":""},{"heading":"12. From covariance matrix to portfolio variance","body":"Đối với n assets, đặt vector w và covariance matrix Σ: σp² = wᵀΣw. Ví dụ 3 assets: tổng 3 diagonal contributions wi²σi² + ba cross-pair contributions 2wiwjCovij. Hãy đọc đúng ô hàng/cột trong bảng covariance; không nhân thêm 2 nếu bảng đã cung cấp tổng hai ô đối xứng. Trường hợp correlation matrix được cung cấp, Covij=ρijσiσj.","trap":""},{"heading":"13. Units: variance, covariance, SD","body":"Nếu Ri biểu diễn 0.10 nghĩa là 10%, thì Var(R) ở decimal², còn SD decimal. Nếu đề ghi returns là số 10 đại diện 10%, variance/covariance số tương ứng ở percentage-points squared và SD là percentage points. Khi chuyển đơn vị returns từ decimal sang %, variance/covariance nhân 100²=10,000. Kiểm tra scale trước khi đối chiếu đáp án.","trap":""},{"heading":"14. Long/short positions and risk arithmetic","body":"Trong công thức tuyến tính, short position có thể làm một wi âm và các vị thế khác có weight >1; khi đó sign của cross term thay đổi theo wi wj. Không tùy tiện khẳng định giảm correlation chắc chắn giảm portfolio risk nếu có negative weights. Đề Level I thường là long-only, nhưng hiểu điều kiện của kết luận giúp tránh suy luận máy móc.","trap":""},{"heading":"15. A practical exam calculation sequence","body":"(1) Tính/kiểm tra market-value weights. (2) Tính E(Rp)=Σwiμi. (3) Xác nhận covariance hay correlation đang được cung cấp. (4) Tính covariance từ rho nếu cần. (5) Đối với 2 assets tính hai variance terms và cross term; với 3 assets tính các cặp độc lập một lần ×2. (6) Lấy căn, làm tròn cuối cùng, diễn giải mức dispersion của portfolio returns chứ không phải xác suất lỗ.","trap":""},{"heading":"16. What zero correlation does and does not mean","body":"ρ=0 nghĩa là covariance zero nếu cả hai σ dương, nên cross term biến mất; nhưng cả hai variance riêng vẫn góp vào portfolio risk. Hai biến độc lập có covariance zero khi moments tồn tại; chiều ngược lại không luôn đúng. Đây là vấn đề logic rất dễ nhầm trong các câu hỏi định nghĩa, khác với việc ρ bằng 0 hay không được ước lượng chính xác từ một mẫu hữu hạn.","trap":""}],"formulas":[{"name":"Market-value portfolio weight","expr":"wᵢ = MVᵢ / ΣⱼMVⱼ","meaning":"Tỷ trọng vốn đầu tư theo market value.","conditions":"Portfolio long-only: Σᵢwᵢ=1, wᵢ≥0."},{"name":"Portfolio realized return","expr":"Rₚ = ΣᵢwᵢRᵢ","meaning":"Tổng return có trọng số trên cùng một horizon.","conditions":"Weights cố định đầu kỳ; không có cash flow làm thay đổi định nghĩa."},{"name":"Expected portfolio return","expr":"E(Rₚ) = ΣᵢwᵢE(Rᵢ)","meaning":"Linearity of expectation.","conditions":"Không cần assets độc lập."},{"name":"Probability covariance","expr":"Cov(RA,RB) = Σₛ pₛ(RA,s−μA)(RB,s−μB)","meaning":"Độ đồng biến dự báo từ probability model.","conditions":"pₛ không âm, tổng 1; μA=E(RA), μB=E(RB)."},{"name":"Historical sample covariance","expr":"sAB = Σₜ(RA,t−meanA)(RB,t−meanB)/(n−1)","meaning":"Covariance ước lượng từ n cặp quan sát.","conditions":"n>1; không áp cho distribution probabilities."},{"name":"Covariance and correlation relation","expr":"CovAB = ρAB σA σB; ρAB=CovAB/(σA σB)","meaning":"Correlation không đơn vị và trong [−1,1].","conditions":"σA>0, σB>0 để ρ xác định."},{"name":"Two-asset portfolio variance","expr":"σₚ²=wA²σA²+wB²σB²+2wAwBCovAB","meaning":"Phương sai danh mục hai tài sản.","conditions":"Tổng weights đúng; input cùng kỳ và đơn vị."},{"name":"Two-asset variance from correlation","expr":"σₚ²=wA²σA²+wB²σB²+2wAwBσAσBρAB","meaning":"Dạng thay covariance bằng correlation.","conditions":"ρAB hợp lệ [−1,1]."},{"name":"Portfolio standard deviation","expr":"σₚ = √σₚ²","meaning":"Volatility của danh mục.","conditions":"Không lấy căn từng variance rồi cộng nếu correlation chưa bằng +1."},{"name":"Multi-asset portfolio variance","expr":"σₚ²=ΣᵢΣⱼwᵢwⱼCov(Ri,Rj)=wᵀΣw","meaning":"Dạng covariance matrix cho n assets.","conditions":"Covariance matrix symmetric, positive semidefinite."},{"name":"Perfect positive correlation","expr":"ρAB=+1 ⇒ σₚ=|wAσA+wBσB|","meaning":"Với weights long-only, σₚ=weighted average of component SD.","conditions":"Dạng đặc biệt."},{"name":"Perfect negative correlation","expr":"ρAB=−1 ⇒ σₚ=|wAσA−wBσB|","meaning":"Có thể triệt tiêu hoàn toàn dispersion trong mô hình.","conditions":"Đòi hỏi perfect negative linear co-movement."},{"name":"Zero-variance weights under ρ=−1","expr":"wA=σB/(σA+σB), wB=σA/(σA+σB)","meaning":"Hedge portfolio long-only khi perfect negative correlation.","conditions":"σA>0,σB>0; không bao gồm estimation errors."},{"name":"Variance terms in 3 assets","expr":"σₚ²=Σᵢwi²σi² + 2Σᵢ<ⱼwiwjCovij","meaning":"Tính mỗi cặp covariance độc lập đúng một lần.","conditions":"i<j quy ước unique unordered pairs."}],"examples":[{"question_en":"Market values of three assets are USD 40,000, USD 35,000, and USD 25,000. Their expected returns are 12%, 5%, and 8%, respectively. Calculate portfolio expected return.","steps_vi":["Tổng market value=100,000; weights=0.40,0.35,0.25.","E(Rp)=0.40(0.12)+0.35(0.05)+0.25(0.08).","=0.048+0.0175+0.0200=0.0855."],"answer":"8.55%.","check":"Σweights=1."},{"question_en":"A portfolio invests 60% in Asset A with expected return 10% and 40% in Asset B with expected return 4%. Compute expected return.","steps_vi":["Áp dụng linearity: 0.60(10%)+0.40(4%)=7.60%."],"answer":"7.60%.","check":"Variance/correlation không ảnh hưởng expected return."},{"question_en":"Weights are 60% in A and 40% in B. σA=20%, σB=10%, and ρAB=0.25. Calculate portfolio variance and standard deviation.","steps_vi":["Var=0.60²(0.20²)+0.40²(0.10²)+2(0.60)(0.40)(0.20)(0.10)(0.25).","=0.0144+0.0016+0.0024=0.0184.","σp=sqrt(0.0184)≈0.13565."],"answer":"Variance = 0.0184; SD ≈13.56%.","check":"Cross term includes factor 2."},{"question_en":"Use the preceding two-asset portfolio, but change correlation from +0.25 to −0.50. Find portfolio standard deviation.","steps_vi":["Var=0.0144+0.0016+2(0.60)(0.40)(0.20)(0.10)(−0.50).","=0.0160−0.0048=0.0112.","σp=sqrt(0.0112)≈0.10583."],"answer":"SD ≈10.58%.","check":"Lower correlation lowers SD for long-only weights."},{"question_en":"Two assets have volatilities 20% and 10%, with weights 60% and 40%. If correlation is +1, calculate portfolio volatility.","steps_vi":["σp=0.60×0.20+0.40×0.10.","=0.12+0.04=0.16."],"answer":"16.00%.","check":"Only for rho=+1."},{"question_en":"With σA=20%, σB=10%, and correlation −1, find the weights that generate zero portfolio volatility.","steps_vi":["wA=σB/(σA+σB)=0.10/0.30=1/3.","wB=σA/(σA+σB)=0.20/0.30=2/3.","wAσA−wBσB=(1/3)(0.20)−(2/3)(0.10)=0."],"answer":"A: 33.33%; B: 66.67%; σp=0.","check":"Pure theoretical perfect negative correlation."},{"question_en":"Asset return standard deviations are 15% and 25%, and correlation is −0.40. Calculate covariance.","steps_vi":["CovAB=ρσAσB=(−0.40)(0.15)(0.25)."],"answer":"−0.0150 (decimal-return squared).","check":""},{"question_en":"The covariance of returns A and B is 0.006. Their standard deviations are 20% and 15%. Calculate correlation.","steps_vi":["ρ=0.006/(0.20×0.15)=0.006/0.03."],"answer":"+0.20.","check":""},{"question_en":"Three historical paired returns are A=[0%, 10%, 20%] and B=[10%, 0%, −10%]. Compute sample covariance.","steps_vi":["Sample means: meanA=10%, meanB=0%.","Sum deviations products=(−0.10)(0.10)+0×0+(0.10)(−0.10)=−0.0200.","Sample covariance=−0.0200/(3−1)."],"answer":"−0.0100 (decimal-return squared).","check":"Not population covariance: denominator n−1."},{"question_en":"A three-asset portfolio has weights [0.5,0.3,0.2], volatilities [20%,10%,15%], and correlations ρ12=0.2, ρ13=−0.1, ρ23=0.3. Find variance and standard deviation.","steps_vi":["Diagonal variance terms: 0.5²×0.2²+0.3²×0.1²+0.2²×0.15²=0.0118.","Cross terms: 2(0.5)(0.3)(0.2)(0.2)(0.1)=0.0012; 2(0.5)(0.2)(−0.1)(0.2)(0.15)=−0.0006; 2(0.3)(0.2)(0.3)(0.1)(0.15)=0.00054.","Total=0.0118+0.0012−0.0006+0.00054=0.01294.","SD=sqrt(0.01294)≈0.11375."],"answer":"Variance = 0.01294; SD ≈11.38%.","check":"Each unique covariance counted once ×2."},{"question_en":"Two equal-weight assets each have volatility 20%. The correlation between their returns is zero. Calculate portfolio standard deviation.","steps_vi":["Var=0.5²(0.2²)+0.5²(0.2²)+0 (zero cross term).","=0.01+0.01=0.02; SD=sqrt(0.02)."],"answer":"SD ≈14.14%.","check":"Uncorrelated does not mean riskless."},{"question_en":"A portfolio consists of USD 240,000 in A and USD 160,000 in B. A and B have expected returns of 7% and 11%. Calculate portfolio expected return.","steps_vi":["Weights = 0.6 and 0.4.","E(Rp)=0.6×0.07+0.4×0.11=0.042+0.044."],"answer":"8.60%.","check":""},{"question_en":"If σA=25% and σB=15%, calculate covariance for return correlation of −0.80.","steps_vi":["CovAB=−0.80×0.25×0.15."],"answer":"−0.0300.","check":""},{"question_en":"For a long-only portfolio with weights 30%/70%, volatilities 10%/20%, and correlation −1, calculate portfolio volatility.","steps_vi":["σp=|0.3×0.10−0.7×0.20|=|0.03−0.14|."],"answer":"11.00%.","check":"Negative perfect correlation does not guarantee zero risk unless weights are chosen to offset exposures."}],"questions":[{"stem_en":"Which input is required to calculate an asset’s weight in a standard market-value-weighted portfolio?","options":["Its market value divided by the total portfolio market value","Its number of shares divided by the total shares outstanding","Its expected return divided by the sum of expected returns"],"correct":0,"why_vi":"Market-value weights được tính theo vốn hiện tại của mỗi holding, không phải số lượng cổ phiếu hay return.","trap_vi":""},{"stem_en":"A portfolio invests 70% in an asset expected to return 9% and 30% in an asset expected to return 5%. Its expected return is closest to:","options":["6.20%","7.80%","9.00%"],"correct":1,"why_vi":"0.70×9% + 0.30×5%=6.3%+1.5%=7.8%.","trap_vi":""},{"stem_en":"Which additional input is generally required to compute the variance of a two-risky-asset portfolio from asset weights and asset standard deviations?","options":["The correlation of the two asset returns","The risk-free rate","The portfolio expense ratio"],"correct":0,"why_vi":"Var(Rp) bao gồm cross term 2wAwBσAσBρAB; không có ρ/covariance thì chưa xác định chính xác.","trap_vi":""},{"stem_en":"For a two-asset, long-only portfolio with positive asset volatilities, decreasing correlation while holding everything else constant will:","options":["Increase expected return","Decrease portfolio variance","Increase both asset variances"],"correct":1,"why_vi":"Cross term là 2wAwBσAσBρ; khi ρ giảm, portfolio variance giảm trong trường hợp wA,wB≥0.","trap_vi":""},{"stem_en":"The covariance of a random variable with itself equals its:","options":["Standard deviation","Correlation coefficient","Variance"],"correct":2,"why_vi":"Cov(X,X)=E[(X−EX)²]=Var(X).","trap_vi":""},{"stem_en":"Which statement about covariance is most accurate?","options":["It is always between −1 and +1","It depends on the units of measurement","It is always nonnegative"],"correct":1,"why_vi":"Correlation bị chặn [−1,1]; covariance có thể lớn/nhỏ hơn 1 và thay đổi theo đơn vị return.","trap_vi":""},{"stem_en":"If σA=20%, σB=10%, and correlation is −0.50, the covariance is:","options":["−0.0100","−0.0500","+0.0100"],"correct":0,"why_vi":"CovAB=ρσAσB=(−0.5)(0.20)(0.10)=−0.0100.","trap_vi":""},{"stem_en":"A covariance of 0.006 and asset volatilities of 20% and 15% imply a correlation closest to:","options":["0.02","0.20","0.60"],"correct":1,"why_vi":"ρ=0.006/(0.20×0.15)=0.20.","trap_vi":""},{"stem_en":"Two risky assets are perfectly positively correlated. With nonnegative weights, portfolio standard deviation equals:","options":["The sum of squared weighted volatilities","The difference between asset volatilities","The weighted sum of asset standard deviations"],"correct":2,"why_vi":"Khi ρ=+1 và weights ≥0, σp=wAσA+wBσB.","trap_vi":""},{"stem_en":"When the correlation between two risky assets is exactly −1, zero portfolio variance is possible if:","options":["Their weighted volatilities exactly offset","The two asset expected returns are equal","The holdings have equal market values"],"correct":0,"why_vi":"Điều kiện σp=|wAσA−wBσB|=0 là wAσA=wBσB.","trap_vi":""},{"stem_en":"Two equally weighted assets each have standard deviation 20% and zero return correlation. Portfolio standard deviation is closest to:","options":["10.00%","14.14%","20.00%"],"correct":1,"why_vi":"Variance=0.25×0.04+0.25×0.04=0.02; √0.02≈14.14%.","trap_vi":""},{"stem_en":"For a covariance matrix, the elements on the main diagonal represent:","options":["Correlations between distinct assets","Expected returns of each asset","Variances of each asset"],"correct":2,"why_vi":"Diagonal Cov(Ri,Ri)=Var(Ri); matrix covariance đối xứng.","trap_vi":""},{"stem_en":"For a portfolio of four assets, how many unique pairwise covariances are there, excluding asset variances?","options":["Six","Eight","Twelve"],"correct":0,"why_vi":"n(n−1)/2=4×3/2=6 cặp duy nhất.","trap_vi":""},{"stem_en":"A portfolio holds 60% in A (standard deviation 20%) and 40% in B (standard deviation 10%) with correlation 0.25. Its standard deviation is closest to:","options":["10.00%","13.56%","16.00%"],"correct":1,"why_vi":"Var=0.0184 → σp≈13.56%.","trap_vi":""},{"stem_en":"Which formula is appropriate for estimating sample covariance from n paired historical return observations?","options":["Divide the sum of cross-deviations by n−1","Divide the sum of cross-deviations by n²","Divide the sum of squared deviations by n"],"correct":0,"why_vi":"Sample covariance dùng n−1; mô hình forecast probabilities dùng Σp deviations chứ không chia n−1.","trap_vi":""},{"stem_en":"Which statement about independent returns with finite variances is correct?","options":["Their correlation is always +1","Their covariance is zero","Their standard deviations are equal"],"correct":1,"why_vi":"Independence ⇒ Cov=0 khi moments tồn tại; converse không luôn đúng.","trap_vi":""},{"stem_en":"A two-asset portfolio has 50% weights, 10% volatility for A, 20% for B, and correlation +1. Portfolio volatility is:","options":["5.00%","11.18%","15.00%"],"correct":2,"why_vi":"Với perfect positive correlation, σp=0.5×0.10+0.5×0.20=0.15.","trap_vi":""},{"stem_en":"A 10% return written as 0.10 has a variance of 0.01. The equivalent variance when returns are measured in percentage points is:","options":["1","10","100"],"correct":2,"why_vi":"Quy đổi decimal sang percentage points nhân 100; variance nhân 100²=10,000: 0.01×10,000=100.","trap_vi":""},{"stem_en":"An asset portfolio’s expected return changes when return correlation falls from 0.8 to 0.1, holding weights and each asset’s expected return constant. The change is:","options":["Zero","Positive","Negative"],"correct":0,"why_vi":"E(Rp)=Σwμ không phụ thuộc correlation, do đó không thay đổi.","trap_vi":""},{"stem_en":"For a two-asset portfolio, which cross term is correct when covariance is directly given?","options":["wAwBCovAB","2wAwBCovAB","2wAwB/CovAB"],"correct":1,"why_vi":"Var(Rp) có CovAB và CovBA nên cross term bằng 2wAwBCovAB.","trap_vi":""}],"cards":[{"front_en":"What is the portfolio weight of Asset i?","back_vi":"wᵢ=MVᵢ/ΣMV; market value thay vì số cổ phiếu."},{"front_en":"What determines portfolio expected return?","back_vi":"Weighted average of constituent expected returns, E(Rp)=ΣwiE(Ri); correlation không tham gia."},{"front_en":"What three components drive two-asset portfolio variance?","back_vi":"Hai variance terms và một covariance cross term có hệ số 2."},{"front_en":"What does negative covariance of asset returns suggest?","back_vi":"Khi một return lệch phía trên mean thì return kia thường lệch phía dưới mean (inverse linear co-movement)."},{"front_en":"What is covariance of an asset with itself?","back_vi":"Cov(R,R)=Var(R)."},{"front_en":"What are the units and range of covariance?","back_vi":"Đơn vị return²; không bị giới hạn trong [−1,1]."},{"front_en":"What is the range of correlation?","back_vi":"−1 ≤ρ≤1, không có đơn vị; cần σAσB>0."},{"front_en":"How are covariance and correlation linked?","back_vi":"CovAB=ρABσAσB."},{"front_en":"What formula gives two-asset portfolio variance?","back_vi":"wA²σA²+wB²σB²+2wAwBρABσAσB."},{"front_en":"What is the result when correlation is +1 for a long-only portfolio?","back_vi":"σp=wAσA+wBσB; không hưởng diversification benefit về volatility."},{"front_en":"When can two perfectly negatively correlated assets produce zero portfolio SD?","back_vi":"Khi wAσA=wBσB, với long-only weights."},{"front_en":"What is the no-risk weight of A when ρ=−1?","back_vi":"wA=σB/(σA+σB)."},{"front_en":"What is the historical sample covariance denominator?","back_vi":"n−1, với n quan sát cặp và mean ước lượng từ cùng sample."},{"front_en":"What is the probability-based covariance denominator?","back_vi":"Không chia n−1; tính Σpₛ(RA,s−μA)(RB,s−μB)."},{"front_en":"What lies on the covariance matrix diagonal?","back_vi":"Variances của từng assets."},{"front_en":"How many unique covariances exist among n distinct assets?","back_vi":"n(n−1)/2, không tính diagonal variances."},{"front_en":"Does zero correlation guarantee the returns are independent?","back_vi":"Không. Independence thường hàm ý zero covariance (finite moments), chiều đảo không tổng quát."},{"front_en":"What does w-transpose Sigma w represent?","back_vi":"Portfolio variance for n assets, wᵀΣw."},{"front_en":"How does variance scale when returns are displayed as decimal versus percent?","back_vi":"Phương sai theo percentage-point units lớn gấp 10,000 so với decimal-return²."}]},{"id":"CFA26-01-05-LOS02","letter":"5.b","title_en":"Covariance and Correlation from a Joint Probability Function","outcome_en":"Calculate and interpret the covariance and correlation of portfolio returns using a joint probability function for returns.","overview_vi":"Joint probability function gắn xác suất cho từng cặp return (RA,RB), cho phép tính marginal expected return/variance của từng asset, cross-product expected value, covariance và correlation. Phải phân biệt xác suất joint, marginal và conditional, tính mọi ô một lần, kiểm tra tổng xác suất và không suy ra độc lập chỉ từ bảng có nhiều trạng thái.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM5","pages":"169–172 (physical PDF; joint probability and independence)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 5","pages":"70–71 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 5","pages":"225–228 (physical PDF; LOS 5.b). Prerequisite probability slides pp229–245 are separate."}],"sections":[{"heading":"1. Meaning of a joint return probability","body":"Joint probability function P(RA=a,RB=b) mô tả xác suất xảy ra đồng thời return a của tài sản A và b của tài sản B. Một bảng hai chiều có hàng là các outcomes của A, cột là các outcomes của B và từng ô là probability của cặp. Nếu đề cho danh sách các states kinh tế, mỗi state kèm RA, RB và pₛ, đó là một dạng joint distribution được liệt kê bằng dòng.","trap":""},{"heading":"2. Validate the state space before calculating","body":"Các cells (hay states có cặp return riêng biệt) phải mutually exclusive và jointly exhaustive; mọi p≥0 và tổng tất cả p=1. Không giả định các ô có xác suất bằng nhau trừ khi đề chỉ rõ. Nếu bảng thiếu một ô và đề nói tất cả các outcomes đều đã liệt kê, ô thiếu có thể bằng 1 trừ tổng các ô còn lại; không tự điền nếu chưa đủ điều kiện.","trap":""},{"heading":"3. Marginal distribution of Asset A","body":"Để tính P(RA=aᵢ), cộng mọi joint probabilities trong hàng có RA=aᵢ: pA,i=Σⱼpij. Tương tự P(RB=bⱼ)=Σᵢpij ở cột. Tổng row marginals và column marginals đều phải bằng 1. Không được nhầm marginal với conditional: marginal không điều kiện vào giá trị của tài sản kia.","trap":""},{"heading":"4. Compute each asset expected return from marginals","body":"μA=Σᵢ pA,i aᵢ=ΣᵢΣⱼ pij aᵢ; μB=Σⱼ pB,j bⱼ=ΣᵢΣⱼ pij bⱼ. Nếu mô hình là danh sách paired states, lấy pₛ nhân RA,s hoặc RB,s rồi cộng. Hai cách phải khớp; đó là test toàn vẹn bảng quan trọng trước khi làm covariance.","trap":""},{"heading":"5. Compute each marginal variance and SD","body":"σA²=ΣᵢpA,i(aᵢ−μA)²; σB²=ΣⱼpB,j(bⱼ−μB)², hoặc dùng E(RA²)−μA² và tương tự cho B. Căn bậc hai của variances cho σA,σB. Dùng decimal return nhất quán, không chia số states hay n−1 vì đây là phân phối xác suất đã cho.","trap":""},{"heading":"6. Direct covariance method: deviation cross-products","body":"CovAB=ΣᵢΣⱼpij(aᵢ−μA)(bⱼ−μB). Để làm nhanh, tạo cột RA−μA, RB−μB, nhân, nhân p, rồi cộng. Một cell có deviations trái dấu đóng góp âm; nhưng covariance tổng có thể dương hoặc âm tùy xác suất và mức độ lớn của mọi cells.","trap":""},{"heading":"7. Covariance shortcut using E(RARB)","body":"CovAB=E(RARB)−μAμB, trong đó E(RARB)=ΣᵢΣⱼpij aᵢbⱼ. Tính bằng các tích paired returns từng cell trước, sau đó trừ sản phẩm hai means. Không được thay E(RARB) bằng E(RA)E(RB) trừ khi covariance thực sự bằng 0 (như trường hợp independence được thiết lập).","trap":""},{"heading":"8. Convert covariance to correlation","body":"Khi σA>0 và σB>0, ρAB=CovAB/(σAσB). Check −1≤ρ≤1; nếu tính ra 1.3 hoặc −1.2, có lỗi dữ liệu/đơn vị/phép tính (hoặc covariance matrix không hợp lệ). Covariance dương và σ dương cho correlation dương, âm cho âm. Correlation giúp so sánh mức độ co-movement giữa các cặp tài sản với volatility khác nhau.","trap":""},{"heading":"9. Probability of an event conditional on another","body":"Ví dụ P(RB=high | RA=high)=P(RA=high,RB=high)/P(RA=high), với denominator >0. Điều này KHÁC với joint probability ở numerator. Các conditional probabilities theo các outcome của RB, với cùng RA được cho, phải cộng bằng 1.","trap":""},{"heading":"10. Independence is a stronger condition than zero covariance","body":"Hai return variables độc lập khi pij=pA,i pB,j cho mọi pair (i,j) có trong không gian mẫu, không chỉ một ô. Khi độc lập và moments tồn tại, E(RARB)=μAμB và CovAB=0; zero correlation (khi SD>0) theo đó cũng bằng 0. Nhưng covariance=0 không phải bằng chứng độc lập tổng quát đối với quan hệ nonlinear.","trap":""},{"heading":"11. Portfolio risk from the joint distribution","body":"Khi đã tính μA, μB, σA², σB² và CovAB từ joint table, áp dụng Var(Rp)=wA²σA²+wB²σB²+2wAwBCovAB. Hoặc với mỗi joint cell tính Rp,ij=wAaᵢ+wBbⱼ rồi trực tiếp lấy variance của portfolio outcomes; cả hai cách phải cho cùng kết quả. Đây là kiểm tra rất tốt khi joint table chỉ có 3–4 states.","trap":""},{"heading":"12. Relationship to scenario analysis in Module 4","body":"Module 4 tính expected values/probability trees từ một hoặc nhiều biến ngẫu nhiên; Module 5 mở rộng sang hai dòng return cùng xuất hiện. Nếu A/B returns là hàm của cùng macro state, phải giữ cặp return theo state. Không trộn return A của trạng thái boom với return B của trạng thái recession và vẫn gán xác suất state đó, vì sẽ phá mối quan hệ giữa biến.","trap":""},{"heading":"13. How to read a joint table with repeated return levels","body":"Nếu nhiều states cho cùng RA và cùng RB, gộp xác suất của các states vào ô chung; không gộp số returns bằng phép trung bình không trọng số. Nếu đề chỉ cho marginal distributions của A và B mà không cho independence, không đủ thông tin để xác định covariance—vì joint distribution chưa được nhận diện.","trap":""},{"heading":"14. Interpreting negative versus positive covariance","body":"Covariance dương có nghĩa deviations có xu hướng cùng dấu hơn mức ngược dấu theo trọng số; không đảm bảo hai asset cùng tăng ở mọi state. Covariance âm thường hỗ trợ diversification cho long-only positions. Để đánh giá rủi ro danh mục vẫn cần thêm weights và asset variances, không chỉ dấu covariance.","trap":""},{"heading":"15. End-to-end joint-probability exam workflow","body":"Bước 1: sum cell probabilities. Bước 2: marginal sums. Bước 3: μA, μB. Bước 4: σA², σB² (và căn). Bước 5: E(RARB) hoặc deviations cross-products để tìm Cov. Bước 6: ρ=Cov/(σAσB). Bước 7 (nếu có portfolio): dùng weights để tìm mean, variance, SD. Bước 8: kiểm tra ρ∈[−1,1], variance≥0 và mean nằm trong range return.","trap":""}],"formulas":[{"name":"Joint probabilities normalization","expr":"pᵢⱼ=P(RA=aᵢ,RB=bⱼ); ΣᵢΣⱼpᵢⱼ=1","meaning":"Tổng xác suất các cặp phải bằng 1.","conditions":"Mutually exclusive, exhaustive cells."},{"name":"Marginal probability of A","expr":"P(RA=aᵢ)=Σⱼpᵢⱼ","meaning":"Cộng theo hàng A.","conditions":"Mọi p≥0."},{"name":"Marginal probability of B","expr":"P(RB=bⱼ)=Σᵢpᵢⱼ","meaning":"Cộng theo cột B.","conditions":""},{"name":"Expected returns from joint function","expr":"μA=ΣᵢΣⱼpᵢⱼaᵢ; μB=ΣᵢΣⱼpᵢⱼbⱼ","meaning":"Means của hai asset theo joint distribution.","conditions":""},{"name":"Marginal variances from joint function","expr":"σA²=ΣᵢΣⱼpᵢⱼ(aᵢ−μA)²; σB²=ΣᵢΣⱼpᵢⱼ(bⱼ−μB)²","meaning":"Tính σA,σB để scale covariance thành correlation.","conditions":""},{"name":"Joint covariance (deviations)","expr":"CovAB=ΣᵢΣⱼpᵢⱼ(aᵢ−μA)(bⱼ−μB)","meaning":"Probability-weighted deviations cross-products.","conditions":""},{"name":"Joint covariance (product shortcut)","expr":"CovAB=ΣᵢΣⱼpᵢⱼaᵢbⱼ−μAμB","meaning":"Dùng E(RARB)−E(RA)E(RB).","conditions":""},{"name":"Correlation from joint function","expr":"ρAB=CovAB/(σAσB)","meaning":"Đo quan hệ tuyến tính chuẩn hóa.","conditions":"σA,σB>0."},{"name":"Conditional probability within a joint distribution","expr":"P(Bⱼ | Aᵢ)=pᵢⱼ / P(Aᵢ)","meaning":"Conditional khác joint probability.","conditions":"P(Aᵢ)>0."},{"name":"Independence test","expr":"RA ⫫ RB ⇔ pᵢⱼ=P(Aᵢ)P(Bⱼ) for every i,j","meaning":"Independence đủ để suy ra zero covariance khi hữu hạn moments.","conditions":"Phải kiểm tra toàn bộ cells."},{"name":"Direct joint portfolio-return variance","expr":"Var(Rp)=ΣᵢΣⱼpᵢⱼ[wAaᵢ+wBbⱼ−E(Rp)]²","meaning":"Đối chiếu variance từ covariance formula.","conditions":"Weights cố định, đúng pairing theo từng cell."}],"examples":[{"question_en":"Joint probabilities for A (low/high) and B (low/high) are 0.25, 0.15, 0.20, and 0.40 in row-major order. Calculate the two A marginal probabilities.","steps_vi":["Row A low: 0.25+0.15=0.40.","Row A high: 0.20+0.40=0.60."],"answer":"P(A low)=0.40; P(A high)=0.60.","check":""},{"question_en":"For the same joint table, calculate the two B marginal probabilities.","steps_vi":["Column B low: 0.25+0.20=0.45.","Column B high: 0.15+0.40=0.55."],"answer":"P(B low)=0.45; P(B high)=0.55.","check":""},{"question_en":"In the joint table, A returns are −10% and +20%, and B returns are −5% and +15%. Calculate each expected return.","steps_vi":["For A: μA=0.40(−0.10)+0.60(0.20)=0.08.","For B: μB=0.45(−0.05)+0.55(0.15)=0.06."],"answer":"E(RA)=8.00%; E(RB)=6.00%.","check":""},{"question_en":"Using the same joint distribution, calculate E(RA RB).","steps_vi":["Pair by cell (A low, B low): 0.25(−0.10)(−0.05)=0.00125.","A low/B high: 0.15(−0.10)(0.15)=−0.00225.","A high/B low: 0.20(0.20)(−0.05)=−0.00200.","A high/B high: 0.40(0.20)(0.15)=0.01200.","Sum=0.00900."],"answer":"E(RA RB)=0.0090.","check":""},{"question_en":"Calculate the covariance of A and B in the preceding joint distribution.","steps_vi":["Cov=E(RARB)−μAμB=0.00900−(0.08)(0.06).","=0.00900−0.00480=0.00420."],"answer":"CovAB=+0.00420 (decimal-return squared).","check":"Positive although there is also probability of opposite-sign returns."},{"question_en":"Calculate the variance of A using the joint distribution with P(A low)=0.4 and P(A high)=0.6.","steps_vi":["E(RA²)=0.4(−0.10)²+0.6(0.20)²=0.028.","VarA=0.028−(0.08)²=0.0216.","σA=sqrt(0.0216)≈0.14697."],"answer":"VarA=0.0216; σA≈14.70%.","check":""},{"question_en":"Calculate the variance of B in the joint distribution where B returns are −5% and +15% with probabilities 0.45 and 0.55.","steps_vi":["E(RB²)=0.45(−0.05)²+0.55(0.15)²=0.0135.","VarB=0.0135−(0.06)²=0.0099.","σB=sqrt(0.0099)≈0.09950."],"answer":"VarB=0.0099; σB≈9.95%.","check":""},{"question_en":"Given CovAB=0.0042, VarA=0.0216, and VarB=0.0099, calculate correlation.","steps_vi":["ρ=0.0042/[sqrt(0.0216)sqrt(0.0099)].","Denominator≈0.014624; ρ≈0.2872."],"answer":"ρAB≈+0.287.","check":"Within valid range [−1,1]."},{"question_en":"In the same joint distribution, calculate P(B high | A high).","steps_vi":["P(A high,B high)=0.40.","P(A high)=0.20+0.40=0.60.","P(B high | A high)=0.40/0.60."],"answer":"66.67%.","check":""},{"question_en":"In the same table, determine whether A and B are independent.","steps_vi":["P(A low)=0.40; P(B low)=0.45.","Under independence P(A low,B low) would be 0.40×0.45=0.18.","The actual joint probability of A low,B low is 0.25≠0.18."],"answer":"Not independent.","check":"One contradicted cell is sufficient to reject independence."},{"question_en":"Calculate portfolio variance for a 70% A / 30% B allocation using VarA=0.0216, VarB=0.0099 and CovAB=0.0042.","steps_vi":["Varp=0.7²(0.0216)+0.3²(0.0099)+2(0.7)(0.3)(0.0042).","=0.010584+0.000891+0.001764=0.013239.","σp=sqrt(0.013239)≈0.11506."],"answer":"Varp=0.013239; σp≈11.51%.","check":""},{"question_en":"A two-asset joint distribution has only three possible paired states: probability [0.25,0.50,0.25], A return [−10%,5%,20%], and B return [−5%,10%,25%]. Find correlation.","steps_vi":["E(A)=5%; E(B)=10%.","Both assets have deviations [−15%,0,+15%] relative to their own means.","CovAB=0.25(0.15²)+0.25(0.15²)=0.01125.","VarA=VarB=0.01125, so ρ=0.01125/0.01125=1."],"answer":"Correlation = +1.00.","check":"Different return levels do not prevent perfect linear co-movement."},{"question_en":"If P(A high)=0.60 and P(B high)=0.55 and returns are independent, calculate P(A high,B high).","steps_vi":["P(A high,B high)=P(A high)P(B high)=0.60×0.55."],"answer":"0.330 (33%).","check":"Valid only under independence assumption."},{"question_en":"For a joint table with probabilities 0.20, 0.35, 0.15, and one missing cell, what must the missing cell probability be if the four cells are exhaustive?","steps_vi":["Missing probability = 1−(0.20+0.35+0.15)=1−0.70."],"answer":"0.30.","check":""}],"questions":[{"stem_en":"A joint probability function for two asset returns describes the probability of:","options":["A particular return for A and a particular return for B occurring together","A return for A being greater than its historical mean only","One asset return occurring regardless of the other"],"correct":0,"why_vi":"Joint P(RA=a,RB=b) là probability của cặp outcome đồng thời.","trap_vi":""},{"stem_en":"A joint probability table lists four exhaustive states with probabilities 0.20, 0.30, 0.25, and an unknown value. The unknown value is:","options":["0.15","0.25","0.35"],"correct":1,"why_vi":"Missing p=1−(0.20+0.30+0.25)=0.25.","trap_vi":""},{"stem_en":"How is the marginal probability of a particular return for Asset A obtained from a joint probability table?","options":["Multiply all probabilities in its row","Divide the row probability by the column total","Sum joint probabilities across that row"],"correct":2,"why_vi":"Marginal distribution A được tính bằng cộng các joint probabilities có cùng return A.","trap_vi":""},{"stem_en":"A joint table gives P(A low,B low)=0.25 and P(A low,B high)=0.15. What is P(A low)?","options":["0.40","0.25","0.10"],"correct":0,"why_vi":"P(A low)=0.25+0.15=0.40.","trap_vi":""},{"stem_en":"If P(A high,B high)=0.40 and P(A high)=0.60, P(B high | A high) is closest to:","options":["40.0%","66.7%","60.0%"],"correct":1,"why_vi":"Conditional=0.40/0.60=2/3=66.7%.","trap_vi":""},{"stem_en":"For a valid joint probability function, which statement must hold?","options":["Each cell is equally likely","Every asset has the same expected return","The sum of all cells is 1"],"correct":2,"why_vi":"Mọi p≥0, sum joint outcomes=1; marginal distributions cũng cộng 1.","trap_vi":""},{"stem_en":"Which formula correctly computes joint-distribution covariance?","options":["Sum of probability-weighted products of each return’s deviations from its own mean","Sum of the unweighted two asset returns","Product of individual standard deviations without correlation"],"correct":0,"why_vi":"CovAB=Σpij(RA,i−μA)(RB,j−μB).","trap_vi":""},{"stem_en":"Which shortcut is equivalent to the deviation-based covariance formula?","options":["E(RA) + E(RB) − E(RARB)","E(RARB) − E(RA)E(RB)","E(RARB) + E(RA)E(RB)"],"correct":1,"why_vi":"Identity Cov(X,Y)=E(XY)−EX·EY.","trap_vi":""},{"stem_en":"If E(RARB)=0.009, E(RA)=8%, and E(RB)=6%, covariance equals:","options":["0.0138","0.0090","0.0042"],"correct":2,"why_vi":"Cov=0.009−0.08×0.06=0.0042.","trap_vi":""},{"stem_en":"From a joint function, VarA=0.0216, VarB=0.0099, and CovAB=0.0042. Correlation is closest to:","options":["0.287","0.420","0.750"],"correct":0,"why_vi":"ρ=0.0042/sqrt(0.0216×0.0099)≈0.287.","trap_vi":""},{"stem_en":"Asset returns A and B are independent. Provided their variances exist, covariance between returns is:","options":["Equal to +1","Zero","Equal to the difference between means"],"correct":1,"why_vi":"Independence ⇒ E(RARB)=E(RA)E(RB) ⇒ Cov=0.","trap_vi":""},{"stem_en":"Which property is sufficient to prove two discrete random variables are independent?","options":["Their sample mean returns are equal","Their covariance is nonnegative","For every cell, P(Ai,Bj)=P(Ai)P(Bj)"],"correct":2,"why_vi":"Independence cần factorization cho toàn bộ joint cells.","trap_vi":""},{"stem_en":"If the marginal probabilities are P(A high)=0.60 and P(B high)=0.55, independence implies P(A high,B high) of:","options":["0.33","0.55","0.60"],"correct":0,"why_vi":"0.60×0.55=0.33.","trap_vi":""},{"stem_en":"A joint table has P(A low,B low)=0.25, P(A low)=0.40, and P(B low)=0.45. Which conclusion is correct?","options":["The returns must be independent","The returns are not independent","The correlation must be exactly −1"],"correct":1,"why_vi":"Nếu independent, P(low,low)=0.4×0.45=0.18; thực tế .25 ⇒ not independent.","trap_vi":""},{"stem_en":"When converting the covariance from a joint probability function into correlation, the denominator is:","options":["The sum of variances","The product of expected returns","The product of the two standard deviations"],"correct":2,"why_vi":"ρ=Cov/(σAσB); phải tính σA,σB từ marginal return distribution.","trap_vi":""},{"stem_en":"The covariance calculated from a joint distribution is −0.003 and both asset standard deviations are positive. Correlation must be:","options":["Negative","Positive","Undefined in all cases"],"correct":0,"why_vi":"Denominator σAσB>0, nên dấu ρ trùng dấu Cov.","trap_vi":""},{"stem_en":"Which probability is a conditional probability rather than a joint probability?","options":["P(A high, B high)","P(B high | A high)","P(A high)"],"correct":1,"why_vi":"Conditional probability có ký hiệu | và denominator điều kiện.","trap_vi":""},{"stem_en":"The marginal distributions of two assets are known but their joint distribution is not. Without an independence assumption, what generally cannot be determined?","options":["Expected returns of each asset","Standard deviation of each asset","Covariance between asset returns"],"correct":2,"why_vi":"Covariance cần thông tin sự đồng xuất hiện của paired outcomes; marginals riêng chưa đủ.","trap_vi":""},{"stem_en":"A probability-based covariance calculation uses:","options":["Probability weights and no additional n−1 divisor","An n−1 divisor for all probability tables","A simple count of positive-return outcomes"],"correct":0,"why_vi":"Đây là population/model covariance; n−1 dành cho sample estimator.","trap_vi":""},{"stem_en":"An analyst calculates correlation as 1.24 from a valid return joint distribution with nonzero standard deviations. The result is:","options":["Evidence of perfect positive dependence","Mathematically impossible and indicates a computation or input problem","Proof that one asset is risk-free"],"correct":1,"why_vi":"Correlation phải thuộc [−1,+1] khi variance dương.","trap_vi":""},{"stem_en":"For two perfectly linearly related asset returns with the same direction, the correlation is:","options":["0","−1","+1"],"correct":2,"why_vi":"Perfect positive linear relation ⇒ρ=+1 nếu SD>0.","trap_vi":""}],"cards":[{"front_en":"What does P(RA=a,RB=b) represent?","back_vi":"Probability cho hai return outcomes đồng thời, không phải conditional probability."},{"front_en":"What must the sum of all joint probabilities equal?","back_vi":"1; mọi probability phải không âm."},{"front_en":"How to calculate an Asset A marginal probability?","back_vi":"Cộng xác suất các ô cùng hàng/outcome A."},{"front_en":"How to calculate an Asset B marginal probability?","back_vi":"Cộng xác suất các ô cùng cột/outcome B."},{"front_en":"How to calculate E(RA) from a joint probability table?","back_vi":"Σij pij RA,i, hoặc trước tiên tính marginal distribution của A."},{"front_en":"How to calculate Var(RA) from a joint probability table?","back_vi":"Σij pij(RA,i−μA)² hoặc E(RA²)−μA²."},{"front_en":"What is the joint covariance definition?","back_vi":"Σij pij(RA,i−μA)(RB,j−μB)."},{"front_en":"What is the product-moment covariance shortcut?","back_vi":"CovAB=E(RARB)−E(RA)E(RB)."},{"front_en":"How to calculate correlation after joint covariance?","back_vi":"ρAB=CovAB/(σAσB), với cả hai σ dương."},{"front_en":"What is P(B high | A high)?","back_vi":"P(A high,B high)/P(A high); cần P(A high)>0."},{"front_en":"How can independence be tested from a discrete joint table?","back_vi":"Kiểm tra pij=pA,i×pB,j cho MỌI cell."},{"front_en":"Does independence imply zero covariance?","back_vi":"Có, khi relevant expectations/variances hữu hạn."},{"front_en":"Does zero covariance imply independence?","back_vi":"Không trong trường hợp tổng quát; có thể tồn tại quan hệ phi tuyến."},{"front_en":"What is missing if only two marginal return distributions are known?","back_vi":"Joint pairing/co-movement, cần để xác định covariance (trừ khi có giả định bổ sung như independence)."},{"front_en":"How to cross-check a computed portfolio variance from a joint table?","back_vi":"Tính trực tiếp return của portfolio tại mỗi cell rồi probability-weighted variance; phải bằng covariance formula."},{"front_en":"Why does a correlation outside [−1,1] indicate an error?","back_vi":"Không thể xảy ra với covariance/variance nhất quán của một valid joint distribution."}]},{"id":"CFA26-01-05-LOS03","letter":"5.c","title_en":"Shortfall Risk and Roy’s Safety-First Criterion","outcome_en":"Define shortfall risk, calculate the safety-first ratio, and identify an optimal portfolio using Roy’s safety-first criterion.","overview_vi":"Roy’s safety-first criterion tập trung vào nguy cơ return hoặc ending wealth thấp hơn ngưỡng tối thiểu RL trong một horizon. Học cách chuyển mức tài sản cuối kỳ thành threshold return, tính (E(Rp)−RL)/σp, so sánh các portfolios, diễn giải xác suất shortfall bằng normal CDF khi có giả định normal distribution, và nhận diện giới hạn của mô hình.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM5","pages":"173–178 (physical PDF; shortfall risk, normal-distribution application and Roy criterion)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 5","pages":"71–74 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 5","pages":"246–248 (physical PDF; normal-distribution prerequisites are pp239–245, separate from core LOS 5.c)"}],"sections":[{"heading":"1. Shortfall risk identifies a downside event relative to a target","body":"Shortfall risk là xác suất portfolio return hoặc portfolio ending value thấp hơn mức tối thiểu mà nhà đầu tư muốn đạt trong kỳ. Sự kiện cần tính thường là P(Rp<RL), trong đó RL là threshold/minimum acceptable return. Nếu mục tiêu của người học là không mất vốn danh nghĩa, RL=0%; nếu phải tăng vốn tối thiểu 3% để đáp ứng nghĩa vụ, RL=3%.","trap":"Không đánh đồng shortfall với SD: SD là dispersion hai phía, shortfall là xác suất vùng dưới ngưỡng."},{"heading":"2. Translate a dollar target into a threshold return","body":"Nếu portfolio start value V0 và minimum ending value Vmin, RL=(Vmin−V0)/V0, với cùng horizon và chưa xét external cash flows; V0=USD 200,000, Vmin=USD 210,000 ⇒ RL=5%. Không so trực tiếp Vmin bằng USD với expected return bằng %. Nếu mục tiêu là bảo toàn principal 100%, RL thường 0% nominal, không mặc nhiên bằng risk-free rate.","trap":""},{"heading":"3. The role of expected return and standard deviation","body":"Roy’s safety-first ratio SF=(μp−RL)/σp (σp>0). Tử số là khoảng cách giữa expected return và minimum acceptable return; mẫu số scale khoảng cách theo standard deviation. SF là số standard deviations mà mean nằm trên ngưỡng. Giá trị SF lớn có nghĩa threshold nằm xa mean hơn theo volatility scale, tốt hơn trong khung normal-return comparison.","trap":""},{"heading":"4. Calculating and ranking multiple candidate portfolios","body":"Khi các portfolios có returns cùng thời hạn và threshold RL chung, tính SF riêng cho từng portfolio. Roy chọn portfolio có safety-first ratio LỚN NHẤT. Đừng chọn danh mục chỉ vì mean lớn nhất hoặc SD nhỏ nhất; phải nhìn đồng thời mean−threshold và SD. Ví dụ A: μ12%,σ18%, RL0% ⇒SF=.667; B: μ10%,σ12% ⇒.833: B được ưa thích.","trap":""},{"heading":"5. Normal-return standardization to a shortfall probability","body":"Nếu Rp∼N(μp,σp²) với σp>0, Z=(Rp−μp)/σp và P(Rp<RL)=Φ((RL−μp)/σp)=Φ(−SF). Vì Φ là hàm phân phối tích lũy tăng, maximizing SF tương đương minimizing P(Rp<RL) trong nhóm normal portfolios. Nếu SF=0.50, shortfall≈Φ(−0.5)=30.85%; SF càng lớn ⇒ xác suất shortfall càng nhỏ.","trap":"Không lấy Φ(+SF) rồi gọi đó là shortfall."},{"heading":"6. A negative safety-first ratio is meaningful","body":"Khi μp<RL, tử số âm ⇒ SF<0. Nếu returns normal, shortfall probability >50%; ví dụ μ2%, RL5%, σ10% ⇒SF=−0.30, P(shortfall)=Φ(+0.30)≈61.79%. SF âm không làm công thức vô hiệu; nó cho biết ngưỡng nằm phía trên mean.","trap":""},{"heading":"7. A ratio of zero","body":"Khi μp=RL và σp>0, SF=0; với normal returns, half the distribution nằm dưới ngưỡng, nên P(shortfall)=50%. Đây là tính chất của symmetric normal distribution, không phải bất cứ return distribution nào cũng có median bằng mean.","trap":""},{"heading":"8. Distinguish Roy’s safety-first ratio from the Sharpe ratio","body":"Sharpe ratio=(μp−Rf)/σp và Roy’s SF=(μp−RL)/σp. Khi threshold RL=Rf và cùng SD/horizon, chúng có cùng giá trị số; ngữ nghĩa khác: Sharpe đo expected excess return per total risk còn safety-first đánh giá mức độ bảo vệ ngưỡng tối thiểu. Nếu RL=0% hoặc investor-specific goal, thường không bằng risk-free rate.","trap":""},{"heading":"9. Normality assumption is critical to exact probability ordering","body":"Nếu portfolio returns không normal, SF vẫn là descriptive standardized distance, nhưng P(Rp<RL)=Φ(−SF) KHÔNG còn là exact relation. Hai portfolios với cùng mean và variance vẫn có thể có tail risk khác nhau do skewness, kurtosis và distributions khác. Khi bài hỏi “probability of shortfall” từ SF, phải có giả định normality (hoặc distribution function khác được cho).","trap":"Không trình bày safety-first ratio như xác suất chắc chắn chống lỗ."},{"heading":"10. Target return and risk horizon must match","body":"RL, expected return μp và standard deviation σp phải thuộc cùng time horizon. Không dùng annual μ với monthly σ và một ngưỡng 6-month. Khi chuyển σ qua horizon thường cần assumptions riêng về return independence và distribution; bài toán Level I này không cấp quyền annualize tùy tiện chỉ vì có số liệu tháng.","trap":""},{"heading":"11. Compare portfolios when thresholds are different","body":"Roy’s rule thường giả định một investor xác định cùng một RL đối với các portfolios. Nếu mỗi portfolio được gắn một threshold khác nhau, SF có thể tính nhưng không còn phép so sánh cùng mục tiêu; phải làm rõ mục tiêu đầu tư. Cũng cần lưu ý inflation, liability target và currency nếu yêu cầu threshold real versus nominal.","trap":""},{"heading":"12. Risk-free or deterministic zero-volatility case","body":"Nếu σp=0, SF formula chia cho zero nên không xác định. Khi return cố định r, shortfall probability trực tiếp bằng 1 nếu r<RL và bằng 0 nếu r≥RL đối với sự kiện strict R<RL. Không được cho SF=∞ rồi so vô điều kiện nếu không nói rõ behavior của deterministic return.","trap":""},{"heading":"13. Why shortfall probability differs from expected shortfall","body":"Shortfall risk P(R<RL) chỉ là xác suất rơi dưới ngưỡng, không đo mức lỗ trung bình một khi bị shortfall. Hai portfolio có shortfall probability bằng nhau nhưng mức lỗ khi xảy ra có thể rất khác nhau. Expected shortfall (tail conditional expectation) là khái niệm khác; không trộn vào formula SF ở LOS này.","trap":""},{"heading":"14. A large ratio is not a guarantee","body":"SF cao làm xác suất dưới threshold thấp hơn trong normal model nhưng không bảo đảm outcome tốt trong từng năm. Model forecasts μ,σ có estimation error; các tài sản có thể bị fat tails, liquidity crises, regime changes. Khi trả lời câu hỏi “optimal” theo Roy criterion, phải ghi “optimal according to the stated criterion/assumptions”, không tuyên bố tối ưu cho mọi utility function.","trap":""},{"heading":"15. Compute target amount from a given threshold","body":"Nếu portfolio beginning value V0 và RL mong muốn, mục tiêu ending value Vmin=V0(1+RL). Ví dụ V0=USD 1,000,000 và RL=4% ⇒Vmin=USD 1,040,000. Cần xác định thời điểm dòng tiền và consistency of valuations; ví dụ này giả định không có cash flows ngoài.","trap":""},{"heading":"16. Full exam workflow for Roy’s criterion","body":"Bước 1: xác nhận cùng horizon và return units. Bước 2: nếu mục tiêu bằng tiền, tính RL=(target/start)−1. Bước 3: SFk=(μk−RL)/σk cho từng candidate (σk>0). Bước 4: chọn SFk cao nhất. Bước 5: chỉ khi normality được nêu, tính P(shortfall)=Φ(−SFk) và báo % đúng phía đuôi trái. Bước 6: diễn giải về xác suất underperform threshold, không phải absolute expected loss.","trap":""}],"formulas":[{"name":"Shortfall event","expr":"Shortfall = {Rₚ < Rᴸ}; shortfall risk = P(Rₚ < Rᴸ)","meaning":"Xác suất không đạt return tối thiểu.","conditions":"Nếu đề định nghĩa ≤ thay vì <, dùng đúng sự kiện; continuous case bằng nhau."},{"name":"Threshold return from ending value","expr":"Rᴸ = (Vmin / V0) − 1","meaning":"Chuyển target wealth sang return.","conditions":"No external cash flows; V0>0, same horizon/currency."},{"name":"Minimum ending wealth","expr":"Vmin=V0(1+Rᴸ)","meaning":"Chuyển threshold return sang dollar goal.","conditions":"Same horizon."},{"name":"Roy safety-first ratio","expr":"SFₚ = [E(Rₚ) − Rᴸ] / σₚ","meaning":"Khoảng cách của expected return phía trên threshold, theo SD.","conditions":"σₚ>0; μ,RL,σ cùng đơn vị/horizon."},{"name":"Normal return standardized threshold","expr":"zᴸ = (Rᴸ−E(Rₚ))/σₚ = −SFₚ","meaning":"Ngưỡng chuẩn hóa dùng z-table.","conditions":"Normal model nếu dùng để suy ra probability."},{"name":"Normal shortfall probability","expr":"P(Rₚ<Rᴸ) = Φ(−SFₚ)","meaning":"Left-tail normal probability.","conditions":"Rₚ normal, σₚ>0."},{"name":"Roy optimal choice","expr":"p* = arg maxₚ SFₚ","meaning":"Trong normal candidates, SF lớn nhất cho lowest modeled shortfall probability.","conditions":"Common RL, compatible horizon, σp>0."},{"name":"Sharpe-special-case relation","expr":"If Rᴸ=Rƒ, then SFₚ=(E(Rₚ)−Rƒ)/σₚ=Sharpe ratio","meaning":"Coincide numerically only for threshold equal to risk-free rate.","conditions":"Same return type/horizon/total volatility."},{"name":"Deterministic shortfall risk","expr":"If σₚ=0: P(Rₚ<Rᴸ)=1 when fixed Rₚ<Rᴸ; otherwise 0","meaning":"Không chia 0 để tính safety-first ratio.","conditions":"Return deterministic."}],"examples":[{"question_en":"An investor starts with USD 200,000 and requires at least USD 210,000 at year-end. Calculate the minimum acceptable return.","steps_vi":["RL=(210,000/200,000)−1=1.05−1."],"answer":"5.00%.","check":""},{"question_en":"A portfolio has an expected return of 12%, standard deviation 18%, and minimum acceptable return of 0%. Calculate the safety-first ratio.","steps_vi":["SF=(0.12−0.00)/0.18."],"answer":"0.6667.","check":""},{"question_en":"Portfolio B has expected return 10% and standard deviation 12%. With a 0% threshold, compare its safety-first ratio to Portfolio A (12% expected return, 18% volatility).","steps_vi":["SFA=0.12/0.18=0.6667.","SFB=0.10/0.12=0.8333.","Since 0.8333>0.6667, choose Portfolio B under Roy."],"answer":"Portfolio B has the larger safety-first ratio.","check":""},{"question_en":"Under normally distributed returns, a portfolio has safety-first ratio 0.50. Estimate the shortfall probability.","steps_vi":["z_threshold=−SF=−0.50.","Normal CDF Φ(−0.50)≈0.308538."],"answer":"30.85%.","check":""},{"question_en":"Expected return is 2%, minimum return 5%, and standard deviation 10%. Calculate the safety-first ratio and normal shortfall probability.","steps_vi":["SF=(0.02−0.05)/0.10=−0.30.","z_threshold=+0.30.","Φ(0.30)≈0.617911."],"answer":"SF=−0.30; P(shortfall)≈61.79%.","check":""},{"question_en":"Three portfolios have (expected return, SD): A (12%,16%), B (10%,10%), C (15%,22%). For a 4% threshold, which is preferred under Roy?","steps_vi":["SFA=(.12−.04)/.16=0.500.","SFB=(.10−.04)/.10=0.600.","SFC=(.15−.04)/.22=0.500.","Largest safety-first ratio is B."],"answer":"Portfolio B.","check":""},{"question_en":"A portfolio return is normally distributed with expected return 12%, standard deviation 10%, and threshold 8%. Calculate the shortfall probability.","steps_vi":["SF=(.12−.08)/.10=.40.","P(shortfall)=Φ(−0.4)=0.344578."],"answer":"≈34.46%.","check":""},{"question_en":"A USD 1,000,000 account must finish the year at no less than USD 1,040,000. Calculate the target return and target wealth from either input.","steps_vi":["RL=(1,040,000/1,000,000)−1=.04.","Vmin=1,000,000(1+.04)=1,040,000."],"answer":"RL=4%; required end value = USD 1,040,000.","check":""},{"question_en":"A portfolio has expected return equal to a 6% threshold and normally distributed returns with 12% volatility. What is the shortfall probability?","steps_vi":["SF=(.06−.06)/.12=0.","Φ(0)=0.5."],"answer":"50.00%.","check":""},{"question_en":"An investor’s minimum acceptable return is the risk-free rate of 3%. A portfolio has expected return 9% and standard deviation 15%. Calculate both Roy and Sharpe ratios.","steps_vi":["Both ratios use the same threshold Rf=RL=3%.","(0.09−0.03)/0.15=0.4."],"answer":"Both ratios = 0.40.","check":""},{"question_en":"Portfolio X has expected return 11%, volatility 20%, and a 5% return threshold. Portfolio Y has expected return 10%, volatility 10%, and the same threshold. Choose under Roy.","steps_vi":["SFX=(.11−.05)/.20=0.30.","SFY=(.10−.05)/.10=0.50.","Y has greater standardized distance from threshold."],"answer":"Portfolio Y.","check":""},{"question_en":"A portfolio earns a deterministic 4% return, and the threshold is 3%. What is the shortfall probability?","steps_vi":["Return is always 4%, which is above 3%.","σ=0, so the safety-first ratio is undefined by division; calculate the event directly."],"answer":"P(R<3%)=0.","check":""},{"question_en":"A deterministic return is 2% while a minimum acceptable threshold is 3%. What is the shortfall probability?","steps_vi":["2% is always less than 3%.","No uncertainty: shortfall event occurs with probability 1."],"answer":"100% (Roy ratio undefined because σ=0).","check":""},{"question_en":"A normally distributed portfolio has E(R)=7%, σ=10%, and a threshold of 2%. Calculate Roy’s ratio and shortfall probability.","steps_vi":["SF=(.07−.02)/.10=0.50.","P(shortfall)=Φ(−0.50)=0.308538."],"answer":"SF=0.50; P(shortfall)≈30.85%.","check":""}],"questions":[{"stem_en":"Shortfall risk is best defined as the probability that a portfolio return:","options":["Falls below a specified minimum acceptable return","Falls below its expected return by exactly one standard deviation","Exceeds a specified target return"],"correct":0,"why_vi":"Shortfall risk = P(Rp<RL) với ngưỡng RL do nhà đầu tư xác định.","trap_vi":""},{"stem_en":"An investment starts at USD 500,000 and must be worth at least USD 520,000 in one year. Its threshold return is:","options":["2.00%","4.00%","5.00%"],"correct":1,"why_vi":"RL=(520,000−500,000)/500,000=4%.","trap_vi":""},{"stem_en":"Which formula represents Roy’s safety-first ratio when portfolio return volatility is nonzero?","options":["[RL−E(Rp)]/σp","[E(Rp)+RL]/σp","[E(Rp)−RL]/σp"],"correct":2,"why_vi":"SF=(expected return−threshold)/standard deviation.","trap_vi":""},{"stem_en":"Under Roy’s safety-first criterion and a common minimum acceptable return, the optimal portfolio is the one with:","options":["The highest safety-first ratio","The highest expected return without regard to risk","The lowest expected return"],"correct":0,"why_vi":"Chọn maximum SF; nếu normal, đồng nghĩa minimize modeled shortfall probability.","trap_vi":""},{"stem_en":"With expected return 12%, volatility 18%, and a zero minimum acceptable return, a portfolio’s safety-first ratio is closest to:","options":["0.50","0.67","1.50"],"correct":1,"why_vi":"SF=0.12/0.18≈0.6667.","trap_vi":""},{"stem_en":"Portfolio A has μ=12% and σ=18%; Portfolio B has μ=10% and σ=12%. For a zero return threshold, Roy prefers:","options":["A because it has higher expected return","Both equally","B because its safety-first ratio is larger"],"correct":2,"why_vi":"SFA=.667, SFB=.833 ⇒ chọn B.","trap_vi":""},{"stem_en":"Assuming normally distributed portfolio returns, shortfall probability is computed as:","options":["Φ(−safety-first ratio)","Φ(+safety-first ratio)","1 minus portfolio expected return"],"correct":0,"why_vi":"Chuẩn hóa threshold: z=(RL−μ)/σ=−SF; left-tail probability=Φ(z).","trap_vi":""},{"stem_en":"A normally distributed portfolio has a safety-first ratio of 0.50. Its shortfall probability is closest to:","options":["69.15%","30.85%","50.00%"],"correct":1,"why_vi":"Φ(−0.5)=0.3085.","trap_vi":""},{"stem_en":"A portfolio has mean return 2%, threshold return 5%, and volatility 10%. The safety-first ratio is:","options":["+0.30","+0.70","−0.30"],"correct":2,"why_vi":"SF=(.02−.05)/.10=−0.30.","trap_vi":""},{"stem_en":"If expected return is below the threshold and returns are normally distributed, the shortfall probability is:","options":["Greater than 50%","Always exactly 50%","Always below 10%"],"correct":0,"why_vi":"μ<RL ⇒ SF<0 ⇒ z=−SF>0 ⇒Φ(z)>0.5.","trap_vi":""},{"stem_en":"If E(Rp)=RL and portfolio returns are normally distributed with positive standard deviation, shortfall probability is:","options":["0%","50%","100%"],"correct":1,"why_vi":"SF=0, z=0, Φ(0)=0.5.","trap_vi":""},{"stem_en":"Roy’s safety-first ratio is numerically identical to the Sharpe ratio when:","options":["The threshold return is zero","The threshold equals portfolio expected return","The threshold is the risk-free rate"],"correct":2,"why_vi":"Với RL=Rf và cùng volatility, numerator giống nhau.","trap_vi":""},{"stem_en":"A portfolio has μ=9%, σ=15%, and a minimum acceptable return equal to a 3% risk-free rate. Its Roy safety-first ratio is:","options":["0.40","0.60","3.00"],"correct":0,"why_vi":"SF=(.09−.03)/.15=.40.","trap_vi":""},{"stem_en":"Which condition is needed to calculate shortfall probability exactly as Φ(−SF)?","options":["Every portfolio has zero covariance","Portfolio return follows a normal distribution","All assets have the same expected return"],"correct":1,"why_vi":"Normality là giả định quan trọng để dùng standard normal CDF cho tail probability.","trap_vi":""},{"stem_en":"Two portfolios have identical means and standard deviations but different, non-normal return distributions. Their actual shortfall probabilities:","options":["Must always be equal","Must both be 50%","May differ"],"correct":2,"why_vi":"SF chỉ dùng mean/SD, nhưng skew/tails khác nhau có thể cho actual P(R<RL) khác nhau.","trap_vi":""},{"stem_en":"A portfolio has expected return 12%, standard deviation 10%, and minimum acceptable return 8%. Under normality, shortfall risk is closest to:","options":["34.46%","65.54%","40.00%"],"correct":0,"why_vi":"SF=.4 ⇒ P=Φ(−.4)≈34.46%.","trap_vi":""},{"stem_en":"If portfolio return is deterministic at 4% and the threshold is 3%, the safety-first ratio formula is:","options":["Equal to zero","Undefined because standard deviation is zero","Equal to one"],"correct":1,"why_vi":"σ=0 nên công thức chia không có nghĩa; P(R<3%)=0 trực tiếp.","trap_vi":""},{"stem_en":"Which statement correctly distinguishes shortfall risk from standard deviation?","options":["Both measure only negative returns","Standard deviation is the probability of falling below a threshold","Shortfall is threshold-specific downside probability, while SD measures total dispersion"],"correct":2,"why_vi":"SD đo phân tán quanh mean cả hai phía; shortfall P(R<RL) phụ thuộc threshold.","trap_vi":""},{"stem_en":"Three portfolios have (mean, SD): A (12%,16%), B (10%,10%), and C (15%,22%). At a common 4% threshold, Roy selects:","options":["Portfolio B","Portfolio A","Portfolio C"],"correct":0,"why_vi":"SFA=.50, SFB=.60, SFC=.50; B cao nhất.","trap_vi":""},{"stem_en":"When evaluating a portfolio against a one-year threshold, which set of inputs is most appropriate?","options":["Monthly volatility, annual expected return, and a two-year target","One-year expected return, one-year volatility, and a one-year threshold","One-year expected return, monthly volatility, and a monthly threshold"],"correct":1,"why_vi":"Mean, SD và threshold phải cùng horizon; annualize chỉ khi điều kiện/giả định rõ.","trap_vi":""},{"stem_en":"A portfolio with safety-first ratio 1.2 and normally distributed returns has shortfall probability that is:","options":["Greater than a portfolio with safety-first ratio 0.4","Exactly equal to a portfolio with safety-first ratio 0.4","Lower than a portfolio with safety-first ratio 0.4"],"correct":2,"why_vi":"Φ(−1.2)<Φ(−0.4), vì standard normal CDF tăng.","trap_vi":""},{"stem_en":"A portfolio with a deterministic 2% return faces a 3% minimum acceptable return. Its shortfall probability is:","options":["100%","50%","0%"],"correct":0,"why_vi":"2%<3% chắc chắn ⇒ shortfall risk=1; SF undefined vì σ=0.","trap_vi":""}],"cards":[{"front_en":"What is shortfall risk?","back_vi":"P(Rp<RL), xác suất return không đạt minimum acceptable threshold."},{"front_en":"What is the threshold return for starting wealth V0 and minimum ending wealth Vmin?","back_vi":"RL=Vmin/V0−1 (không có external cash flows)."},{"front_en":"What is Roy’s safety-first ratio?","back_vi":"SF=(E(Rp)−RL)/σp, σp>0."},{"front_en":"How is the optimal portfolio selected under Roy?","back_vi":"Chọn portfolio có SF lớn nhất (so cùng threshold/horizon)."},{"front_en":"What does a safety-first ratio of 0.7 mean?","back_vi":"Expected return cao hơn RL 0.7 standard deviation của portfolio."},{"front_en":"What is the z-score of the safety-first threshold?","back_vi":"zL=(RL−μp)/σp=−SF."},{"front_en":"How to get normal shortfall probability?","back_vi":"Φ(−SF), left tail standard normal CDF."},{"front_en":"What is normal shortfall probability if SF=0?","back_vi":"50%, vì threshold đúng bằng mean normal distribution."},{"front_en":"What is normal shortfall probability if SF=0.5?","back_vi":"≈30.85% =Φ(−0.5)."},{"front_en":"What happens if expected return is below threshold?","back_vi":"SF âm; dưới normality, shortfall probability >50%."},{"front_en":"When does Roy SF equal Sharpe ratio numerically?","back_vi":"Khi RL=Rf với cùng định nghĩa expected return và σp."},{"front_en":"Does a large safety-first ratio guarantee no loss?","back_vi":"Không; chỉ làm modeled normal shortfall probability nhỏ hơn."},{"front_en":"Can Φ(−SF) be used for any return distribution?","back_vi":"Không; exact normal CDF cần normal-return assumption."},{"front_en":"What happens to Roy SF if σp=0?","back_vi":"Division by zero; evaluate deterministic shortfall event directly."},{"front_en":"How do shortfall risk and standard deviation differ?","back_vi":"Shortfall là threshold-specific downside probability; SD là total dispersion."},{"front_en":"Should Roy comparisons mix monthly and annual inputs?","back_vi":"Không; mean, σ và RL phải nhất quán horizon."},{"front_en":"Why may two portfolios with equal mean and SD have different actual shortfall probabilities?","back_vi":"Phân phối có skew/tails khác nhau; SF chỉ chứa two moments."},{"front_en":"What dollar ending target corresponds to V0 and RL?","back_vi":"Vmin=V0(1+RL)."}]}]},{"version":"2026.11.22-quant6-sourcefirst-01","module_id":"CFA26-01-06","module_title":"Simulation Methods","language":"Vietnamese teaching / English assessment","qa_status":"SOURCE_MAPPED_ORIGINAL_DRAFT_NUMERICAL_QA_PENDING_FULL_ACADEMIC_SIGNOFF","disclaimer_vi":"Nội dung/ví dụ/câu hỏi do dự án biên soạn theo CFAI 2026 LM6, Kaplan 2026 Book1 và slide Quant. Mô hình giả định không phải số liệu thị trường thực, và các phần t/chi-square/F trong slide được đánh dấu prerequisite thay vì tự coi là LOS chính 2026.","los":[{"id":"CFA26-01-06-LOS01","letter":"6.a","title_en":"Normal and Lognormal Distributions, and Continuously Compounded Returns","outcome_en":"Explain the relationship between normal and lognormal distributions and why a lognormal model is useful for asset prices driven by continuously compounded returns.","overview_vi":"Nếu continuously compounded return r=ln(P_T/P_0) được mô hình hóa normal, giá P_T=P_0e^r có lognormal distribution: dương và right-skewed. Cần phân biệt phân phối của returns và prices, log vs simple return, moment parameters của ln(price) với moment thực của price, iid time scaling và điều kiện để annualize volatility.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM6","pages":"183–190 physical PDF; normal/lognormal and continuous compounding (LOS 6.a)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 6","pages":"76–77 physical PDF"},{"id":"SAPP Quant Slide Notes 2026 — Module 6","pages":"257–264 physical PDF (core LOS 6.a); pp265–267 t/chi-square/F prerequisite, not core"}],"sections":[{"heading":"1. What it means to be normally distributed","body":"Normal distribution N(μ,σ²) đối xứng quanh mean, có hỗ trợ giá trị từ −∞ đến +∞; mean=median=mode. Nó thường hữu ích cho mô hình hóa log returns trong một khoảng thời gian giả định, nhưng không thích hợp trực tiếp cho giá của một tài sản limited liability vì normal distribution có thể tạo giá âm. Việc giả định “returns normal” luôn phải làm rõ đó là simple return hay log return.","trap":""},{"heading":"2. Definition of a lognormal random variable","body":"Một random variable Y theo lognormal nếu ln(Y) theo normal; tương đương tồn tại X normal sao cho Y=e^X. Vì e^X luôn dương với X hữu hạn, lognormal support Y>0, distribution skewed right. Các parameters μ và σ của lognormal được định nghĩa trên X=ln(Y), không mặc định là mean/SD của Y.","trap":""},{"heading":"3. Why lognormal is plausible for asset prices","body":"Equity price thông thường không thể thấp hơn 0 (trừ sản phẩm/quote đặc biệt), nhưng price có thể tăng nhiều lần; lognormal có lower bound 0 và right tail dài. Khi log price changes được mô tả như biến normal, future price có dạng lognormal. Mô hình là approximation có giả định, không phải mọi thị trường/tài sản luôn lognormal.","trap":""},{"heading":"4. Returns versus prices must not be confused","body":"r=ln(P_T/P_0) có thể âm hoặc dương và normal theo giả định. P_T=P_0e^r luôn dương. Simple return R=P_T/P_0−1=e^r−1 có lower bound −100%, không giống phân phối normal của r và cũng không phải chính là lognormal (gross return 1+R mới lognormal nếu r normal).","trap":"Đừng nói “simple percentage return follows lognormal distribution” nếu 1+R mới là biến lognormal."},{"heading":"5. Continuous compounding and inverse transformation","body":"r=ln(P_T/P_0)=ln(1+R), với giá đầu/cuối dương; R=e^r−1. Ví dụ giá 100→110, simple return10%, log return ln(1.10)=9.531%. Với log return 6%, simple return e^.06−1≈6.184%. Hai loại return gần nhau khi biến động nhỏ nhưng không trùng khi biến động lớn.","trap":""},{"heading":"6. Log returns add across holding subperiods","body":"Nếu không có distributions/dividends làm cần điều chỉnh, ln(P_T/P_0)=Σₜln(P_t/P_{t−1}), vì log của tích các gross price relatives bằng tổng logs. Với subperiod r1=4% và r2=−2%, combined log return=2%, simple cumulative return=e^.02−1≈2.02%. Simple returns phải compound (1+R1)(1+R2)−1, không cộng trực tiếp.","trap":""},{"heading":"7. Mean of the lognormal variable is not e^mu","body":"Nếu X~N(μ,σ²), Y=e^X thì E(Y)=e^{μ+0.5σ²}. e^μ là median của Y, không phải mean trừ σ=0. Right skew kéo expected level lên cao hơn median. Với price P_T=P_0e^X, E(P_T)=P_0e^{μ+0.5σ²}, so với median P_0e^μ.","trap":"Không lấy E(e^X)=e^{E(X)} vì kỳ vọng và phi tuyến không hoán đổi."},{"heading":"8. Variance and SD of lognormal variable","body":"Var(Y)=e^{2μ+σ²}(e^{σ²}−1), σY=sqrt(Var(Y)). Hai parameters μ,σ² thuộc X=ln(Y), còn mean/variance của Y là những hàm phi tuyến khác. Khi scale lên P_T=P_0Y, E(P_T)=P_0E(Y), Var(P_T)=P_0²Var(Y).","trap":""},{"heading":"9. Median and skew of lognormal price","body":"Median(Y)=e^μ; mode(Y)=e^{μ−σ²}. Khi σ>0, mean>median>mode. Giá trung bình dự báo trong lognormal model không bằng median future price; cùng log drift, tăng variance làm mean lognormal tăng, một tính chất dễ gây ngộ nhận khi đánh giá typical price.","trap":""},{"heading":"10. Time aggregation under independent and identically distributed returns","body":"Nếu one-period log returns rₜ là iid với E(rₜ)=μ và Var(rₜ)=σ², T-period sum r_{0,T} có mean Tμ, variance Tσ², SD=√Tσ. Khi từng rₜ còn normal, tổng chính xác normal; nếu không normal thì việc tổng xấp xỉ normal cần thêm điều kiện và thường dùng CLT cho đủ nhiều terms. Independence quan trọng để bỏ các covariance cross terms của time series.","trap":"Không scale volatility theo T thay vì √T; nếu serial dependence, scaling đơn giản có thể sai."},{"heading":"11. Volatility annualization","body":"Đối với daily continuously compounded returns có daily SD s_d và giả định iid, annualized volatility≈s_d√N, với N thường khoảng 250 trading days/year trong tài liệu. Nếu s_d=1.2%, annual SD≈1.2%√250≈18.97%. Annualizing cần đồng nhất frequency, sample vs population estimator và n−1 nếu tính SD mẫu từ lịch sử.","trap":""},{"heading":"12. Nonnegative price versus possibility of near-zero prices","body":"Lognormal Y=e^X không âm và thực tế strictly positive nếu X finite, nhưng có thể tiến sát 0. Với limited liability equity, giá về 0 khi default có thể tạo probability mass ở zero mà lognormal thuần không mô tả đúng. Vì vậy lognormal assumption là công cụ modeling; không nhất thiết fit tails/default perfectly.","trap":""},{"heading":"13. Total return and corporate actions caveat","body":"Công thức r=ln(P_T/P_0) phản ánh price return; nếu dividends, splits, distributions, subscriptions hay corporate actions quan trọng, phải dùng adjusted/total-return price series hoặc gross return phù hợp. Dùng closing prices thô có thể mô tả return sai nếu bỏ qua dividends/splits.","trap":""},{"heading":"14. Examination workflow for the lognormal relationship","body":"Xác định đề hỏi log return hay simple return, gross return hay price. Đổi giá thành r=ln(P_T/P_0); nếu cần price, dùng P_T=P_0e^r. Nếu X~N(μ,σ²), hãy phân biệt μ,σ của lnY với mean/SD của Y trước khi dùng lognormal moments. Với multi-period model cần kiểm tra iid/normality; report expected level, median level, volatility đúng đơn vị và horizon.","trap":""}],"formulas":[{"name":"Lognormal definition","expr":"X ~ N(μ,σ²) ⇒ Y=eˣ is lognormal; lnY~N(μ,σ²)","meaning":"Lognormal support Y>0, right-skewed.","conditions":""},{"name":"Continuously compounded return","expr":"r₀,ₜ=ln(Pₜ/P₀)=ln(1+R)","meaning":"Log return giữa hai giá positive.","conditions":"P₀,Pₜ>0; adjust distributions if total return."},{"name":"Price from log return","expr":"Pₜ=P₀exp(r₀,ₜ)","meaning":"Tạo price dương từ continuous return.","conditions":""},{"name":"Simple from log return","expr":"R=exp(r)−1","meaning":"Inverse conversion of r=ln(1+R).","conditions":"R>−1."},{"name":"Additivity of log returns","expr":"r₀,ₜ=Σₖrₖ₋₁,ₖ","meaning":"Holding period continuous return equals sum over subperiods.","conditions":""},{"name":"Lognormal mean","expr":"E(Y)=exp(μ+σ²/2)","meaning":"Mean of Y=e^X, with X~Normal(μ,σ²).","conditions":""},{"name":"Lognormal variance","expr":"Var(Y)=exp(2μ+σ²)[exp(σ²)−1]","meaning":"Variance of lognormal Y.","conditions":""},{"name":"Lognormal median and mode","expr":"median(Y)=exp(μ); mode(Y)=exp(μ−σ²)","meaning":"With σ²>0, mean>median>mode.","conditions":"Optional interpretive extension; distinguishes center of distribution."},{"name":"Lognormal future price moments","expr":"E(Pₜ)=P₀exp(μ+σ²/2); Var(Pₜ)=P₀²Var(exp(X))","meaning":"For Pₜ=P₀eˣ and X distributed normally over horizon T.","conditions":"μ and σ are parameters of log-return over T, not per-period unless aggregated."},{"name":"i.i.d. log-return scaling","expr":"E(r₀,ₜ)=Tμ; Var(r₀,ₜ)=Tσ²; SD(r₀,ₜ)=σ√T","meaning":"Independent identically distributed periods.","conditions":""},{"name":"Annualized daily volatility","expr":"σannual≈σdaily√250","meaning":"Scale daily log-return SD to annual under iid assumption.","conditions":"250 trading days is a convention, not universal."}],"examples":[{"question_en":"A stock rises from USD 100 to USD 110. Find its simple and continuously compounded returns.","steps_vi":["Simple return=(110/100)−1=10%.","Log return=ln(110/100)=ln(1.10)≈0.095310."],"answer":"Simple return 10.00%; log return ≈9.53%.","check":""},{"question_en":"A stock begins at USD 100 and has continuously compounded return 6%. Find its future price and simple return.","steps_vi":["P1=100e^0.06≈106.1837.","R=e^0.06−1≈0.061837."],"answer":"Price ≈USD 106.18; simple return ≈6.18%.","check":""},{"question_en":"Two successive continuously compounded returns are +4% and −2%. Compute total log and simple holding-period return.","steps_vi":["Total r=0.04−0.02=0.02.","Simple cumulative return=e^0.02−1≈0.020201."],"answer":"Total log return 2.00%; simple cumulative return ≈2.02%.","check":""},{"question_en":"If X is normal with mean 0.05 and standard deviation 0.20, calculate the mean of Y=e^X.","steps_vi":["σ²=0.04.","E(Y)=exp(0.05+0.04/2)=exp(0.07)."],"answer":"E(Y)≈1.07251.","check":""},{"question_en":"Using X~N(0.05,0.20²), calculate the median of Y=e^X and compare it with the mean.","steps_vi":["median(Y)=e^0.05≈1.05127.","mean(Y)=e^0.07≈1.07251.","Right skew implies mean>median."],"answer":"Median≈1.05127; mean≈1.07251.","check":""},{"question_en":"Using X~N(0.05,0.20²), compute variance of Y=e^X.","steps_vi":["Var(Y)=exp(2×0.05+0.04)[exp(0.04)−1].","=exp(0.14)[exp(0.04)−1]."],"answer":"Var(Y)≈0.04694.","check":"These parameters belong to ln(Y), not Y."},{"question_en":"Daily log-return volatility is 1.2%. Assuming i.i.d. returns and 250 trading days, estimate annualized volatility.","steps_vi":["σannual=0.012×sqrt(250)≈0.189737."],"answer":"≈18.97%.","check":""},{"question_en":"Daily log returns are i.i.d. with mean 0.04% and SD 1.2%. For 250 trading days, find total log-return mean and SD.","steps_vi":["Mean Tμ=250×0.0004=0.10.","SD sqrt(250)×0.012≈0.189737."],"answer":"Mean 10.00%; SD ≈18.97%.","check":""},{"question_en":"A USD 100 stock price evolves with a normally distributed one-year log return having mean 8% and standard deviation 20%. Find the expected future stock price.","steps_vi":["E(P1)=100 exp(0.08+0.20²/2)=100e^0.10."],"answer":"Expected future price≈USD 110.52.","check":""},{"question_en":"A stock’s simple holding-period return is −30%. What is its continuously compounded return?","steps_vi":["Gross return=1−0.30=0.70.","r=ln(0.70)≈−0.356675."],"answer":"Log return≈−35.67%.","check":""},{"question_en":"A stock starts at USD 100, rises to USD 110, then falls to USD 99. Find the cumulative log and simple price returns.","steps_vi":["r=ln(110/100)+ln(99/110)=ln(0.99)≈−0.0100503.","Simple return=(99/100)−1=−0.01."],"answer":"Log return≈−1.005%; simple return=−1.00%.","check":""}],"questions":[{"stem_en":"If the natural logarithm of a positive random variable is normally distributed, that variable follows a:","options":["Lognormal distribution","Uniform distribution","Normal distribution"],"correct":0,"why_vi":"Definition: ln(Y) normal ⇒Y lognormal.","trap_vi":""},{"stem_en":"Which characteristic of lognormal distributions supports their use in modeling ordinary equity prices?","options":["Perfect symmetry around the mean","Support restricted to strictly positive values","Equal probability of negative and positive prices"],"correct":1,"why_vi":"Giá cổ phiếu nonnegative; lognormal không cho giá âm khi lnPrice finite.","trap_vi":""},{"stem_en":"A lognormal random variable is generally:","options":["Negatively skewed","Exactly symmetric","Positively skewed"],"correct":2,"why_vi":"Lognormal có right tail dài, skewness dương.","trap_vi":""},{"stem_en":"A stock price increases from 100 to 110. Its continuously compounded return is closest to:","options":["9.53%","10.00%","10.53%"],"correct":0,"why_vi":"r=ln(1.10)≈0.09531.","trap_vi":""},{"stem_en":"A continuously compounded return of 6% corresponds to a simple return closest to:","options":["6.00%","6.18%","5.83%"],"correct":1,"why_vi":"R=e^0.06−1≈6.1837%.","trap_vi":""},{"stem_en":"Successive continuously compounded returns are 4% and −2%. The combined continuously compounded return is:","options":["−8%","2.02%","2.00%"],"correct":2,"why_vi":"Log returns additive: 4%−2%=2%.","trap_vi":""},{"stem_en":"If X~N(μ,σ²), the mean of Y=exp(X) is:","options":["exp(μ+σ²/2)","exp(μ)","μ+σ²"],"correct":0,"why_vi":"Lognormal mean là exp(μ+0.5σ²), không phải exp(μ).","trap_vi":""},{"stem_en":"If Y=exp(X) with X normal, exp(E[X]) is the:","options":["Variance of Y","Median of Y","Mean of Y"],"correct":1,"why_vi":"Median of lognormal Y=e^μ.","trap_vi":""},{"stem_en":"For lognormal Y=exp(X), where X~N(0.05,0.20²), E(Y) is closest to:","options":["1.0513","1.0500","1.0725"],"correct":2,"why_vi":"E(Y)=e^{.05+.04/2}=e^.07≈1.0725.","trap_vi":""},{"stem_en":"If daily continuously compounded return volatility is 1.2%, annualized volatility over 250 independent trading days is closest to:","options":["18.97%","3.00%","30.00%"],"correct":0,"why_vi":"σannual=.012√250≈18.97%.","trap_vi":""},{"stem_en":"For i.i.d. log returns, the variance over T identical periods scales approximately with:","options":["The square root of T","T","T squared"],"correct":1,"why_vi":"Var(sum r)=T Var(r) under independence; SD scales sqrt(T).","trap_vi":""},{"stem_en":"For independent normally distributed one-period log returns, the cumulative T-period log return is:","options":["Necessarily lognormal","Necessarily uniform","Normally distributed"],"correct":2,"why_vi":"Sum of independent normal variables remains normal.","trap_vi":""},{"stem_en":"Which variable is lognormal when log return r is normal and the initial price is positive?","options":["The gross price relative P_T/P_0","The continuously compounded return r itself","The simple return R without adding one"],"correct":0,"why_vi":"P_T/P_0=e^r lognormal; simple return=e^r−1 shifted lognormal.","trap_vi":""},{"stem_en":"Which statement about the lower bound of continuously compounded returns is correct?","options":["They cannot be below −100%","They can approach negative infinity as price approaches zero","They are always nonnegative"],"correct":1,"why_vi":"r=ln(Pt/P0), khi Pt↓0 thì r→−∞; simple return có lower bound −100%.","trap_vi":""},{"stem_en":"Which assumption allows simple variance scaling of sums of log returns with time?","options":["Equal portfolio weights only","Equal expected return only","Independence across subperiods"],"correct":2,"why_vi":"Không có serial covariance khi independent; để Tσ² còn cần identical period variances.","trap_vi":""},{"stem_en":"An asset’s lognormal future price distribution is described by parameters that are the mean and variance of:","options":["Its log price","Its simple return","Its raw price itself"],"correct":0,"why_vi":"μ,σ² của lnY, không trực tiếp mean/variance Y.","trap_vi":""},{"stem_en":"A stock priced at USD 100 has a one-year log return equal to 8%. Its modeled future price is closest to:","options":["USD 108.00","USD 108.33","USD 112.00"],"correct":1,"why_vi":"100e^.08≈108.3287.","trap_vi":""},{"stem_en":"If a stock’s simple holding-period return is −30%, its continuously compounded return is closest to:","options":["−30.00%","−26.24%","−35.67%"],"correct":2,"why_vi":"r=ln(.70)=−.356675.","trap_vi":""},{"stem_en":"Which statement about lognormal asset price modeling is most accurate?","options":["It is an approximation that may not capture all default or tail features","It guarantees realistic prices under every market condition","It assigns negative probabilities to returns"],"correct":0,"why_vi":"Lognormal practical model with limitations; exact point mass at zero/default not captured.","trap_vi":""},{"stem_en":"Why does adding simple returns generally fail to compute multi-period cumulative performance?","options":["The lognormal mean becomes zero","Gross returns must be compounded across periods","Simple returns can never be negative"],"correct":1,"why_vi":"Cumulative simple return=Π(1+Ri)−1; log returns mới additive.","trap_vi":""}],"cards":[{"front_en":"What is the definition of a lognormal variable?","back_vi":"lnY normally distributed ⇒ Y lognormal; Y=e^X with X normal."},{"front_en":"What is the support of a lognormal price model?","back_vi":"Y>0; không cho price âm."},{"front_en":"What is the shape of a lognormal distribution?","back_vi":"Right-skewed (long right tail), mean>median when σ>0."},{"front_en":"How to compute continuously compounded return?","back_vi":"r=ln(P_T/P_0)=ln(1+simple R)."},{"front_en":"How to invert log return to simple return?","back_vi":"R=e^r−1."},{"front_en":"How to compute future price from log return?","back_vi":"P_T=P_0e^r."},{"front_en":"How are log returns aggregated across time?","back_vi":"Cộng tất cả log subperiod returns."},{"front_en":"How do simple returns aggregate over time?","back_vi":"Compound Π(1+Ri)−1, không cộng riêng các Ri."},{"front_en":"What is the mean of Y=e^X with X~N(μ,σ²)?","back_vi":"E(Y)=e^{μ+σ²/2}."},{"front_en":"What is the variance of Y=e^X?","back_vi":"e^{2μ+σ²}(e^{σ²}−1)."},{"front_en":"What is the lognormal median?","back_vi":"e^μ, khác expected Y khi σ²>0."},{"front_en":"What is the lognormal mode?","back_vi":"e^{μ−σ²}, nhỏ hơn median nếu σ²>0."},{"front_en":"Under iid log returns, what is cumulative mean over T periods?","back_vi":"Tμ."},{"front_en":"Under iid log returns, how does SD scale with T?","back_vi":"σ√T, còn variance Tσ²."},{"front_en":"How to annualize daily log-return volatility under 250-day assumption?","back_vi":"σannual=σdaily√250."},{"front_en":"What price-related limitation does a pure lognormal model have?","back_vi":"Không có mass at exact zero, khó mô tả một số default/tail events."},{"front_en":"Can unadjusted closing prices always represent total investment return?","back_vi":"Không; cần điều chỉnh dividends/splits/distributions khi phù hợp."}]},{"id":"CFA26-01-06-LOS02","letter":"6.b","title_en":"Monte Carlo Simulation in Investment Analysis","outcome_en":"Describe Monte Carlo simulation and explain how it can be used in investment applications.","overview_vi":"Monte Carlo simulation lấy rất nhiều random draws theo phân phối xác suất/giả định đã thiết lập, chuyển các risk factors thành asset prices, returns hoặc cash flows, tính payoffs và aggregate kết quả để ước lượng risk, probabilities, valuation hoặc sensitivity. Phân biệt random model từ giả định với observed-data bootstrap; xem path-dependence, discounting, precision và model risk.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM6","pages":"190–195 physical PDF (Monte Carlo; LOS 6.b)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 6","pages":"77–79 physical PDF"},{"id":"SAPP Quant Slide Notes 2026 — Module 6","pages":"268–269 physical PDF (Monte Carlo 6.b)"}],"sections":[{"heading":"1. Definition of Monte Carlo simulation","body":"Monte Carlo là một phương pháp numerical simulation lặp lại: chỉ định distributions cho uncertain risk factors, sinh random realizations, áp dụng mô hình kinh tế/tài chính để tạo outcomes và tổng hợp thành estimated distribution. Simulation không thay thế chứng minh nhân-quả; kết quả luôn phụ thuộc vào mô hình, distributions, dependencies và số trials.","trap":""},{"heading":"2. Input distributions and model specification","body":"Trước khi sinh số ngẫu nhiên, xác định cái cần ước lượng: expected return, probability of loss, tail quantile, embedded option value, liability coverage, project NPV. Chọn risk factors như interest rates, volatility, spreads, FX, commodity prices, demand; xác định probability distributions/parameters tương ứng và correlations cần giữ. Model sai thì simulation lớn cũng chỉ tạo kết quả sai một cách chính xác hơn về mặt Monte Carlo noise.","trap":""},{"heading":"3. Six-stage workflow for path-dependent assets","body":"Một workflow: (1) chọn quantity of interest, (2) đặt initial asset state, horizon và time grid K, (3) đặt stochastic model/risks và method of draws, (4) sinh từng path, (5) compute terminal/path-dependent cash flow rồi discount, (6) lặp N trials và summarize average, volatility, quantiles. Khi sản phẩm chỉ phụ thuộc terminal value, có thể đơn giản hóa time grid; Asian/lookback options đòi path details.","trap":""},{"heading":"4. Time grid and number of simulation paths are different","body":"Time grid chia horizon T thành K increments Δt=T/K; mỗi simulation path có K steps. N là số đường mô phỏng lặp lại để estimate distribution, KHÔNG phải số steps. Với 12 tháng một năm và N=5,000 paths, thường có 60,000 step draws cho một independent risk factor trước khi dùng phương pháp tối ưu.","trap":""},{"heading":"5. Generating lognormal stock price paths","body":"Giả sử period log return Δr=μΔt+σ√Δt Z, Z~N(0,1), μ là drift của LOG return trên một đơn vị thời gian. Từ S_{t+Δt}=S_t exp(Δr), mọi simulated stock prices dương. Trong geometric Brownian motion khi μ input là expected simple-price growth drift, log drift thường được điều chỉnh μ−0.5σ²; phải đọc định nghĩa μ trước khi áp dụng.","trap":"Không trộn drift của arithmetic/simple return với log-return drift mà không điều chỉnh."},{"heading":"6. Simulating correlated factors","body":"Với portfolio có nhiều assets, random Z draws cần giữ cross-asset covariance/correlation theo giả định. Nếu mô phỏng từng asset một cách independent khi risk factors thực tế correlated, sẽ đánh giá sai portfolio dispersion và joint tail exposures. Có thể dùng correlated normals/cholesky transformation trong các mô hình phù hợp; kỹ thuật triển khai là mở rộng không bắt buộc thuộc công thức LOS.","trap":""},{"heading":"7. Estimating expected returns and loss probabilities","body":"Nếu simulated outcomes x₁…x_N, sample mean N^{-1}Σxi ước lượng expected outcome của mô hình; fraction of paths with xᵢ<0 ước lượng probability of loss trong giả định đó. Sample standard deviation mô tả dispersion of trials; nếu cần probability of breaching threshold, đếm number simulated breaches / N. Quyết định dựa simulation phải nhắc model-specific estimates, không phải realized future probabilities chắc chắn.","trap":""},{"heading":"8. Valuing contingent claims using discounted simulated payoffs","body":"Với payoff C_T^{(i)} ở path i và discount rate d phù hợp risk pricing, simulated value C0≈N^{-1}Σ PV(C_T^{(i)}). Với simple annual rate d và one-year payoff, PV=C_T/(1+d); với continuous rf r, PV=e^{−rT}C_T. Việc dùng risk-neutral probabilities/drift và risk-free discount cho derivatives cần model pricing nhất quán, không tự dùng real-world return để discount risk-neutral value.","trap":""},{"heading":"9. Path dependence and lookback/Asian contracts","body":"Nếu option payoff dựa average price, running max/min hoặc barrier crossing, terminal price một mình không đủ. Ví dụ Asian-style payoff max(S_T−average(S₁…S_K),0); lookback payoff có thể dùng max(S_T−minimum path price,0). Mỗi trial phải giữ đủ path để tính correct payoff rồi mới discount và average.","trap":""},{"heading":"10. Sensitivity, scenario analysis and stress testing","body":"Monte Carlo cho phép thay đổi assumptions (volatility, correlation, distributions, spreads, time horizon) rồi chạy lại simulation để quan sát effect trên payoff distribution hoặc valuation. Đây là ưu điểm lớn đối với sản phẩm phức tạp, assets with nonnormal distributions và các tập hợp risk factors không giải được dạng closed-form. Simulation noise phải phân biệt với thay đổi do input assumptions.","trap":""},{"heading":"11. Strengths of Monte Carlo simulation","body":"Linh hoạt với nonlinear payoffs, portfolios nhiều assets, path-dependent cash flows và dependencies; có thể tạo distributions, tail percentiles, expected shortfall/trượt mục tiêu theo model. Không bắt buộc có một analytic pricing formula. Có thể dùng phần mềm/spreadsheets; output visualization như histogram giúp giải thích range outcomes.","trap":""},{"heading":"12. Limitations and sources of error","body":"Kết quả chỉ là estimate, không exact; có simulation sampling error, parameter estimation error, incorrect distributions, dependency misspecification, computational cost. Tăng N giảm sampling noise nhưng không tự sửa model bias. Analytical solutions khi có thường giúp hiểu causal relation và kiểm tra simulation. Lợi thế sensitivity analysis không có nghĩa simulation tự xác lập quan hệ nhân-quả.","trap":""},{"heading":"13. Monte Carlo standard error versus asset volatility","body":"Nếu trial outcomes có estimated SD s và N trials independent, SE(sample mean)≈s/√N. SE của average simulated payoff là uncertainty do mô phỏng, khác σ của asset return distribution. Gấp bốn lần N thường giảm SE một nửa; không giảm 4 lần. Nếu paths correlated hoặc variance reduction đặc biệt, formula cần điều chỉnh.","trap":""},{"heading":"14. Interpret frequencies, histograms, confidence and rare events","body":"Một simulated shortfall frequency 40 trên 1,000 paths là 4% estimate trong mô hình; nó không đảm bảo thật sự đúng 4% ngoài đời. Tail event rất hiếm cần N đủ lớn để ước lượng ổn định; histogram phụ thuộc binning; quantile estimates gần tail dễ noisy hơn mean. Kết quả phải dùng đơn vị và time horizon đúng.","trap":""},{"heading":"15. Distinguish simulations from deterministic what-if calculations","body":"Deterministic scenarios như +10%,0%,−10% là vài giả định được cho; Monte Carlo tạo nhiều draws theo distributions và trọng số thống kê. Cả hai hữu ích: scenarios kiểm tra cụ thể cú shock, Monte Carlo đánh giá outcome distribution theo model. Không biến vài outcomes cân bằng thành normal model nếu không có chứng cứ.","trap":""}],"formulas":[{"name":"Time-grid increment","expr":"Δt=T/K","meaning":"K bước trong horizon T.","conditions":""},{"name":"Normal-driven log-return step","expr":"Δr=μ_logΔt+σ√ΔtZ; Z~N(0,1)","meaning":"Một ví dụ thiết lập log-return stochastic model.","conditions":"μ_log là expected log return drift, σ cùng horizon scaling; independent step shocks nếu assumed."},{"name":"Simulated stock-price step","expr":"Sₖ=Sₖ₋₁exp(Δrₖ)","meaning":"Update multiplicatively so modeled price remains positive.","conditions":""},{"name":"Geometric Brownian price-drift adjustment","expr":"Δr=(μ_price−σ²/2)Δt+σ√ΔtZ","meaning":"Alternative when μ_price denotes instantaneous expected proportional PRICE growth.","conditions":"Not interchangeable with μ_log formula."},{"name":"Simulated expected outcome","expr":"mean_sim=(1/N)Σᵢxᵢ","meaning":"Average of N trial results.","conditions":""},{"name":"Simulated event probability","expr":"P̂(event)=(1/N)Σᵢ 1{event in path i}","meaning":"Frequency of modeled events.","conditions":""},{"name":"Simulated discounted claim price","expr":"Ĉ₀=(1/N)Σᵢe^{−rT}C_T^(i)","meaning":"Average present value of simulated payoff under consistent valuation assumptions.","conditions":"Risk-neutral model inputs and discount convention if option pricing."},{"name":"Sampling SE of simulated mean","expr":"SE(mean_sim)≈s_trials/√N","meaning":"Monte Carlo noise in sample mean, not asset volatility.","conditions":"Independent trials, finite variance."},{"name":"Asian-type path-dependent payoff","expr":"C_T=max(S_T−(1/K)ΣₖSₖ,0)","meaning":"Illustrative payoff depending on average path prices.","conditions":""}],"examples":[{"question_en":"A one-year Monte Carlo model uses 12 monthly steps and 5,000 independent paths. What is the step size and the number of step-level random draws for one risk factor?","steps_vi":["Δt=1/12 year.","Draws=12×5,000=60,000."],"answer":"Δt=1/12 year; 60,000 draws.","check":""},{"question_en":"Four simulation trials produce annual returns of 5%, 10%, −8%, and 13%. Estimate expected return and the simulated probability of a negative return.","steps_vi":["Mean=(5+10−8+13)/4=5%.","One of four simulated outcomes is negative."],"answer":"Simulated mean =5.00%; estimated loss probability=25%.","check":""},{"question_en":"Three simulated claim payoffs in one year are USD 0, USD 8, and USD 16. Using an annual discount rate of 5%, compute an illustrative simulated present value.","steps_vi":["Mean payoff=(0+8+16)/3=8.","PV=8/1.05≈7.619."],"answer":"Simulated PV≈USD 7.62.","check":"Illustrates discounting; pricing validity still depends on probability measure."},{"question_en":"A two-step stock-price path starts at 100 and has simple returns of +10% and −10%. Find each price and the terminal price.","steps_vi":["S1=100×1.10=110.","S2=110×0.90=99."],"answer":"Prices=110 then 99; terminal=99.","check":""},{"question_en":"Using the path prices [110, 99] and a path-average-based payoff max(final price − path average,0), calculate the payoff.","steps_vi":["Path average=(110+99)/2=104.5.","Final−average=99−104.5=−5.5.","Payoff=max(−5.5,0)."],"answer":"Payoff=USD 0.","check":""},{"question_en":"A Monte Carlo estimator of a claim value uses trial payoffs [0, 12, 6], discounted one year at 4%. Find the estimated present value.","steps_vi":["Mean payoff=(0+12+6)/3=6.","PV=6/1.04≈5.7692."],"answer":"≈USD 5.77.","check":""},{"question_en":"An estimated trial payoff standard deviation is USD 20 and 400 independent simulation trials are run. What is the standard error of the simulated mean?","steps_vi":["SE≈20/sqrt(400)=20/20."],"answer":"USD 1.00.","check":""},{"question_en":"With the same trial payoff standard deviation of USD 20, increase simulation trials to 1,600. What is the standard error of the mean?","steps_vi":["SE≈20/sqrt(1,600)=20/40."],"answer":"USD 0.50.","check":""},{"question_en":"Suppose Δt=0.25 years, expected quarterly log-return drift parameter is specified by annual μ_log=6%, annual σ=20%, and simulated Z=0.5. Compute the log-return increment.","steps_vi":["Δr=0.06×0.25+0.20×sqrt(0.25)×0.50.","=0.015+0.050=0.065."],"answer":"Δr=6.50%.","check":""},{"question_en":"For the preceding 6.5% simulated log-return increment, a stock starting at USD 100 has which next simulated price?","steps_vi":["S1=100e^.065≈106.7159."],"answer":"USD 106.72.","check":""},{"question_en":"Out of 1,000 simulated paths, 40 finish below a capital-protection threshold. Estimate the shortfall frequency.","steps_vi":["Frequency=40/1,000=0.04."],"answer":"4.00% (model-based estimate).","check":""}],"questions":[{"stem_en":"Monte Carlo simulation primarily generates a large number of outcomes by:","options":["Drawing observations from specified probability distributions and evaluating a model","Repeating the same deterministic forecast without randomness","Replacing every risk factor with its sample mean"],"correct":0,"why_vi":"Monte Carlo sinh random values từ distributions đã định để ước lượng output distribution của mô hình.","trap_vi":""},{"stem_en":"Which application is particularly suitable for Monte Carlo simulation?","options":["A payoff that depends only on a single fixed cash flow","A path-dependent derivative with no convenient closed-form price","An arithmetic operation with no uncertainty"],"correct":1,"why_vi":"Nonlinear/path-dependent payoffs thường cần mô phỏng nhiều đường giá.","trap_vi":""},{"stem_en":"A one-year simulation uses 12 equal monthly steps. The time increment Δt is:","options":["One year","12 years","1/12 year"],"correct":2,"why_vi":"Δt=T/K=1/12.","trap_vi":""},{"stem_en":"A simulation uses 5,000 paths with 12 time steps each for one risk factor. How many step draws are required?","options":["60,000","5,012","416.7"],"correct":0,"why_vi":"5,000×12=60,000 (nếu một draw mỗi step-factor).","trap_vi":""},{"stem_en":"Four simulated returns are 5%, 10%, −8%, and 13%. Their sample mean is:","options":["20.00%","5.00%","8.00%"],"correct":1,"why_vi":"(5+10−8+13)/4=5%.","trap_vi":""},{"stem_en":"If 40 of 1,000 simulated paths breach a loss threshold, estimated shortfall probability is:","options":["40%","0.4%","4%"],"correct":2,"why_vi":"40/1000=0.04=4%.","trap_vi":""},{"stem_en":"Three simulated end-of-year payoffs are 0, 8, and 16. If discounted at 5% annually, the estimated present value is closest to:","options":["7.62","8.00","8.40"],"correct":0,"why_vi":"Average payoff 8, PV=8/1.05≈7.619.","trap_vi":""},{"stem_en":"Which limitation applies even if the number of Monte Carlo trials is extremely large?","options":["Path dependence can never be modeled","Incorrect input assumptions can bias results","Simulation always yields a closed-form analytical formula"],"correct":1,"why_vi":"N→∞ giảm simulation noise nhưng không sửa misspecified model distributions/correlation.","trap_vi":""},{"stem_en":"Monte Carlo simulation is most accurately described as producing:","options":["Guaranteed future asset prices","Exact answers regardless of model specification","Statistical estimates conditional on model assumptions"],"correct":2,"why_vi":"Simulation estimates, không phải exact outcome.","trap_vi":""},{"stem_en":"A path-dependent payoff based on the minimum simulated asset price requires:","options":["The simulated asset-price path, not only terminal price","Only the asset expected return","Only the risk-free interest rate"],"correct":0,"why_vi":"Minimum path price cần quan sát toàn bộ path.","trap_vi":""},{"stem_en":"If simulated trial outcomes have SD 20 and there are 400 independent trials, the standard error of the simulated mean is:","options":["20.00","1.00","0.05"],"correct":1,"why_vi":"SE=s/√N=20/20=1.","trap_vi":""},{"stem_en":"To approximately halve the standard error of a Monte Carlo sample mean with independent trials, increase the number of trials by a factor of:","options":["Two","Eight","Four"],"correct":2,"why_vi":"SE∝1/√N; N×4 ⇒ SE/2.","trap_vi":""},{"stem_en":"Which approach best investigates the effect of increased forecast volatility on a simulated option value?","options":["Rerun the model with a changed volatility input, holding other assumptions consistently","Replace option payoffs with the mean price","Use the same deterministic cash flow twice"],"correct":0,"why_vi":"Sensitivity: change volatility assumption and compare modeled outcomes.","trap_vi":""},{"stem_en":"A model requires positively correlated asset returns, but the simulation draws each asset independently. This most directly introduces an error in:","options":["The definition of portfolio weights","Simulated joint return behavior and portfolio risk","The arithmetic calculation of individual expected returns only"],"correct":1,"why_vi":"Ignoring correlations distorts portfolio variance/joint tail.","trap_vi":""},{"stem_en":"In simulation, K denotes 12 monthly time increments while N denotes 1,000 paths. Which statement is accurate?","options":["K and N necessarily refer to the same quantity","Only K determines the simulated standard error of the mean","K controls path resolution and N controls number of repeated trials"],"correct":2,"why_vi":"K là steps mỗi path; N là số paths.","trap_vi":""},{"stem_en":"A two-step asset path starts at 100 and has simple returns of +10% and −10%. Terminal price is:","options":["99","100","101"],"correct":0,"why_vi":"100×1.10×0.90=99, không về 100.","trap_vi":""},{"stem_en":"A simulated stock-price model uses Δr=μ_logΔt+σ√Δt Z. If μ_log=6%, σ=20%, Δt=0.25, and Z=0.5, the increment is:","options":["1.50%","6.50%","11.50%"],"correct":1,"why_vi":"0.06×0.25+0.20×sqrt(.25)×.5=.015+.05=.065.","trap_vi":""},{"stem_en":"A major reason Monte Carlo estimates may differ across runs using the same model is:","options":["A change in the security’s true face value","A guaranteed data corruption","Random sampling variation"],"correct":2,"why_vi":"Finite random draws produce different estimates; Monte Carlo sampling error.","trap_vi":""},{"stem_en":"To simulate a derivative price consistently under a risk-neutral option-pricing model, the analyst should:","options":["Use risk-neutral input dynamics with a compatible discounting convention","Use any real-world expected return and risk-free discount automatically","Never discount simulated terminal payoffs"],"correct":0,"why_vi":"Phải nhất quán pricing probability/drift và discount convention; không trộn real-world drift vô điều kiện.","trap_vi":""},{"stem_en":"Which quantity measures the precision of a simulated sample mean rather than the volatility of the underlying asset?","options":["The portfolio covariance matrix","The simulation standard error","The expected dividend yield"],"correct":1,"why_vi":"SE của sample mean khác asset σ.","trap_vi":""}],"cards":[{"front_en":"What is the defining procedure of Monte Carlo simulation?","back_vi":"Sinh random draws theo specified probability distribution(s), chạy mô hình nhiều lần, tổng hợp outcomes."},{"front_en":"What is K in a time-grid Monte Carlo?","back_vi":"Number of subperiods/steps on each simulated path."},{"front_en":"What is N in a Monte Carlo simulation?","back_vi":"Number of simulated paths/trials, thường quyết định sampling precision."},{"front_en":"What is Δt in a T-period model with K steps?","back_vi":"Δt=T/K."},{"front_en":"How are simulated log-return increments converted to prices?","back_vi":"Snext=Sprev e^{Δr}."},{"front_en":"What if input μ refers to expected price drift rather than log drift?","back_vi":"GBM log drift thường cần μ_price−σ²/2, nếu mô hình giả định phù hợp."},{"front_en":"What are common Monte Carlo investment applications?","back_vi":"Portfolio P&L distributions, complex derivatives/embedded options, liquidity/risk scenarios, contingent cash flows."},{"front_en":"How to estimate a loss probability from N simulated paths?","back_vi":"Number of paths satisfying loss event divided by N."},{"front_en":"How to value a claim from simulated terminal payoffs?","back_vi":"Average discounted payoff under consistent pricing assumptions."},{"front_en":"Why do Asian or lookback options need price paths?","back_vi":"Payoff dựa path average/minimum/maximum chứ không chỉ terminal S."},{"front_en":"What is a major Monte Carlo strength?","back_vi":"Flexible nonlinear/path-dependent modeling and sensitivity analysis."},{"front_en":"What is a major Monte Carlo limitation?","back_vi":"Only statistical estimates, dependent on assumptions; large N cannot remove model bias."},{"front_en":"What is the standard error of a simulated sample mean?","back_vi":"≈s_trials/√N under independent trials."},{"front_en":"How to approximately halve simulation standard error?","back_vi":"Increase N about 4 times, holding trial SD similar."},{"front_en":"Why preserve correlations when simulating a multiasset portfolio?","back_vi":"Sai correlation sẽ sai portfolio variance và joint tail risk."},{"front_en":"What distinguishes N from K?","back_vi":"N là số paths; K là số time steps trong một path."},{"front_en":"How should Monte Carlo outputs be described?","back_vi":"Model-based estimates, không phải exact forecasts hay guaranteed future probabilities."}]},{"id":"CFA26-01-06-LOS03","letter":"6.c","title_en":"Bootstrap Resampling Based on Observed Data","outcome_en":"Describe the use of bootstrap resampling in conducting a simulation based on observed data in investment applications.","overview_vi":"Bootstrap coi sample quan sát như một empirical distribution và lặp lại việc lấy resamples WITH replacement, thường mỗi resample có n observations bằng sample gốc, để lập sampling distribution của estimator hoặc xây return/price paths. Phân biệt với Monte Carlo draws từ theoretical assumed distributions; hiểu statistical inference, payoff simulation, ưu/nhược điểm và giới hạn dữ liệu lịch sử.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM6","pages":"195–198 physical PDF (bootstrap and investment application; LOS 6.c)"},{"id":"Kaplan SchweserNotes 2026 Book 1 — Reading 6","pages":"78–79 physical PDF"},{"id":"SAPP Quant Slide Notes 2026 — Module 6","pages":"270–273 physical PDF; question slides pp274–275 for teaching context"}],"sections":[{"heading":"1. Resampling versus sampling from a known population","body":"Trong inferential statistics, ta thường chỉ có một observed sample, không biết full population. Bootstrap sử dụng empirical sample đã quan sát làm stand-in cho population để mô phỏng sampling variation. Nhiều resamples tạo distribution của một statistic như mean, variance, correlation, VaR estimate hoặc derivative payoff. Đây không phải lấy lại samples trực tiếp từ population thực mà ta không có.","trap":""},{"heading":"2. Bootstrap means sampling WITH replacement","body":"Một bootstrap resample gồm n draws độc lập từ các n observed records (theo basic iid bootstrap), mỗi draw rút một record và bỏ lại trước lần rút kế tiếp. Vì vậy một observation có thể xuất hiện 0,1,2... lần trong một resample. Without replacement chỉ hoán vị dữ liệu gốc và không tạo được biến thiên mẫu thống kê mean giống ý đồ bootstrap.","trap":""},{"heading":"3. Resample size versus number of bootstrap replications","body":"Nếu observed sample có n rows, resample thường có n rows; thực hiện B resamples. n kiểm soát kích thước mỗi pseudo-sample, B kiểm soát độ mượt của empirical bootstrap distribution. Ví dụ n=4, B=500 có 500 replicate sample means tính từ 2,000 draws, mỗi lần có replacement.","trap":""},{"heading":"4. Empirical distribution behind a bootstrap","body":"Nếu observed returns là [−2%,1%,5%,8%] và bốn observations được coi equally weighted, empirical distribution gán mass 1/4 cho từng observed record. Resampled values chỉ lấy từ các record hiện có trong basic nonparametric bootstrap; không tự tạo new tail returns vượt range lịch sử. Nếu raw records trùng số, probability của giá trị ấy là tổng mass của các records tương ứng.","trap":""},{"heading":"5. Build a bootstrap sampling distribution for an estimator","body":"Procedure: (1) quan sát sample x1…xn; (2) draw n times with replacement, tạo bootstrap sample b; (3) tính statistic θ̂_b; (4) lặp b=1…B; (5) phân tích distribution của các θ̂_b. Mean của replicate statistics có thể dùng để assess bias; SD của replicate statistics ước lượng standard error của estimator; percentiles tạo approximate confidence intervals theo conventions phù hợp.","trap":""},{"heading":"6. Computing bootstrap mean and standard error","body":"Với B replicate estimates θ̂1…θ̂B, bootstrap average θ̄*=Σθ̂b/B, bootstrap estimated standard error ≈sqrt(Σ(θ̂b−θ̄*)²/(B−1)). SD của replicate MEANS khác sample SD của raw observations. Bootstrap does not remove all estimation bias and its quality depends critically on whether original sample represents population.","trap":""},{"heading":"7. Percentile confidence intervals in intuitive terms","body":"Một approximate percentile bootstrap confidence interval có thể lấy empirical quantiles của ordered bootstrap estimates, chẳng hạn lower 2.5% và upper 97.5% cho một 95% interval. Các phương pháp nâng cao có bias correction hoặc studentization; đó là extension, không nên khẳng định một percentile CI luôn đúng cho mọi statistic/sample design.","trap":""},{"heading":"8. Contrast with parametric Monte Carlo","body":"Monte Carlo thường rút từ assumed fitted/theoretical distributions, ví dụ normal/lognormal với μ,σ. Basic nonparametric bootstrap rút trực tiếp từ observed sample mà không cần chỉ định functional form của phân phối returns. Cả hai dùng repeated draws và simulation logic; khác biệt chính là nguồn tạo risk-factor values, đồng thời bootstrap mang theo giới hạn của lịch sử observed data.","trap":""},{"heading":"9. Bootstrap paths in investment valuation","body":"Có thể thay Step 3 của Monte Carlo path simulation: thay vì sinh model-driven log returns từ assumed distribution, rút observed returns hoặc price changes từ empirical distribution với replacement; tạo paths, tính payoff trên từng path, discount, average. Must align observation frequency with chosen time grid: monthly historical changes để mô phỏng monthly steps, không tự ghép daily với annual.","trap":""},{"heading":"10. Bootstrap applications in financial analysis","body":"Resampling có thể ước lượng uncertainty của sample mean return, Sharpe ratio, tracking error, correlations hay parameters trong backtesting; đánh giá sampling distribution của portfolio performance measure khi analytic formulas khó dùng. Với path-dependent security, bootstrap có thể tạo simulated price scenarios dựa trên historical asset changes thay vì parametric shocks.","trap":""},{"heading":"11. Practical strengths","body":"Implementation tương đối đơn giản, bớt yêu cầu giả định explicit parametric distribution, có thể preserve some empirical asymmetry/moments in finite sample và estimate sampling distributions không cần derivation phức tạp. Bootstrap đặc biệt hữu ích khi observed sample có tương đối nhiều representative observations và statistic ổn định.","trap":""},{"heading":"12. Practical weaknesses and historical-data dependence","body":"Original sample nhỏ/không representative sẽ tạo estimates kém, empirical tails bị giới hạn những gì đã thấy; sample selection bias và regime changes được lặp lại thay vì tự sửa. Bootstrap vẫn là statistical estimate, không exact; B lớn chỉ giảm resampling simulation noise, không tạo ra information thiếu trong original data.","trap":""},{"heading":"13. Serial dependence and block resampling caveat","body":"Basic iid bootstrap ngầm xem observations có thể resample riêng lẻ không giữ thứ tự. Với time series có autocorrelation hoặc volatility clustering, random single-observation draws có thể phá dynamic dependence. Có thể dùng block bootstrap để giữ những cụm sequence ngắn; đây là phương án mở rộng, không đồng nghĩa basic method mặc định đã giải quyết serial correlation.","trap":""},{"heading":"14. Why one observation can appear multiple times","body":"Khi drawing with replacement, một record được trả vào sample pool mỗi lần nên có cùng xác suất n^{-1} trong mỗi draw. Ví dụ original records [1,3,5], bootstrap draw [5,5,1] là hợp lệ, có thể lấy mean 11/3. Điều đó minh họa sampling distribution khác nhau giữa nhiều resamples dù original observed sample cố định.","trap":""},{"heading":"15. Exam step-by-step comparison","body":"Nếu đề nói “observed sample”, “resampling with replacement”, “same size as original”, “sampling distribution”, đó thường là bootstrap. Nếu đề nói “specify distribution for risk factors”, “draw random values from fitted Normal”, “scenario simulations”, đó thường là Monte Carlo. Cả hai dùng model paths cho investment applications; đọc đúng source of generated shocks trước khi trả lời.","trap":""}],"formulas":[{"name":"Bootstrap sample draw","expr":"X*ₖ ∈ {x₁,…,xₙ}, with equal probability 1/n per original record","meaning":"Basic iid nonparametric bootstrap from observed records.","conditions":"Sampling WITH replacement."},{"name":"Bootstrap resample dimensions","expr":"n draws per replicate × B replicates","meaning":"Often Bn individual record draws in total.","conditions":""},{"name":"Bootstrap sample mean","expr":"mean*₍ᵦ₎=(1/n)ΣₖX*₍ᵦ,ₖ₎","meaning":"Compute a statistic on each resample.","conditions":""},{"name":"Average bootstrap estimate","expr":"θ̄*=(1/B)Σᵦθ̂*ᵦ","meaning":"Mean of B replicate statistics.","conditions":""},{"name":"Bootstrap standard error estimate","expr":"SE_boot=√[Σᵦ(θ̂*ᵦ−θ̄*)²/(B−1)]","meaning":"Dispersion of bootstrap replicate estimates.","conditions":""},{"name":"Percentile interval","expr":"CI_95%≈[quantile_2.5%(θ̂*), quantile_97.5%(θ̂*)]","meaning":"Illustrative bootstrap percentile confidence interval.","conditions":"Appropriate bootstrap validity assumptions; for finite B quantile convention matters."},{"name":"Empirical resampled event frequency","expr":"p̂*=(number of bootstrap simulated events)/B","meaning":"Model-based event estimate from bootstrap simulation trials.","conditions":""},{"name":"Probability an observation is omitted in n bootstrap draws","expr":"P(never selected)=(1−1/n)^n","meaning":"Useful illustration of WITH-replacement sampling.","conditions":"Each record equally likely and draws independent; supplementary conceptual math."}],"examples":[{"question_en":"A sample contains four observed returns: −2%, 1%, 5%, and 8%. What is the empirical probability assigned to each observation under a basic bootstrap?","steps_vi":["Four observed records, each equally likely in a resample draw.","Probability per record=1/4."],"answer":"25% per observed record.","check":""},{"question_en":"The original return sample is [−2%,1%,5%,8%]. A bootstrap sample is [8%,8%,−2%,1%]. Calculate its mean.","steps_vi":["Resampled sum=8+8−2+1=15 percentage points.","Divide by n=4."],"answer":"3.75%.","check":""},{"question_en":"The original observations are [1,3,5], and the resampled data are [5,5,1]. Calculate bootstrap sample mean.","steps_vi":["Sample with replacement is allowed to repeat 5.","Mean=(5+5+1)/3=11/3."],"answer":"3.6667.","check":""},{"question_en":"An observed dataset contains 4 records and 500 bootstrap replications of size 4 are generated. How many total record draws occur?","steps_vi":["Bn=500×4."],"answer":"2,000 draws.","check":""},{"question_en":"A sample has two observations [0,2]. Enumerate all ordered bootstrap samples of size two and their means.","steps_vi":["With replacement, ordered draws are (0,0),(0,2),(2,0),(2,2).","Means are 0,1,1,2."],"answer":"Bootstrap means: [0,1,1,2].","check":""},{"question_en":"Using all four equally likely bootstrap means [0,1,1,2], calculate the bootstrap distribution mean and population variance of the mean statistic.","steps_vi":["Mean=(0+1+1+2)/4=1.","Variance as four-point distribution=((0−1)²+0²+0²+(2−1)²)/4=0.5."],"answer":"Mean=1.00; variance=0.50; SD≈0.7071.","check":"This is exact enumeration for a toy empirical distribution, not an unbiased population estimate."},{"question_en":"Four bootstrap replicate mean estimates are 2, 4, 6, and 8. Calculate their average.","steps_vi":["θ̄*=(2+4+6+8)/4."],"answer":"Bootstrap mean estimate=5.00.","check":""},{"question_en":"Four bootstrap replicate estimates are 2,4,6,8. Compute the bootstrap estimated standard error using the sample SD of replicates.","steps_vi":["Bootstrap mean=5.","Sum squared deviations=9+1+1+9=20.","SEboot=sqrt(20/(4−1))≈2.582."],"answer":"Estimated bootstrap SE≈2.582.","check":""},{"question_en":"In a bootstrap simulation of 500 portfolio paths, 35 finish below a threshold. What fraction of modeled paths is shortfall?","steps_vi":["Shortfall fraction=35/500=0.07."],"answer":"7.00%.","check":""},{"question_en":"Suppose 500 bootstrap replications are based on 100 historical daily observations, each replication drawing 100 observations with replacement. How many record draws are made?","steps_vi":["B×n=500×100."],"answer":"50,000 draws.","check":""},{"question_en":"In an observed sample of four equally weighted records, what is the probability that a particular record is absent from one size-four bootstrap resample?","steps_vi":["Probability not picked on one draw=3/4.","Across four replacement draws, P(never selected)=(3/4)^4=81/256."],"answer":"≈31.64%.","check":""}],"questions":[{"stem_en":"The defining feature of basic nonparametric bootstrap resampling is drawing observations:","options":["With replacement from an observed sample","Without replacement from the entire unknown population","From a newly specified normal distribution"],"correct":0,"why_vi":"Basic bootstrap rút từ sample quan sát WITH replacement.","trap_vi":""},{"stem_en":"If an original sample has 50 observations, a standard bootstrap resample typically contains:","options":["Five observations","50 observations, with replacement","50 unique observations without replacement"],"correct":1,"why_vi":"Resample size n thường bằng original n, nhưng values có thể lặp.","trap_vi":""},{"stem_en":"A bootstrap resample is allowed to contain the same historical return record:","options":["No more than once","Exactly once","Multiple times"],"correct":2,"why_vi":"With replacement nên record có thể được chọn nhiều lần.","trap_vi":""},{"stem_en":"The main statistical objective of repeatedly calculating an estimate from bootstrap resamples is to approximate its:","options":["Sampling distribution","Coupon rate","Face value"],"correct":0,"why_vi":"Bootstrap tạo distribution của statistic θ̂, giúp SE/CI/bias insights.","trap_vi":""},{"stem_en":"Which statement best distinguishes basic bootstrap from parametric Monte Carlo simulation?","options":["Bootstrap requires a lognormal model but Monte Carlo does not","Bootstrap draws from observed empirical data; parametric Monte Carlo draws from specified distributions","Bootstrap never uses computer simulation"],"correct":1,"why_vi":"Source of random shocks khác nhau; cả hai là methods repeated simulation.","trap_vi":""},{"stem_en":"The observed return sample is [−2%,1%,5%,8%]. The bootstrap draw [8%,8%,−2%,1%] has mean:","options":["3.00%","4.00%","3.75%"],"correct":2,"why_vi":"(8+8−2+1)/4=3.75%.","trap_vi":""},{"stem_en":"A resample of size 3 from observations [1,3,5] is [5,5,1]. Its mean is closest to:","options":["3.67","3.00","5.00"],"correct":0,"why_vi":"(5+5+1)/3=11/3≈3.67.","trap_vi":""},{"stem_en":"A dataset has 4 records and 500 bootstrap replicates of size 4 are generated. Total number of record draws is:","options":["500","2,000","4,000"],"correct":1,"why_vi":"n×B=4×500=2,000.","trap_vi":""},{"stem_en":"What is a basic bootstrap sample’s probability of drawing a particular one of n equally weighted original records on one draw?","options":["0","n","1/n"],"correct":2,"why_vi":"Empirical distribution gán probability 1/n cho mỗi original record.","trap_vi":""},{"stem_en":"Which limitation is inherent in a basic bootstrap based on a nonrepresentative historical sample?","options":["It repeatedly reflects the sample’s omissions and biases","It automatically generates every tail event in the population","It can never compute a sample mean"],"correct":0,"why_vi":"Bootstrap không tự sửa selection bias hoặc missing extremes.","trap_vi":""},{"stem_en":"The standard error estimated from bootstrap replications is typically:","options":["The raw sample mean","The standard deviation of bootstrap replicate estimates","The maximum observed return minus minimum observed return"],"correct":1,"why_vi":"Bootstrap SE là SD of θ̂* replicates, không phải SD of raw data.","trap_vi":""},{"stem_en":"Four bootstrap replicate estimates are 2, 4, 6, and 8. The sample standard deviation across replicates is closest to:","options":["2.00","4.00","2.58"],"correct":2,"why_vi":"Mean5, sum sq deviations20; sample SD=sqrt(20/3)=2.582.","trap_vi":""},{"stem_en":"A basic bootstrap with replacement from the historical observations [1,3,5] could produce which resample of size three?","options":["[5,5,1]","[5,7,9]","Only [1,3,5]"],"correct":0,"why_vi":"[5,5,1] hợp lệ; unseen 7,9 không có trong empirical sample.","trap_vi":""},{"stem_en":"Bootstrap resampling can be used in investment analysis to approximate:","options":["The exact future return of an asset","The sampling distribution of an estimated portfolio statistic","A risk-free outcome that is independent of market conditions"],"correct":1,"why_vi":"Bootstrap hỗ trợ estimate sampling variability của mean/Sharpe/correlation…","trap_vi":""},{"stem_en":"Which feature of naive observation-by-observation bootstrap can be problematic for time-series returns?","options":["It automatically preserves every volatility cluster","It always produces more observations than the original data","It may destroy serial dependence and volatility clustering"],"correct":2,"why_vi":"iid bootstrap breaks sequence; consider block approaches where dependence matters.","trap_vi":""},{"stem_en":"In a bootstrap model, increasing the number of replications B without improving an unrepresentative original sample generally:","options":["Reduces simulation noise but does not eliminate underlying sample bias","Eliminates all estimation risk","Makes the empirical distribution normal"],"correct":0,"why_vi":"B lớn không thêm thông tin lịch sử mới.","trap_vi":""},{"stem_en":"If a simulation draws risk factors from a fitted normal distribution rather than resampling historical observations, the primary method is:","options":["Basic empirical bootstrap","Parametric Monte Carlo simulation","Historical resampling without replacement"],"correct":1,"why_vi":"Specified theoretical distribution => Monte Carlo (parametric in this contrast).","trap_vi":""},{"stem_en":"A bootstrap simulation has 35 shortfall paths out of 500. The simulated shortfall frequency is:","options":["35%","0.7%","7%"],"correct":2,"why_vi":"35/500=.07=7%.","trap_vi":""},{"stem_en":"For an empirical sample [0,2] and an ordered bootstrap resample of size two, which sample is possible?","options":["[0,0]","[0,3]","[2,4]"],"correct":0,"why_vi":"With replacement allows [0,0], but cannot draw unobserved values 3,4.","trap_vi":""},{"stem_en":"What is the most appropriate interpretation of a 95% percentile bootstrap interval?","options":["An exact guaranteed bound on the population parameter","An approximate confidence interval based on quantiles of bootstrap replicate estimates","The range between the largest and smallest returns"],"correct":1,"why_vi":"Percentile CI dùng empirical distribution of estimates và validity assumptions.","trap_vi":""},{"stem_en":"A dataset has 100 observations. Each of 500 bootstrap replications draws 100 records with replacement. The number of individual draws is:","options":["5,000","500","50,000"],"correct":2,"why_vi":"100×500=50,000.","trap_vi":""},{"stem_en":"A particular historical record is one of four equally weighted observations. The probability it is absent from a size-four bootstrap resample is closest to:","options":["31.64%","25.00%","68.36%"],"correct":0,"why_vi":"P(no selection)=(3/4)^4=81/256≈31.64%.","trap_vi":""}],"cards":[{"front_en":"What is the core principle of bootstrap resampling?","back_vi":"Rút từ observed empirical sample with replacement để mô phỏng sampling variability."},{"front_en":"Does basic bootstrap require a theoretical normal model?","back_vi":"Không; draws directly from empirical records."},{"front_en":"What is the usual bootstrap resample size?","back_vi":"n observations, bằng size original sample (với replacement)."},{"front_en":"What does B stand for in bootstrap?","back_vi":"Số bootstrap replications/resamples."},{"front_en":"Can an observation repeat in a bootstrap sample?","back_vi":"Có, vì with replacement."},{"front_en":"Can some original observations be omitted from one resample?","back_vi":"Có; không phải original records nào cũng bắt buộc xuất hiện."},{"front_en":"How to calculate a bootstrap sample mean?","back_vi":"Lấy trung bình n observations của bootstrap replicate đó."},{"front_en":"What distribution does bootstrap simulate for an estimator?","back_vi":"Distribution của θ̂* từ B resampled datasets."},{"front_en":"How to estimate bootstrap standard error?","back_vi":"Sample SD của B replicate statistics θ̂*."},{"front_en":"What is the bootstrap percentile interval idea?","back_vi":"Lấy quantiles của sorted bootstrap estimates, theo validity assumptions."},{"front_en":"What is the empirical probability of each unique observed record under iid bootstrap?","back_vi":"1/n trên mỗi record; duplicate values có thể có combined mass lớn hơn."},{"front_en":"What is the main difference between bootstrap and parametric Monte Carlo?","back_vi":"Bootstrap draws from observed empirical data; parametric MC draws from specified distributions."},{"front_en":"How is bootstrap used to simulate investment option payoffs?","back_vi":"Resample observed price changes, xây paths, tính payoff, discount rồi aggregate."},{"front_en":"What is a bootstrap strength?","back_vi":"Simple, fewer parametric shape assumptions, estimates sampling distribution."},{"front_en":"What is a bootstrap weakness?","back_vi":"Chịu sample selection bias, missing tail events, nonstationarity/regime shifts."},{"front_en":"Why can naive iid bootstrap be problematic with time series?","back_vi":"Không giữ serial correlation/volatility clustering khi randomize từng record riêng."},{"front_en":"What is block bootstrap?","back_vi":"Extension resamples consecutive blocks để giữ một số dependence structure; không phải bước mặc định của core iid method."},{"front_en":"Does increasing B fix a poor original sample?","back_vi":"Không; giảm simulation noise nhưng không thêm thông tin về population chưa quan sát."},{"front_en":"What is the probability a given record is not selected in n independent draws from n records?","back_vi":"(1−1/n)^n; phần bổ trợ để hiểu replacement sampling."}]}]},{"version":"2026.11.22-quant7-sourcefirst-01","module_id":"CFA26-01-07","module_title":"Estimation and Inference","language":"Vietnamese lesson text / English MCQ stems and all A-B-C choices / Vietnamese explanations","qa_status":"SOURCE_MAPPED_SELF_STUDY_DRAFT_PENDING_INDEPENDENT_FULL_SIGNOFF","disclaimer_vi":"Học liệu và bài tập tự biên soạn trên cơ sở đối chiếu CFAI 2026, Kaplan 2026 và slide. Các formulas extension được gắn nhãn; không tái bản ngân hàng câu hỏi thương mại. Kiểm tra cấu trúc, số học và lựa chọn đáp án không đồng nghĩa nghiệm thu tất cả 3 LOS.","los":[{"id":"CFA26-01-07-LOS01","letter":"7.a","title_en":"Sampling Methods and Sampling Error","outcome_en":"Compare and contrast simple random, stratified random, cluster, convenience, and judgmental sampling and their implications for sampling error in an investment problem.","overview_vi":"Cốt lõi LOS 7.a là xác định population, sampling frame, statistic/parameter và chọn đúng sampling mechanism; phân biệt five named methods, systematic sampling như kỹ thuật liên quan; đánh giá bias, precision, cost và đặc biệt vai trò homogeneity, stratification và clusters. Câu hỏi thi thường mô tả thao tác chọn dữ liệu rồi yêu cầu phân loại, hoặc hỏi vì sao sample lớn chưa chắc tốt.","source":[{"id":"CFAI Curriculum 2026 — Quant LM7","pages":"201–211 (physical PDF; LOS and sampling methods)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 7","pages":"80–82 (physical PDF; methods and comparisons)"},{"id":"SAPP Quant Slide Notes 2026 — Module 7","pages":"277–282 (physical PDF; sampling chart)"}],"sections":[{"heading":"1. Population, sample, parameter, statistic","body":"Population là toàn bộ đối tượng phù hợp câu hỏi nghiên cứu (ví dụ, tất cả quỹ nội địa trong một năm). Sample là tập con thực sự được quan sát. Parameter như μ hoặc σ² mô tả population; statistic như sample mean x̄ hoặc s² được tính từ sample và dùng để ước lượng parameter. Trước khi chọn mẫu phải xác định kỳ quan sát, quốc gia, survivorship rules và measurement units.","trap":""},{"heading":"2. Sampling frame and selection mechanism","body":"Sampling frame là danh sách hoặc cơ sở tiếp cận các đơn vị có thể lấy mẫu. Frame bỏ sót quỹ giải thể khiến ngay cả simple random sampling từ danh sách cũng có thể bị coverage bias. Randomize selection không khắc phục việc frame ban đầu không đại diện. Phân biệt population mục tiêu với danh sách có thể truy cập.","trap":""},{"heading":"3. Why financial analysts sample instead of conducting a census","body":"Census quan sát mọi đơn vị thuộc population thường tốn tiền, thời gian và có thể không khả thi (giao dịch toàn thị trường, khách hàng toàn quốc). Sampling giảm chi phí nhưng tạo sampling variation. Sự khác nhau giữa độ tin cậy của thiết kế và tốc độ lấy mẫu là trade-off; sample lớn không luôn tốt nếu dữ liệu sai phạm vi.","trap":""},{"heading":"4. Probability versus non-probability sampling","body":"Probability sampling sử dụng quy tắc lựa chọn theo xác suất đã xác định; trong mô tả simple random, mỗi thành viên có cơ hội bằng nhau. Non-probability sampling dựa trên khả năng truy cập hoặc phán đoán cá nhân nên khó tính sampling uncertainty theo thiết kế và dễ thiếu đại diện. Không kết luận random design xóa hết measurement errors, nonresponse hoặc missing population.","trap":""},{"heading":"5. Simple random sampling (SRS)","body":"Trong SRS lấy n phần tử từ N phần tử sao cho mỗi phần tử có xác suất được đưa vào mẫu như nhau (thực hành dùng random-number generator). Nếu không thay thế, các mẫu n phần tử khả dĩ có xác suất như nhau theo thiết kế SRS lý tưởng. Thích hợp hơn khi population tương đối homogeneous; không đảm bảo mọi nhóm nhỏ chắc chắn xuất hiện.","trap":""},{"heading":"6. Systematic sampling is interval-based","body":"Chọn random start rồi lấy mỗi k-th item từ ordered frame; ví dụ 200 doanh nghiệp, cần 20 observations ⇒ khoảng k=10. Cách này nhanh và có thể gần random nếu list không có cấu trúc tuần hoàn. Nếu dữ liệu được sắp xếp theo pattern có chu kỳ trùng k, sampling sẽ lệch. Nội dung này là supplemental mechanism nằm trong giải thích CFAI LOS 7.a, không phải một LOS thứ sáu.","trap":""},{"heading":"7. Stratified random sampling","body":"Chia population thành các strata có ý nghĩa (issuer type, duration bucket, region), sau đó lấy random subsample từ MỌI stratum; thường phân bổ nₕ tương ứng weight Nₕ/N. Điều này giúp các phân khúc hiện diện và có thể tăng precision, đặc biệt strata khá homogeneous nội bộ nhưng khác nhau giữa nhóm. Cần trọng số khi gộp nếu fraction lấy mẫu không giống nhau.","trap":""},{"heading":"8. Why stratified sampling is useful in bond index replication","body":"Index có hàng nghìn trái phiếu, full replication tốn giao dịch và thanh khoản. Chia strata theo duration, sector, credit quality, coupon hoặc callable exposure giúp chọn đại diện các risk factors. Nếu sau khi phân tầng chuyên viên chọn trái phiếu vì liquidity một cách chủ quan thì bước lựa chọn trong strata có thể không còn strictly random; phải mô tả đúng phương pháp được sử dụng.","trap":""},{"heading":"9. Cluster sampling","body":"Chia population thành clusters, thường theo địa lý hoặc nhóm tổ chức. Randomly select CHỈ MỘT SỐ clusters, sau đó hoặc lấy mọi phần tử trong clusters được chọn (one-stage), hoặc random subset trong mỗi cluster đã chọn (two-stage). Cụm lý tưởng là những mini-populations đa dạng; cùng số quan sát, cluster có thể kém precision khi observations trong cluster quá giống nhau.","trap":""},{"heading":"10. Stratified versus cluster: the most testable distinction","body":"Stratified: mỗi stratum được đại diện trong sample, chọn các elements trong từng stratum. Cluster: chọn một tập clusters, bỏ những clusters không được chọn, có thể khảo sát tất cả phần tử trong clusters selected. Strata nên nội bộ tương đồng; clusters có xu hướng cố gắng phản ánh toàn bộ population. Không chỉ nhìn từ “groups” để kết luận.","trap":""},{"heading":"11. Convenience sampling","body":"Chọn dữ liệu dễ lấy: khách hàng sẵn có, dữ liệu nội bộ, các công ty có sẵn trong vendor extract, nhà đầu tư bước vào quầy khảo sát. Nhanh và rẻ cho pilot study; thường không có representative guarantee. Một cơ sở dữ liệu lớn sẵn có vẫn là convenience nếu cách chọn dựa vào khả năng tiếp cận chứ không dựa vào probability design.","trap":""},{"heading":"12. Judgmental sampling","body":"Nhà nghiên cứu chủ động chọn transactions, công ty hay hồ sơ dựa trên kinh nghiệm. Ví dụ kiểm toán viên tập trung các bút toán bất thường theo fraud indicators. Có thể hữu ích cho mục tiêu kiểm tra chuyên sâu khi thời gian hạn chế, nhưng không nên lấy mean từ những quan sát có chủ đích như thể là representative random sample cho toàn bộ population.","trap":""},{"heading":"13. Sampling error versus nonsampling error","body":"Sampling error cho mean = x̄−μ: khác biệt do chỉ quan sát sample thay vì census, nên đổi sample có thể ra statistic khác. Nonsampling error gồm báo cáo sai, xử lý dữ liệu sai, nonresponse và coverage bias; có thể xuất hiện cả khi census. Không gọi systematic selection bias là một thứ tự biến mất theo n như random sampling error.","trap":""},{"heading":"14. Sample size, precision, and hidden changes in the population","body":"Tăng n thường giảm random sampling variability nếu assumptions đúng, nhưng không sửa sampling frame sai hoặc data regime change. Gộp quarterly returns của chiến lược ít rủi ro và chiến lược nhiều rủi ro thành một population giả có thể khiến estimate không đại diện cho cả hai giai đoạn. Đánh giá representativeness trước khi áp dụng công thức standard error.","trap":""},{"heading":"15. Precision, cost, and risk of selection bias","body":"Stratified thích hợp khi muốn bảo đảm các nhóm theo risk factor đều có mặt; cluster thích hợp khi di chuyển/tiếp cận cá nhân rải rác rất tốn kém; SRS đơn giản khi có frame tốt; convenience/judgment nhanh nhưng khó đưa ra inferential statement cho population. Có thể tồn tại selection bias ngay trong một mẫu rất lớn.","trap":""},{"heading":"16. A reliable exam decision tree","body":"(1) Chọn vì dễ lấy → convenience. (2) Chọn có chủ đích bởi chuyên gia → judgmental. (3) Every kth from list → systematic. (4) Mọi stratum đều có random selected elements → stratified. (5) Randomly choose only certain groups/clusters → cluster. (6) Random units toàn population không phân nhóm → simple random. Sau đó kiểm tra sample representativeness và sampling error.","trap":""}],"formulas":[{"name":"Sample mean","expr":"x̄=(1/n)Σᵢxᵢ","meaning":"Statistic ước lượng population mean μ.","conditions":"Samples n>0; các quan sát thuộc đúng population."},{"name":"Sampling error of mean","expr":"sampling error = x̄−μ","meaning":"Chênh lệch statistic và true population parameter.","conditions":"Nếu μ không biết, sampling error thực thường không quan sát trực tiếp được."},{"name":"Simple random inclusion rate","expr":"P(inclusion of a unit)=n/N","meaning":"Trong simple random sampling without replacement từ N units.","conditions":"0≤n≤N, mỗi unit có xác suất như nhau."},{"name":"Stratified proportional allocation","expr":"nₕ≈n×(Nₕ/N)","meaning":"Số observations từ stratum h theo tỷ lệ population.","conditions":"Làm tròn integers một cách nhất quán để tổng là n."},{"name":"Stratified mean estimator","expr":"x̄_st=Σₕ (Nₕ/N) x̄ₕ","meaning":"Kết hợp stratum-specific means bằng population weights.","conditions":"Cần sampling design hợp lệ trong từng stratum."},{"name":"Strata count","expr":"number of strata = product of classification-category counts","meaning":"Dùng khi cross-classifying issuer type, maturity and coupon categories.","conditions":"Không mặc nhiên cần chọn tối thiểu một item nếu cell không khả thi/không có thành viên."},{"name":"Systematic selection interval","expr":"k≈N/n","meaning":"Approximate step for selecting every k-th item in an ordered list.","conditions":"Random start và không có periodic ordering problem."}],"examples":[{"question_en":"A population contains 240 mutual funds. An analyst selects 24 funds by simple random sampling without replacement. What is each fund’s inclusion probability?","steps_vi":["Chọn n=24 trong N=240, mọi quỹ có chance bằng nhau.","P=n/N=24/240=0.10."],"answer":"10%","check":""},{"question_en":"A population mean annual return is 7.0%, and the selected sample mean is 7.8%. Compute the realized sampling error of the mean.","steps_vi":["Sampling error=x̄−μ=7.8%−7.0%.","Error có dấu; absolute error sẽ bằng 0.8 percentage point."],"answer":"+0.8 percentage point","check":""},{"question_en":"An index contains 800 bonds: 600 government and 200 corporate. A proportionally stratified random sample of 80 bonds is required. How many from each stratum?","steps_vi":["Government weight 600/800=.75; corporate .25.","nG=80×.75=60; nC=80×.25=20."],"answer":"60 government bonds; 20 corporate bonds.","check":""},{"question_en":"A stratified sample contains 20 observations from an 80% population stratum (mean 6%) and 20 from a 20% stratum (mean 12%). What is the population-weighted estimated mean?","steps_vi":["Weights dựa trên population, KHÔNG dựa vào equal sample sizes.","x̄_st=.8×6%+.2×12%=7.2%."],"answer":"7.20%","check":""},{"question_en":"A bond classification uses 4 credit groups, 5 maturity buckets, and 2 callable-status categories. How many nonempty cells can be defined at most?","steps_vi":["Total classification combinations=4×5×2.","Một số cell có thể không có issues, nên đây là số tối đa."],"answer":"40 classification cells at most.","check":""},{"question_en":"A dataset of 360 investors is ordered by client ID. A researcher wants 30 observations using systematic sampling. What sampling interval is appropriate?","steps_vi":["N/n=360/30.","Chọn random start rồi mỗi 12th record."],"answer":"k=12","check":""},{"question_en":"A researcher randomly chooses 8 of 40 districts and surveys all 25 households in each selected district. Classify the design and compute observations.","steps_vi":["Choose clusters (districts), then census within selected clusters.","One-stage cluster; 8×25=200."],"answer":"One-stage cluster sampling; 200 households.","check":""},{"question_en":"From 10 selected regions, a researcher randomly surveys 15 households per region. Which cluster sampling stage and sample size apply?","steps_vi":["Chọn clusters trước, rồi random sample trong selected clusters.","Total 10×15=150."],"answer":"Two-stage cluster sampling; 150 households.","check":""},{"question_en":"An analyst selects the 50 firms with conveniently available historical financial statements. Classify the selection method.","steps_vi":["Không thực hiện random selection; ease of data access quyết định."],"answer":"Convenience sampling.","check":""},{"question_en":"An experienced auditor picks 30 unusual transactions based on professional red flags. Classify the method.","steps_vi":["Researcher judgment, không phải equal-probability selection."],"answer":"Judgmental sampling.","check":""},{"question_en":"The population has three segments with sizes [100, 300, 600]. A proportionally stratified sample of n=50 is planned. Allocate counts.","steps_vi":["Weights .1,.3,.6.","Counts 50×(.1,.3,.6)=(5,15,30)."],"answer":"5, 15, and 30 observations.","check":""},{"question_en":"Two subgroups comprise 70% and 30% of investors and have estimated means of 4% and 9%. Compute a stratified weighted mean.","steps_vi":["Weighted mean=.7×.04+.3×.09=.055."],"answer":"5.50%","check":""},{"question_en":"In a survey, the sample mean salary is USD 75,000 and the true population mean is USD 72,000. What is the signed sampling error?","steps_vi":["75,000−72,000=3,000."],"answer":"USD +3,000","check":""},{"question_en":"A random sample contains 5 firms, and the population contains 250. What proportion of the population is sampled?","steps_vi":["Sampling fraction=n/N=5/250=.02."],"answer":"2%","check":""}],"questions":[{"stem_en":"Which quantity describes an entire population rather than only a sample?","options":["A sample mean","A population mean","A sample variance"],"correct":1,"why_vi":"Population parameter μ mô tả toàn population; x̄ là statistic từ sample.","trap_vi":""},{"stem_en":"An analyst chooses 20 of 200 firms using a random-number generator so that each firm has the same inclusion probability. The method is:","options":["Simple random sampling","Convenience sampling","Judgmental sampling"],"correct":0,"why_vi":"Random selection equally likely is simple random sampling.","trap_vi":""},{"stem_en":"Which sampling method selects randomly from every defined subgroup?","options":["Cluster sampling","Judgmental sampling","Stratified random sampling"],"correct":2,"why_vi":"Stratified dùng sample trong tất cả strata, không chỉ chọn một số nhóm.","trap_vi":""},{"stem_en":"Which method randomly selects several neighborhoods and then surveys all residents within selected neighborhoods?","options":["Stratified random sampling","One-stage cluster sampling","Convenience sampling"],"correct":1,"why_vi":"Cluster là sampling unit; survey all elements in selected clusters.","trap_vi":""},{"stem_en":"An analyst randomly selects some branches and then randomly selects clients within those branches. This is:","options":["Two-stage cluster sampling","One-stage cluster sampling","Simple random sampling over all clients"],"correct":0,"why_vi":"Two-stage: chọn clusters rồi random individuals trong clusters chọn.","trap_vi":""},{"stem_en":"An analyst selects every 12th account after a random starting account. The method is:","options":["Convenience sampling","Systematic sampling","Stratified sampling"],"correct":1,"why_vi":"Every k-th item = systematic; random start làm thiết kế gần random hơn nếu ordering không tuần hoàn.","trap_vi":""},{"stem_en":"An analyst uses only the records already available in an internal spreadsheet. This is most likely:","options":["Simple random sampling","Cluster sampling","Convenience sampling"],"correct":2,"why_vi":"Ease of availability quyết định, không có random mechanism.","trap_vi":""},{"stem_en":"An experienced forensic auditor selects transactions based on suspected irregularities. This is:","options":["Judgmental sampling","Convenience sampling","Simple random sampling"],"correct":0,"why_vi":"Dựa vào professional judgment và risk flags.","trap_vi":""},{"stem_en":"A major advantage of stratified random sampling is that it:","options":["Guarantees zero estimation error","Ensures designated population subgroups are included","Requires sampling only a few clusters"],"correct":1,"why_vi":"Stratified bảo đảm mẫu từ mọi strata; không bảo đảm zero error.","trap_vi":""},{"stem_en":"The main practical advantage of cluster sampling for geographically dispersed investors is often:","options":["Perfect representativeness","Elimination of within-cluster correlation","Lower travel and data-collection costs"],"correct":2,"why_vi":"Chọn một số locations/branches giảm chi phí khảo sát.","trap_vi":""},{"stem_en":"A population contains 500 securities. A simple random sample of 50 securities is drawn without replacement. Each security’s inclusion probability is:","options":["10%","1%","50%"],"correct":0,"why_vi":"n/N=50/500=.10.","trap_vi":""},{"stem_en":"An index contains 75% sovereign bonds and 25% corporate bonds. A proportional stratified sample has 120 issues. How many should be corporate?","options":["90","30","25"],"correct":1,"why_vi":"Corporate count=120×.25=30.","trap_vi":""},{"stem_en":"A firm classifies bonds into 3 sectors, 4 duration categories, and 2 coupon categories. The number of classification cells is:","options":["9","12","24"],"correct":2,"why_vi":"3×4×2=24 cells.","trap_vi":""},{"stem_en":"A population has subgroup weights 80% and 20%, with subgroup mean returns of 5% and 10%. The population-weighted estimated mean is:","options":["6.0%","7.5%","9.0%"],"correct":0,"why_vi":"0.8×5%+0.2×10%=6%; population weights, không phải 50/50.","trap_vi":""},{"stem_en":"If a population mean is 9% and a sample mean is 8%, signed sampling error is:","options":["+1 percentage point","−1 percentage point","−9 percentage points"],"correct":1,"why_vi":"Sampling error = sample mean − population mean =8−9=−1 pp.","trap_vi":""},{"stem_en":"Which statement regarding sample size is most accurate?","options":["Larger samples always eliminate selection bias","A census is always cheaper than sampling","Increasing sample size does not fix a systematically unrepresentative sample frame"],"correct":2,"why_vi":"Larger n giảm sampling variability dưới assumptions; không chữa selection bias.","trap_vi":""},{"stem_en":"Which contrast between stratified and cluster sampling is correct?","options":["Stratified draws from every stratum; cluster draws from selected clusters","Both draw all units from every group","Cluster samples must contain one unit from every cluster"],"correct":0,"why_vi":"Phân biệt all strata vs only selected clusters.","trap_vi":""},{"stem_en":"The population is listed in a repeating pattern of five risk categories. Selecting every fifth observation may introduce:","options":["Guaranteed reduction in selection bias","Periodic-ordering bias","A zero-variance estimate"],"correct":1,"why_vi":"Periodic list pattern trùng k có thể sampling lệch nhóm.","trap_vi":""},{"stem_en":"Which is a nonprobability sampling method?","options":["Simple random","Stratified random","Judgmental"],"correct":2,"why_vi":"Judgmental selection phụ thuộc professional judgment.","trap_vi":""},{"stem_en":"A sample average return changes from 6% to 9% merely because the sampled firms are different. This variation is associated with:","options":["Sampling variability","The definition of a population parameter changing","Guaranteed measurement fraud"],"correct":0,"why_vi":"Statistic thay đổi giữa samples; sự thay đổi là sampling variability.","trap_vi":""},{"stem_en":"An analyst wants a random sample that represents all credit-rating categories of an index. Which design is most suitable?","options":["Convenience sampling","Stratified random sampling","Judgmental sampling"],"correct":1,"why_vi":"Đảm bảo từng rating category nằm trong sample.","trap_vi":""},{"stem_en":"A sample of 120 observations is drawn from a population of 1,000. Its sampling fraction is:","options":["1.2%","120%","12%"],"correct":2,"why_vi":"120/1000=.12=12%.","trap_vi":""}],"cards":[{"front_en":"Population vs sample?","back_vi":"Population là toàn bộ đối tượng mục tiêu; sample là tập con quan sát thực tế."},{"front_en":"Parameter vs statistic?","back_vi":"Parameter (μ, σ²) mô tả population; statistic (x̄, s²) tính từ sample."},{"front_en":"What is the signed sampling error of the mean?","back_vi":"x̄−μ; sample statistic trừ true population mean."},{"front_en":"Definition of a simple random sample?","back_vi":"Mỗi element population có cơ hội chọn như nhau dưới random design."},{"front_en":"Systematic sampling procedure?","back_vi":"Random start, rồi every k-th ordered item (k≈N/n)."},{"front_en":"Main risk of systematic sampling?","back_vi":"Periodic ordering trùng step k làm mẫu thiếu đại diện."},{"front_en":"Stratified random sampling procedure?","back_vi":"Phân strata, chọn random observations từ EVERY stratum, rồi kết hợp."},{"front_en":"When is stratified sampling useful?","back_vi":"Khi phải đại diện các risk factor groups và có thể giảm sampling variance."},{"front_en":"One-stage cluster sampling?","back_vi":"Randomly select clusters, khảo sát tất cả elements ở selected clusters."},{"front_en":"Two-stage cluster sampling?","back_vi":"Chọn random clusters, sau đó random elements trong selected clusters."},{"front_en":"Key distinction between stratified and cluster?","back_vi":"Stratified đại diện mọi stratum; cluster chỉ chọn một số clusters."},{"front_en":"Convenience sampling definition?","back_vi":"Lấy observations dễ tiếp cận hoặc dữ liệu sẵn có."},{"front_en":"Judgmental sampling definition?","back_vi":"Chọn observations theo chuyên môn và nhận định người nghiên cứu."},{"front_en":"Why is an extremely large convenience sample potentially biased?","back_vi":"Sample frame/selection mechanism không đại diện; n lớn không tự sửa bias."},{"front_en":"Proportional allocation across stratum h?","back_vi":"nₕ≈n×Nₕ/N."},{"front_en":"Population-weighted stratified mean?","back_vi":"x̄_st=Σₕ(Nₕ/N)x̄ₕ; không dùng sample weights khi disproportionate sampling."},{"front_en":"Typical advantage and disadvantage of cluster sampling?","back_vi":"Chi phí thấp cho population phân tán; within-cluster similarity có thể làm precision thấp."},{"front_en":"Does an equal-probability random sample guarantee zero sampling error?","back_vi":"Không, chỉ làm design có cơ sở inferential; sampling variation vẫn tồn tại."}]},{"id":"CFA26-01-07-LOS02","letter":"7.b","title_en":"Central Limit Theorem and the Standard Error of the Mean","outcome_en":"Explain the central limit theorem and its importance for the distribution and standard error of the sample mean.","overview_vi":"LOS 7.b đòi hỏi hiểu sampling distribution là phân phối của estimator qua những mẫu lặp lại; CLT phát biểu phân phối x̄ xấp xỉ normal khi n đủ lớn, dù population không normal, dưới assumptions phù hợp. Phải tính σ/√n hoặc s/√n, hiểu SD khác SE, quy tắc 1/√n, và không diễn giải CLT thành bảo đảm mức sai số của một sample duy nhất.","source":[{"id":"CFAI Curriculum 2026 — Quant LM7","pages":"211–215 (physical PDF; CLT, formulas, interpretive checks)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 7","pages":"82–84 (physical PDF; SE examples)"},{"id":"SAPP Quant Slide Notes 2026 — Module 7","pages":"283–287 (physical PDF; CLT/SE charts)"}],"sections":[{"heading":"1. Distribution of raw observations versus distribution of means","body":"Population distribution thể hiện cách single Xi biến động; sampling distribution of x̄ thể hiện x̄ biến động khi lấy vô số random samples cùng size n. Hai distributions là hai đối tượng khác nhau: data có thể skewed, còn distribution của means gần normal nếu điều kiện CLT được đáp ứng. Không gọi histogram của n raw returns là sampling distribution của mean.","trap":""},{"heading":"2. Precise central limit theorem in the curriculum","body":"Với observations lấy random độc lập từ cùng một population có finite mean μ và finite variance σ², khi n lớn, x̄ có distribution xấp xỉ N(μ,σ²/n). Ý nghĩa: shape hội tụ normal, mean của sampling distribution là μ, variance là σ²/n. Thực tế financial returns có time dependence hoặc heavy tails; assumptions có thể không phù hợp.","trap":""},{"heading":"3. What n≥30 means and what it does not mean","body":"CFA thường dùng n≥30 như rule of thumb để gọi sample large. Nhưng mức đủ lớn phụ thuộc asymmetry và tail; population quá skewed cần n lớn hơn. n=30 không phải định lý áp dụng máy móc; finite variance và sampling design phù hợp vẫn cần.","trap":""},{"heading":"4. Population need not be normal for CLT asymptotics","body":"Nếu returns có distribution lệch phải nhưng finite variance và observations thỏa assumptions, sample mean của n lớn có thể gần normal. Không yêu cầu individual observations trở nên normal, chỉ sampling distribution of mean. Nếu underlying population normal và observations independent, x̄ normal ở mọi n, không cần đợi n≥30.","trap":""},{"heading":"5. Expected value of the sample mean","body":"Nếu Xi identically distributed, E(Xi)=μ và sample được chọn unbiased, E(x̄)=μ. Sự bằng nhau thể hiện sample mean là unbiased estimator of population mean trong thiết kế đúng. Một realized x̄ riêng lẻ có thể khác μ và vẫn là unbiased estimator theo repeated sampling.","trap":""},{"heading":"6. Variance of sample mean","body":"Under independent observations with Var(Xi)=σ², Var(x̄)=Var((ΣXi)/n)=(nσ²)/n²=σ²/n. Covariances phải được tính thêm nếu observations correlated: công thức σ²/n không được áp máy móc cho time-series returns phụ thuộc mạnh.","trap":""},{"heading":"7. Standard error versus standard deviation","body":"σ là SD của individual observations, đo dispersion dữ liệu; SE(x̄)=σ/√n là SD của statistic qua repeated samples, đo precision của estimate. Đơn vị cả hai giống return hoặc monetary value nhưng phạm vi khác. Không tính SE bằng s/n (thiếu căn).","trap":""},{"heading":"8. Estimated standard error when population σ is unknown","body":"Thực tế hiếm biết population σ; ước lượng s²=Σ(Xi−x̄)²/(n−1), s=√s², rồi estimated SE=s/√n. Mẫu phải đủ đại diện. n−1 là denominator của sample variance estimator, không phải denominator của estimated SE.","trap":""},{"heading":"9. An intuitive repeated-sampling thought experiment","body":"Giả sử population mean =5%, σ=18%, và lặp lại chọn 81 independent observations: E(x̄)=5%, SE=18%/9=2%. Điều này không bảo đảm x̄ nằm chính xác cách mean 2%; SE là dispersion của sampling distribution. Những sample means khác nhau do random draw.","trap":""},{"heading":"10. The square-root sample-size relationship","body":"SE∝1/√n khi σ cố định. Nhân n lên 4 ⇒ SE giảm 2 lần; nhân n lên 9 ⇒ SE giảm 3 lần. Nếu muốn giảm SE từ 2% xuống 0.5%, cần khoảng 16 lần sample size với assumptions không đổi. Đổi n mà σ thay đổi thì không dùng tỷ lệ đơn giản.","trap":""},{"heading":"11. Find sample size for a desired standard error","body":"Từ target SE=σ/√n suy ra n=(σ/target SE)², rồi round UP integer để không vượt mục tiêu; dùng estimated σ nếu cần. Việc chọn cỡ mẫu còn phụ thuộc cost, representativeness, finite-population context, autocorrelation và missing observations.","trap":""},{"heading":"12. Inference and confidence intervals link","body":"Vì x̄ có sampling distribution gần normal trong điều kiện phù hợp, có thể chuẩn hóa z=(x̄−μ)/(σ/√n) để tính xác suất liên quan đến estimator hoặc xây confidence interval. Chi tiết cấu trúc intervals/tests thuộc prerequisites và LM8; bản chất ở đây là sampling precision chứ không phải xác suất μ là biến ngẫu nhiên.","trap":"Không diễn giải frequentist 95% CI là 95% xác suất parameter cố định nằm trong interval sau khi đã quan sát data."},{"heading":"13. CLT is not a portfolio diversification theorem","body":"Số lượng assets tăng không tự dẫn portfolio risk về 0 khi returns correlated. CLT ở đây mô tả mean của random independent samples, không thay công thức portfolio variance có covariance. Hãy phân biệt n observations với n holdings và phân biệt average of independent observations với market portfolio.","trap":""},{"heading":"14. Time-series dependence breaks naive σ/√n","body":"Nếu monthly returns autocorrelated, Var(x̄) bao gồm covariance between observations, không chỉ σ²/n. Khi đó effective sample size có thể nhỏ hơn số months. Trong bài CFA cơ bản nếu đề cho independent observations, dùng standard formula; ngoài điều kiện đó phải nhận diện limitation.","trap":""},{"heading":"15. Finite population and sampling assumptions","body":"Với finite population sampling without replacement chiếm tỷ lệ đáng kể, exact SE có thể có finite-population correction. Đây là extension để hiểu giới hạn của σ/√n; curriculum áp dụng công thức chuẩn trong setting large population/independent draws. Không tự thêm correction nếu CFA đề không yêu cầu.","trap":""},{"heading":"16. A repeatable exam strategy","body":"(1) Xác định câu hỏi là SD of data hay SE of mean. (2) Đọc n, σ known hay s estimated. (3) Dùng σ/√n hoặc s/√n. (4) Phân biệt x̄ point estimate và spread of x̄. (5) Nếu thay n, áp square-root scaling. (6) Với CLT statement, nhớ “mean μ, variance σ²/n, approximately normal for sufficiently large n”.","trap":""}],"formulas":[{"name":"Sample mean","expr":"x̄=(Σᵢ₌₁ⁿXᵢ)/n","meaning":"Trung bình của n independent observations.","conditions":"n≥1"},{"name":"Expected sampling mean","expr":"E(x̄)=μ","meaning":"Mean of sampling distribution equals true population mean.","conditions":"Independent or other suitable unbiased sampling with same μ."},{"name":"Variance of sample mean","expr":"Var(x̄)=σ²/n","meaning":"Sampling distribution variance.","conditions":"Xi independent, common finite variance σ²."},{"name":"Standard error of sample mean, known σ","expr":"SE(x̄)=σ/√n","meaning":"SD of sampling distribution of mean.","conditions":"Independent common-population sample; population σ known."},{"name":"Unbiased sample variance estimator","expr":"s²=[Σᵢ(Xᵢ−x̄)²]/(n−1)","meaning":"Estimate population variance.","conditions":"n>1 independent representative observations."},{"name":"Estimated standard error, σ unknown","expr":"estimated SE(x̄)=s/√n","meaning":"Approximate sampling mean precision using sample SD.","conditions":"n>1; sampling assumptions apply."},{"name":"Large sample CLT approximation","expr":"x̄≈N(μ,σ²/n)","meaning":"Mean distribution approximately normal.","conditions":"Sufficiently large n; independent identically distributed, finite variance."},{"name":"Z-standardized sample mean","expr":"z=(x̄−μ)/(σ/√n)","meaning":"Standardization when known σ in model.","conditions":"Population and sampling assumptions valid."},{"name":"Sample size for target SE","expr":"n≥(σ/target SE)²","meaning":"Choose minimum n by ceiling result.","conditions":"Known/reasonably estimated σ; no corrections and independent sample."},{"name":"SE scaling across sample sizes","expr":"SE₂/SE₁=√(n₁/n₂)","meaning":"Compare SE for same σ.","conditions":"Same population variance and sampling design."},{"name":"Mean variance with dependence (extension)","expr":"Var(x̄)=[ΣᵢVar(Xᵢ)+2Σᵢ<ⱼCov(Xᵢ,Xⱼ)]/n²","meaning":"Covariance terms matter if returns dependent.","conditions":"Extension beyond basic CLT; illustrates key assumption."}],"examples":[{"question_en":"A random sample has n=100 and the known population standard deviation is 15%. What is the standard error of the sample mean?","steps_vi":["SE=σ/√n=.15/10=.015."],"answer":"1.50%","check":""},{"question_en":"A sample of 64 observations has sample standard deviation of 24%. The population SD is unknown. Estimate the standard error.","steps_vi":["Estimated SE=s/√n=.24/8=.03."],"answer":"3.00%","check":""},{"question_en":"If the population mean is 6%, population standard deviation is 12%, and n=36, identify the mean and standard deviation of the sampling distribution.","steps_vi":["E(x̄)=μ=6%.","SE=12%/√36=2%."],"answer":"Mean 6.00%; SE 2.00%.","check":""},{"question_en":"A population has variance 0.09 (in decimal-return units squared). A random sample has n=25. Calculate the variance of the sample mean.","steps_vi":["Var(x̄)=σ²/n=.09/25=.0036."],"answer":"0.0036","check":""},{"question_en":"The estimated standard error is 4% for n=25. If the population SD does not change, what is the SE at n=100?","steps_vi":["SE₂=SE₁×√(25/100)=4%×.5."],"answer":"2.00%","check":""},{"question_en":"An analyst has n=40 and wants to reduce standard error by 50% without changing population variance. How large a sample is needed?","steps_vi":["Need n_new=4×n_old.","n_new=4×40."],"answer":"160 observations.","check":""},{"question_en":"A population SD is 18%. What sample size is needed so that SE is at most 2%?","steps_vi":["n≥(.18/.02)²=9²=81."],"answer":"At least 81 observations.","check":""},{"question_en":"A population SD is 25%. What minimum sample size makes the SE no greater than 3%?","steps_vi":["n≥(25/3)²≈69.444.","Round UP, not down."],"answer":"At least 70 observations.","check":""},{"question_en":"A sample has observations [1, 3, 5]. Find the sample variance, sample standard deviation, and estimated SE of the mean.","steps_vi":["x̄=3; squared deviations 4+0+4=8.","s²=8/(3−1)=4, s=2.","SE=2/√3≈1.1547."],"answer":"s²=4; s=2; estimated SE≈1.1547.","check":""},{"question_en":"Independent observations have σ=10 and n=400. What is the variance of their sample mean?","steps_vi":["Population variance=100.","Var(x̄)=100/400=.25."],"answer":"0.25","check":""},{"question_en":"A sample mean is 8%, a hypothesized mean is 6%, population SD is 12%, and n=36. What is the standardized z value?","steps_vi":["SE=.12/√36=.02.","z=(.08−.06)/.02=1."],"answer":"z=+1.00.","check":""},{"question_en":"Population standard deviation is 9%. What is the approximate SE with n=81 and with n=324?","steps_vi":["SE81=9%/9=1%.","SE324=9%/18=.5%."],"answer":"1.00% and 0.50%.","check":""},{"question_en":"An estimated standard error from n=49 is 2.8%, assuming identical SD at any sample size. What is the estimated SE at n=196?","steps_vi":["n grows by factor 4; SE decreases by factor 2."],"answer":"1.40%","check":""},{"question_en":"A population variance is 16 and sample size is 64. Find the standard error of the mean.","steps_vi":["σ=√16=4; √n=8.","SE=4/8=.5."],"answer":"0.50","check":""}],"questions":[{"stem_en":"The sampling distribution of the sample mean is the distribution of:","options":["All raw observations in one sample","Means computed across repeated samples of the same size","All population parameters across different populations"],"correct":1,"why_vi":"Sampling distribution là distribution của statistic qua samples lặp.","trap_vi":""},{"stem_en":"According to the central limit theorem, as sample size increases, the sampling distribution of the mean approaches:","options":["A normal distribution under appropriate conditions","The exact distribution of each raw observation","A uniform distribution regardless of sample design"],"correct":0,"why_vi":"CLT: sampling mean approximately normal for sufficiently large n with suitable assumptions.","trap_vi":""},{"stem_en":"The expected value of the sampling distribution of the sample mean under unbiased random sampling is:","options":["The sample variance","The population standard deviation","The population mean"],"correct":2,"why_vi":"E(x̄)=μ.","trap_vi":""},{"stem_en":"For independent identically distributed observations with population variance σ², the variance of the sample mean is:","options":["σ²/n","σ²×n","σ²/√n"],"correct":0,"why_vi":"Var(x̄)=σ²/n.","trap_vi":""},{"stem_en":"A sample has n=81, and population SD is 18%. The standard error of the mean is:","options":["9%","2%","0.22%"],"correct":1,"why_vi":"18%/√81=18%/9=2%.","trap_vi":""},{"stem_en":"If the population standard deviation is unknown, the standard error of the sample mean is commonly estimated using:","options":["s/n","s²/n","s/√n"],"correct":2,"why_vi":"Estimated SE=s/√n, với s=sample SD.","trap_vi":""},{"stem_en":"To halve the standard error of a sample mean, assuming unchanged population volatility, the sample size should be multiplied by:","options":["Four","Two","Eight"],"correct":0,"why_vi":"SE∝1/√n ⇒ n×4.","trap_vi":""},{"stem_en":"A sample of 25 observations has sample SD 10%. Estimated SE is closest to:","options":["0.4%","2.0%","5.0%"],"correct":1,"why_vi":"10%/5=2%.","trap_vi":""},{"stem_en":"A population has variance 0.04. For n=100 independent observations, the variance of the sample mean is:","options":["0.004","0.04","0.0004"],"correct":2,"why_vi":"0.04/100=0.0004.","trap_vi":""},{"stem_en":"The key difference between standard deviation and standard error is that standard error measures:","options":["Variation across estimates from different samples","Only negative deviations of raw returns","All uncertainty due to model specification"],"correct":0,"why_vi":"SE đo sampling variability of statistic; SD đo dispersion observations.","trap_vi":""},{"stem_en":"Which statement about the often-used rule n ≥ 30 is most accurate?","options":["It guarantees a perfect normal approximation for every distribution","It is a rule of thumb; highly skewed populations may require more observations","It eliminates the need for finite population variance"],"correct":1,"why_vi":"Skewed/heavy tails và dependence có thể cản CLT approximation ở n=30.","trap_vi":""},{"stem_en":"If the population itself is normally distributed and observations are independent, the sampling distribution of the mean is:","options":["Only normal when n > 1,000","Always uniform for n < 30","Normal for any positive sample size"],"correct":2,"why_vi":"Normal population ⇒ independent sample mean exactly normal for any n.","trap_vi":""},{"stem_en":"An analyst increases n from 50 to 200 with unchanged population SD. The SE becomes:","options":["One-half the original SE","One-quarter the original SE","Twice the original SE"],"correct":0,"why_vi":"n grows 4× ⇒ SE ÷2.","trap_vi":""},{"stem_en":"Population σ=20%, and the target standard error is 2%. The minimum sample size using the standard formula is:","options":["20","100","400"],"correct":1,"why_vi":"n=(20/2)²=100.","trap_vi":""},{"stem_en":"The central limit theorem implies which distributional property for a sufficiently large independent random sample?","options":["Population observations become normal","Population variance must equal zero","Sample mean is approximately normally distributed"],"correct":2,"why_vi":"Phân phối sample mean gần normal; raw observations vẫn có original distribution.","trap_vi":""},{"stem_en":"A sample mean is an unbiased estimator when:","options":["The expected sample mean equals the population mean","Each sample mean exactly equals the population mean","The sample contains at least 30 observations"],"correct":0,"why_vi":"Unbiased means E(x̄)=μ, not individual equality.","trap_vi":""},{"stem_en":"Population mean is 6%, sample mean is 8%, σ=12%, n=36. The z-score for the sample mean is:","options":["0.17","1.00","2.00"],"correct":1,"why_vi":"(8−6)/(12/6)=2/2=1.","trap_vi":""},{"stem_en":"A sample of 64 observations has population SD 16. The standard error is:","options":["0.25","8","2"],"correct":2,"why_vi":"16/√64=2.","trap_vi":""},{"stem_en":"When individual monthly returns have substantial positive autocorrelation, blindly using σ/√n can:","options":["Understate the actual sampling uncertainty","Guarantee unbiased inference","Make population SD zero"],"correct":0,"why_vi":"Positive covariances trong Var(x̄) tăng SE so với independence benchmark.","trap_vi":""},{"stem_en":"Which statement incorrectly applies the central limit theorem?","options":["The sample mean can be approximately normal even if raw data are skewed","Portfolio risk necessarily reaches zero as the number of correlated assets increases","The sampling distribution of the mean has mean μ for unbiased random sampling"],"correct":1,"why_vi":"CLT không chứng minh risk portfolio→0 khi có covariance.","trap_vi":""},{"stem_en":"A population variance is 36, with n=9 independent observations. The standard error of the mean is:","options":["4","6","2"],"correct":2,"why_vi":"σ=6; √9=3; SE=2.","trap_vi":""},{"stem_en":"If n increases by a factor of nine with constant population SD, standard error is multiplied by:","options":["1/3","1/9","3"],"correct":0,"why_vi":"√9=3 ⇒ SE/3.","trap_vi":""}],"cards":[{"front_en":"What is a sampling distribution?","back_vi":"Phân phối của một statistic qua mọi repeated samples cùng size/design."},{"front_en":"What distribution does CLT apply to?","back_vi":"Sampling distribution của x̄, không phải raw population observations."},{"front_en":"CLT approximation for sample mean?","back_vi":"x̄≈N(μ,σ²/n) khi sample large và assumptions hợp lệ."},{"front_en":"Is normal population required for CLT?","back_vi":"Không; finite variance và sampling assumptions phù hợp, n đủ lớn."},{"front_en":"Common CFA large-n heuristic?","back_vi":"n≥30 là rule of thumb, không phải absolute guarantee."},{"front_en":"Expected value of sample mean?","back_vi":"E(x̄)=μ cho unbiased random sampling."},{"front_en":"Sampling mean variance?","back_vi":"Var(x̄)=σ²/n với independent, equal-variance observations."},{"front_en":"Known-σ standard error of mean?","back_vi":"SE(x̄)=σ/√n."},{"front_en":"Unknown-σ estimated standard error?","back_vi":"estimated SE=s/√n, s sample SD."},{"front_en":"Why sample variance uses n−1?","back_vi":"Correction khi estimate population variance từ deviations quanh sample mean."},{"front_en":"SD versus SE?","back_vi":"SD mô tả độ phân tán raw data; SE mô tả độ phân tán estimator qua samples."},{"front_en":"Effect on SE if n quadruples?","back_vi":"SE giảm một nửa, assuming unchanged population variance."},{"front_en":"Sample size for target SE?","back_vi":"n=ceiling[(σ/target SE)²]."},{"front_en":"When raw population is normal?","back_vi":"Mean của independent normal observations cũng normal với mọi n."},{"front_en":"What can cause σ/√n to fail?","back_vi":"Dependence/autocorrelation, poorly specified population, problematic sampling."},{"front_en":"Does CLT guarantee zero risk for large portfolios?","back_vi":"Không; portfolio risk phụ thuộc covariance; CLT không phải diversification theorem."},{"front_en":"Why use CLT in statistical inference?","back_vi":"Mean có approximate normal sampling distribution để đánh giá uncertainty của estimate."}]},{"id":"CFA26-01-07-LOS03","letter":"7.c","title_en":"Bootstrap and Jackknife Resampling","outcome_en":"Describe the use of resampling (bootstrap, jackknife) to estimate the sampling distribution of a statistic.","overview_vi":"LOS 7.c đòi hỏi hiểu cách xây empirical sampling distributions của statistic từ observed sample: bootstrap draws n items WITH replacement B lần; jackknife bỏ từng observation một WITHOUT replacement, thường tạo n leave-one-out samples. Biết cách đo estimated standard error từ resampled estimates, phân biệt số resamples với sample size và giới hạn dữ liệu không đại diện/time-series dependence.","source":[{"id":"CFAI Curriculum 2026 — Quant LM7","pages":"215–218 (physical PDF; bootstrap and jackknife)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 7","pages":"84–86 (physical PDF; resampling)"},{"id":"SAPP Quant Slide Notes 2026 — Module 7","pages":"294–297, 301 (physical PDF; bootstrap/jackknife and checklist)"}],"sections":[{"heading":"1. Why resampling is useful","body":"Số lần quan sát thực tế có hạn, còn analytical sampling distribution của estimator (median, skewness, strategy performance) có thể khó xác định. Resampling dùng observed data để mô phỏng repeated estimation, tạo empirical distribution of statistic. Nó không thay thế việc kiểm tra dữ liệu ban đầu có đại diện population hay không.","trap":""},{"heading":"2. Empirical distribution as proxy for population","body":"Bootstrap xem observed sample như empirical approximation của unknown population; chọn các giá trị từ sample với equal empirical mass trong basic nonparametric bootstrap. Bởi vậy kết quả phụ thuộc quality, coverage, regime và sample size của original dataset. Không thêm thông tin mới về những events hoàn toàn không có trong dữ liệu.","trap":""},{"heading":"3. Bootstrap procedure, step by step","body":"Cho original sample of n returns. Một bootstrap resample lấy ngẫu nhiên n observations FROM ORIGINAL SAMPLE với replacement. Tính statistic θ̂ᵦ cho resample đó. Lặp B lần tạo θ̂₁,...,θ̂ᴮ; histogram estimates xấp xỉ sampling distribution. Mỗi resample cùng n với original sample, dù có lặp observations.","trap":""},{"heading":"4. Replacement means repeat and omission are allowed","body":"With replacement: sau mỗi draw, observation trở lại pool; một data point có thể xuất hiện 0,1,2,... lần trong resample. Ví dụ original [1,3,7], một resample hợp lệ là [7,7,1] nhưng [7,8,1] không hợp lệ nếu 8 không có trong original sample. Không nhầm bootstrap sample thành chọn n distinct observations.","trap":""},{"heading":"5. B is not n","body":"n là số observations trong original dataset và trong mỗi bootstrap resample; B là số repeated bootstrap resamples/estimates. n=100, B=1,000 ⇒ 100,000 element draws trong quy trình nguyên thủy. Nhiều resamples làm distribution estimate mượt hơn nhưng không biến n=100 thành 100,000 independent observations.","trap":""},{"heading":"6. Bootstrap standard error from estimated statistic replicates","body":"Từ θ̂₁,...,θ̂ᴮ, tính average θ̄* rồi sample SD across B statistics: SE_boot≈√[Σ(θ̂ᵦ−θ̄*)²/(B−1)]. Dùng B−1 như sample variance across bootstrap estimates. Đơn vị của SE cùng đơn vị của statistic được ước lượng.","trap":""},{"heading":"7. Bootstrap can estimate uncertainty of a median","body":"Formula s/√n thuộc standard error of sample MEAN, không phải standard error of sample MEDIAN. Với median, bootstrap lập nhiều resamples, tính median mỗi resample rồi xem dispersion. Tương tự có thể thực nghiệm confidence intervals cho một số estimators phức tạp khi analytical methods không thuận tiện.","trap":""},{"heading":"8. Bootstrap for finance applications","body":"Dùng trong đánh giá dispersion của strategy Sharpe/active return estimates, backtest uncertainty, asset allocation scenarios dựa historical sample. Nếu stress regime hiếm không nằm trong sample, plain historical bootstrap không tự mô hình hóa tail đó. Các applications phải giữ time horizon, compounding và cross-asset relationship phù hợp.","trap":""},{"heading":"9. IID bootstrap limitation for serially correlated returns","body":"Nếu monthly returns autocorrelated mà randomly resample individual months, bạn phá cấu trúc serial dependence. Có thể dùng block bootstrap trong nghiên cứu cao hơn, nhưng đó là extension chứ không phải prescribed core formulas ở LOS 7.c. Cần nói assumptions; không khẳng định naive bootstrap luôn valid cho mọi time series.","trap":""},{"heading":"10. Jackknife procedure, step by step","body":"Từ original observations x₁,...,xₙ, lần lượt bỏ x₁, rồi x₂, ..., đến xₙ; mỗi replicate có n−1 observations, không thay thế. Tính θ̂_(−i) trên mỗi leave-one-out dataset; có n deterministic replicates. Khác bootstrap vì không chọn random samples with replacement.","trap":""},{"heading":"11. Bootstrap versus jackknife: essential differences","body":"Bootstrap: resample n items WITH replacement, B random replicates; repeated runs có thể khác do random seed. Jackknife: từng lần OMIT một item, n replicates size n−1, deterministic given original data và estimator. Jackknife thường đơn giản tính toán hơn; bootstrap linh hoạt cho distribution của estimator phức tạp.","trap":""},{"heading":"12. Jackknife for estimation bias and SE","body":"Jackknife thường dùng để đánh giá/reduce estimator bias, estimate standard errors, đôi khi xây intervals. Với leave-one-out estimates θ̂_(−i), sample variation của replicates được scale phù hợp để có jackknife SE. Không được lấy raw SD của n leave-one-out means và tự xem là SE thông thường nếu chưa scale.","trap":""},{"heading":"13. Correct jackknife standard error scaling (extension)","body":"Conventional jackknife SE=√[(n−1)/n × Σ(θ̂_(−i)−θ̄_(−))²]. Factor (n−1)/n×SUM, không phải 1/(n−1) đơn thuần. Hữu ích để hiểu vì sao nhiều near-identical leave-one-out means vẫn có nonzero SE; curriculum chỉ yêu cầu describe use of jackknife, công thức này là explanatory extension.","trap":""},{"heading":"14. Jackknife and mean: an analytical special case","body":"Với statistic mean, leave-one-out means là (n x̄−xi)/(n−1). Jackknife SE của mean khớp s/√n dưới usual independent-sample setting. Đây là cross-check đơn giản có thể kiểm thử bằng vài numbers; không mặc nhiên mở rộng equality sang median và nonlinear estimators.","trap":""},{"heading":"15. Resampling estimation versus Monte Carlo modeling","body":"Module 6 Monte Carlo thường tạo random outcomes từ ASSUMED probability model/estimated parameters; basic bootstrap Module 7 lấy draws từ empirical data được quan sát. Cả hai có repeated simulation nhưng source of randomness khác. Bootstrap chỉ phản ánh phạm vi observed sample; Monte Carlo kết quả nhạy với assumed model.","trap":""},{"heading":"16. Resampling exam workflow and interpretation","body":"(1) Xác định statistic quan tâm: mean, median, Sharpe, etc. (2) Mô tả bootstrap replacement / jackknife omission. (3) Phân biệt n versus B. (4) Nếu đề cung cấp resample estimates, tính sample SD across estimates với B−1. (5) Đọc kỹ units và number of replicates. (6) Nêu limitation data quality, tail coverage, dependence và nonrepresentativeness.","trap":""}],"formulas":[{"name":"Bootstrap resample size","expr":"n* = n","meaning":"Each bootstrap sample has same size as original sample.","conditions":"Simple ordinary nonparametric bootstrap."},{"name":"Bootstrap replicate mean","expr":"θ̂*ᵦ=(1/n)Σⱼ x*ᵦ,ⱼ","meaning":"When the statistic is the mean, compute it on each resample.","conditions":"Bootstrap with replacement."},{"name":"Mean across B bootstrap statistics","expr":"θ̄*=(1/B)Σᵦ θ̂*ᵦ","meaning":"Center of empirical bootstrap sampling distribution.","conditions":"B≥1."},{"name":"Bootstrap estimated standard error","expr":"SE_boot=√{[Σᵦ(θ̂*ᵦ−θ̄*)²]/(B−1)}","meaning":"Sample SD of B bootstrap estimates.","conditions":"B>1, same statistic on every bootstrap resample."},{"name":"Bootstrap total element draws","expr":"total draws = n×B","meaning":"Operational count when each resample contains n draws.","conditions":"Basic bootstrap, no block sampling."},{"name":"Jackknife leave-one-out sample size","expr":"n_jack=n−1","meaning":"Each resample omits one observation.","conditions":"Original n≥2."},{"name":"Jackknife number of replicates","expr":"B_jack=n","meaning":"One leave-one-out replicate per original observation.","conditions":"Standard delete-one jackknife."},{"name":"Leave-one-out mean","expr":"x̄_(−i)=(n x̄−xᵢ)/(n−1)","meaning":"Efficient calculation of leave-one-out sample means.","conditions":"n>1."},{"name":"Mean jackknife estimate","expr":"θ̄_(−)=(1/n)Σᵢθ̂_(−i)","meaning":"Average across jackknife replicate statistics.","conditions":"Original sample has n observations."},{"name":"Jackknife SE (extension)","expr":"SE_jack=√{[(n−1)/n]Σᵢ[θ̂_(−i)−θ̄_(−)]²}","meaning":"Scaled dispersion of jackknife replicates.","conditions":"Smooth estimators and usual delete-one jackknife assumptions."},{"name":"Jackknife bias estimate (extension)","expr":"bias_jack=(n−1)[θ̄_(−)−θ̂_full]","meaning":"Approximate bias from leave-one-out estimates.","conditions":"Appropriate smooth estimator; this is extension, not core computation requirement."}],"examples":[{"question_en":"An original dataset contains [2, 4, 8, 10]. Is [10, 10, 2, 4] a valid ordinary bootstrap resample?","steps_vi":["Mỗi item phải thuộc original; có replacement.","10 appears twice and 8 does not appear, both allowed."],"answer":"Yes; it is a valid size-4 bootstrap sample.","check":""},{"question_en":"A dataset contains 80 observations and an analyst generates 500 standard bootstrap samples. How many draws are made in total?","steps_vi":["n=80, B=500.","Draws=80×500."],"answer":"40,000 draws.","check":""},{"question_en":"An analyst has 6 observations. Standard delete-one jackknife produces how many replicates, and what is the size of each?","steps_vi":["n replicates, each excluding one original item.","n=6 ⇒ 6 replicates size 5."],"answer":"6 replicates, 5 observations each.","check":""},{"question_en":"Bootstrap replicate means are 2, 4, 6, and 8. Calculate the average across the four estimates.","steps_vi":["θ̄*=(2+4+6+8)/4=5."],"answer":"5.00","check":""},{"question_en":"Bootstrap replicate means are 2, 4, 6, and 8. Estimate the standard error using the sample SD of these four estimates.","steps_vi":["Mean=5, squared differences=9+1+1+9=20.","Sample variance=20/(4−1)=20/3.","SE_boot=√(20/3)≈2.582."],"answer":"≈2.582","check":""},{"question_en":"For a sample [3, 6, 9, 12], list the four leave-one-out jackknife sample means.","steps_vi":["Omit 3: (6+9+12)/3=9.","Omit 6: (3+9+12)/3=8.","Omit 9: (3+6+12)/3=7.","Omit 12: (3+6+9)/3=6."],"answer":"Jackknife means: 9, 8, 7, 6.","check":""},{"question_en":"An analyst has 10 original returns and wants 1,000 ordinary bootstrap replicates. How large is each bootstrap sample?","steps_vi":["Bootstrap uses resample size equal original n=10; B affects replicate count only."],"answer":"10 observations per resample.","check":""},{"question_en":"A sample has n=5 and full-sample mean 10. If one observation is 6, find the mean after omitting that observation.","steps_vi":["x̄_(−i)=(5×10−6)/(5−1)=44/4."],"answer":"11.00","check":""},{"question_en":"Four bootstrap statistic estimates are [0.01, 0.03, 0.03, 0.05]. Calculate bootstrap standard error.","steps_vi":["Mean=.03.","Squared deviations=.0004+0+0+.0004=.0008.","Sample variance=.0008/3; square root≈.0163299."],"answer":"≈0.01633 (1.633 percentage points if returns are decimal).","check":""},{"question_en":"An analyst reports B=101 bootstrap replicate estimates whose squared deviations sum to 0.25. Estimate bootstrap standard error.","steps_vi":["SE=√(0.25/(101−1))=√(.0025)."],"answer":"0.0500","check":""},{"question_en":"The original sample is [1, 3, 5]. What is the median of the bootstrap resample [5, 5, 1]?","steps_vi":["Sort [1,5,5]; middle observation=5."],"answer":"Median 5.","check":""},{"question_en":"The original sample is [2, 2, 6, 10]. A bootstrap resample is [2, 6, 6, 10]. Calculate its mean.","steps_vi":["Sum=24; n=4.","Mean=24/4=6."],"answer":"6.00","check":""},{"question_en":"A sample [2, 4, 6] has original mean 4. Compute its three jackknife leave-one-out means.","steps_vi":["Omit 2 => (4+6)/2=5.","Omit 4 => (2+6)/2=4.","Omit 6 => (2+4)/2=3."],"answer":"5, 4, and 3.","check":""},{"question_en":"For leave-one-out means [5, 4, 3] from n=3 original observations, compute the scaled jackknife standard error.","steps_vi":["Average=4; deviations squared: 1,0,1; sum=2.","SE_jack=√[(n−1)/n×sum]=√[(2/3)×2]=√(4/3)."],"answer":"≈1.1547 (jackknife SE).","check":""},{"question_en":"For the original sample [2, 4, 6], compute the classical estimated standard error of its mean and compare with the jackknife result.","steps_vi":["Sample mean=4; squared deviations=4+0+4=8; s²=8/(3−1)=4.","s=2, estimated SE=2/√3≈1.1547."],"answer":"≈1.1547; equal to mean jackknife SE in this example.","check":""}],"questions":[{"stem_en":"In ordinary nonparametric bootstrapping, each resample is drawn:","options":["Without replacement and smaller than the original sample","With replacement and of the same size as the original sample","With replacement and necessarily larger than the original sample"],"correct":1,"why_vi":"Bootstrap: n draws with replacement per replicate.","trap_vi":""},{"stem_en":"A jackknife resample is typically formed by:","options":["Omitting one original observation at a time","Taking n observations with replacement","Drawing from a specified lognormal price model"],"correct":0,"why_vi":"Jackknife delete-one: leave one out, no replacement.","trap_vi":""},{"stem_en":"If an original sample has n=40 observations, the number of standard delete-one jackknife replicates is:","options":["39","1,600","40"],"correct":2,"why_vi":"n jackknife replicates; size each n−1=39.","trap_vi":""},{"stem_en":"With n=40 and B=1,000 standard bootstrap resamples, the number of individual draws is:","options":["40,000","1,040","960"],"correct":0,"why_vi":"n×B=40×1000=40,000.","trap_vi":""},{"stem_en":"Which sample can result from ordinary bootstrap resampling of [1, 3, 5]?","options":["[1, 3, 7]","[5, 5, 1]","[1, 5]"],"correct":1,"why_vi":"Item repeats allowed; length must equal n=3 and observations in original.","trap_vi":""},{"stem_en":"A primary purpose of bootstrap resampling is to estimate:","options":["The exact future path of a stock","A predetermined population parameter without uncertainty","The sampling distribution of a statistic"],"correct":2,"why_vi":"Distribution of replicate estimates approximates estimator sampling distribution.","trap_vi":""},{"stem_en":"An original sample contains 50 observations. Each ordinary bootstrap sample contains:","options":["50 observations","49 observations","B observations where B is the number of resamples"],"correct":0,"why_vi":"Bootstrap resample size n=50.","trap_vi":""},{"stem_en":"The sampling distribution of a median is difficult to calculate analytically. A useful approach is:","options":["Use s/√n as an exact median SE","Bootstrap resample medians and estimate their dispersion","Set the median standard error to zero"],"correct":1,"why_vi":"s/√n for mean; bootstrap applicable for median.","trap_vi":""},{"stem_en":"Which statement about bootstrap replicate count B is most accurate?","options":["B is always equal to the original sample size","Increasing B creates new information about missing historical regimes","Increasing B reduces numerical simulation noise but not original data bias"],"correct":2,"why_vi":"B larger => more stable empirical bootstrap distribution; not more original observations.","trap_vi":""},{"stem_en":"Jackknife normally produces resamples of size:","options":["n−1","n","n+1"],"correct":0,"why_vi":"Leave one observation out per replicate.","trap_vi":""},{"stem_en":"Which resampling method is deterministic given the original dataset and statistic in its ordinary form?","options":["Random bootstrap","Delete-one jackknife","Monte Carlo with fresh independent random draws"],"correct":1,"why_vi":"Every leave-one-out dataset fixed, no random seed.","trap_vi":""},{"stem_en":"Bootstrap estimated standard error from B replicate statistic estimates is generally their:","options":["Population sum without centering","Absolute maximum","Sample standard deviation"],"correct":2,"why_vi":"SE_boot = sample SD across replicate estimates.","trap_vi":""},{"stem_en":"Four bootstrap mean estimates are 2, 4, 6, and 8. Their estimated standard error is closest to:","options":["2.58","5.00","6.67"],"correct":0,"why_vi":"Mean=5, sum squared deviations=20, sample SD=sqrt(20/3)=2.582.","trap_vi":""},{"stem_en":"For original data [2, 4, 6], omitting 4 leaves a jackknife mean of:","options":["3","4","5"],"correct":1,"why_vi":"(2+6)/2=4.","trap_vi":""},{"stem_en":"For n=8 observed returns, delete-one jackknife produces which combination?","options":["Seven replicates of size eight","Eight replicates of size eight","Eight replicates of size seven"],"correct":2,"why_vi":"One omitted at a time: n samples, n−1 members.","trap_vi":""},{"stem_en":"An analyst has correlated monthly returns. Randomly resampling individual months with replacement may be problematic because it:","options":["Discards serial dependence","Always increases the number of historical observations","Forces every bootstrapped mean to zero"],"correct":0,"why_vi":"IID bootstrap thay đổi structure time dependence.","trap_vi":""},{"stem_en":"Which is the most important limitation of bootstrap resampling from an incomplete database?","options":["It requires a population to be exactly normal","It cannot recover historical regimes absent from the observed dataset","It always gives precisely the same random samples"],"correct":1,"why_vi":"Dựa vào empirical observed data, không tạo tail missing có căn cứ.","trap_vi":""},{"stem_en":"A jackknife sample with n=5 has how many observations after deleting one?","options":["3","5","4"],"correct":2,"why_vi":"n−1=4.","trap_vi":""},{"stem_en":"An original sample contains [4, 4, 8]. Which is a valid ordinary bootstrap sample?","options":["[8, 8, 4]","[8, 4]","[8, 8, 10]"],"correct":0,"why_vi":"Length=3 and draws from observed set with repeats allowed.","trap_vi":""},{"stem_en":"What is the conceptual difference between basic bootstrap and parametric Monte Carlo simulation?","options":["Both always assume the same theoretical normal distribution","Bootstrap resamples observed data; Monte Carlo samples from a specified probabilistic model","Bootstrap is necessarily a nonrandom algorithm"],"correct":1,"why_vi":"Nguồn generated trials khác: empirical sample vs assumed model.","trap_vi":""},{"stem_en":"One hundred bootstrap statistics have squared deviations summing to 0.99. The estimated standard error is:","options":["0.99","0.001","0.10"],"correct":2,"why_vi":"sqrt(0.99/(100−1))=sqrt(.01)=.10.","trap_vi":""},{"stem_en":"Which statement about the bootstrap result is least defensible?","options":["Bootstrap guarantees correction of survivorship bias in the original data","Bootstrap can approximate the sampling distribution of complex statistics","Bootstrap can be used to quantify variability of a sample median"],"correct":0,"why_vi":"Không thể xóa survivorship bias bằng resampling từ dữ liệu thiếu firms bị loại.","trap_vi":""}],"cards":[{"front_en":"What is resampling used for?","back_vi":"Ước lượng empirical sampling distribution của statistic khi analytical distribution khó tính."},{"front_en":"Bootstrap replacement rule?","back_vi":"Sample n data points WITH replacement từ original sample."},{"front_en":"Bootstrap resample size?","back_vi":"Mỗi bootstrap replicate có size n như original sample."},{"front_en":"Meaning of B in bootstrap?","back_vi":"Số independent resample repetitions/statistic estimates."},{"front_en":"Why can bootstrap samples contain repeats?","back_vi":"Drawn with replacement nên observation có thể lặp hoặc không xuất hiện."},{"front_en":"Bootstrap estimated standard error formula?","back_vi":"Sample SD of B resampled statistics, denominator B−1."},{"front_en":"Can bootstrap approximate median standard error?","back_vi":"Có, compute median mỗi resample rồi dispersion của các medians."},{"front_en":"Does a larger B increase original sample information?","back_vi":"Không; B chỉ giảm MC noise của resampling."},{"front_en":"Delete-one jackknife sample size and count?","back_vi":"n replicates, each contains n−1 observations."},{"front_en":"What is jackknife often used to assess?","back_vi":"Estimator bias và standard error; đôi khi confidence interval."},{"front_en":"Is ordinary jackknife random each run?","back_vi":"Không; leave-one-out deterministic given original data."},{"front_en":"Key difference: bootstrap vs jackknife?","back_vi":"Bootstrap WITH replacement and B random repeats; jackknife OMIT each observation once."},{"front_en":"Leave-one-out mean formula?","back_vi":"(n x̄−xi)/(n−1)."},{"front_en":"Scaled jackknife standard error (extension)?","back_vi":"√[(n−1)/n × Σ(θ̂_(−i)−θ̄_(−))²]."},{"front_en":"Resampling versus Monte Carlo?","back_vi":"Bootstrap draws empirical observed observations; Monte Carlo samples specified stochastic model."},{"front_en":"What is a common bootstrap issue in finance time series?","back_vi":"IID resampling may destroy serial correlation; block methods are extensions."},{"front_en":"Can resampling correct missing-bankruptcy survivorship bias by itself?","back_vi":"Không, bootstrap vẫn phụ thuộc original data có representative hay không."},{"front_en":"When might resampling be especially helpful?","back_vi":"Statistic phức tạp như median, Sharpe ratio, percentile với analytic SE khó."}]}]},{"version":"2026.11.22-quant8-sourcefirst-01","module_id":"CFA26-01-08","module_title":"Hypothesis Testing","language":"Vietnamese explanations with English terms; original English MCQs and choices; bilingual flashcards","qa_status":"SOURCE_MAPPED_SELF_STUDY_DRAFT_PENDING_FULL_ACADEMIC_APPROVAL","disclaimer_vi":"Đây là học liệu tự biên soạn, không sao chép câu hỏi thương mại. CFAI 2026 Quant PDF trang vật lý 232 có lỗi bất nhất ở chi-square test Ha variance < threshold: lower-tail reject-if-less-than nhưng nguồn in reject-if-greater và kết luận reject. Bản này công khai phân biệt source error với quy tắc toán đúng; không coi mọi nội dung khác đã kiểm toán toàn diện. Các công thức extension được đánh dấu.","los":[{"id":"CFA26-01-08-LOS01","letter":"8.a","title_en":"Hypothesis-Testing Framework, Errors, and Power","outcome_en":"Explain hypothesis testing and its components, including statistical significance, Type I and Type II errors, and the power of a test.","overview_vi":"LOS 8.a tập trung vào tư duy ra quyết định từ sample: H₀/Ha, mức ý nghĩa α, test statistic, critical values, p-values, Type I/II errors, test power và statistical versus economic significance. Cần nói đúng “fail to reject” chứ không kết luận chứng minh H₀ đúng. Thủ tục sáu bước phải gắn với bối cảnh quản lý quỹ và rủi ro quyết định.","source":[{"id":"CFA Institute Curriculum 2026 — Quant LM8","pages":"223–230 (physical PDF; LOS 8.a, hypothesis framework and errors)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 8","pages":"87–92 (physical PDF; process, tails, errors and power)"},{"id":"SAPP Quant Slide Notes 2026 — Module 8","pages":"307–339 (physical PDF; core 8.a and prerequisite context)"}],"sections":[{"heading":"1. What a hypothesis test actually establishes","body":"Hypothesis testing đánh giá mức độ tương thích của sample evidence với một phát biểu cụ thể về population parameter (hoặc một giả định khác). Không phải chứng minh một giả thuyết đúng 100%. Ví dụ, quỹ tự tuyên bố expected abnormal return bằng 0; sample chỉ cung cấp evidence để bác bỏ hoặc không bác bỏ tại một mức α.","trap":""},{"heading":"2. Null hypothesis H₀ versus alternative Hₐ","body":"H₀ là baseline statement, thường có dấu = (hoặc inequality gồm equality với one-tailed test). Hₐ là claim cần evidence ủng hộ như μ≠μ₀, μ>μ₀, hoặc μ<μ₀. Hướng Hₐ xác định miền bác bỏ; không đổi hướng kiểm định chỉ vì sample result bất ngờ.","trap":""},{"heading":"3. A six-step hypothesis-testing workflow","body":"(1) State H₀ and Hₐ; (2) choose test statistic and distribution given assumptions; (3) specify significance α; (4) establish rejection rule/critical values; (5) collect sample data and compute test statistic; (6) reject or fail to reject H₀ and explain economically. Pre-specification giúp tránh “đổi luật khi thấy kết quả”.","trap":""},{"heading":"4. One-tailed versus two-tailed tests","body":"Hₐ: μ>μ₀ ⇒ right-tailed; Hₐ: μ<μ₀ ⇒ left-tailed; Hₐ: μ≠μ₀ ⇒ two-tailed. Với normal Z tại α=5%: two-tail critical values ±1.96; right-tail +1.645; left-tail −1.645. One-tailed không có automatic “một nửa alpha” ở cả hai phía.","trap":""},{"heading":"5. Test statistic and its null distribution","body":"Test statistic gom sample evidence thành con số chuẩn hóa (vd t=(x̄−μ₀)/(s/√n)). Under H₀ và assumptions, biết sampling distribution để xác định extreme observations. Test statistic khác critical value: một bên từ data, một bên từ α và null reference distribution.","trap":""},{"heading":"6. Critical values and rejection regions","body":"Critical values chia distribution thành rejection region và non-rejection region. Nếu test statistic rơi vùng đuôi phù hợp Ha, reject H₀. Ví dụ z=2.10 cho two-sided α=5% vượt +1.96 nên reject; z=1.80 chưa vượt +1.96 nên fail to reject. Đọc rõ tail và chiều bất đẳng thức.","trap":""},{"heading":"7. P-value: definition and correct interpretation","body":"p-value là xác suất, giả sử H₀ đúng, quan sát test statistic ít nhất extreme như thống kê đã thấy theo hướng Hₐ. Nếu p≤α thì reject H₀. p=0.03 KHÔNG có nghĩa P(H₀ true | observed data)=3%; cũng không phải xác suất Type I error của riêng kết luận sau khi nhìn data.","trap":""},{"heading":"8. Significance α is a long-run Type I error rate","body":"α=P(reject H₀ | H₀ true). α=0.05 cho biết với H₀ thật và kiểm định hợp lệ, xác suất false rejection theo procedure là 5% trong repeated use. Đây không phải “95% xác suất giả thuyết nghiên cứu đúng”. Confidence level thường =1−α trong tương ứng two-sided CI framework.","trap":""},{"heading":"9. Type I error = false positive","body":"Type I: bác bỏ một H₀ đúng. Ví dụ tuyên bố manager có alpha >0 dù alpha thật =0. Hệ quả có thể là mua chiến lược không tạo giá trị. Probability α under H₀ và test assumptions; tăng stringency (giảm α) thường giảm Type I nhưng làm khó phát hiện effect.","trap":""},{"heading":"10. Type II error = false negative","body":"Type II: fail to reject một H₀ sai. Ví dụ bỏ qua một chiến lược thật sự tạo alpha khi test có ít observations. Probability β phụ thuộc effect size, n, variance, α, assumptions; β không tự bằng 1−α và không thể tính chỉ từ α khi không biết alternative distribution.","trap":""},{"heading":"11. Power = 1−β","body":"Power là probability correct rejection khi H₀ false. Test có power 80% ⇒ β=20% tại specific true effect. Increasing sample size, larger true effect hoặc lower noise thường cải thiện power; α cố định. Không nói power là xác suất H₀ sai.","trap":""},{"heading":"12. Trade-off between Type I and Type II errors","body":"Giữ n/effect/variance không đổi, giảm α từ 5% xuống 1% thu hẹp rejection region, thường tăng β và giảm power. Tăng sample size có thể giảm cả risks bằng cách tăng precision. Lựa chọn α tùy cost of false positive vs false negative trong investment decision.","trap":""},{"heading":"13. Two-by-two decision table","body":"H₀ true + fail reject → correct (1−α). H₀ true + reject → Type I α. H₀ false + fail reject → Type II β. H₀ false + reject → correct (power 1−β). Bốn outcome này áp cho mọi hợp lệ parametric/nonparametric tests, không phải 4 p-values.","trap":""},{"heading":"14. Fail to reject H₀ is not accept H₀","body":"Evidence chưa đủ bác bỏ H₀ không tương đương chứng minh không có effect; sample có thể thiếu power. Câu trả lời thi nên nói “insufficient evidence to reject H₀” thay vì “H₀ is true” hoặc “H₀ accepted”. Điều này đặc biệt quan trọng nếu effect economically relevant nhưng sample nhỏ.","trap":""},{"heading":"15. Statistical versus economic significance","body":"Một effect 0.02% có thể statistically significant nếu sample rất lớn, nhưng sau transaction costs/taxes không hấp dẫn. Một 3% alpha quan trọng về kinh tế có thể không statistical significant nếu noisy observations. Quyết định đầu tư cần đánh giá cả magnitude và uncertainty, không chỉ p<0.05.","trap":""},{"heading":"16. Confidence interval decision equivalence","body":"Với cùng two-sided α và assumptions, reject H₀:μ=μ₀ nếu μ₀ nằm ngoài 100(1−α)% confidence interval. Đó là một kiểm tra nhất quán với t/z decision, không phải lời khẳng định μ là random variable với probability posterior. One-sided intervals cần điều chỉnh phù hợp.","trap":""},{"heading":"17. Multiple testing caution (labelled extension)","body":"Nếu thử hàng trăm trading rules ở α=5%, một phần false positives có thể phát sinh ngẫu nhiên dù từng test được thực hiện đúng. Multiple-testing correction/holdout samples là extension ngoài trọng tâm LOS 8.a; trong thực tế phản biện backtests cần phân biệt discovered pattern với replicated evidence.","trap":""},{"heading":"18. Exam checklist for testing decisions","body":"Hãy viết đúng H₀/Ha theo hướng claim; chọn tail trước khi tính; xác định α; đọc test statistic signs; so critical value hoặc p; phát biểu “reject/fail to reject” và diễn giải trong đơn vị returns/variance. Khi có power, nhớ β=1−power, không nhầm 1−α.","trap":""}],"formulas":[{"name":"Type I error rate","expr":"α=P(reject H₀ | H₀ true)","meaning":"Significance level; false positive rate conditional on true null.","conditions":""},{"name":"Type II error rate","expr":"β=P(fail to reject H₀ | H₀ false)","meaning":"False negative rate at a specified alternative.","conditions":""},{"name":"Power","expr":"power=1−β","meaning":"P(correctly reject a false null).","conditions":""},{"name":"Confidence-level complement","expr":"confidence level =1−α","meaning":"For corresponding confidence interval interpretation.","conditions":""},{"name":"P-value decision rule","expr":"reject H₀ if p≤α","meaning":"Compare sample p-value with preselected significance.","conditions":""},{"name":"Standard normal two-tail 5% cutoff","expr":"|z|>1.96 ⇒ reject H₀ (α=0.05)","meaning":"Two-sided normal-reference critical region.","conditions":""},{"name":"Standard normal right-tail 5% cutoff","expr":"z>1.645 ⇒ reject H₀ (α=0.05)","meaning":"Right-sided normal-reference critical region.","conditions":""},{"name":"Standard normal left-tail 5% cutoff","expr":"z<−1.645 ⇒ reject H₀ (α=0.05)","meaning":"Left-sided normal-reference critical region.","conditions":""},{"name":"One-sample mean t statistic","expr":"t=(x̄−μ₀)/(s/√n)","meaning":"Test single population mean with unknown population variance.","conditions":"Normal population (small sample) or suitable large-sample approximation; df=n−1."},{"name":"Pooled decision rule","expr":"p≤α ↔ statistic in rejection region","meaning":"Equivalent procedures under same reference distribution and tail.","conditions":"Correctly computed p-value, α and tail."}],"examples":[{"question_en":"A two-sided z-test at 5% significance produces z=2.20. What is the decision?","steps_vi":["Two-sided critical values: ±1.96.","2.20>1.96 ⇒ reject H₀."],"answer":"Reject H₀.","check":""},{"question_en":"A right-tailed z-test at 5% significance produces z=1.40. What is the decision?","steps_vi":["Right-tail critical +1.645.","1.40<1.645 ⇒ insufficient evidence."],"answer":"Fail to reject H₀.","check":""},{"question_en":"A left-tailed z-test at 5% significance produces z=−1.80. What is the decision?","steps_vi":["Left-tail critical −1.645.","−1.80<−1.645 ⇒ reject H₀."],"answer":"Reject H₀.","check":""},{"question_en":"A test uses α=1% and produces p=0.023. What decision follows?","steps_vi":["Compare p=.023 with α=.01.",".023>.01 ⇒ fail to reject."],"answer":"Fail to reject H₀.","check":""},{"question_en":"A test has Type II error probability β=0.18. Calculate its power.","steps_vi":["Power=1−β=1−.18."],"answer":"82%","check":""},{"question_en":"A test has 90% power for a specified true effect. What is β?","steps_vi":["β=1−power=1−.90."],"answer":"10%","check":""},{"question_en":"A two-sided test has α=0.04. How much nominal rejection probability is assigned to each tail under a symmetric reference distribution?","steps_vi":["Each tail α/2=.04/2."],"answer":"2% per tail.","check":""},{"question_en":"An investment test has p=0.004 and a preset 5% significance level. State the statistical decision.","steps_vi":["0.004<0.05."],"answer":"Reject H₀.","check":""},{"question_en":"An analyst uses α=0.05 and has β=0.35 at a particular alternative. Identify power.","steps_vi":["Power=1−.35=.65."],"answer":"65%","check":""},{"question_en":"For a two-sided normal z-test, the observed z-statistic is −2.30. At 5% significance, what decision applies?","steps_vi":["Critical lower value −1.96.","−2.30<−1.96."],"answer":"Reject H₀.","check":""},{"question_en":"A two-sided 95% confidence interval for a population mean is [3%, 7%]. Test H₀: μ=5% at 5% significance using interval logic.","steps_vi":["5% is inside [3%,7%]."],"answer":"Fail to reject H₀.","check":""},{"question_en":"A two-sided 95% confidence interval for the same parameter is [3%, 7%]. Test H₀: μ=8% at 5% significance.","steps_vi":["8% lies outside [3%,7%]."],"answer":"Reject H₀.","check":""},{"question_en":"A researcher selects α=0.10. What is the corresponding confidence level?","steps_vi":["1−α=1−.10."],"answer":"90%","check":""}],"questions":[{"stem_en":"Which hypothesis typically includes the equality condition?","options":["The alternative hypothesis","The null hypothesis","Neither hypothesis"],"correct":1,"why_vi":"H₀ thường chứa equality hoặc inequality có equality; Ha mang claim directional/two-sided.","trap_vi":""},{"stem_en":"To test whether a manager’s mean alpha is greater than zero, the appropriate alternative hypothesis is:","options":["Hₐ: μ>0","Hₐ: μ=0","Hₐ: μ<0"],"correct":0,"why_vi":"“Greater than” ⇒ right-tailed Ha.","trap_vi":""},{"stem_en":"A research question asks whether mean return differs from 5%. The alternative hypothesis is:","options":["Hₐ: μ>5%","Hₐ: μ<5%","Hₐ: μ≠5%"],"correct":2,"why_vi":"“Differs” ⇒ two-tailed.","trap_vi":""},{"stem_en":"A 5% significance level is best interpreted as:","options":["A 5% probability that the null is true","A 5% probability of rejecting a true null under the test procedure","A 95% probability that the alternative is true"],"correct":1,"why_vi":"α=P(Type I error | H₀ true).","trap_vi":""},{"stem_en":"A Type I error occurs when an analyst:","options":["Rejects a true null hypothesis","Fails to reject a false null hypothesis","Correctly rejects a false null hypothesis"],"correct":0,"why_vi":"False positive = Type I.","trap_vi":""},{"stem_en":"A Type II error occurs when an analyst:","options":["Correctly fails to reject a true null","Rejects a false null","Fails to reject a false null"],"correct":2,"why_vi":"False negative = Type II.","trap_vi":""},{"stem_en":"The power of a test equals:","options":["1−α","1−β","α+β"],"correct":1,"why_vi":"Power=P(reject H₀ | H₀ false)=1−β.","trap_vi":""},{"stem_en":"If β=0.25, the power of the test is:","options":["75%","25%","95%"],"correct":0,"why_vi":"1−0.25=0.75.","trap_vi":""},{"stem_en":"A test has 90% power under a particular true alternative. Its probability of a Type II error is:","options":["90%","5%","10%"],"correct":2,"why_vi":"β=1−power=.1.","trap_vi":""},{"stem_en":"A two-sided standard normal test uses α=5%. Rejection occurs when:","options":["z>1.645 only","|z|>1.96","z<0"],"correct":1,"why_vi":"Two-tail α=.05 critical ±1.96.","trap_vi":""},{"stem_en":"A right-tailed normal z-test at 5% significance yields z=1.80. The decision is to:","options":["Reject H₀","Fail to reject H₀","Accept H₀ as proven true"],"correct":0,"why_vi":"z=1.80>+1.645.","trap_vi":""},{"stem_en":"A left-tailed normal z-test at 5% significance yields z=−1.20. The decision is to:","options":["Reject H₀","Accept H₀","Fail to reject H₀"],"correct":2,"why_vi":"−1.20 is not <−1.645; insufficient evidence.","trap_vi":""},{"stem_en":"An analyst obtains p=0.03 with preselected α=0.05. The proper decision is:","options":["Fail to reject H₀","Reject H₀","Conclude P(H₀ true)=3%"],"correct":1,"why_vi":"p<α => reject.","trap_vi":""},{"stem_en":"Which p-value interpretation is correct?","options":["The probability, assuming H₀ true, of a statistic at least as extreme as observed","The posterior probability that H₀ is true","The power of the test"],"correct":0,"why_vi":"Frequentist p-value conditioned on H₀.","trap_vi":""},{"stem_en":"Failing to reject a null hypothesis means:","options":["The null is established to be true","The alternative is impossible","There is insufficient evidence to reject the null at the specified level"],"correct":2,"why_vi":"Fail to reject ≠ accept H₀ as proven.","trap_vi":""},{"stem_en":"Holding sample size, effect and variance fixed, decreasing α will usually:","options":["Increase power and decrease β","Decrease power and increase β","Eliminate all decision errors"],"correct":1,"why_vi":"Rejection region smaller => lower Type I, higher Type II conditional on alternative.","trap_vi":""},{"stem_en":"Which change can commonly raise power while keeping α fixed?","options":["Increasing sample size","Decreasing true effect size","Increasing measurement noise"],"correct":0,"why_vi":"More precision improves discrimination under assumptions.","trap_vi":""},{"stem_en":"A manager’s alpha estimate is statistically significant but smaller than transaction costs. This most directly illustrates:","options":["No possible sampling error","A guaranteed Type I error","A distinction between statistical and economic significance"],"correct":2,"why_vi":"Economic attractiveness phụ thuộc magnitude net costs, không chỉ p.","trap_vi":""},{"stem_en":"At a two-sided 5% test, a 95% confidence interval contains the hypothesized mean. The decision is usually to:","options":["Reject H₀","Fail to reject H₀","Claim H₀ has 95% probability"],"correct":1,"why_vi":"Consistent CI duality for same test.","trap_vi":""},{"stem_en":"Which statement regarding significance and power is accurate?","options":["A 5% α does not by itself determine power","Power always equals 95% when α=5%","β always equals α"],"correct":0,"why_vi":"β cần effect, variance, n, reference distribution.","trap_vi":""},{"stem_en":"A researcher specifies a one-tailed test after observing the sample sign. This practice is problematic because it:","options":["Makes the sample mean unbiased","Guarantees a valid p-value","Can distort the prespecified Type I error control"],"correct":2,"why_vi":"Direction must follow economic question before inspecting data.","trap_vi":""},{"stem_en":"A two-sided test with α=4% allocates approximately which probability to each tail under a symmetric null distribution?","options":["4%","2%","8%"],"correct":1,"why_vi":"α/2=.02 per tail.","trap_vi":""}],"cards":[{"front_en":"What is the null hypothesis H₀?","back_vi":"Baseline claim cần statistical evidence để reject; thường bao gồm equality condition."},{"front_en":"What determines the rejection tail?","back_vi":"Alternative hypothesis: > right, < left, ≠ two-sided."},{"front_en":"Six steps of a hypothesis test?","back_vi":"State hypotheses; choose statistic; set α; define decision rule; compute statistic; decide."},{"front_en":"Definition of test statistic?","back_vi":"Một statistic tính từ sample để so với null reference distribution/critical value."},{"front_en":"Meaning of α?","back_vi":"P(reject true H₀), Type I error probability."},{"front_en":"Meaning of β?","back_vi":"P(fail to reject false H₀), Type II error probability."},{"front_en":"Meaning of statistical power?","back_vi":"1−β=P(reject false H₀)."},{"front_en":"Type I vs Type II error?","back_vi":"Type I false positive; Type II false negative."},{"front_en":"Two-tailed 5% normal critical z?","back_vi":"±1.96."},{"front_en":"Right-tailed 5% normal critical z?","back_vi":"+1.645."},{"front_en":"Left-tailed 5% normal critical z?","back_vi":"−1.645."},{"front_en":"How to decide using p-value?","back_vi":"Reject H₀ if p≤α."},{"front_en":"Is p-value the probability H₀ is true?","back_vi":"Không; p-value conditional on H₀, not posterior probability."},{"front_en":"What does fail to reject H₀ mean?","back_vi":"Insufficient evidence; không chứng minh H₀ đúng."},{"front_en":"How does decreasing α affect β at fixed sample information?","back_vi":"Thường β tăng và power giảm."},{"front_en":"What tends to increase test power at fixed α?","back_vi":"Larger sample, larger true effect, lower noise."},{"front_en":"Statistical significance versus economic significance?","back_vi":"p-value cho evidence; magnitude net costs cho economic value."},{"front_en":"How is a two-sided confidence interval used for testing?","back_vi":"Reject H₀:μ=μ₀ nếu μ₀ nằm ngoài matching CI."}]},{"id":"CFA26-01-08-LOS02","letter":"8.b","title_en":"Construct Hypothesis Tests and Assess Statistical Significance","outcome_en":"Construct hypothesis tests and determine their statistical significance, the associated Type I and Type II errors, and power of the test given a significance level.","overview_vi":"LOS 8.b triển khai kiểm định mẫu thật: one-mean t/z, independent two-means pooled t, paired differences t, single population variance χ², equality of two variances F; xác định one/two-tail, degrees of freedom, critical values, p-value, Type I/II errors và power. Có một inconsistency rõ trong CFAI PDF vật lý trang 232: ví dụ left-tail variance dùng critical chi-square lower tail nhưng lại viết reject nếu statistic greater và kết luận reject; phép thử đúng là reject nếu statistic LESS than lower critical. Bài học này nêu công khai sự sai lệch nguồn và áp dụng quy tắc toán đúng.","source":[{"id":"CFA Institute Curriculum 2026 — Quant LM8","pages":"223–242 (physical PDF; 8.b and variance erratum p232)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 8","pages":"92–102 (physical PDF; mean t, paired, chi-square and F)"},{"id":"SAPP Quant Slide Notes 2026 — Module 8","pages":"340–369 (physical PDF; testing return and variance; correct left-tail derivation pp360–362)"}],"sections":[{"heading":"1. From the verbal claim to a testable Ha","body":"“Mean return below benchmark” ⇒ Ha: μ<μ₀; “different from benchmark” ⇒ Ha: μ≠μ₀; “greater” ⇒ Ha: μ>μ₀. Null contains the equality boundary. Cần chỉ rõ scale: testing population mean μ, difference μ1−μ2, population variance σ² hay variance ratio.","trap":""},{"heading":"2. Choosing test statistic by the parameter","body":"Single mean with σ unknown under normal/large-sample assumptions: t=(x̄−μ₀)/(s/√n), df=n−1. Known σ permits z=(x̄−μ₀)/(σ/√n). Independent two means require independent groups and appropriate variance assumptions; paired data require d differences; single variance χ²; two variances F. Đừng dùng z/t mean test để trực tiếp kiểm định population variance.","trap":""},{"heading":"3. Degrees of freedom matter","body":"For one-sample t: n−1. Paired t: number of pairs n−1. Equal-variance pooled independent t: n1+n2−2. Single variance χ²: n−1. F for variance ratio: df numerator=n1−1 and df denominator=n2−1. Cùng α nhưng df khác nhau cho critical values khác.","trap":""},{"heading":"4. One-sample mean t-test calculation","body":"Khi σ unknown, tính sample SE=s/√n, subtract null μ₀, divide, compare with t critical df n−1. Một sample of returns x̄=8%, μ₀=6%, s=5%, n=25 ⇒ t=2/(5/5)=2.00, chưa reject two-tail α=5% nếu df24 critical≈2.064. Cùng statistic=2.00 sẽ khác decision nếu one-tail right critical≈1.711.","trap":""},{"heading":"5. When a z approximation is sensible","body":"Known population σ => z exact if normal population or suitable large-sample result. With large n and unknown σ, t and z critical values gần nhau; t vẫn là theoretical reference khi σ unknown under stated model. Nếu population heavy-tailed hoặc sample rất nhỏ, reliance on large-n approximation may be invalid.","trap":""},{"heading":"6. One-sided and two-sided rejection boundaries","body":"Right-tail reject when t>t_(1−α,df) hoặc z>z_(1−α). Left-tail reject when t<t_(α,df) hoặc z<z_(α). Two-sided reject if |t|>t_(1−α/2,df). Đọc signs: for left tail, smaller/more negative values provide stronger evidence; for right tail, larger values.","trap":""},{"heading":"7. Independent-samples test of means: core assumptions","body":"Two populations unrelated, each sample independent; khi assume unknown but equal population variances và approximately normal assumptions, dùng pooled variance. Statistic compares x̄1−x̄2 with null difference δ₀ (thường 0). Không sử dụng paired formula khi observations thuộc hai populations không được match.","trap":""},{"heading":"8. Pooled variance and independent two-mean t-test","body":"s_p²=[(n1−1)s1²+(n2−1)s2²]/(n1+n2−2). SE difference=√[s_p²(1/n1+1/n2)]. t=[(x̄1−x̄2)−δ₀]/SE, df=n1+n2−2. Pooled estimator cần reasonable equal-variance assumption; không simply average SDs bằng (s1+s2)/2.","trap":""},{"heading":"9. Unequal variances and Welch (labelled extension)","body":"Nếu group variances clearly unequal, Welch t uses sqrt(s1²/n1+s2²/n2) và approximate degrees of freedom, không phải pooled df. Đây là complementary statistical context; CFAI 2026 LM8 phần main calculation tập trung pooled equal-variance case, nên đừng tự giả thiết Welch nếu đề nói equal variances.","trap":""},{"heading":"10. Paired comparisons: compare differences, not raw groups","body":"Paired data gồm observations matched by time, security, person, before/after; đặt di=Xi−Yi theo định nghĩa nhất quán. Dùng d̄, sd và SEd=sd/√n. t=(d̄−d0)/(sd/√n), df=n−1. Nếu có covariance d_i between paired components, paired design giữ thông tin kết nối và thường precision tốt hơn independent samples.","trap":""},{"heading":"11. Single population variance: chi-square test","body":"Nếu population normally distributed, H₀:σ²=σ₀² dùng χ²=(n−1)s²/σ₀², df=n−1. Statistic strictly nonnegative, χ² distribution skewed. Alternative σ²>σ₀² ⇒ right tail; σ²<σ₀² ⇒ LEFT tail; σ²≠σ₀² ⇒ two tails. Cần dùng variance chứ không đưa σ₀ (SD) vào denominator.","trap":""},{"heading":"12. Source correction: CFAI p232 chi-square tail-direction inconsistency","body":"CFA Institute Curriculum 2026 Quant physical PDF p232, Exhibit 6, viết Ha: variance LESS, critical χ² lower 5%≈13.0905 (df23), computed χ²=18.63, nhưng hướng dẫn “reject if greater” và kết luận reject. Với left-tailed test toán học, phải reject khi χ² <13.0905; vì 18.63>13.0905 nên phải FAIL TO REJECT H₀. Đây là lỗi bất nhất trong ví dụ nguồn được ghi rõ, không chép lại như đáp án đúng. Slide Quant pp360–362 lại đưa đúng rule χ²<13.091 và quyết định fail to reject, giúp đối chiếu độc lập. Ngoài ra nhãn variance 16 được trình bày theo đơn vị percent-squared, cần nhất quán với SD 4%.","trap":""},{"heading":"13. Two-population variance comparison: F test","body":"Under normality and independent samples, F=s1²/s2² follows F distribution if H₀:σ1²=σ2²; df1=n1−1 for numerator, df2=n2−1 for denominator. Với two-sided, critical rejection tails có area α/2 mỗi bên, không symmetric around 1. Có thể đặt larger observed sample variance trên numerator cho two-sided approach với upper critical convention nếu phù hợp, nhưng giữ đúng df tương ứng.","trap":""},{"heading":"14. Tests of mean and variance are distinct","body":"Mean t evaluates return level; chi-square or F evaluates dispersion/volatility. Hai quỹ có equal mean nhưng different variances; null mean test không đưa kết luận equality of variances và ngược lại. Trong thực tế variance tests nhạy với normality violation, cần ghi giả định.","trap":""},{"heading":"15. Statistical decision versus choice of α","body":"α=.05 nghĩa là tolerate 5% Type I error long-run under null; không phải p-value. Nếu calculated p=.07, fail at 5% nhưng could reject at 10% nếu test design predetermined. Đừng âm thầm chọn α sau khi xem p vì sẽ nâng false-positive rate.","trap":""},{"heading":"16. Power and Type II risk depend on true effect","body":"Power cannot generally be computed from α alone. Với fixed α, n larger/σ lower/effect larger làm distributions of statistic tách nhau nhiều hơn, tăng power. Tests of variance likewise require specific alternative and sampling distribution; đừng lấy 1−α làm power.","trap":""},{"heading":"17. Directional conclusion must match rejection tail","body":"Nếu Ha: μ<μ₀ và sample t positive, đó là evidence opposite direction; dù |t| large, không được reject left-tail. Chỉ reject when statistic in rejection region of the stated Ha. Với F variance ratio, ensure ratio numerator corresponds to hypothesized > or < relation.","trap":""},{"heading":"18. P-value and critical-value methods must agree","body":"Nếu p computed from correct null distribution and same one/two-tail, decision p≤α tương đương statistic vượt critical. Khi hai cách cho khác kết quả, kiểm tra tail, df, units, numerical rounding, assumptions and whether wrong distribution was used.","trap":""},{"heading":"19. Practical exam ordering","body":"(i) Identify population parameter and Ha. (ii) Test type and assumptions. (iii) Write df and α. (iv) Compute SE or ratio. (v) Get proper critical/p. (vi) Reject or fail to reject, quantify context. (vii) If no rejection, do not claim null proved. (viii) Check Type I/II consequences and power interpretation.","trap":""}],"formulas":[{"name":"Single population mean z statistic","expr":"z=(x̄−μ₀)/(σ/√n)","meaning":"Known σ / suitable normal-reference test.","conditions":"Independent observations; known σ."},{"name":"Single population mean t statistic","expr":"t=(x̄−μ₀)/(s/√n)","meaning":"Population σ unknown; t distribution with df=n−1.","conditions":"Normal population for exact t; appropriate approximations for large n."},{"name":"Two-tail rejection for t","expr":"Reject if |t|>t_(1−α/2,df)","meaning":"Hypothesis mean different from benchmark.","conditions":"Reference t distribution and matching df."},{"name":"Right-tail rejection","expr":"Reject if t>t_(1−α,df)","meaning":"Ha parameter > null value.","conditions":""},{"name":"Left-tail rejection","expr":"Reject if t<t_(α,df)","meaning":"Ha parameter < null value.","conditions":""},{"name":"Pooled variance for equal-variance two-sample test","expr":"s_p²=[(n₁−1)s₁²+(n₂−1)s₂²]/(n₁+n₂−2)","meaning":"Estimate common unknown population variance.","conditions":"Independent normal populations, equal true variances."},{"name":"Pooled independent two-sample mean SE","expr":"SE=√[s_p²(1/n₁+1/n₂)]","meaning":"Standard error of x̄1−x̄2.","conditions":"Independent samples and equal variance assumption."},{"name":"Pooled two-mean t statistic","expr":"t=[(x̄₁−x̄₂)−δ₀]/√[s_p²(1/n₁+1/n₂)]","meaning":"Compare group mean difference with hypothesized δ₀.","conditions":"df=n₁+n₂−2."},{"name":"Paired differences","expr":"dᵢ=Xᵢ−Yᵢ","meaning":"Match observations before calculating differences.","conditions":"Same paired units, sign definition consistent."},{"name":"Paired mean difference","expr":"d̄=(1/n)Σᵢdᵢ","meaning":"Mean of n matched differences.","conditions":""},{"name":"Paired difference sample SD","expr":"s_d=√[Σᵢ(dᵢ−d̄)²/(n−1)]","meaning":"Dispersion of pair differences.","conditions":""},{"name":"Paired t statistic","expr":"t=(d̄−d₀)/(s_d/√n)","meaning":"Paired comparisons test of population mean difference.","conditions":"df=n−1; appropriate difference distribution."},{"name":"Single variance chi-square statistic","expr":"χ²=(n−1)s²/σ₀²","meaning":"Compare sample variance with null population variance.","conditions":"Normal population; df=n−1."},{"name":"Chi-square right-tail rule","expr":"Ha:σ²>σ₀² ⇒ reject if χ²>χ²_(1−α,df)","meaning":"High variance yields large statistic.","conditions":""},{"name":"Chi-square LEFT-tail rule","expr":"Ha:σ²<σ₀² ⇒ reject if χ²<χ²_(α,df)","meaning":"Low variance yields small statistic.","conditions":"This is the mathematically correct rule; CFAI p232 contradicts it."},{"name":"Chi-square two-tail rule","expr":"Reject if χ²<χ²_(α/2,df) or χ²>χ²_(1−α/2,df)","meaning":"Variance differs in either direction.","conditions":""},{"name":"Two-variance F statistic","expr":"F=s₁²/s₂²","meaning":"Ratio of independent sample variances.","conditions":"Normal independent samples; df1=n₁−1, df2=n₂−1."},{"name":"F two-sided rejection","expr":"Reject if F<F_(α/2,df1,df2) or F>F_(1−α/2,df1,df2)","meaning":"F distribution asymmetric; do not use symmetric ± criticals.","conditions":""},{"name":"Unpooled unequal-variance SE (extension)","expr":"SE_W=√(s₁²/n₁+s₂²/n₂)","meaning":"Welch test denominator when variances not assumed equal.","conditions":"Extension; separate df approximation required."},{"name":"Power and false negative","expr":"power=1−β","meaning":"Probability of rejecting false null at stated true effect.","conditions":""}],"examples":[{"question_en":"A sample has n=25, mean return 12%, sample SD 4%, and H₀: μ=10%. Calculate the one-sample t statistic.","steps_vi":["SE=4%/√25=.8%.","t=(12−10)/.8=2.5, df=24."],"answer":"t=+2.50 (df=24).","check":""},{"question_en":"For the preceding t=2.50 and df=24, test H₀: μ=10% versus Hₐ: μ≠10% at α=5%, given two-sided t critical ±2.064.","steps_vi":["|2.50|>2.064, test statistic in rejection region."],"answer":"Reject H₀.","check":""},{"question_en":"A sample of 36 has mean 5.5%, known population SD 6%, and H₀: μ=4%. Calculate the z statistic.","steps_vi":["SE=6%/√36=1%.","z=(5.5−4)/1=1.5."],"answer":"z=+1.50.","check":""},{"question_en":"With z=1.50 and a right-tail 5% test, critical z=1.645. What is the decision?","steps_vi":["1.50<1.645 ⇒ insufficient evidence for greater mean."],"answer":"Fail to reject H₀.","check":""},{"question_en":"Two independent samples have n1=25, n2=25, means 9% and 5%, and SDs both 5%. Compute pooled variance and the two-mean t statistic under equal variances.","steps_vi":["s_p²=(24×25+24×25)/48=25 in percent-squared units.","SE=√[25/25+25/25]=√2=1.4142 percentage points.","t=(9−5)/1.4142≈2.8284; df48."],"answer":"Pooled variance=25 (%²); t≈2.8284.","check":""},{"question_en":"For a two-sided pooled t-test with t=2.8284 and df=48, assume 5% critical values ±2.011. State the decision.","steps_vi":["|2.8284|>2.011."],"answer":"Reject H₀.","check":""},{"question_en":"Two independent groups have n1=16, n2=25, SDs 4 and 4, with means 5 and 3. Calculate their pooled t statistic under H₀: μ1−μ2=0.","steps_vi":["s_p²=16 because both sample variances equal 16.","SE=√(16/16+16/25)=√1.64≈1.2806.","t=2/1.2806≈1.5617, df39."],"answer":"t≈1.5617 (df=39).","check":""},{"question_en":"Paired return differences are [2, 4, 6, 8, 10] percentage points. Compute the mean difference and sample standard deviation of differences.","steps_vi":["d̄=6.","Sum squared deviations 16+4+0+4+16=40.","s_d²=40/(5−1)=10; s_d≈3.1623."],"answer":"Mean difference=6; sample SD≈3.1623.","check":""},{"question_en":"For the preceding 5 paired differences with d̄=6 and s_d=√10, test d₀=0. Calculate t and df.","steps_vi":["SE=√10/√5=√2≈1.4142.","t=6/1.4142≈4.2426."],"answer":"t≈4.2426; df=4.","check":""},{"question_en":"A normally distributed population has null variance 16, a sample of n=16, and sample variance 4. Calculate its chi-square variance test statistic.","steps_vi":["χ²=(n−1)s²/σ₀²=15×4/16=3.75."],"answer":"χ²=3.75 (df=15).","check":""},{"question_en":"For a left-tailed chi-square variance test with df=15, α=5%, and a supplied lower critical value of 7.261, what decision follows when χ²=3.75?","steps_vi":["Ha: variance lower ⇒ reject if statistic BELOW lower cutoff.","3.75<7.261 ⇒ reject H₀."],"answer":"Reject H₀ (left-tailed variance test).","check":""},{"question_en":"CFAI 2026 Quant PDF p232 shows Ha: σ²<16 (%²), a lower chi-square cutoff 13.0905 and computed χ²=18.63. What is the mathematically correct decision?","steps_vi":["Correct left-tail rule: reject only for χ²<13.0905.","18.63>13.0905; NOT in rejection region."],"answer":"Fail to reject H₀.","check":"Source erratum illustration; book page gives conflicting greater-than rejection rule."},{"question_en":"Two independent normal samples have variances 25 and 9. Calculate the F statistic with the first variance in the numerator.","steps_vi":["F=s1²/s2²=25/9≈2.7778."],"answer":"F≈2.7778.","check":""},{"question_en":"A two-sided variance-ratio F test uses n1=n2=20 and an upper 97.5% critical value of 2.526. Sample variances are 25 and 9. State the decision.","steps_vi":["F=25/9=2.7778>2.526, in upper rejection tail.","DF=(19,19); reject equality of variances."],"answer":"Reject H₀.","check":""},{"question_en":"Another F test has sample variances 16 and 9, n1=n2=20, and two-sided 5% critical values 0.396 and 2.526. What is the decision?","steps_vi":["F=16/9=1.7778, between critical bounds."],"answer":"Fail to reject H₀.","check":""},{"question_en":"A pooled two-mean test has n1=30 and n2=40. What degrees of freedom apply?","steps_vi":["df=n1+n2−2=30+40−2."],"answer":"68 degrees of freedom.","check":""},{"question_en":"A paired t-test uses 18 matched observations. What degrees of freedom apply?","steps_vi":["df=n−1=18−1."],"answer":"17 degrees of freedom.","check":""},{"question_en":"A one-population variance chi-square test uses n=32. What degrees of freedom apply?","steps_vi":["df=n−1=31."],"answer":"31 degrees of freedom.","check":""},{"question_en":"Two independent sample variances are placed as s1²/s2² with n1=21 and n2=16. What are the F degrees of freedom?","steps_vi":["df numerator=n1−1=20.","df denominator=n2−1=15."],"answer":"df=(20,15).","check":""},{"question_en":"A two-sided test has α=5% and p=0.07. State the decision and whether α=10% would change it.","steps_vi":["At α=.05, p=.07>.05 ⇒ fail to reject.","At α=.10, p=.07<.10 ⇒ reject (if α were set a priori)."],"answer":"Fail to reject at 5%; reject at prespecified 10%.","check":""}],"questions":[{"stem_en":"For a single population mean with unknown population variance under a normal model, the appropriate test statistic is typically:","options":["The one-sample t-statistic","An F-statistic for two variances","A chi-square test of one variance"],"correct":0,"why_vi":"Single mean σ unknown => t, df n−1.","trap_vi":""},{"stem_en":"A one-sample mean t-test with n=26 observations has degrees of freedom equal to:","options":["26","25","24"],"correct":1,"why_vi":"df=n−1=25.","trap_vi":""},{"stem_en":"A one-sample test has n=25, mean 12%, null mean 10%, and s=4%. Its t statistic is:","options":["1.25","0.50","2.50"],"correct":2,"why_vi":"(12−10)/(4/5)=2.5.","trap_vi":""},{"stem_en":"A two-sided one-sample t-test has t=2.50, df=24 and critical ±2.064. The decision is:","options":["Reject H₀","Fail to reject H₀","Set α=0"],"correct":0,"why_vi":"|2.50|>2.064.","trap_vi":""},{"stem_en":"A sample mean is 5.5%, null mean 4%, σ=6% known, n=36. The z statistic is:","options":["0.25","1.50","2.50"],"correct":1,"why_vi":"SE=6/6=1%; z=1.5/1=1.5.","trap_vi":""},{"stem_en":"Which test is appropriate for comparing mean returns of two independent normal samples with unknown but equal population variances?","options":["A paired t-test","A chi-square single-variance test","A pooled two-sample t-test"],"correct":2,"why_vi":"Independent, equal unknown variances => pooled t.","trap_vi":""},{"stem_en":"The degrees of freedom of an equal-variance pooled t-test for sample sizes n1=30 and n2=40 are:","options":["68","70","69"],"correct":0,"why_vi":"n1+n2−2=68.","trap_vi":""},{"stem_en":"In an independent equal-variance t-test, pooled sample variance is:","options":["The unweighted average of standard deviations","[(n1−1)s1²+(n2−1)s2²]/(n1+n2−2)","The difference of the two sample means"],"correct":1,"why_vi":"Pooled variance weights squared SD by df.","trap_vi":""},{"stem_en":"A matched before-and-after return comparison should generally be analyzed using:","options":["A two-variance F-test","An independent two-mean t-test ignoring matching","A paired-differences t-test"],"correct":2,"why_vi":"Matched pairs => di observations then t on mean differences.","trap_vi":""},{"stem_en":"A paired t-test based on 18 matched observations has degrees of freedom of:","options":["17","18","34"],"correct":0,"why_vi":"df=n−1=17.","trap_vi":""},{"stem_en":"Five paired differences are [2,4,6,8,10]. Their sample mean is:","options":["5","6","10"],"correct":1,"why_vi":"Sum=30 /5=6.","trap_vi":""},{"stem_en":"For a single variance test from a normally distributed population, the test statistic is:","options":["A z-statistic","An F-statistic with two samples","χ²=(n−1)s²/σ₀²"],"correct":2,"why_vi":"Chi-square with df n−1.","trap_vi":""},{"stem_en":"For a left-tailed test of Hₐ: σ²<σ₀², the proper chi-square rejection rule is:","options":["Reject when χ² is sufficiently SMALL","Reject when χ² is sufficiently LARGE","Reject when χ² is near its expected value"],"correct":0,"why_vi":"Sample variance low ⇒ chi-square low. CFAI p232 erroneously prints a greater-than rule.","trap_vi":""},{"stem_en":"CFAI 2026 Quant p232 states a left-tail variance test with χ²=18.63 and lower critical χ²=13.0905. The mathematically correct conclusion is:","options":["Reject H₀ because χ² is larger than 13.0905","Fail to reject H₀ because χ² is not in the left rejection tail","Accept H₀ as certainly true"],"correct":1,"why_vi":"Critical lower-tail rule requires statistic<13.0905; 18.63 fails. Source printed contradiction is documented.","trap_vi":""},{"stem_en":"A one-sample variance chi-square test with n=32 has degrees of freedom equal to:","options":["32","30","31"],"correct":2,"why_vi":"n−1=31.","trap_vi":""},{"stem_en":"For two independent normally distributed populations, a test of equal variances typically uses:","options":["F=s1²/s2²","t=(x̄−μ₀)/(s/√n)","z=(x̄−μ₀)/(σ/√n)"],"correct":0,"why_vi":"F for variance ratio under H0 equality.","trap_vi":""},{"stem_en":"Two sample variances are 25 and 9, with the first in the numerator. F equals:","options":["1.56","2.78","0.36"],"correct":1,"why_vi":"25/9≈2.7778.","trap_vi":""},{"stem_en":"If F=s1²/s2² and samples contain 21 and 16 observations, the F degrees of freedom are:","options":["(21,16)","(15,20)","(20,15)"],"correct":2,"why_vi":"Numerator n1−1=20; denominator n2−1=15.","trap_vi":""},{"stem_en":"Which statement about a two-sided F-test is correct?","options":["F rejection regions are in both tails and need not be symmetric about 1","The critical values must be +1.96 and −1.96","All F statistics may be negative"],"correct":0,"why_vi":"F>0, distribution asymmetric; two tails based on α/2 each.","trap_vi":""},{"stem_en":"An F statistic is 1.78, between the stated two-sided rejection cutoffs 0.40 and 2.53. The decision is to:","options":["Reject H₀","Fail to reject H₀","Conclude the two variances are exactly equal"],"correct":1,"why_vi":"Inside non-rejection region.","trap_vi":""},{"stem_en":"A single-mean test has p=0.07 and the significance level was set to 5%. The appropriate action is:","options":["Reject H₀","Declare Type I error has occurred","Fail to reject H₀"],"correct":2,"why_vi":"p=.07>.05.","trap_vi":""},{"stem_en":"Which test directly evaluates whether a portfolio’s return variance is lower than a specific threshold?","options":["A chi-square one-population variance test, under normality","A paired two-mean t-test","A one-sample mean z-test"],"correct":0,"why_vi":"Variance parameter => chi-square, normality critical.","trap_vi":""},{"stem_en":"A sample mean t statistic is +3.0, but the test is left-tailed at α=5%. Most accurately, the result:","options":["Must reject because |t| is large","Does not support rejection in the specified left tail","Provides proof H₀ is false in the negative direction"],"correct":1,"why_vi":"Right-sign positive test statistic not in left-tail rejection region.","trap_vi":""},{"stem_en":"For a paired-differences test, which quantity belongs in the denominator?","options":["The sum of the two mean returns","The larger of the two sample variances","The sample SD of paired differences divided by √n"],"correct":2,"why_vi":"Use sd/√n where sd is sample SD of differences.","trap_vi":""},{"stem_en":"Which relationship is correct for test power?","options":["Power=1−β","Power=1−α","Power=α/2"],"correct":0,"why_vi":"Power probability reject false null; β false negative.","trap_vi":""},{"stem_en":"To estimate the equal unknown population variance for two independent samples, which assumption is essential?","options":["The groups are exact pairs","The population variances can reasonably be assumed equal","All observations are the same number"],"correct":1,"why_vi":"Pooled procedure assumes equal true variances.","trap_vi":""}],"cards":[{"front_en":"One-sample mean t statistic?","back_vi":"(x̄−μ₀)/(s/√n), df=n−1."},{"front_en":"Known-σ mean test statistic?","back_vi":"z=(x̄−μ₀)/(σ/√n)."},{"front_en":"Pooled two-mean t df?","back_vi":"n1+n2−2 for independent equal-variance normal populations."},{"front_en":"Formula for pooled variance?","back_vi":"[(n1−1)s1²+(n2−1)s2²]/(n1+n2−2)."},{"front_en":"Pooled two-mean test SE?","back_vi":"sqrt(sp²/n1+sp²/n2)."},{"front_en":"When to use paired t-test?","back_vi":"Matched observations (before-after, same security/date); use sample of differences."},{"front_en":"Paired t formula?","back_vi":"(d̄−d0)/(sd/√n), df=n−1."},{"front_en":"One-population variance test statistic?","back_vi":"χ²=(n−1)s²/σ0²; df=n−1."},{"front_en":"Left-tail variance test rejection?","back_vi":"Reject H₀ when χ² is LESS than lower chi-square critical value."},{"front_en":"CFAI 2026 Quant physical p232 erratum?","back_vi":"Example writes greater-than rejection for Ha variance lower. Correct mathematics: χ²18.63 > lower critical 13.09 ⇒ FAIL to reject."},{"front_en":"Right-tail variance test rejection?","back_vi":"Reject H₀ when χ² GREATER than upper critical value."},{"front_en":"Two-sided variance test rule?","back_vi":"Reject if statistic below lower α/2 or above upper 1−α/2 cutoff."},{"front_en":"F statistic for two independent variances?","back_vi":"F=s1²/s2², df=(n1−1,n2−1)."},{"front_en":"Can an F statistic be negative?","back_vi":"Không; ratio of nonnegative variances, under positive denominators."},{"front_en":"Are F critical values symmetric around one?","back_vi":"Không; F distribution asymmetric."},{"front_en":"Which t test compares independent two means with equal unknown variance?","back_vi":"Pooled two-sample t-test."},{"front_en":"What if population variances clearly unequal?","back_vi":"Welch approach is extension; equal-variance pooled assumption unsuitable."},{"front_en":"Effect of prespecified α change on decision?","back_vi":"p-value fixed; reject if p≤α, but must not choose α after seeing data."},{"front_en":"Degrees of freedom for paired test with n pairs?","back_vi":"n−1."},{"front_en":"Degrees of freedom for F=s1²/s2²?","back_vi":"numerator n1−1; denominator n2−1."}]},{"id":"CFA26-01-08-LOS03","letter":"8.c","title_en":"Parametric and Nonparametric Tests","outcome_en":"Compare and contrast parametric and nonparametric tests, and describe situations where each is the more appropriate type of test.","overview_vi":"LOS 8.c là quyết định chọn loại kiểm định theo parameter, distributional assumptions, sample size, outliers, ranks và nghiên cứu về randomness. Phải nhận diện các nonparametric alternatives chính thức trong CFAI table: Wilcoxon signed-rank cho one-sample/paired, Mann–Whitney U cho independent samples, sign test cho paired, runs test cho randomness. Giải thích nonparametric không phải “không có giả định” hay luôn mạnh hơn t-test.","source":[{"id":"CFA Institute Curriculum 2026 — Quant LM8","pages":"242–243 (physical PDF; LOS 8.c and alternative-test table)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 8","pages":"102–105 (physical PDF; parametric versus nonparametric)"},{"id":"SAPP Quant Slide Notes 2026 — Module 8","pages":"370 (physical PDF; Module 8 LOS 8.c summary; Module 9 begins p378)"}],"sections":[{"heading":"1. Parametric tests use parameters and/or distribution assumptions","body":"Parametric tests kiểm định parameter (μ, variance) hoặc rely on a specified probability distribution. One-sample mean t, two-mean t, variance χ², and variance ratio F are typical cases. Những công thức này mạnh nếu assumptions phù hợp; điều quan trọng là test target và assumptions chứ không phải độ phức tạp của formula.","trap":""},{"heading":"2. What counts as nonparametric","body":"Nonparametric tests đặt ít assumptions hơn hoặc kiểm định property không phải numeric population parameter. Thường dùng ranks, signs, order information hoặc randomness sequence. “Nonparametric” không đồng nghĩa completely assumption-free: independence, continuity/symmetry hoặc exchangeability có thể vẫn quan trọng theo test.","trap":""},{"heading":"3. Situation 1: unsuitable distributional assumptions","body":"Khi small sample và data strong skewness/heavy tails, test dựa normal model có thể không justified. Có thể cân nhắc rank-/sign-based approach, nhưng phải test đúng hypothesis; ví dụ Mann–Whitney thường kiểm định relative distribution/rank shift, không tự động equivalent test mean differences dưới mọi distributions.","trap":""},{"heading":"4. Situation 2: outliers","body":"Outlier có thể ảnh hưởng sample mean/s² mạnh; median/rank inference ít nhạy một cách tự nhiên. Ví dụ salaries [1,2,3,4,100] có mean22 nhưng median3; rank-based analysis có thể làm rõ typical observation. Tuy nhiên rank methods cũng có trade-off power/information loss.","trap":""},{"heading":"5. Situation 3: ordinal/ranked observations","body":"Khi portfolio managers chỉ có rank 1–10 hoặc investor satisfaction ordinal levels, distances between ranks không phải numeric return differences. Nonparametric rank-based tests thường thích hợp hơn t-test cho raw rankings. Đừng suy diễn khoảng cách “rank 1→2” bằng “rank 6→7” có cùng underlying utility.","trap":""},{"heading":"6. Situation 4: non-parameter hypotheses","body":"Khi mục tiêu là randomness of price changes hoặc samples from specific distribution, không chỉ kiểm định mean/variance. Runs test là nonparametric test dựa vào chuỗi tăng/giảm (hoặc signs) và số runs. Nó gắn với random-walk-related questions nhưng không tự kiểm định mọi hình thức market efficiency.","trap":""},{"heading":"7. Wilcoxon signed-rank: one-sample alternative","body":"Một cách kiểm định location shift/median-related hypothesis bằng signed ranks của deviations so với hypothesized value (loại zero differences và xử lý ties đúng). Thường cần sample independent và đối xứng differences để interpretation về median/location thuận lợi. CFAI nêu như nonparametric alternative to one-sample mean test.","trap":""},{"heading":"8. Wilcoxon signed-rank: paired comparison","body":"Tính differences cho matched pairs, rank absolute nonzero differences, gán signs, tổng positive/negative rank. So với paired t, ít phụ thuộc normality of paired differences; vẫn cần assumptions về shape/symmetry cho một số kết luận. Khi paired dữ liệu, không chuyển thành Mann–Whitney independent test.","trap":""},{"heading":"9. Mann–Whitney U (Wilcoxon rank-sum)","body":"Dùng cho hai independent samples để đánh giá systematic ranking/relative location, thay thế thông dụng cho independent two-mean t khi parametric assumptions không phù hợp. Pool observations, assign ranks, compare rank sums. Interpretation as median shift chỉ khi distributional shapes và related conditions phù hợp.","trap":""},{"heading":"10. Sign test for paired data","body":"Dùng dấu +/− của paired differences, bỏ ties. Không dùng magnitude, do đó robust nhưng có thể kém power hơn Wilcoxon signed-rank hoặc paired t khi assumptions của các test này đều đáp ứng. Một null phổ biến là probabilities of positive and negative signs equal.","trap":""},{"heading":"11. Runs test for sequence randomness","body":"Một run là dãy liên tiếp cùng loại/sign. Với sequence AAA BB A, có 3 runs; quá ít runs có thể cho dependence/persistence, quá nhiều runs có thể cho alternation. Decision cần reference distribution cho numbers of +/−, không chỉ đếm runs mà kết luận ngẫu nhiên hay không.","trap":""},{"heading":"12. Which test usually has more power?","body":"Nếu normality và các parametric assumptions được thỏa mãn, parametric t-type test thường power cao hơn rank/sign alternatives cho mục tiêu parameter tương ứng. Nonparametric tăng robustness trong môi trường assumptions yếu, nhưng “robust” không đồng nghĩa superiority trong mọi settings.","trap":""},{"heading":"13. Nonparametric tests and data transformation","body":"Rank conversion làm giảm sensitivity to outliers nhưng cũng bỏ thông tin khoảng cách magnitude giữa observations. Chọn test phải phù hợp research claim: một test sự khác biệt của ranks không chứng minh expected return hơn chính xác 2%. Nếu cần kinh tế tác động, báo cáo effect size/CI cùng test.","trap":""},{"heading":"14. Different data structures require different nonparametric alternatives","body":"Single sample location => Wilcoxon signed-rank; two independent groups => Mann–Whitney U; before/after matched observations => Wilcoxon signed-rank hoặc sign test; sequence of up/down changes => runs test. “Non-normal” chỉ là một tín hiệu, pairing và question type mới quyết định test.","trap":""},{"heading":"15. Parametric/nonparametric results can be reported together","body":"Nếu assumptions chưa chắc, trình bày both t-test and rank test như robustness analysis, với caveat rằng họ có thể test khác nhau một cách tinh tế. Nếu conclusions bất đồng, kiểm tra outlier, distributional shape, ties, sample dependence và effect size; không chọn kết luận phù hợp mong muốn.","trap":""},{"heading":"16. Exam checklist","body":"(1) Câu hỏi muốn kiểm định mean/variance/rank/randomness? (2) Có independent samples hay matched pairs? (3) Có normality, equal variance, sample lớn đủ không? (4) Extreme outliers/ordinal scale? (5) Chọn parametric nếu assumptions phù hợp; nonparametric nếu không. (6) Ghi đúng strengths, costs và caveats.","trap":""}],"formulas":[{"name":"Wilcoxon signed-rank positive rank sum (illustrative)","expr":"W₊=Σ ranks(|dᵢ|) for dᵢ>0","meaning":"Rank absolute differences, sum ranks of positive-signed differences.","conditions":"Zeros removed; tie handling and symmetry assumptions matter."},{"name":"Mann–Whitney U for group 1 (illustrative)","expr":"U₁=R₁−n₁(n₁+1)/2","meaning":"R₁ sum of pooled ranks for group 1.","conditions":"Independent samples, correct treatment of ties; related conventions may swap U labels."},{"name":"Complement of Mann–Whitney U","expr":"U₁+U₂=n₁n₂","meaning":"Counts relative pairwise ranks.","conditions":"No ties in simple textbook setting; consistent rank conventions."},{"name":"Sample mean versus sample median","expr":"mean=(Σxᵢ)/n; median=middle sorted observation(s)","meaning":"Highlights sensitivity to outliers, not itself a test statistic.","conditions":""},{"name":"Sign test binomial reference (extension)","expr":"K~Binomial(m,0.5) under equal-sign null","meaning":"Number of positive signs among m nonzero differences.","conditions":"Independence and symmetric signs under null."},{"name":"Number of runs (descriptive)","expr":"R=1+Σᵢ₌₂ⁿ1{signᵢ≠signᵢ₋₁}","meaning":"Run count from a binary sign sequence.","conditions":"Used only as descriptive step before a proper runs-test decision."}],"examples":[{"question_en":"An analyst has sample returns with extreme outliers and wants to compare the location of one small sample with a benchmark. Which broad test family is worth considering?","steps_vi":["Parametric mean assumptions may be weak.","Wilcoxon signed-rank is a possible nonparametric location alternative when its assumptions apply."],"answer":"Consider a Wilcoxon signed-rank test.","check":""},{"question_en":"Two independent hedge-fund groups have ordinal performance rankings and strong skewness. Which named nonparametric test is suitable?","steps_vi":["Two INDEPENDENT groups and ranks.","Mann–Whitney U/Wilcoxon rank-sum is the matching alternative."],"answer":"Mann–Whitney U test.","check":""},{"question_en":"The same 12 managers receive ratings before and after training. The paired differences are highly nonnormal. Which alternatives to a paired t-test may be considered?","steps_vi":["Data are paired; calculate manager-by-manager differences.","Use Wilcoxon signed-rank or sign test as conditions permit."],"answer":"Wilcoxon signed-rank or sign test.","check":""},{"question_en":"An analyst tests whether daily price-change signs appear random. Which nonparametric technique directly relates to their sequence?","steps_vi":["Sequence random vs nonrandom, rather than mean return."],"answer":"Runs test.","check":""},{"question_en":"Returns [1, 2, 3, 4, 100] have which sample mean and median?","steps_vi":["Mean=(1+2+3+4+100)/5=110/5=22.","Median sorted middle=3."],"answer":"Mean=22; median=3.","check":""},{"question_en":"A binary sequence of market movements is U U D D U U. How many runs does it contain?","steps_vi":["First U U is run 1; D D is run 2; final U U is run 3."],"answer":"3 runs.","check":""},{"question_en":"A sample of paired differences is [2, −1, 3, −4]. With no ties in absolute magnitude, calculate the signed-rank sums.","steps_vi":["Absolute magnitudes [2,1,3,4] have ranks [2,1,3,4].","Positive ranks 2+3=5; negative ranks 1+4=5."],"answer":"W+=5; W−=5.","check":""},{"question_en":"Independent samples A=[2,4,6] and B=[1,3,5] are pooled and ranked. Calculate the rank sum for A.","steps_vi":["Pooled sorted values [1(B),2(A),3(B),4(A),5(B),6(A)].","Ranks of A are [2,4,6], sum=12."],"answer":"R_A=12.","check":""},{"question_en":"Using the preceding group A of size n1=3 with rank sum 12, calculate U_A using U_A=R_A−n1(n1+1)/2.","steps_vi":["U_A=12−3×4/2=12−6."],"answer":"U_A=6.","check":""},{"question_en":"In the previous two-group rank example, n1=n2=3 and U_A=6. Calculate the complement U_B.","steps_vi":["U_A+U_B=n1×n2=9.","U_B=9−6."],"answer":"U_B=3.","check":""},{"question_en":"Eight paired comparisons yield 6 positive and 2 negative nonzero differences. Under a sign test with H0:P(positive)=0.5, what is the expected count of positive signs?","steps_vi":["m=8.","E(K)=m×0.5=4."],"answer":"4 positive signs expected under H₀.","check":""},{"question_en":"A sequence of signs is + − + − + −. How many runs does it have?","steps_vi":["Every adjacent sign changes; each item forms its own run."],"answer":"6 runs.","check":""}],"questions":[{"stem_en":"A parametric test is most closely associated with:","options":["Few or no distributional assumptions and only ranks","A population parameter and/or specified distributional assumptions","A guaranteed absence of Type I errors"],"correct":1,"why_vi":"Parametric quan tâm μ/variance hoặc specified distribution.","trap_vi":""},{"stem_en":"Which circumstance most strongly supports a nonparametric test?","options":["Ordinal manager rankings with no meaningful numeric spacing","Normally distributed interval data and valid equal-variance assumptions","A larger sample with well-behaved residuals"],"correct":0,"why_vi":"Ordinal ranks phù hợp rank-based procedures.","trap_vi":""},{"stem_en":"Which test is a nonparametric alternative for two independent groups?","options":["Paired t-test","One-sample chi-square variance test","Mann–Whitney U test"],"correct":2,"why_vi":"Mann–Whitney U (Wilcoxon rank-sum) for independent samples.","trap_vi":""},{"stem_en":"A nonparametric alternative for matched nonnormally distributed paired differences is:","options":["Pooled two-sample t-test","Wilcoxon signed-rank test","Independent two-variance F-test"],"correct":1,"why_vi":"Paired => signed-rank/sign test, not independent t.","trap_vi":""},{"stem_en":"Which test is commonly used to investigate randomness in a binary up/down sequence?","options":["Runs test","Mann–Whitney U test","Two-sample pooled t-test"],"correct":0,"why_vi":"Runs test counts sequences of identical signs.","trap_vi":""},{"stem_en":"Compared with a well-specified parametric test, a nonparametric test is generally:","options":["Always more powerful","Completely free of assumptions","Potentially less powerful when parametric assumptions hold"],"correct":2,"why_vi":"Parametric thường power cao hơn under valid assumptions.","trap_vi":""},{"stem_en":"Which statement about nonparametric tests is most accurate?","options":["They always test a population mean directly","They often use ranks or signs and make fewer distribution assumptions","They are invalid whenever there are outliers"],"correct":1,"why_vi":"Ranks/signs, fewer distribution assumptions; some structural assumptions remain.","trap_vi":""},{"stem_en":"Which test is suited to a single-sample location comparison based on signed ranks?","options":["Wilcoxon signed-rank test","Mann–Whitney U test for independent samples","Variance-ratio F-test"],"correct":0,"why_vi":"One-sample signed rank vs hypothesized location.","trap_vi":""},{"stem_en":"An extreme outlier changes a mean dramatically. Which statistic is often more robust for location?","options":["Sample mean","Sample variance","Sample median"],"correct":2,"why_vi":"Median less sensitive to extreme observations.","trap_vi":""},{"stem_en":"For data [1,2,3,4,100], the sample mean is:","options":["3","22","55"],"correct":1,"why_vi":"(1+2+3+4+100)/5=22.","trap_vi":""},{"stem_en":"For data [1,2,3,4,100], the sample median is:","options":["3","22","4"],"correct":0,"why_vi":"Middle sorted item=3.","trap_vi":""},{"stem_en":"A sequence U U D D U U contains how many runs?","options":["6","2","3"],"correct":2,"why_vi":"UU, DD, UU gives three runs.","trap_vi":""},{"stem_en":"Which nonparametric method directly uses only the signs of matched differences?","options":["Mann–Whitney U","Sign test","Chi-square variance test"],"correct":1,"why_vi":"Sign test discards magnitude, counts +/-.","trap_vi":""},{"stem_en":"Which property does a rank-based test often sacrifice?","options":["Information on the magnitude of differences","All information on the order of observations","Every possible inference about location"],"correct":0,"why_vi":"Rank conversion preserves order, not exact distances.","trap_vi":""},{"stem_en":"The Mann–Whitney U test is generally an alternative to the parametric test for:","options":["A single population variance","A paired mean difference only","Differences between two independent samples"],"correct":2,"why_vi":"Independent groups, ranks / relative location.","trap_vi":""},{"stem_en":"Paired differences are [2,−1,3,−4], with absolute ranks [2,1,3,4]. The sum of positive signed ranks is:","options":["3","5","7"],"correct":1,"why_vi":"Positive ranks:2+3=5.","trap_vi":""},{"stem_en":"Group A consists of [2,4,6] and group B of [1,3,5]. The pooled rank sum for A is:","options":["12","9","6"],"correct":0,"why_vi":"A has pooled ranks 2,4,6, total12.","trap_vi":""},{"stem_en":"In the prior example with n1=3 and R_A=12, the U_A value computed as R_A−n1(n1+1)/2 is:","options":["12","9","6"],"correct":2,"why_vi":"12−6=6.","trap_vi":""},{"stem_en":"If U_A=6 and n1=n2=3, the complementary U_B equals:","options":["6","3","9"],"correct":1,"why_vi":"U_B=9−6=3.","trap_vi":""},{"stem_en":"Which statement about Mann–Whitney U is most accurate?","options":["It directly tests equality of population means under every possible distribution","It can compare relative ranks of two independent groups; a median interpretation requires conditions","It should be used for any two paired samples"],"correct":1,"why_vi":"Mann–Whitney test not automatically equal test of means/medians in arbitrary shapes.","trap_vi":""},{"stem_en":"When the population distribution is normal and all assumptions hold, a parametric t-test is generally preferred because it:","options":["Can have greater statistical power","Eliminates sampling variation","Guarantees a correct null hypothesis decision"],"correct":0,"why_vi":"Parametric test may have more power with correct assumptions.","trap_vi":""},{"stem_en":"A sequence of six movements alternates U D U D U D. The number of runs is:","options":["1","3","6"],"correct":2,"why_vi":"Every observation is a new run =>6.","trap_vi":""}],"cards":[{"front_en":"What defines a parametric test?","back_vi":"Parameter of population and/or specified distribution assumptions."},{"front_en":"What defines a nonparametric test?","back_vi":"Few distributional assumptions or questions not about a parameter; often ranks/signs."},{"front_en":"Four nonparametric use situations in CFAI?","back_vi":"Assumptions invalid, outliers, ranked/ordinal data, nonparameter hypotheses."},{"front_en":"Independent two-group nonparametric alternative?","back_vi":"Mann–Whitney U / Wilcoxon rank-sum test."},{"front_en":"Paired differences nonparametric alternatives?","back_vi":"Wilcoxon signed-rank or sign test."},{"front_en":"One-sample nonparametric location test?","back_vi":"Wilcoxon signed-rank test."},{"front_en":"Test for randomness of sign sequence?","back_vi":"Runs test."},{"front_en":"When is a parametric test often more powerful?","back_vi":"When its assumptions and target parameter are appropriate."},{"front_en":"Why can ranks be robust?","back_vi":"Relative order less sensitive to extreme numeric magnitudes."},{"front_en":"Does nonparametric mean zero assumptions?","back_vi":"Không; independence, symmetry, exchangeability or other conditions can matter."},{"front_en":"What can Mann–Whitney U compare?","back_vi":"Relative ranks/distributional tendency across two independent groups."},{"front_en":"Is Mann–Whitney U always a test of mean equality?","back_vi":"Không; claim về mean/median needs extra assumptions."},{"front_en":"Signed-rank test uses what information?","back_vi":"Signs AND ranks of absolute differences."},{"front_en":"Sign test discards which information?","back_vi":"Magnitude của difference, chỉ giữ +/- sign."},{"front_en":"What is a run?","back_vi":"Dãy liên tiếp observations cùng sign/category."},{"front_en":"Three examples of unsuitable t-test data?","back_vi":"Small highly skewed returns, extreme outliers, ordinal rankings."},{"front_en":"Why compare parametric and nonparametric results?","back_vi":"Robustness check về assumptions/outliers and sensitivity."}]}]},{"version":"2026.11.22-quant9-original-first-draft","module_id":"CFA26-01-09","module_title":"Parametric and Non-Parametric Tests of Independence","language":"Vietnamese explanations / English original questions","qa_status":"SOURCE_MAPPED_WITH_CFAI_SUMMARY_ERRATUM_P252_AND_PENDING_FULL_INDEPENDENT_REVIEW","disclaimer_vi":"Nội dung tự biên soạn từ đối chiếu CFAI Curriculum 2026, Kaplan và slide Quant; câu hỏi mới bằng tiếng Anh. Lưu ý CFAI Quant physical p252 ghi nhầm bậc tự do chi-square (r−1)(c−2); các worked examples p264+ áp dụng đúng (r−1)(c−1). Spearman no-ties shortcut không exact khi có ties. Tất cả bài còn cần nghiệm thu học thuật hoàn toàn.","los":[{"id":"CFA26-01-09-LOS01","letter":"9.a","title_en":"Pearson and Spearman Correlation Significance Tests","outcome_en":"Explain parametric and nonparametric tests of the hypothesis that the population correlation coefficient equals zero, and determine whether the hypothesis is rejected at a given level of significance.","overview_vi":"LOS 9.a phân biệt hệ số Pearson (linear co-movement của giá trị gốc) và Spearman (monotonic co-movement của ranks), tính test statistic t để kiểm định tương quan tổng thể bằng 0, chọn đúng one-/two-tailed rejection region, đối chiếu α và n−2 degrees of freedom. Nhấn mạnh p-value, sample size, ties trong rank data và tính không đồng nghĩa giữa correlation và causation.","source":[{"id":"CFA Institute Curriculum 2026 — Quant LM9","pages":"251–261 (physical PDF; Pearson / Spearman correlation tests and decisions)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 9","pages":"106–107 and 110 (physical PDF; Pearson and rank methods)"},{"id":"SAPP Quant Slide Notes 2026 — Module 9","pages":"378–387 (physical PDF; correlation significance and rank tests)"}],"sections":[{"heading":"1. Objective: test a population correlation coefficient","body":"Sample correlation r hoặc rₛ cho biết quan sát sample của two variables. Kiểm định H₀: ρ=0 hỏi evidence có đủ cho nonzero population association không; r≠0 trên sample không đủ khẳng định population association. Mục tiêu khác với chỉ tính covariance hoặc đưa ra forecast regression.","trap":""},{"heading":"2. Pearson coefficient measures linear association","body":"Pearson r = sample covariance / (sample standard deviations product), bị chặn [−1,+1], sign cho direction và magnitude cho strength of linear association. Cần hai series paired numeric observations. Pearson có thể gần 0 khi quan hệ phi tuyến dạng U rõ rệt: “uncorrelated” không tự chứng minh independent.","trap":""},{"heading":"3. Parametric test for H₀: ρ=0","body":"Dùng t = r√(n−2)/√(1−r²), df=n−2, n>2, |r|<1. Với paired observations independent từ suitable jointly normal model, statistic theo t dưới H₀. Công thức này không phải t-test cho population mean; khác df=n−1 của one-mean t-test.","trap":""},{"heading":"4. Two-tailed alternatives","body":"Nếu hỏi “correlation is different from zero” ⇒ H₀:ρ=0, Hₐ:ρ≠0. α=5% phân cho hai đuôi, reject khi |t|>t₍1−α/2,n−2₎. Không cộng covariance hoặc tự chọn 1-tail sau khi quan sát sign r.","trap":""},{"heading":"5. Right-tailed positive correlation","body":"Nếu mục tiêu “positive relationship” ⇒ H₀:ρ≤0, Hₐ:ρ>0. α=.05, reject khi t>t₍.95, n−2₎. Một t âm lớn về độ lớn không chứng minh positive correlation. Critical value right tail khác two-tailed ở cùng α.","trap":""},{"heading":"6. Left-tailed negative correlation","body":"Nếu mục tiêu “negative relationship” ⇒ H₀:ρ≥0, Hₐ:ρ<0. Reject khi t<−t₍1−α, n−2₎; test statistic sign theo r vì denominator positive. Không dùng |t| để ra quyết định one-sided mà không xét hướng.","trap":""},{"heading":"7. Standard six-step calculation","body":"(1) H₀/Ha đúng direction; (2) chọn Pearson/Spearman và test t; (3) chọn α trước khi nhìn data; (4) critical rule/tails; (5) tính t và n−2 df; (6) reject/fail to reject và diễn giải “evidence about correlation”, không nói nguyên nhân đã được chứng minh.","trap":""},{"heading":"8. What happens when sample size increases?","body":"Giữ fixed nonzero r, |t| = |r|√((n−2)/(1−r²)) tăng theo √(n−2); threshold |r| cần để significant thường giảm khi n tăng. Do đó r=.25 có thể significant với sample lớn nhưng not significant với n nhỏ. Statistical significance vẫn không phản ánh magnitude có ý nghĩa kinh tế.","trap":""},{"heading":"9. Threshold correlation approach","body":"Từ tcrit cho two-tailed, giải tcrit = |r|√((n−2)/(1−r²)) ⇒ rcrit = tcrit/√(tcrit²+n−2). Reject nếu |r|>rcrit. Dùng để nhận diện sample size làm thay đổi test sensitivity. rcrit luôn 0–1; không dùng critical t trực tiếp so với r.","trap":""},{"heading":"10. P-values for Pearson correlation","body":"Under H₀ and t reference, two-sided p = 2P(Tdf≥|tobs|); right p=P(Tdf≥tobs); left p=P(Tdf≤tobs). So p≤α ⇒ reject. p không phải P(H₀ true|data), cũng không phải probability returns sẽ cùng tăng trong kỳ kế.","trap":""},{"heading":"11. Assumptions for Pearson significance","body":"Pearson r là statistic mô tả tuyến tính; để dùng exact small-sample t-reference, paired samples nên drawn independently from joint normal (bivariate normal) population. Serial dependence/time series autocorrelation và outliers có thể làm inference sai. Một số large-sample approximations được sử dụng trong thực hành nhưng không tự bảo đảm mọi assumptions.","trap":""},{"heading":"12. Spearman rank correlation as nonparametric option","body":"Khi variables là ranks hoặc non-normal/outlier-heavy, Spearman rₛ là Pearson correlation tính trên ranks của từng variable. Nó đo monotonic association (thường không cần linear shape). “Nonparametric” không đồng nghĩa assumption-free hoặc automatically causal.","trap":""},{"heading":"13. No-ties Spearman formula","body":"Nếu mỗi variable có ranks 1,2,…,n và KHÔNG CÓ TIES, rₛ = 1−6Σdᵢ²/[n(n²−1)], dᵢ là chênh lệch hai ranks cho pair i. Tránh đổi Σdᵢ² thành (Σdᵢ)² hoặc n² thành n. Với perfect same ranks, Σd²=0 ⇒ rₛ=+1; reverse ranks ⇒ rₛ=−1.","trap":""},{"heading":"14. Ties: use average ranks and rank-based Pearson","body":"Khi observations trùng nhau, gán midranks cho ties rồi tính Pearson correlation của hai rank vectors để có Spearman chính xác. Công thức no-ties đơn giản 1−6Σd²/[n(n²−1)] nói chung không hoàn toàn chính xác khi có ties. Source CFAI có ví dụ ranks 2.5 cho ties nên kết quả từ shortcut có thể hơi lệch — ghi rõ đây là sự khác nhau kỹ thuật, không chép y nguyên như luật chung.","trap":""},{"heading":"15. Spearman hypothesis decision","body":"H₀: population rank association =0 vs chosen Ha. CFAI/Kaplan giới thiệu tₛ≈rₛ√(n−2)/√(1−rₛ²), df=n−2 như reference phổ biến. Với n nhỏ/ties, test exact/permutation hoặc tie-aware approximation có thể thích hợp hơn; test t này là approximation, không bảo đảm exact law cho mọi samples.","trap":""},{"heading":"16. Ranking examples and monotonic patterns","body":"X tăng đều, Y tăng theo xu thế nhưng cong (Y=X² khi X≥0), Spearman≈+1 dù Pearson có thể <+1. Nếu X ranks tăng nhưng Y ranks giảm hoàn toàn, Spearman=−1. Trong dữ liệu returns và market indices, hiểu “monotonic” khác “linear slope”.","trap":""},{"heading":"17. Outliers can change Pearson more than Spearman","body":"Một unusual pair có thể làm mạnh hoặc yếu Pearson r vì cross-deviations lớn; Spearman dùng positions nên thường ít sensitivity hơn. Tuy nhiên rank methods vẫn bị ảnh hưởng bởi composition, ties và sample design. Nêu rõ vì sao chọn Spearman trong investment returns có skew/outliers.","trap":""},{"heading":"18. Significance is not causation","body":"Correlation between asset returns, fees, or factor exposures có thể đến từ common market factor, reverse causality hoặc omitted variables. Reject H₀ chỉ hỗ trợ conclusion về statistically nonzero association under assumptions, không chứng minh một biến gây ra biến kia.","trap":""},{"heading":"19. Pairing and effective sample size","body":"n trong t formula là số pairs Xᵢ,Yᵢ hợp lệ, không phải tổng số data values 2n. Nếu 20 annual observations of two return series, n=20 và df=18. Nếu sample returns theo thời gian autocorrelated, effective number of independent observations có thể nhỏ hơn n, làm p-value naïve thiếu tin cậy.","trap":""},{"heading":"20. Corner cases with |r|=1","body":"Nếu perfect linear relationship và |r|=1, denominator √(1−r²)=0; t expression diverges trong lý tưởng. Không nhập 0 vào calculator để chia không xác định; interpretation là sample perfect alignment nhưng assumptions và possible small sample vẫn quan trọng.","trap":""},{"heading":"21. Comparing Pearson and Spearman","body":"Pearson: raw numeric scale, linear sensitivity, potentially affected by extremes, parametric t under bivariate normality. Spearman: ranks, monotonic relationship, robust to shape/outliers, rank ties need handling, t approach approximate. Cả hai có null association zero nhưng “zero Spearman” và “zero Pearson” là claims khác nhau.","trap":""},{"heading":"22. CFA exam checklist for correlation significance","body":"Ghi r/rₛ và n, chọn đúng test; xác nhận null=0 và one-/two-tailed; tính df=n−2; tính t theo √(1−r²); so tcrit/p; giải thích về population linear/rank association; xem ties/outlier và không tuyên bố causal link.","trap":""}],"formulas":[{"name":"Sample Pearson correlation","expr":"rₓᵧ=sₓᵧ/(sₓsᵧ)","meaning":"Covariance standardized by standard deviations.","conditions":"Paired numeric data, sₓ,sᵧ>0."},{"name":"Pearson zero-correlation t test","expr":"t=r√(n−2)/√(1−r²)","meaning":"t reference df=n−2 for H₀: ρ=0.","conditions":"n>2; independent paired observations, suitable joint normal model."},{"name":"Correlation t degrees of freedom","expr":"df=n−2","meaning":"NOT n−1.","conditions":"n number of complete pairs."},{"name":"Two-sided rejection rule","expr":"reject if |t|>t₍1−α/2,n−2₎","meaning":"Both tails under Ha:ρ≠0.","conditions":"t quantiles from null."},{"name":"Right-sided rejection rule","expr":"reject if t>t₍1−α,n−2₎","meaning":"Positive association Ha:ρ>0.","conditions":"Must predefine direction."},{"name":"Left-sided rejection rule","expr":"reject if t<−t₍1−α,n−2₎","meaning":"Negative association Ha:ρ<0.","conditions":"Must predefine direction."},{"name":"Minimum significant |r|","expr":"rcrit=tcrit/√(tcrit²+n−2)","meaning":"Inverts Pearson t-test to threshold on |r|.","conditions":"Two-tailed threshold uses appropriate tcrit."},{"name":"Two-sided correlation p-value","expr":"p=2P(Tdf≥|tobs|)","meaning":"Null-tail probability for two-sided alternative.","conditions":"Use df=n−2."},{"name":"Right-tailed correlation p-value","expr":"p=P(Tdf≥tobs)","meaning":"Null upper-tail probability.","conditions":"Preselected Ha positive."},{"name":"Left-tailed correlation p-value","expr":"p=P(Tdf≤tobs)","meaning":"Null lower-tail probability.","conditions":"Preselected Ha negative."},{"name":"Spearman no-ties shortcut","expr":"rₛ=1−6Σdᵢ²/[n(n²−1)]","meaning":"dᵢ=rank(Xᵢ)−rank(Yᵢ).","conditions":"Exact shortcut only in absence of tied ranks."},{"name":"Spearman with ties","expr":"rₛ=Corr(rank(X),rank(Y))","meaning":"Pearson correlation on midranks.","conditions":"Average ranks for ties; shortcut may be inaccurate."},{"name":"Spearman approximate t","expr":"t≈rₛ√(n−2)/√(1−rₛ²)","meaning":"t approximation for rank-correlation significance.","conditions":"Approximate; small n and ties call for care."},{"name":"Decision via p-value","expr":"reject H₀ if p≤α","meaning":"Same logic for rank and Pearson tests.","conditions":"Correct test-tail p-value."},{"name":"Degrees of freedom example","expr":"n=20 pairs ⇒ df=18","meaning":"Quick setup from paired observations.","conditions":"Do not count 40 separate data values."}],"examples":[{"question_en":"A sample of 27 paired annual returns has Pearson r=0.40. Compute the correlation t statistic and degrees of freedom.","steps_vi":["df=27−2=25.","t=0.4√25/√(1−0.16)=2/√.84."],"answer":"t≈2.1822; df=25.","check":""},{"question_en":"For the preceding r=0.40,n=27, a two-sided 5% critical value is ±2.060. Decide.","steps_vi":["Observed |t|≈2.1822 exceeds 2.060."],"answer":"Reject H₀: population Pearson correlation equals zero.","check":""},{"question_en":"A sample of 12 paired observations has r=0.35. Calculate t.","steps_vi":["df=10; t=.35√10/√(1−.35²)."],"answer":"t≈1.1815; df=10.","check":""},{"question_en":"A sample of 32 paired observations has r=0.35. Calculate t and interpret relative to two-sided 5% critical ±2.042.","steps_vi":["df=30; t=.35√30/√(1−.35²)≈2.046.","2.046>2.042."],"answer":"t≈2.046; reject H₀ at 5% two-sided.","check":""},{"question_en":"There are 33 paired return observations with r=0.43051. Compute the correlation t statistic.","steps_vi":["n−2=31; t=.43051√31/√(1−.43051²)."],"answer":"t≈2.6557; df=31.","check":""},{"question_en":"For a right-tailed test with df=31 and t=2.6557, the 1% critical value is 2.4528. Decide.","steps_vi":["2.6557>2.4528, in right rejection tail."],"answer":"Reject H₀; evidence of positive Pearson correlation.","check":""},{"question_en":"A sample has n=50 paired observations and r=−0.25. Compute the Pearson t statistic.","steps_vi":["t=−.25√48/√(1−.0625)."],"answer":"t≈−1.7889; df=48.","check":""},{"question_en":"Using the preceding negative t≈−1.789, a left-tail 5% critical is −1.677. Decide.","steps_vi":["−1.789<−1.677, in left rejection tail."],"answer":"Reject H₀; evidence of negative Pearson correlation.","check":""},{"question_en":"A sample has n=20 pairs. What is the correct degrees of freedom for the Pearson zero-correlation t test?","steps_vi":["df=n−2=20−2."],"answer":"18.","check":""},{"question_en":"A sample has n=30 and a two-sided critical t=2.048. Find the threshold absolute correlation.","steps_vi":["rcrit=2.048/√(2.048²+28)."],"answer":"rcrit≈0.3609.","check":""},{"question_en":"A sample has n=52 and Pearson r=0.50. Compute the correlation t statistic.","steps_vi":["t=.50√50/√(1−.25)."],"answer":"t≈4.0825; df=50.","check":""},{"question_en":"A perfectly monotonic ordering of six X observations is exactly the reverse ordering of Y. What is Spearman rank correlation?","steps_vi":["Every X rank has reversed Y rank.","Perfect descending monotonic relation."],"answer":"rₛ=−1.","check":""},{"question_en":"For untied ranks with n=6 and Σdᵢ²=4, calculate Spearman rₛ.","steps_vi":["rₛ=1−6×4/[6(36−1)].","=1−24/210."],"answer":"rₛ≈0.8857.","check":""},{"question_en":"For untied ranks n=5 with rank differences [0,1,−1,2,−2], calculate the Spearman coefficient.","steps_vi":["Σd²=0+1+1+4+4=10.","rₛ=1−6×10/[5(25−1)]."],"answer":"rₛ=0.50.","check":""},{"question_en":"Two ranked series have a single tied pair. Should the simplified no-ties Spearman formula be assumed exact?","steps_vi":["With ties, the exact Spearman coefficient is Pearson correlation on midranks."],"answer":"No; use rank-based Pearson with average ranks for ties.","check":""},{"question_en":"For a Spearman coefficient rₛ=0.60 with n=18, calculate the t approximation.","steps_vi":["t≈.60√16/√(1−.36)=2.4/.8."],"answer":"t≈3.0000; df=16.","check":""},{"question_en":"A non-normal sample exhibits an increasing but curved relationship. Which correlation measure may better capture monotonic association?","steps_vi":["Spearman ranks can capture order agreement without linear assumption."],"answer":"Spearman rank correlation.","check":""},{"question_en":"A sample Pearson r=−0.10 is calculated from 152 independent pairs. Estimate t.","steps_vi":["df=150; t=−0.10√150/√(1−.01)."],"answer":"t≈−1.2309; df=150.","check":""},{"question_en":"For a two-sided correlation test, t=2.30 with df=40 and supplied critical values ±2.021. What decision follows?","steps_vi":["|2.30|>2.021."],"answer":"Reject H₀.","check":""},{"question_en":"A correlation test has p=0.07 and preselected α=5%. What decision follows?","steps_vi":["0.07>0.05."],"answer":"Fail to reject H₀.","check":""}],"questions":[{"stem_en":"The null hypothesis in a standard population correlation significance test is:","options":["The population correlation equals 1","The population correlation equals 0","The sample correlation must equal 0"],"correct":1,"why_vi":"H₀:ρ=0; sample statistic có thể khác 0 do random sampling.","trap_vi":""},{"stem_en":"The t statistic used to test zero Pearson population correlation has degrees of freedom equal to:","options":["n−2","n−1","n"],"correct":0,"why_vi":"t test correlation có df=n−2.","trap_vi":""},{"stem_en":"For n=27 and r=0.40, the Pearson correlation t statistic is closest to:","options":["1.250","2.182","4.000"],"correct":1,"why_vi":"t=.4√25/√.84≈2.182.","trap_vi":""},{"stem_en":"A two-sided 5% correlation test has calculated |t|=2.18 and critical |t|=2.06. The decision is to:","options":["Reject the zero-correlation null","Fail to reject the null","Conclude that one return series causes the other"],"correct":0,"why_vi":"2.18>2.06 nên reject H₀.","trap_vi":""},{"stem_en":"The parametric Pearson correlation is primarily a measure of:","options":["Linear association of two variables","Causation of one variable by the other","Rank agreement only"],"correct":0,"why_vi":"Pearson chuẩn hóa covariance và đo association tuyến tính.","trap_vi":""},{"stem_en":"A right-tailed population correlation alternative should be written as:","options":["Hₐ:ρ≠0","Hₐ:ρ>0","Hₐ:ρ<0"],"correct":1,"why_vi":"Positive correlation claim ⇒ right-tail Hₐ:ρ>0.","trap_vi":""},{"stem_en":"A left-tailed correlation test yields t=−2.10 and left critical value −1.70. The analyst should:","options":["Reject H₀","Fail to reject H₀","Change the test to two-sided"],"correct":0,"why_vi":"−2.10<−1.70 ⇒ reject left tail.","trap_vi":""},{"stem_en":"For n=20 paired observations, the correct correlation-test degrees of freedom is:","options":["19","40","18"],"correct":2,"why_vi":"df=n−2=18.","trap_vi":""},{"stem_en":"Which statement about sample size and correlation significance is most accurate?","options":["Increasing sample size generally lowers the minimum |r| needed for significance","A correlation of 0.20 is always significant","The significance threshold does not depend on sample size"],"correct":0,"why_vi":"|t| tăng với √(n−2) nếu r cố định khác 0.","trap_vi":""},{"stem_en":"Which approach is more appropriate for strongly nonnormal ordinal ratings?","options":["Spearman rank correlation","Pearson correlation must always be used","A chi-square test of a single population variance"],"correct":0,"why_vi":"Ordinal/rank observations phù hợp Spearman.","trap_vi":""},{"stem_en":"In the absence of tied ranks, the Spearman coefficient is calculated using:","options":["1−6Σd²/[n(n²−1)]","Σd/(n−1)","Σd²/(n+1)"],"correct":0,"why_vi":"Shortcut Spearman ranks không ties.","trap_vi":""},{"stem_en":"For n=6 and Σd²=4 without ties, Spearman rₛ is closest to:","options":["0.1143","0.8857","0.5000"],"correct":1,"why_vi":"1−24/210=.885714.","trap_vi":""},{"stem_en":"When tied observations occur in ranked data, the most accurate general computation of Spearman rho is:","options":["Pearson correlation of average ranks","Apply the no-ties shortcut without changes","Discard every tied observation"],"correct":0,"why_vi":"Midranks rồi correlation ranks; no-ties shortcut không exact khi ties.","trap_vi":""},{"stem_en":"For Spearman rₛ=0.60 with n=18, its approximate t statistic equals:","options":["1.500","3.000","6.000"],"correct":1,"why_vi":"t≈.6√16/√.64=3.","trap_vi":""},{"stem_en":"In a two-sided Pearson correlation test, which rejection rule is correct?","options":["Reject if |t| is greater than its two-sided critical threshold","Reject whenever the sample correlation is positive","Reject if the p-value exceeds α"],"correct":0,"why_vi":"Hai đuôi xét |t| > threshold hoặc p≤α.","trap_vi":""},{"stem_en":"A Pearson r of −0.25 based on 50 pairs implies a correlation t statistic closest to:","options":["+1.789","−1.789","−5.000"],"correct":1,"why_vi":"−.25√48/√(1−.0625)=−1.789.","trap_vi":""},{"stem_en":"An observed correlation test has a two-sided p-value of 0.07 at α=0.05. The appropriate decision is:","options":["Reject H₀","Fail to reject H₀","Accept that population correlation is exactly zero"],"correct":1,"why_vi":"p>.05 nên chưa đủ evidence bác bỏ; không accept H₀.","trap_vi":""},{"stem_en":"If returns are highly autocorrelated over time, the ordinary Pearson zero-correlation t-test may be unreliable because:","options":["Observations may not satisfy independence assumptions","Degrees of freedom always equal n+2","Correlation is incapable of being negative"],"correct":0,"why_vi":"Phụ thuộc serial làm invalid naïve inference.","trap_vi":""},{"stem_en":"Which claim is NOT justified by statistically significant correlation?","options":["Evidence of nonzero association under assumptions","Proof that one variable causes the other","Sample relationship is unlikely under the specified zero-correlation null"],"correct":1,"why_vi":"Association không chứng minh causal direction.","trap_vi":""},{"stem_en":"A perfectly decreasing monotonic rank relationship has Spearman coefficient:","options":["+1","0","−1"],"correct":2,"why_vi":"Thứ tự đảo hoàn toàn =>−1.","trap_vi":""},{"stem_en":"In a Pearson correlation zero test, r=0 implies the calculated t statistic equals:","options":["0","1","Undefined for every sample size"],"correct":0,"why_vi":"Với n>2 và r=0, numerator t=0.","trap_vi":""},{"stem_en":"For two-sided α=5%, the cutoff t is determined by:","options":["α and df=n−2","The sample covariance alone","Only the correlation sign"],"correct":0,"why_vi":"Critical quantile phụ thuộc α, n−2 df.","trap_vi":""},{"stem_en":"The Spearman rank coefficient best captures:","options":["Monotonic association","Only a positive linear slope","Conditional probability of default"],"correct":0,"why_vi":"Spearman measures monotonic relationship on ranks.","trap_vi":""},{"stem_en":"A rank-correlation t test for a small sample with many tied ranks should be regarded as:","options":["Exact under every possible sampling distribution","A possible approximation requiring care","Proof that the data are independent"],"correct":1,"why_vi":"T approximation không exact universally, nhất là small n/ties.","trap_vi":""},{"stem_en":"If |r| is fixed at a nonzero value and n increases, the absolute correlation t statistic generally:","options":["Decreases","Stays constant","Increases"],"correct":2,"why_vi":"t proportional √(n−2) /√(1−r²).","trap_vi":""},{"stem_en":"An analyst has 12 paired monthly returns for two funds. For a Pearson correlation significance test, n equals:","options":["24","12","11"],"correct":1,"why_vi":"Một cặp returns là một observation; n=12.","trap_vi":""},{"stem_en":"An observed t=−2.20 for a prespecified right-tailed positive correlation test should usually:","options":["Support rejecting for positive association","Fail to reject the positive association test","Be converted to +2.20 automatically"],"correct":1,"why_vi":"Right-tailed rejection chỉ với t sufficiently POSITIVE.","trap_vi":""},{"stem_en":"In a correlation test, a p-value of 0.03 is best read as:","options":["The probability H₀ is true","A null-based probability of observing at least as extreme a statistic","The probability of a positive return next month"],"correct":1,"why_vi":"Đúng interpretation p-value conditional on H₀.","trap_vi":""},{"stem_en":"For an untied rank sample with all ranks identical across two variables, Spearman correlation is:","options":["+1","0","−1"],"correct":0,"why_vi":"Σd²=0 =>+1.","trap_vi":""},{"stem_en":"Which change improves the conceptual validity of selecting a correlation test?","options":["Selecting the sign of Ha after seeing r","Checking for linearity, outliers, ranks and pairing before choosing Pearson or Spearman","Interpreting significant r as causation"],"correct":1,"why_vi":"Test choice phải theo data structure và assumptions, không after-the-fact.","trap_vi":""}],"cards":[{"front_en":"Pearson correlation: population test null?","back_vi":"H₀: ρ=0."},{"front_en":"Correlation t test formula?","back_vi":"t=r√(n−2)/√(1−r²)."},{"front_en":"Correlation test degrees of freedom?","back_vi":"n−2 complete pairs."},{"front_en":"Pearson r measures?","back_vi":"Linear relation of raw numerical observations."},{"front_en":"Spearman rₛ measures?","back_vi":"Monotonic association of ranked observations."},{"front_en":"When favor Spearman?","back_vi":"Ordinal ranks, non-normal/outlier-heavy data, monotonic association."},{"front_en":"Two-sided Pearson test?","back_vi":"Reject when |t| > positive two-sided t critical value."},{"front_en":"Right-sided Pearson test?","back_vi":"Hₐ:ρ>0, reject if t > right-tail t critical."},{"front_en":"Left-sided Pearson test?","back_vi":"Hₐ:ρ<0, reject if t < lower negative critical."},{"front_en":"Spearman no-ties formula?","back_vi":"rₛ=1−6Σdᵢ²/[n(n²−1)]."},{"front_en":"What is dᵢ in Spearman?","back_vi":"Rank Xi minus rank Yi for pair i."},{"front_en":"What is wrong with using no-ties shortcut with ties?","back_vi":"May give an inexact rₛ; use correlation on midranks."},{"front_en":"Spearman correlation with ties?","back_vi":"Pearson correlation of average rank values."},{"front_en":"Spearman significance approximation?","back_vi":"t≈rₛ√(n−2)/√(1−rₛ²), df=n−2; small-n/ties caution."},{"front_en":"P-value rejection rule?","back_vi":"p≤preselected α."},{"front_en":"Why does larger n help detect nonzero r?","back_vi":"Fixed nonzero |r| leads to larger absolute t with n."},{"front_en":"Threshold |r| given tcrit?","back_vi":"tcrit/√(tcrit²+n−2)."},{"front_en":"Can correlation imply causation?","back_vi":"No."},{"front_en":"Does Pearson r=0 imply independence?","back_vi":"Not generally; special distributional conditions needed."},{"front_en":"Can sample r be nonzero when population rho is zero?","back_vi":"Yes, sampling variation."},{"front_en":"How to count n for correlation?","back_vi":"Number of paired observations, not 2n."},{"front_en":"Does correlation t use df n−1?","back_vi":"No, df=n−2."},{"front_en":"What if r=1?","back_vi":"Idealized t denominator zero; sample perfect linearity."},{"front_en":"What does failing to reject zero correlation mean?","back_vi":"Insufficient evidence at selected α, not proof exact zero."},{"front_en":"Why inspect serial dependence?","back_vi":"Autocorrelation can invalidate independent-pairs t inference."}]},{"id":"CFA26-01-09-LOS02","letter":"9.b","title_en":"Chi-Square Tests of Independence Using Contingency Tables","outcome_en":"Explain tests of independence based on contingency table data.","overview_vi":"LOS 9.b kiểm định association giữa hai categorical variables bằng contingency table: observed counts Oij, row/column totals, expected count Eij=(row total×column total)/N, Pearson chi-square statistic Σ(O−E)²/E, df=(r−1)(c−1), reject right tail nếu statistic > critical. Bổ sung cách đọc standardized/Pearson residual, expected-frequency limitations, và phân biệt chi-square independence với chi-square variance test.","source":[{"id":"CFA Institute Curriculum 2026 — Quant LM9","pages":"251–252 and 261–270 (physical PDF; independence, table, chi-square, residuals; summary df typo on p252)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 9","pages":"107–110 (physical PDF; contingency-table independence)"},{"id":"SAPP Quant Slide Notes 2026 — Module 9","pages":"388–395 (physical PDF; observed/expected/critical decision)"}],"sections":[{"heading":"1. A contingency table organizes categorical data","body":"Contingency table/two-way table đếm observations theo hai categorical classifications: ví dụ credit quality {low,mid,high} × dividend policy {low,high}. Mỗi cell Oij là frequency, không phải correlation hoặc probability density. Row/column totals là marginal counts, tổng N phải nhất quán.","trap":""},{"heading":"2. The independence hypothesis","body":"H₀: row category và column category độc lập (distribution of column type không phụ thuộc row class). Hₐ: hai classifications associated, không independent. Test nói về categorical association, không xác định yếu tố nào là causal và không tự nhận diện đúng ô responsible nếu không xem residuals.","trap":""},{"heading":"3. Nonparametric chi-square independence framework","body":"Dùng Pearson χ² test (right-tail only) so observed cell counts với expected under H₀. “Chi-square” ở đây là tên statistic/distribution; khác với one-population normal-variance chi-square ở LM8 dù cùng family reference.","trap":""},{"heading":"4. Calculate expected counts under independence","body":"Eij=(row total i×column total j)/N. Ví dụ N=100, row “equity”=40, column “high”=25 ⇒ E=40×25/100=10. Kỳ vọng count không cần integer; có thể 10.25. Đừng nhầm E với observed O.","trap":""},{"heading":"5. Why expected counts are a product of marginals","body":"Under H₀, P(row i & col j)=P(row i)P(col j), nên predicted count N×(rowTotal/N)×(colTotal/N)=row×col/N. Đây là independence implication, không phải đo empirical conditional association ngoài H₀.","trap":""},{"heading":"6. Summation of chi-square contributions","body":"χ² = Σ_iΣ_j (Oij−Eij)²/Eij. Mỗi cell contribution nonnegative, nên overall χ²≥0. Khi O=E ở mọi cell thì statistic=0. Một cell có difference 5 trong expected 2 có contribution lớn hơn difference 5 trong expected 100: cần scale by E.","trap":""},{"heading":"7. Degrees of freedom of r×c table","body":"df=(r−1)(c−1). Bảng 2×2 ⇒1 df; 2×3 ⇒2; 3×3 ⇒4. Bắt buộc phân biệt với (n−1) của variance χ², n−2 của correlation t. **Source erratum:** CFAI Quant PDF physical p252 in Learning Module Overview ghi nhầm (r−1)(c−2), nhưng phần solved example physical p264 dùng chính xác (3−1)(3−1)=4.","trap":""},{"heading":"8. The right-tail rejection rule","body":"H₀ independent; large deviations => large χ². Reject if χ²>χ²₍1−α,df₎. Không dùng lower-tail cutoff để reject independence; χ² gần 0 phù hợp null hơn, không tự chứng minh independence.","trap":""},{"heading":"9. P-value approach","body":"p=P(χ²df≥observed χ²). If p≤α, reject H₀. p không cho biết probability hai variables associated hoặc posterior probability H₀. Chi-square test là omnibus: reject nghĩa ít nhất vài counts lệch expected đáng kể.","trap":""},{"heading":"10. Steps for a chi-square independence question","body":"(1) Xác định two categorical variables và H₀/Ha. (2) Lập observed table và margins. (3) Tính Eij cho mọi cell. (4) χ² contribution mỗi cell rồi cộng. (5) df=(r−1)(c−1), α, critical right-tail. (6) quyết định; giải thích non-independent association nếu reject.","trap":""},{"heading":"11. A 2×2 worked table","body":"Ví dụ O=[[30,10],[20,40]], rowTotals=[40,60], colTotals=[50,50], N=100. Expected E=[[20,20],[30,30]]. χ²=100/20+100/20+100/30+100/30≈16.6667, df=1; right-tail cutoff at 5%≈3.841. Reject independence; table indicates row membership associated with column classification.","trap":""},{"heading":"12. A 2×3 worked table","body":"Ví dụ observed row1=[12,18,30], row2=[18,12,10], rowTotals 60 and 40, colTotals 30,30,40, N=100. Expected row1=[18,18,24], row2=[12,12,16]. χ²=36/18 +0 +36/24 +36/12 +0 +36/16 = 8.75, df=2; cutoff α5%=5.991 ⇒ reject.","trap":""},{"heading":"13. A 3×3 table and degrees of freedom","body":"Bảng 3 levels của maturity × 3 levels của credit rating có 9 cells nhưng df=(3−1)(3−1)=4, KHÔNG phải 9−1=8. Constrained row/column margins làm số điều kiện tự do giảm. CFAI official worked 3×3 exercise sử dụng df=4 với right-tail critical 9.4877.","trap":""},{"heading":"14. Expected-frequency assumptions","body":"Chi-square approximation đáng tin cậy khi observations independent, categories mutually exclusive/exhaustive, expected counts đủ lớn; textbook heuristic thường ≥5 mỗi cell (hoặc rules less restrictive nhưng cần caution). Sparse cells ⇒ chi-square approximation yếu; có thể combine defensible categories hoặc dùng exact tests (extension) cho 2×2 nhỏ.","trap":""},{"heading":"15. Observed independence is not equality of raw totals","body":"Bảng có row totals khác nhau vẫn có thể independent: phải so proportions conditional theo hàng và expected counts, không so absolute Oij across unequal-size groups. Eij đã incorporate unequal margins.","trap":""},{"heading":"16. Pearson residual identifies influential cells","body":"Residualᵢⱼ=(Oij−Eij)/√Eij. Positive: more observations than independence predicts; negative: fewer. |residual| lớn chỉ giúp chẩn đoán ô đóng góp nhiều vào χ²; việc suy luận riêng từng cell có multiple-comparison caveat.","trap":""},{"heading":"17. Contribution is square of Pearson residual","body":"(Oij−Eij)²/Eij = residualᵢⱼ²; tổng χ² là sum of squared residuals. Cùng χ² có thể xuất phát từ nhiều mẫu hình counts khác nhau. Báo cáo association không có nghĩa tất cả cells đều off.","trap":""},{"heading":"18. Cramér’s V as effect size (extension)","body":"V=√[χ²/(N×min(r−1,c−1))] là normalized association size cho categorical tables (0–1), khác p-value và khác Pearson r. Đánh dấu kiến thức mở rộng, không biến thành yêu cầu tính mới của LOS chính thức nếu chỉ cần explain χ² independence.","trap":""},{"heading":"19. Comparing χ² independence with regression/correlation","body":"Pearson/Spearman in LOS 9.a thích hợp paired numeric/rank variables; contingency χ² in LOS 9.b cho two nominal/ordinal classifications. Cả hai có thể test association nhưng parameter, statistic, reference distribution và information giữ lại khác nhau.","trap":""},{"heading":"20. Independence is different from homogeneity (extension)","body":"Trong two-way table, chi-square independence và homogeneity thường dùng cùng χ² computational formula nhưng thiết kế lấy mẫu và null verbal framing khác nhau. LOS này nói hai categorical properties of observations độc lập; nên giữ correct context thay vì gán mọi bảng là same population distribution question.","trap":""},{"heading":"21. Correlation and contingency chi-square have different tails","body":"LM9 Pearson t có one-/two-tailed tùy Ha positive/negative/nonzero; chi-square independence chỉ reject khi observed χ² đủ lớn, vì statistic là tổng bình phương nonnegative. Đừng dùng chi-square variance left-tailed rules từ LM8 vào contingency table.","trap":""},{"heading":"22. Practical conclusion wording","body":"Nếu χ²stat>critical: “Reject the null of independence; evidence suggests association between categories.” Nếu χ²stat≤critical: “Fail to reject the null; insufficient evidence of association.” Không viết “proved independent”, và đừng kết luận magnitude association nếu chỉ nhìn p.","trap":""},{"heading":"23. Exam checklist for contingency tables","body":"(1) N và margins; (2) expected Eij=row×column/N; (3) mỗi contribution (O−E)²/E; (4) χ² sum; (5) df=(r−1)(c−1), right-tail χ²critical; (6) reject/fail; (7) nghĩ đến sparse expected và residual; (8) nhớ CFAI p252 summary typo, dùng công thức đúng.","trap":""}],"formulas":[{"name":"Expected cell count under independence","expr":"Eᵢⱼ=(row totalᵢ×column totalⱼ)/N","meaning":"Expected frequency for cell i,j.","conditions":"N>0; well-defined marginal totals."},{"name":"Pearson chi-square independence statistic","expr":"χ²=ΣᵢΣⱼ(Oᵢⱼ−Eᵢⱼ)²/Eᵢⱼ","meaning":"Aggregate scaled squared observed–expected deviations.","conditions":"Eij>0, independently sampled counts."},{"name":"Chi-square degrees of freedom","expr":"df=(r−1)(c−1)","meaning":"r row categories, c column categories.","conditions":"Correct rule; CFAI p252 overview typo says (r−1)(c−2)."},{"name":"Right-tail rejection","expr":"reject H₀ if χ²stat>χ²critical, upper tail α","meaning":"Only large statistics reject independence.","conditions":"Proper df and significance α."},{"name":"Chi-square p-value","expr":"p=P(χ²df≥χ²observed)","meaning":"Right-tail null probability.","conditions":"Approximate reference when expected counts adequate."},{"name":"Pearson standardized residual","expr":"residualᵢⱼ=(Oᵢⱼ−Eᵢⱼ)/√Eᵢⱼ","meaning":"Sign and magnitude of cell departure.","conditions":"Eij>0; descriptive/post hoc."},{"name":"Cell contribution","expr":"contributionᵢⱼ=residualᵢⱼ²","meaning":"Squared standardized deviation contributes to total χ².","conditions":"Eij>0."},{"name":"2×2 table degrees of freedom","expr":"df=(2−1)(2−1)=1","meaning":"Two categories in each dimension.","conditions":"No correction for small expected counts implied."},{"name":"2×3 table degrees of freedom","expr":"df=(2−1)(3−1)=2","meaning":"Two row categories, three column categories.","conditions":"Expected-count assumption needed."},{"name":"3×3 table degrees of freedom","expr":"df=(3−1)(3−1)=4","meaning":"Three levels in each dimension.","conditions":"Contradicts typo c−2 in CFAI p252."},{"name":"Marginal totals","expr":"N=Σ_i rowTotalᵢ=Σ_j colTotalⱼ=ΣᵢΣⱼOᵢⱼ","meaning":"Consistency of observed counts.","conditions":"Counts nonnegative integers."},{"name":"Cramér’s V — extension","expr":"V=√[χ²/(N×min(r−1,c−1))]","meaning":"Normalized categorical association effect size.","conditions":"Beyond core LOS focus; N>0, r,c≥2."},{"name":"Binomial 2×2 exact alternative — extension","expr":"Use exact contingency test when expected counts too small","meaning":"Not χ² formula; different inferential method.","conditions":"Small cell counts and fixed-margin assumptions can motivate it."}],"examples":[{"question_en":"A 2×2 contingency table has observed counts [[30,10],[20,40]]. Find row and column totals and N.","steps_vi":["Rows: 40 and 60; columns: 50 and 50.","N=30+10+20+40=100."],"answer":"Rows (40,60); columns (50,50); N=100.","check":""},{"question_en":"For the preceding 2×2 table, calculate expected counts under independence.","steps_vi":["E11=40×50/100=20; E12=20.","E21=60×50/100=30; E22=30."],"answer":"E=[[20,20],[30,30]].","check":""},{"question_en":"Using observed [[30,10],[20,40]] and expected [[20,20],[30,30]], calculate Pearson chi-square.","steps_vi":["χ²=100/20+100/20+100/30+100/30.","=5+5+3.3333+3.3333."],"answer":"χ²≈16.6667.","check":""},{"question_en":"For a 2×2 independence test with χ²=16.6667 and 5% upper critical 3.841, conclude.","steps_vi":["df=(2−1)(2−1)=1.","16.6667>3.841."],"answer":"Reject H₀; evidence the categorical variables are associated.","check":""},{"question_en":"A 2×3 observed contingency table is [[12,18,30],[18,12,10]]. Calculate its margins.","steps_vi":["Rows 60,40; columns 30,30,40; N=100."],"answer":"Rows (60,40); columns (30,30,40); N=100.","check":""},{"question_en":"For the preceding 2×3 table, calculate expected counts under independence.","steps_vi":["Row1 E=[60×30/100,60×30/100,60×40/100]=[18,18,24].","Row2 E=[12,12,16]."],"answer":"E=[[18,18,24],[12,12,16]].","check":""},{"question_en":"Compute Pearson chi-square for observed [[12,18,30],[18,12,10]] and expected [[18,18,24],[12,12,16]].","steps_vi":["Contributions: 36/18,0,36/24,36/12,0,36/16.","Sum=2+1.5+3+2.25."],"answer":"χ²=8.75.","check":""},{"question_en":"At α=5%, a 2×3 χ² independence test yields χ²=8.75. Given upper critical 5.991, decide.","steps_vi":["df=(2−1)(3−1)=2.","8.75>5.991."],"answer":"Reject H₀; association is statistically significant.","check":""},{"question_en":"A 3×3 table has how many degrees of freedom for χ² independence?","steps_vi":["df=(3−1)(3−1)=4."],"answer":"4 degrees of freedom.","check":""},{"question_en":"A 4×2 categorical table has how many independence-test degrees of freedom?","steps_vi":["df=(4−1)(2−1)=3."],"answer":"3 degrees of freedom.","check":""},{"question_en":"In a contingency table, a cell has O=36 and E=25. Compute Pearson residual.","steps_vi":["(36−25)/√25=11/5."],"answer":"Residual=+2.20.","check":""},{"question_en":"A cell has O=16 and E=25. Calculate its contribution to Pearson chi-square.","steps_vi":["(16−25)²/25=81/25."],"answer":"Contribution=3.24.","check":""},{"question_en":"A cell has O=8 and E=20. Find the Pearson residual and its χ² contribution.","steps_vi":["Residual=(8−20)/√20=−12/4.4721≈−2.6833.","Contribution=144/20=7.20."],"answer":"Residual≈−2.6833; contribution=7.20.","check":""},{"question_en":"A contingency table has r=3 rows and c=4 columns. Compute the degrees of freedom.","steps_vi":["df=(3−1)(4−1)=2×3."],"answer":"6.","check":""},{"question_en":"For a 3×3 table, the observed χ²=12.0 and upper 5% critical is 9.488. What is the conclusion?","steps_vi":["df=4.","12.0>9.488."],"answer":"Reject H₀; insufficient basis to claim independence.","check":""},{"question_en":"For a 3×3 table, χ²=7.5 and upper 5% critical 9.488. What is the conclusion?","steps_vi":["7.5<9.488 so not in rejection region."],"answer":"Fail to reject H₀.","check":""},{"question_en":"A table has two row categories with totals 60 and 40 and two column totals 75 and 25. Find E for row 2, column 2 if N=100.","steps_vi":["E22=40×25/100."],"answer":"Expected count=10.","check":""},{"question_en":"A category table has counts [[10,10],[10,10]]. Compute χ² independence.","steps_vi":["Each expected count equals 10.","All O−E=0."],"answer":"χ²=0.","check":""},{"question_en":"An independence test χ² statistic is 5.2, df=2, at α=5%. With 5.991 upper critical, conclude.","steps_vi":["5.2<5.991."],"answer":"Fail to reject H₀.","check":""},{"question_en":"With r=2,c=4,N=200, and chi-square=24, compute Cramers V as an extension.","steps_vi":["min(r−1,c−1)=min(1,3)=1.","V=√(24/(200×1))."],"answer":"V≈0.3464.","check":""},{"question_en":"In the CFAI 2026 Quant Module 9 overview p252, a formula states (r−1)(c−2). What should an analyst use for a 3×3 chi-square independence test?","steps_vi":["The PDF overview contains an apparent typo.","Use df=(3−1)(3−1)=4, as in its worked examples and standard mathematics."],"answer":"Use df=4 (correct formula (r−1)(c−1)).","check":""}],"questions":[{"stem_en":"The null hypothesis in a chi-square contingency-table independence test states that:","options":["The two categorical variables are independent","The variables have equal arithmetic means","The variables have perfect Pearson correlation"],"correct":0,"why_vi":"H₀ independence giữa hai classifications.","trap_vi":""},{"stem_en":"A contingency-table cell has row total 40, column total 25, and grand total 100. Its expected count under independence is:","options":["25","10","40"],"correct":1,"why_vi":"E=40×25/100=10.","trap_vi":""},{"stem_en":"The Pearson chi-square statistic for independence is calculated as:","options":["Σ(O−E)²/E","Σ(O−E)/E","Σ(O−E)²"],"correct":0,"why_vi":"Các squared deviations được chuẩn theo expected count.","trap_vi":""},{"stem_en":"For a 3×3 contingency table, chi-square independence degrees of freedom equal:","options":["9","3","4"],"correct":2,"why_vi":"df=(3−1)(3−1)=4; CFAI p252 overview typo c−2.","trap_vi":""},{"stem_en":"For a 2×4 contingency table, degrees of freedom are:","options":["3","6","8"],"correct":0,"why_vi":"(2−1)(4−1)=3.","trap_vi":""},{"stem_en":"A chi-square test of independence rejects its null hypothesis when the test statistic is:","options":["Sufficiently small","Sufficiently large","Negative"],"correct":1,"why_vi":"Large deviations imply χ² large, right tail.","trap_vi":""},{"stem_en":"An observed 2×2 table is [[30,10],[20,40]]. Its grand total is:","options":["80","100","120"],"correct":1,"why_vi":"N=30+10+20+40=100.","trap_vi":""},{"stem_en":"For the previous 2×2 observed table, the expected count for row 1, column 1 is:","options":["20","30","40"],"correct":0,"why_vi":"E11=40×50/100=20.","trap_vi":""},{"stem_en":"For observed [[30,10],[20,40]], the expected table under independence is:","options":["[[25,25],[25,25]]","[[30,10],[20,40]]","[[20,20],[30,30]]"],"correct":2,"why_vi":"Expected from marginals [40,60] and [50,50].","trap_vi":""},{"stem_en":"For observed [[30,10],[20,40]] with expected [[20,20],[30,30]], chi-square is closest to:","options":["16.667","3.841","1.000"],"correct":0,"why_vi":"100/20+100/20+100/30+100/30=16.667.","trap_vi":""},{"stem_en":"A 2×2 independence test yields χ²=16.67 and the 5% critical value is 3.841. The correct conclusion is:","options":["Fail to reject independence","Reject independence","Accept independence as proven"],"correct":1,"why_vi":"16.67>3.841.","trap_vi":""},{"stem_en":"A 2×3 table has observed rows [12,18,30] and [18,12,10]. Its row totals are:","options":["[30,70]","[40,60]","[60,40]"],"correct":2,"why_vi":"Row1=60, row2=40.","trap_vi":""},{"stem_en":"For the 2×3 table in the preceding question, expected counts for row 1 are:","options":["[18,18,24]","[12,18,30]","[30,30,40]"],"correct":0,"why_vi":"60×[30,30,40]/100=[18,18,24].","trap_vi":""},{"stem_en":"The Pearson chi-square statistic for observed [[12,18,30],[18,12,10]] is:","options":["2.25","8.75","5.99"],"correct":1,"why_vi":"Σ contributions=2+0+1.5+3+0+2.25=8.75.","trap_vi":""},{"stem_en":"For a 2×3 test with χ²=8.75 and 5% critical 5.991, the decision is:","options":["Reject H₀","Fail to reject H₀","Change to a left-tail test"],"correct":0,"why_vi":"8.75>5.991 ⇒ reject independence.","trap_vi":""},{"stem_en":"If a cell has O=36 and E=25, its Pearson residual is:","options":["+2.20","−2.20","+11.00"],"correct":0,"why_vi":"(36−25)/√25=2.2.","trap_vi":""},{"stem_en":"If a cell has O=16 and E=25, its chi-square contribution is:","options":["−3.24","3.24","0.36"],"correct":1,"why_vi":"(16−25)²/25=81/25=3.24.","trap_vi":""},{"stem_en":"If a cell has O=8 and E=20, its chi-square contribution is:","options":["0.60","12.00","7.20"],"correct":2,"why_vi":"(8−20)²/20=7.2.","trap_vi":""},{"stem_en":"A Pearson residual is negative when:","options":["Observed count is less than expected count","Observed count exceeds expected count","The total chi-square statistic is negative"],"correct":0,"why_vi":"Residual=(O−E)/√E.","trap_vi":""},{"stem_en":"A contingency table has 4 row categories and 2 column categories. Degrees of freedom equal:","options":["8","3","2"],"correct":1,"why_vi":"(4−1)(2−1)=3.","trap_vi":""},{"stem_en":"An observed χ²=7.5 for a 3×3 table with 5% critical 9.488 yields:","options":["Reject the null","Prove the null","Fail to reject the null"],"correct":2,"why_vi":"7.5<9.488.","trap_vi":""},{"stem_en":"Which assumption is important for a chi-square independence test?","options":["Expected cell counts are sufficiently large for the reference approximation","Variables must be jointly normally distributed","All rows must have equal totals"],"correct":0,"why_vi":"Chi-square approximate reference requires adequate expected frequencies and independent sampling.","trap_vi":""},{"stem_en":"The number of degrees of freedom for chi-square independence is:","options":["(r−1)(c−2)","(r−1)(c−1)","r×c"],"correct":1,"why_vi":"Correct formula (r−1)(c−1); CFAI p252 overview mistakenly uses c−2.","trap_vi":""},{"stem_en":"Which statement about chi-square independence is correct?","options":["Small test statistics lead to two-sided rejection","The test statistic may be negative","It tests categorical association with a right-tailed rejection rule"],"correct":2,"why_vi":"χ² nonnegative, rejects only large values.","trap_vi":""},{"stem_en":"The expected cell count under independence must be:","options":["A whole number in every cell","Nonnegative and may be fractional","Equal to the observed count"],"correct":1,"why_vi":"E=row×col/N can be decimal.","trap_vi":""},{"stem_en":"A Pearson residual of +3 suggests:","options":["More observations than expected in that cell","Fewer observations than expected in that cell","Proof of causation"],"correct":0,"why_vi":"Positive residual = O>E.","trap_vi":""},{"stem_en":"The sum of squared Pearson residuals equals:","options":["Pearson correlation","The chi-square test statistic","The F statistic"],"correct":1,"why_vi":"Σ[(O−E)/√E]²=Σ(O−E)²/E.","trap_vi":""},{"stem_en":"If all observed counts equal their expected counts, the chi-square statistic is:","options":["0","1","Negative"],"correct":0,"why_vi":"Every squared contribution =0.","trap_vi":""},{"stem_en":"Rejecting a chi-square null of independence implies:","options":["Causation has been established","Every observed cell has a significant deviation","There is statistical evidence of association"],"correct":2,"why_vi":"Chi-square omnibus test does not identify causality or every cell.","trap_vi":""},{"stem_en":"For a contingency-table 3×3 test, a lower-tail chi-square rejection region would generally be:","options":["Correct for evidence of association","Incorrect; only large chi-square values support rejecting independence","Equivalent to a paired t-test"],"correct":1,"why_vi":"H₀ independence ⇒ χ² deviation sum rejects right-tail.","trap_vi":""}],"cards":[{"front_en":"Chi-square independence null?","back_vi":"The two categorical classifications are independent."},{"front_en":"Chi-square independence alternative?","back_vi":"The two classifications are associated (not independent)."},{"front_en":"What is a contingency table?","back_vi":"Two-way categorical observed counts Oij."},{"front_en":"Expected cell frequency?","back_vi":"Eij=(row total×column total)/grand total."},{"front_en":"Chi-square test statistic?","back_vi":"Σcells(O−E)²/E."},{"front_en":"Degrees of freedom for r×c table?","back_vi":"(r−1)(c−1)."},{"front_en":"2×2 df?","back_vi":"1."},{"front_en":"2×3 df?","back_vi":"2."},{"front_en":"3×3 df?","back_vi":"4."},{"front_en":"4×2 df?","back_vi":"3."},{"front_en":"Tail of chi-square independence test?","back_vi":"Right tail only; reject for large χ²."},{"front_en":"Chi-square independence p-value?","back_vi":"P(χ²df≥observed statistic) under H₀."},{"front_en":"How to interpret reject H0?","back_vi":"Evidence of association, not proof of causal link."},{"front_en":"How to interpret fail reject?","back_vi":"Insufficient evidence of association, not proof of independence."},{"front_en":"Cell chi-square contribution?","back_vi":"(O−E)²/E."},{"front_en":"Pearson residual?","back_vi":"(O−E)/√E."},{"front_en":"Positive Pearson residual?","back_vi":"Count exceeds independence-based expectation."},{"front_en":"Negative Pearson residual?","back_vi":"Observed count is lower than expected."},{"front_en":"Can expected counts be fractional?","back_vi":"Yes."},{"front_en":"How are expected counts derived?","back_vi":"N×P(row)P(column) under H₀ independence."},{"front_en":"Why count margins first?","back_vi":"Need row totals, column totals, N to derive expected counts."},{"front_en":"What if expected cell counts are small?","back_vi":"Chi-square approximation may be inaccurate; consider alternatives."},{"front_en":"What is CFAI 2026 Quant p252 summary typo?","back_vi":"Prints df=(r−1)(c−2); correct df=(r−1)(c−1), matching own worked p264."},{"front_en":"Why chi-square statistic nonnegative?","back_vi":"Sum of squared deviations divided by positive E."},{"front_en":"Does χ² identify which cell differs?","back_vi":"Not alone; inspect residuals/post hoc evidence."},{"front_en":"Chi-square independence vs one-sample variance χ²?","back_vi":"Different null hypotheses and degrees of freedom; same distribution family."},{"front_en":"What does Cramér’s V measure (extension)?","back_vi":"Normalized strength of association in categorical table."},{"front_en":"Core assumptions of χ² independence?","back_vi":"Independent categorical observations and enough expected counts."},{"front_en":"How to obtain df for 3×3 table?","back_vi":"(3−1)(3−1)=4, not 9 or zero."}]}]},{"version":"2026.11.22-quant10-original-draft","module_id":"CFA26-01-10","module_title":"Simple Linear Regression","language":"Vietnamese theory/explanations; original English question stems and A/B/C","qa_status":"CFAI_2026_LOS_MAPPED_SELECTED_SOURCE_SECTIONS_NUMERIC_REVIEW_PENDING_FULL_ACADEMIC_SIGNOFF","disclaimer_vi":"Bài học tự biên soạn trên cơ sở đối chiếu CFA Institute Curriculum 2026, Kaplan SchweserNotes 2026 và SAPP Quant slide. Các nội dung mở rộng được đánh dấu rõ. Công thức và câu hỏi được kiểm tra trong phạm vi audit riêng; chưa phải toàn bộ module được nghiệm thu học thuật độc lập cuối cùng.","los":[{"id":"CFA26-01-10-LOS01","letter":"10.a","title_en":"OLS Model and Regression Coefficients","outcome_en":"describe a simple linear regression model, how the least squares criterion is used to estimate regression coefficients, and the interpretation of these coefficients","overview_vi":"Mô hình Y=β0+β1X+ε, ước lượng OLS từ paired observations, fitted vs actual, residual và ý nghĩa hệ số. Cần tính được slope/intercept, hiểu covariance/correlation link, units, extrapolation và nhận diện giới hạn diễn giải nhân quả.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"271–283 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"111–115 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"398–409 (physical PDF)"}],"sections":[{"heading":"1. What is a simple linear regression?","body":"Simple linear regression đặt Y (dependent/explained variable) là biến muốn hiểu hoặc dự báo, X (independent/explanatory variable) là một biến giải thích. Mô hình population: Yi=β0+β1Xi+εi; fitted sample line: Ŷi=b0+b1Xi. Nó mô tả conditional average relationship chứ tự thân không chứng minh nhân quả.","trap":"Cụm independent variable không đồng nghĩa X statistically independent of Y."},{"heading":"2. Dependent vs explanatory variables","body":"Trong ví dụ investment: excess return của quỹ có thể là Y, market excess return là X; β1 diễn giải sensitivity, không tự đồng nghĩa CAPM beta trong mọi specification. Khi hoán đổi Y và X, OLS line thường khác; slope của Y-on-X không phải 1/(slope X-on-Y) trừ |r|=1.","trap":""},{"heading":"3. Cross-sectional and time-series designs","body":"Cross-section so sánh nhiều doanh nghiệp cùng kỳ (ví dụ ROE theo leverage); time-series xem nhiều kỳ của một doanh nghiệp hoặc index (ví dụ return theo benchmark return). Kiểu dữ liệu ảnh hưởng rủi ro serial correlation, independence, macro trends và khả năng ngoại suy.","trap":""},{"heading":"4. Population coefficients versus estimates","body":"β0, β1 là unknown population parameters. b0, b1 có “hats” trong nhiều sách để thể hiện estimated values. Ɛ là error term thực của population; ei=Yi−Ŷi là residual quan sát sau khi fit, không được đánh đồng hai đại lượng. Y-hat dự báo conditional mean theo X.","trap":""},{"heading":"5. Scatterplot is a first diagnostic","body":"Vẽ các pairs (Xi,Yi): xu hướng thẳng tăng/giảm gợi ý phù hợp với linear approximation. Đường cong, thay đổi độ rộng của cloud hoặc một điểm X quá xa có thể báo sai dạng hàm/homoskedasticity/influential observation. Không đánh giá chất lượng mô hình chỉ bằng dấu slope.","trap":""},{"heading":"6. Vertical residual and OLS objective","body":"Dự báo cho pair i là Ŷi=b0+b1Xi; residual ei=Yi−Ŷi. Ordinary least squares (OLS) chọn b0,b1 để tối thiểu SSE=Σei² (vertical squared deviations). Không phải tối thiểu Σ|ei|, không phải Σ(Yi−X_i)² và không tối thiểu khoảng cách vuông góc đường thẳng.","trap":""},{"heading":"7. Slope from raw paired observations","body":"b1=Sxy/Sxx=Σ(Xi−Xbar)(Yi−Ybar)/Σ(Xi−Xbar)², nếu Sxx>0. Cả numerator và denominator dùng sums, hoặc sample covariance/sample variance cùng chia n−1 nên ratio như nhau. Units b1 = units(Y)/units(X); dấu từ Sxy.","trap":""},{"heading":"8. Intercept and the point of sample means","body":"b0=Ybar−b1Xbar. OLS fitted line with intercept đi qua (Xbar,Ybar). Vì vậy nếu biết b1 và hai means có thể tính ngay intercept; đây cũng là kiểm tra để bắt lỗi kết quả b0.","trap":""},{"heading":"9. Slope versus correlation","body":"b1=Cov(X,Y)/Var(X)=r·sY/sX. r là dimensionless in [−1,+1]; slope có đơn vị và không bị giới hạn ±1. Nếu cả hai SD dương, dấu của b1 và r giống nhau. Chú ý slope âm không đồng nghĩa R² âm.","trap":""},{"heading":"10. Economic meaning of a one-unit change","body":"b1 là mức thay đổi dự báo của Y khi X tăng 1 đơn vị (theo fitted conditional relationship). Ví dụ X là lãi suất biểu diễn phần trăm và Y return %, tăng X 1 điểm phần trăm khiến dự báo Y thay đổi b1 điểm phần trăm. Nếu X đo decimal, tăng 0.01 không phải tăng 1 whole unit.","trap":""},{"heading":"11. Interpretation and limitation of intercept","body":"b0 dự báo Y tại X=0. Nếu X không thể bằng 0 hoặc ngoài vùng quan sát, intercept chủ yếu giúp định vị line, không phải ý nghĩa kinh tế chắc chắn. Intercept âm không mặc nhiên khiến mô hình sai; cần xem units/range.","trap":""},{"heading":"12. Fitted values and OLS residual properties","body":"Với intercept và unweighted OLS: Σei=0, sample mean Ŷ=Ybar và ΣXi·ei=0. Các residual orthogonal to regressors (constant và X); đó là algebraic property trong sample, KHÔNG chứng minh errors ngoài population independent hay homoskedastic.","trap":""},{"heading":"13. Why squared errors instead of signed errors","body":"Σei có thể bằng 0 dù line fit tệ vì lỗi dương/âm bù trừ. Squaring tránh bù trừ và phạt mạnh deviations lớn. OLS có thể nhạy outliers vì residual lớn bị bình phương; median regression/robust fitting là phương án ngoài trọng tâm LOS.","trap":""},{"heading":"14. Worked fitting procedure","body":"Bước 1 ghép n pairs, tính Xbar,Ybar. Bước 2 tính Sxx và Sxy. Bước 3 b1=Sxy/Sxx và b0=Ybar−b1Xbar. Bước 4 tính Ŷ, residual từng quan sát, SSE và kiểm tra Σe≈0. Tránh làm tròn b1 trước bước cuối vì tích lũy sai số.","trap":""},{"heading":"15. Extrapolation versus interpolation","body":"Xf nằm trong vùng sample gọi interpolation; nằm ngoài vùng sample gọi extrapolation. Dù fitted line tính được cho mọi Xf, quan hệ thực ngoài sample có thể khác. Dự báo dựa trên một trend không chắc bền qua regime changes.","trap":""},{"heading":"16. Indicative data limitations","body":"Chỉ n ≥ 3 và Sxx>0 mới có residual df=n−2 để dùng standard errors. Nếu mọi Xi bằng nhau, không nhận dạng được slope; nếu sample observations duplicate/mismeasured, kết quả có thể không hữu ích. Big n không chữa tự động omitted-variable bias.","trap":""}],"formulas":[{"name":"Population regression","expr":"Yi=β0+β1Xi+εi","meaning":"β0 intercept; β1 population slope; εi unobservable error.","conditions":""},{"name":"Estimated fitted line","expr":"Ŷi=b0+b1Xi","meaning":"Conditional prediction at observed Xi; no ε term in fitted value.","conditions":""},{"name":"OLS residual","expr":"ei=Yi−Ŷi","meaning":"Realized actual minus fitted dependent variable.","conditions":""},{"name":"OLS criterion","expr":"minimize SSE(b0,b1)=Σ[Yi−(b0+b1Xi)]²","meaning":"Minimize vertical squared deviations.","conditions":"Ordinary least squares with intercept."},{"name":"Centered X variation","expr":"Sxx=Σ(Xi−X̄)²","meaning":"Denominator for slope and coefficient uncertainty.","conditions":"Requires Sxx>0."},{"name":"Centered cross-product","expr":"Sxy=Σ(Xi−X̄)(Yi−Ȳ)","meaning":"Numerator for slope; sign determines direction.","conditions":""},{"name":"OLS slope","expr":"b1=Sxy/Sxx","meaning":"Sample covariance(X,Y) divided by sample variance(X).","conditions":"OLS with intercept and nonconstant X."},{"name":"OLS intercept","expr":"b0=Ȳ−b1X̄","meaning":"Regression line passes through sample means.","conditions":""},{"name":"Covariance–correlation slope link","expr":"b1=r(X,Y)·sY/sX","meaning":"Sign(b1)=sign(r) when SDs positive.","conditions":""},{"name":"Predicted change","expr":"ΔŶ=b1·ΔX","meaning":"Effect on fitted Y for a change in X holding same model.","conditions":""},{"name":"Residual sum identity","expr":"Σei=0","meaning":"Holds algebraically for unweighted OLS with intercept; not population proof.","conditions":""},{"name":"Centered slope from sums","expr":"b1=[ΣXiYi−nX̄Ȳ]/[ΣXi²−nX̄²]","meaning":"Useful if raw sums supplied.","conditions":""}],"examples":[{"question_en":"Given X = [1, 2, 3, 4, 5] and Y = [2, 3, 5, 4, 6], estimate the OLS slope and intercept.","steps_vi":["Xbar=3, Ybar=4.","Sxx=4+1+0+1+4=10; Sxy=9.","Slope b1=9/10=0.90; intercept b0=4−0.90×3=1.30."],"answer":"Ŷ = 1.30 + 0.90X.","check":""},{"question_en":"For the fitted model Ŷ=1.30+0.90X, predict Y when X=4.","steps_vi":["Insert X=4: Ŷ=1.30+0.90×4.","Compute 1.30+3.60=4.90."],"answer":"4.90","check":""},{"question_en":"A stock return model is Ŷ=−1.8%+1.25X, where X is market return in percentage points. Interpret the slope.","steps_vi":["One-unit in X corresponds to one percentage point if X numbers are percentage points.","Fitted stock return changes by +1.25 percentage points for a +1 percentage-point market return change."],"answer":"+1.25 percentage points per 1 percentage point.","check":""},{"question_en":"Sample means are Xbar=3 and Ybar=7, and the OLS slope is 1.5. Find the intercept.","steps_vi":["OLS line crosses sample means: b0=Ybar−b1Xbar.","b0=7−1.5×3=2.5."],"answer":"2.50","check":""},{"question_en":"The observed Y is 8 and fitted Y is 6.5. What is the OLS residual?","steps_vi":["Residual e=Y−Ŷ=8−6.5."],"answer":"+1.50","check":""},{"question_en":"A regression has sample covariance Cov(X,Y)=12 and sample variance Var(X)=3. Determine the slope.","steps_vi":["b1=Cov(X,Y)/Var(X).","12/3=4 units of Y per unit of X."],"answer":"4.00","check":""},{"question_en":"A sample correlation is −0.40, sY=12 and sX=3. Calculate the OLS slope.","steps_vi":["b1=r·sY/sX.","b1=(−0.40)×12/3=−1.6."],"answer":"−1.60","check":""},{"question_en":"For an intercept OLS model, fitted residuals are 2, −1, −0.5, and an unknown fourth residual. Find the missing residual.","steps_vi":["OLS residuals sum to zero.","Unknown=−(2−1−0.5)=−0.5."],"answer":"−0.50","check":""},{"question_en":"If the fitted model is Ŷ=5−2X, what change in Y-hat follows a 0.5-unit increase in X?","steps_vi":["ΔŶ=b1ΔX=−2×0.5."],"answer":"−1.00","check":""},{"question_en":"For n=5, ΣXY=79, Xbar=3, Ybar=4, and ΣX²=55, determine Sxy and Sxx.","steps_vi":["Sxy=ΣXY−nXbarYbar=79−5×3×4=19.","Sxx=ΣX²−nXbar²=55−5×9=10."],"answer":"Sxy=19; Sxx=10.","check":""},{"question_en":"An analyst claims the model is proven causal because the estimated OLS slope is positive. Is that justified?","steps_vi":["OLS gives a sample linear association conditional on modeling assumptions.","Omitted factors, selection effects and reverse causality remain possible."],"answer":"No; the positive slope alone does not establish causality.","check":""},{"question_en":"What must an analyst check before estimating slope if all observed X values equal 2?","steps_vi":["Then Xbar=2 and Sxx=Σ(Xi−2)²=0.","Slope formula requires dividing by zero, so the slope is unidentified."],"answer":"Slope cannot be estimated from constant X.","check":""}],"questions":[{"stem_en":"Which variable is explained in a simple linear regression?","options":["Independent variable X","Dependent variable Y","The error variance"],"correct":1,"why_vi":"Y là biến cần giải thích; X là một explanatory variable.","trap_vi":""},{"stem_en":"OLS minimizes which quantity?","options":["Sum of absolute vertical errors","Sum of signed residuals","Sum of squared vertical residuals"],"correct":2,"why_vi":"OLS dùng SSE=Σ(Y−Ŷ)².","trap_vi":""},{"stem_en":"Which formula estimates the OLS slope with an intercept?","options":["Sxy/Sxx","Sxx/Sxy","Ybar−Xbar"],"correct":0,"why_vi":"b1=Sxy/Sxx; intercept là Ybar−b1Xbar.","trap_vi":""},{"stem_en":"Which statement about the fitted OLS line with an intercept is correct?","options":["It passes through (Xbar,Ybar).","Its intercept is always economically meaningful.","It always passes through the origin."],"correct":0,"why_vi":"Đường fitted có intercept đi qua điểm means mẫu.","trap_vi":""},{"stem_en":"If X is constant across all observations, what is true?","options":["Slope estimate is always zero.","OLS slope is not identified.","Correlation must be one."],"correct":1,"why_vi":"Sxx=0, nên không thể chia để tính b1.","trap_vi":""},{"stem_en":"Which statement about the sign of the OLS slope is correct when both sample standard deviations are positive?","options":["It must be positive.","It has the opposite sign of correlation.","It has the same sign as correlation."],"correct":2,"why_vi":"b1=r·sY/sX; tỷ số SD dương.","trap_vi":""},{"stem_en":"What does a slope of −0.8 indicate in a level–level model?","options":["A one-unit increase in X lowers fitted Y by 0.8 unit.","A one-percent increase in X lowers Y by 80%.","R-squared equals 0.8."],"correct":0,"why_vi":"Slope có đơn vị Y per unit of X.","trap_vi":""},{"stem_en":"Which observation is most likely to exert disproportionate influence on OLS?","options":["An observation exactly on the line","An observation with a large squared residual and extreme X","An observation at the sample mean with zero residual"],"correct":1,"why_vi":"Outlier có high leverage hoặc large residual có thể làm fitted coefficients thay đổi đáng kể.","trap_vi":""},{"stem_en":"What is the sample OLS residual?","options":["Ŷ−Y","β0+β1X","Y−Ŷ"],"correct":2,"why_vi":"Residual là observed minus fitted value.","trap_vi":""},{"stem_en":"What is a direct caveat about extrapolating a fitted regression?","options":["The fitted relationship may not hold beyond observed X values.","The slope must reverse outside the sample.","OLS predictions cannot be computed for new X."],"correct":0,"why_vi":"Có thể tính Ŷ ngoài sample nhưng độ tin cậy kinh tế khó bảo đảm.","trap_vi":""},{"stem_en":"Which measure is dimensionless?","options":["The OLS slope","The sample correlation coefficient","The regression intercept"],"correct":1,"why_vi":"Correlation không đơn vị, slope thường có Y/X.","trap_vi":""},{"stem_en":"For an intercept OLS regression, which sample identity always holds?","options":["Every residual equals zero.","SSE equals zero.","The sum of residuals equals zero."],"correct":2,"why_vi":"Normal equation với intercept cho Σe=0.","trap_vi":""},{"stem_en":"Xbar=4, Ybar=10, and b1=1.5. What is the fitted intercept?","options":["15.00","7.00","4.00"],"correct":2,"why_vi":"b0=10−1.5×4=4.","trap_vi":""},{"stem_en":"Sample covariance of X and Y is 9, while Var(X)=3. What is the slope?","options":["3.00","12.00","0.33"],"correct":0,"why_vi":"b1=9/3=3.","trap_vi":""},{"stem_en":"For Ŷ=2+0.75X, what is the predicted Y at X=8?","options":["6.00","8.00","10.00"],"correct":1,"why_vi":"Ŷ=2+.75×8=8.","trap_vi":""},{"stem_en":"Observed Y=13 and fitted Y=11.2. What is the residual?","options":["-1.80","1.80","24.20"],"correct":1,"why_vi":"e=13−11.2=1.8.","trap_vi":""},{"stem_en":"The sample correlation is r=−0.6, sY=5, and sX=2. What is b1?","options":["-0.24","-1.50","1.50"],"correct":1,"why_vi":"b1=r(sY/sX)=−.6×2.5=−1.5.","trap_vi":""},{"stem_en":"A slope b1=2.4 is estimated. If X rises by 0.5, how much does predicted Y change?","options":["1.20","2.90","4.80"],"correct":0,"why_vi":"ΔŶ=b1ΔX=2.4×.5=1.2.","trap_vi":""},{"stem_en":"With an OLS intercept, three residuals are 2.5, −1.0, and 0.5. What must the fourth residual equal?","options":["-2.00","2.00","4.00"],"correct":0,"why_vi":"Σe=0, so e4=−(2.5−1+.5)=−2.","trap_vi":""},{"stem_en":"For a sample, Sxy=24 and Sxx=16. What is the OLS slope?","options":["1.50","40.00","0.67"],"correct":0,"why_vi":"b1=24/16=1.5.","trap_vi":""}],"cards":[{"front_en":"Define simple linear regression.","back_vi":"Mô hình Y bằng intercept + slope×1 explanatory variable + error."},{"front_en":"Population simple regression equation?","back_vi":"Y=β0+β1X+ε."},{"front_en":"Estimated fitted value equation?","back_vi":"Ŷ=b0+b1X."},{"front_en":"Define residual.","back_vi":"e=Y−Ŷ, sai lệch dọc so với fitted line."},{"front_en":"What criterion does OLS minimize?","back_vi":"SSE=Σ(Yi−Ŷi)²."},{"front_en":"How to compute OLS slope?","back_vi":"b1=Sxy/Sxx=Cov(X,Y)/Var(X)."},{"front_en":"How to compute intercept?","back_vi":"b0=Ybar−b1Xbar."},{"front_en":"What is special about (Xbar,Ybar)?","back_vi":"Fitted OLS line with intercept passes through it."},{"front_en":"OLS slope from correlation?","back_vi":"b1=r(sY/sX)."},{"front_en":"Interpreting an OLS slope?","back_vi":"Change in Ŷ per one-unit change in X."},{"front_en":"Interpreting OLS intercept?","back_vi":"Ŷ at X=0; may have no economic meaning if X=0 unrealistic."},{"front_en":"When is OLS slope unidentified?","back_vi":"Sxx=0 (no variation in X)."},{"front_en":"Sum of residuals for intercept OLS?","back_vi":"Σei=0 in the sample."},{"front_en":"Is sample OLS residual equal to population error ε?","back_vi":"No; e is a fitted sample residual; ε is theoretical disturbance."},{"front_en":"Interpolation versus extrapolation?","back_vi":"Interpolation uses X inside sample range; extrapolation outside observed range."},{"front_en":"Cross-sectional versus time-series regression?","back_vi":"Many entities one period vs one entity many periods."},{"front_en":"Does significant slope prove causation?","back_vi":"Không; identification assumptions and omitted variables still matter."},{"front_en":"Why is OLS sensitive to extreme outliers?","back_vi":"Squared residual objective emphasizes large deviations."}]},{"id":"CFA26-01-10-LOS02","letter":"10.b","title_en":"Assumptions and Residual Diagnostics","outcome_en":"explain the assumptions underlying the simple linear regression model, and describe how residuals and residual plots indicate if these assumptions may have been violated","overview_vi":"Giải thích giả định tuyến tính, phương sai phần dư không đổi, error độc lập và normality; đọc residual plots và các tình huống heteroskedasticity, serial correlation, outlier và structural break, kèm giới hạn của suy luận chỉ từ biểu đồ.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"283–290 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"115–118 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"409–410 (physical PDF)"}],"sections":[{"heading":"1. Why OLS needs assumptions","body":"Một fitted line luôn tính được khi Sxx>0, nhưng hypothesis tests và forecast intervals chỉ đáng tin khi assumptions hợp lý. CFAI nhấn mạnh linearity, homoskedasticity, independent observations và normality of residuals. Trong ứng dụng còn nên xem exogeneity/correct model specification và stability.","trap":""},{"heading":"2. Linearity of conditional expectation","body":"Giả định conditional mean E(Y|X)=β0+β1X là hàm tuyến tính trên phạm vi thích hợp. Plot residuals theo fitted values hoặc X lý tưởng là random cloud quanh zero, không có U-shaped pattern. Nếu data tạo hình cong rõ, dạng level-level có thể misspecified.","trap":""},{"heading":"3. Why a curved residual pattern matters","body":"Residual dương khi X nhỏ và lớn nhưng âm ở giữa → mô hình có thể thiếu quadratic/log transformation. Chỉ vì slope t-significant chưa bảo đảm dạng hàm đúng; có thể dự báo ngoài sample sai hệ thống.","trap":""},{"heading":"4. Constant residual variance: homoskedasticity","body":"Var(ε|X)=σ² không đổi qua các mức X. Residual cloud có vertical spread tương đối đều. Nếu spread tăng theo X (funnel/fan shape), gọi heteroskedasticity: conventional OLS SE, t-test và F-test có thể không hợp lệ khi không hiệu chỉnh.","trap":""},{"heading":"5. Heteroskedasticity in investment data","body":"Doanh nghiệp lớn có volatility khác doanh nghiệp nhỏ; tail losses có thể lớn khi leverage cao, tạo unequal variance. OLS slope đôi khi vẫn unbiased dưới exogeneity, nhưng usual standard errors sai; không nên suy ra “slope luôn sai” chỉ vì variance không đồng đều.","trap":""},{"heading":"6. Independence of error terms","body":"Nhiễu quan sát không được có systematic serial dependence: Cov(εi,εj)=0 cho i≠j trong mô hình cơ sở. Trong time series, một residual dương thường tiếp tục dương ngay sau đó báo positive autocorrelation; chuỗi alternating signs báo negative autocorrelation.","trap":""},{"heading":"7. Residuals over time and Durbin–Watson intuition","body":"Vẽ residual theo thời gian; runs dài cùng dấu gợi ý positive autocorrelation. Durbin–Watson statistic gần 2 thường không báo autocorrelation bậc nhất mạnh; gần 0 gợi ý positive, gần 4 negative, nhưng ngưỡng formal phụ thuộc mẫu và regressors. Không đánh đồng DW≈2 là chứng minh tất cả assumptions.","trap":""},{"heading":"8. Why normality matters","body":"Giả định residual disturbances normal hỗ trợ exact t/F inference trong small samples dưới model assumptions. QQ plot và histogram giúp chẩn đoán thick tails/skew; trong sample lớn, một số thống kê có xấp xỉ tốt dù normality không hoàn hảo, nhưng không tự chữa serial correlation hay omitted variables.","trap":""},{"heading":"9. Exogeneity and zero conditional mean","body":"E(ε|X)=0 là điều kiện căn bản để b1 phản ánh population conditional mean slope và tránh bias do omitted confounders. Điều kiện mạnh hơn Σe=0 trong mẫu; OLS residuals luôn sum zero nhưng error thật có thể correlated with X.","trap":""},{"heading":"10. Influential observations versus outliers","body":"Outlier in Y có residual lớn; high leverage là X xa Xbar, có thể kéo slope ngay cả nếu residual sau fit nhỏ. Examine scatterplot with/without suspect point; không loại bỏ quan sát chỉ vì nó làm p-value kém đẹp, cần kiểm tra data quality trước.","trap":""},{"heading":"11. Heteroskedasticity vs nonlinear pattern","body":"Funnel shape về độ rộng residual quanh zero gợi heteroskedasticity; systematic curvature về trung bình residual gợi nonlinearity. Có thể đồng thời xảy ra; residual plot cho dấu hiệu, không phải chứng nhận chắc chắn loại lỗi.","trap":""},{"heading":"12. Model instability or structural breaks","body":"Nếu quan hệ Y–X thay đổi trước/sau policy change hay crisis, fitted single slope có thể average của nhiều regimes và dự báo kém. Plot residual over time và compare subperiod fits giúp phát hiện nhưng test formal nằm ngoài trọng tâm LOS.","trap":""},{"heading":"13. Good model requires data quality","body":"Wrong units, missing observations, stale prices và reporting lags tạo pattern giả. Kiểm tra dates, outliers và paired observations trước khi đọc ý nghĩa t-statistic. Survivorship selection có thể gây sample selection bias.","trap":""},{"heading":"14. What diagnostics cannot prove","body":"Residual plot “trông ngẫu nhiên” không chứng minh errors độc lập, normal hay exogenous. Một regression có high R² vẫn có serial correlation hoặc wrong form. Dùng nhiều diagnostics và logic kinh tế, không dùng một metric để kết luận toàn bộ.","trap":""},{"heading":"15. Consequences for inference and forecasts","body":"Heteroskedasticity/autocorrelation có thể làm conventional t/F standard errors sai; nonlinearity khiến fitted slope và prediction có systematic bias; outliers khiến coefficients unstable; heavy-tailed residuals khiến small-sample intervals thiếu chính xác. Lựa chọn robust SE/transformation/time-series modeling là hướng xử lý phù hợp từng loại lỗi.","trap":""},{"heading":"16. CFA exam residual-plot checklist","body":"Xác định axis (X/fitted/time), nhìn zero center (linearity), spread (constant variance), pattern over time (independence), shape/tails (normality), isolated extreme observations (outliers). Nêu assumption đang nghi ngờ bị vi phạm, đừng trả lời “normality proven”.","trap":""}],"formulas":[{"name":"Linearity","expr":"E(Y|X)=β0+β1X","meaning":"Conditional mean linear in X.","conditions":"Appropriate region of X."},{"name":"Zero conditional mean","expr":"E(ε|X)=0","meaning":"Error orthogonal to X in conditional expectation.","conditions":"Exogeneity for OLS unbiasedness."},{"name":"Homoskedasticity","expr":"Var(εi|Xi)=σ² for all i","meaning":"Equal error variance across X.","conditions":""},{"name":"Heteroskedasticity","expr":"Var(εi|Xi)=σ²(Xi)","meaning":"Conditional error variance depends on Xi.","conditions":""},{"name":"No error autocorrelation","expr":"Cov(εi,εj | X)=0 for i≠j","meaning":"Basic independence/uncorrelated error condition.","conditions":""},{"name":"Error normality","expr":"εi | Xi ∼ N(0,σ²)","meaning":"Exact reference for small-sample classical t/F tests under assumptions.","conditions":""},{"name":"Residual estimate","expr":"ei=Yi−(b0+b1Xi)","meaning":"Observable model diagnostic after fitting.","conditions":""},{"name":"Durbin–Watson intuition","expr":"DW=Σᵢ₌₂ⁿ(ei−eᵢ₋₁)²/Σᵢ₌₁ⁿei²","meaning":"Near 2: little first-order serial correlation (heuristic).","conditions":"Roughly 0..4; formal test conditions/critical bounds matter."},{"name":"Leveraged X distance","expr":"(Xi−X̄)²/Sxx","meaning":"Large relative X-distance signals leverage.","conditions":"Diagnostic component, not complete influence measure."}],"examples":[{"question_en":"A residual plot forms a U-shape against X. Which assumption is most suspicious?","steps_vi":["Conditional mean is not captured by straight-line approximation.","Residual systematic curvature supports nonlinearity, not automatically unequal variance."],"answer":"Linearity / functional-form specification.","check":""},{"question_en":"Residual spread grows from about 1 to 7 units as X rises. What is the likely violation?","steps_vi":["Dispersion changes across X.","Constant error variance would predict similar vertical spread."],"answer":"Heteroskedasticity.","check":""},{"question_en":"Residuals are positive for six consecutive quarters and then negative for five quarters. What is the primary concern?","steps_vi":["Persistent sign runs indicate serial dependence in residuals.","For time series, errors may be autocorrelated."],"answer":"Independence of errors (serial correlation).","check":""},{"question_en":"The residual histogram is strongly right-skewed in a sample of 12 observations. What inference concern arises?","steps_vi":["Small-sample classical t-tests rely on appropriate disturbance distribution.","Marked skew challenges normality assumption."],"answer":"Potential non-normality of residuals.","check":""},{"question_en":"A data set has all X values near 4 except one observation at X=50. Which risk deserves attention?","steps_vi":["Point X=50 is far from Xbar and may leverage the fitted slope.","Check entry error and estimate sensitivity to that observation."],"answer":"High leverage / potential influential observation.","check":""},{"question_en":"A fitted model has R-squared of 92%, but residuals display a funnel shape. Is homoskedasticity assured?","steps_vi":["High R² reflects sample fit, not constant conditional variance.","Funnel residual pattern suggests varying error spread."],"answer":"No; heteroskedasticity remains possible.","check":""},{"question_en":"A regression of monthly returns has DW approximately 0.6. What is the likely issue?","steps_vi":["DW markedly less than 2 is indicative of positive first-order serial correlation.","Formal decision would require test bounds and assumptions."],"answer":"Positive residual autocorrelation suspected.","check":""},{"question_en":"A regression of monthly returns has DW approximately 3.2. What is the likely issue?","steps_vi":["DW markedly above 2 is indicative of negative first-order serial correlation."],"answer":"Negative residual autocorrelation suspected.","check":""},{"question_en":"An OLS regression residuals sum to zero. Does this establish exogeneity?","steps_vi":["Sum zero is built into OLS with intercept.","Population E(ε|X)=0 is stronger and unobserved."],"answer":"No.","check":""},{"question_en":"A forecast model is estimated across two interest-rate regimes with visibly different slopes. What is the concern?","steps_vi":["Relationship can change across regimes.","One pooled linear slope can be unstable for forecasts."],"answer":"Structural break / model instability.","check":""},{"question_en":"A residual plot against X is centered near zero with similar spread and no visible pattern. What can be concluded?","steps_vi":["Plot is consistent with linearity and equal variance in visible data.","It does not prove all assumptions, especially exogeneity."],"answer":"No obvious graphical violation, but assumptions not established.","check":""},{"question_en":"If standard error calculations ignore heteroskedasticity, what is a likely consequence?","steps_vi":["Usual textbook SE formulas rely on constant error variance.","Heteroskedasticity can invalidate conventional significance tests."],"answer":"Reported t/F inference may be unreliable.","check":""}],"questions":[{"stem_en":"A U-shaped residual plot against X most directly signals:","options":["Heteroskedasticity only","Nonlinear functional form","Perfect error independence"],"correct":1,"why_vi":"U-shape có mean pattern ⇒ misspecified linearity.","trap_vi":""},{"stem_en":"A fan-shaped residual plot most likely indicates:","options":["Heteroskedasticity","Perfect normality","No explanatory power"],"correct":0,"why_vi":"Spread tăng theo X ⇒ variance không hằng.","trap_vi":""},{"stem_en":"Long runs of residuals with the same sign in a time series suggest:","options":["Homoskedasticity","Independent errors","Positive serial correlation"],"correct":2,"why_vi":"Cùng dấu theo thời gian gợi autocorrelation dương.","trap_vi":""},{"stem_en":"An unusually large X-value relative to other observations may create:","options":["Guaranteed causal identification","A high-leverage observation","Homoskedastic disturbances"],"correct":1,"why_vi":"Leverage là khoảng cách X xa mean; có thể ảnh hưởng fitted slope.","trap_vi":""},{"stem_en":"Which assumption supports exact classical small-sample t-inference, together with other model conditions?","options":["Normality of errors","A high R-squared","A nonzero sample correlation"],"correct":0,"why_vi":"Normal residual distribution giúp t/F reference ở mẫu nhỏ.","trap_vi":""},{"stem_en":"A Durbin–Watson statistic near zero is most consistent with:","options":["Negative serial correlation","Zero serial correlation","Positive serial correlation"],"correct":2,"why_vi":"DW gần 0 phản ánh consecutive residual changes nhỏ hơn levels.","trap_vi":""},{"stem_en":"A Durbin–Watson statistic near four suggests:","options":["Positive first-order autocorrelation","Negative first-order autocorrelation","Perfect homoskedasticity"],"correct":1,"why_vi":"DW gần 4 là heuristic negative serial correlation.","trap_vi":""},{"stem_en":"If Var(error | X) changes with X, which assumption fails?","options":["Homoskedasticity","No perfect collinearity","Normality by definition"],"correct":0,"why_vi":"Variance conditional không constant.","trap_vi":""},{"stem_en":"What is a correct inference from sample residuals summing to zero?","options":["Causality is proved.","Errors are normally distributed.","The intercept OLS normal equation is satisfied."],"correct":2,"why_vi":"Σei=0 là sample algebra, không phải chứng minh population assumptions.","trap_vi":""},{"stem_en":"The most appropriate diagnostic for serial dependence is often:","options":["Only the histogram of X","Residuals plotted against time","A single coefficient sign"],"correct":1,"why_vi":"Residual time plot reveals persistence.","trap_vi":""},{"stem_en":"Which statement about R-squared and model assumptions is accurate?","options":["High R-squared does not guarantee valid assumptions.","High R-squared proves normal residuals.","Low R-squared always implies heteroskedasticity."],"correct":0,"why_vi":"Good in-sample fit khác correctness of inference.","trap_vi":""},{"stem_en":"An outlier with extreme X values and small fitted residual can still be:","options":["Irrelevant by definition","Evidence of zero slope","Highly influential"],"correct":2,"why_vi":"High leverage có thể kéo regression line sát điểm đó.","trap_vi":""},{"stem_en":"What type of error is most concerning when the true conditional mean is curved?","options":["No correlation","Functional-form misspecification","Normal errors"],"correct":1,"why_vi":"Straight line underfits systematic curvature.","trap_vi":""},{"stem_en":"Which is a reasonable limitation of visual residual checks?","options":["Visual diagnostics can suggest but not prove assumptions.","A clean plot guarantees causal identification.","Plot shape guarantees all p-values are exact."],"correct":0,"why_vi":"Diagnostic evidence not mathematical proof.","trap_vi":""},{"stem_en":"Under exogeneity but heteroskedasticity, which claim is most accurate?","options":["OLS slope must always be biased.","OLS output cannot be computed.","Conventional slope standard errors may be wrong."],"correct":2,"why_vi":"Heteroskedasticity primarily threatens conventional SE/inference, không mặc nhiên bias nếu E(error|X)=0.","trap_vi":""},{"stem_en":"An illustrative Durbin–Watson statistic is 0.4. Which is the closer reference value for positive autocorrelation?","options":["4","2","0"],"correct":2,"why_vi":"DW gần 0 là chỉ báo positive residual autocorrelation.","trap_vi":""},{"stem_en":"Under constant-error-variance assumption, two conditional error variances are both 9. What is their ratio?","options":["1.00","0.00","9.00"],"correct":0,"why_vi":"Homoskedasticity: conditional variances bằng nhau; ratio=9/9=1.","trap_vi":""},{"stem_en":"For four residuals [1, −1, 2, −2], what is their sum?","options":["4.00","2.00","0.00"],"correct":2,"why_vi":"1−1+2−2=0; residual sum identity không chứng minh assumptions.","trap_vi":""}],"cards":[{"front_en":"Four core residual assumptions in CFAI regression?","back_vi":"Linearity, homoskedasticity, independence and normality of disturbances."},{"front_en":"What is linearity in the regression model?","back_vi":"E(Y|X)=β0+β1X."},{"front_en":"What is homoskedasticity?","back_vi":"Var(ε|X)=constant."},{"front_en":"What is heteroskedasticity?","back_vi":"Variance errors changes with X."},{"front_en":"Which residual pattern suggests nonlinearity?","back_vi":"Curved or U-shaped mean pattern."},{"front_en":"Which residual pattern suggests heteroskedasticity?","back_vi":"Fan or funnel spread changing with X."},{"front_en":"Which plot helps find serial correlation?","back_vi":"Residuals over time (runs of same sign)."},{"front_en":"Durbin–Watson heuristic?","back_vi":"DW≈2 little first-order autocorrelation; ≈0 positive; ≈4 negative."},{"front_en":"What does residual normality help?","back_vi":"Classical small-sample test reference distributions under assumptions."},{"front_en":"Does high R-squared prove homoskedasticity?","back_vi":"Không; in-sample fit khác residual variance assumptions."},{"front_en":"Why examine high-leverage observations?","back_vi":"Extreme X can strongly influence fitted slope."},{"front_en":"What is a structural break?","back_vi":"Regression relationship changes across regimes/time."},{"front_en":"What is exogeneity / conditional zero mean?","back_vi":"E(ε|X)=0, stronger than Σsample residual=0."},{"front_en":"Does Σe=0 establish error independence?","back_vi":"Không; property of OLS intercept."},{"front_en":"Implication of heteroskedasticity for conventional t-tests?","back_vi":"OLS standard error formula may be invalid without adjustment."},{"front_en":"Are graphical residual diagnostics conclusive proof?","back_vi":"Không; they flag concerns for additional testing."},{"front_en":"What does residual U-shape imply economically?","back_vi":"Misspecified linear relationship can bias predictions."},{"front_en":"Data quality checks before regression?","back_vi":"Align dates, units, pairs and investigate influential outliers."}]},{"id":"CFA26-01-10-LOS03","letter":"10.c","title_en":"Fit Measures and Tests of Regression Coefficients","outcome_en":"calculate and interpret measures of fit and formulate and evaluate tests of fit and of regression coefficients in a simple linear regression","overview_vi":"Hiểu SST, SSR, SSE, R²; kiểm định slope và intercept bằng t, kiểm định correlation, F overall, relationship F=t², ý nghĩa economic vs statistical significance, coefficient CI và trường hợp indicator/dummy.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"290–302 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"119–124, 128–129 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"411–431 (physical PDF)"}],"sections":[{"heading":"1. Fit and inference answer different questions","body":"R² và SEE nói in-sample fit; t-test và F-test đánh giá evidence về population coefficient(s) dưới assumptions. Regression high R² có thể bị misspecification, còn statistically significant small slope có thể economically trivial. Không suy ra causal link từ bất kỳ metric đơn lẻ.","trap":""},{"heading":"2. Decomposition of variation","body":"Viết total variation quanh mean Ȳ thành explained variation quanh Ŷ và residual variation: SST=SSR+SSE (OLS with intercept). SST=Σ(Y−Ȳ)², SSR=Σ(Ŷ−Ȳ)², SSE=Σ(Y−Ŷ)². Đừng nhầm SSR là residual sum of squares: trong CFAI SSR dành cho regression; SSE dành cho error.","trap":""},{"heading":"3. Coefficient of determination R-squared","body":"R²=SSR/SST=1−SSE/SST, với intercept và SST>0 thì 0≤R²≤1. R²=0.75 nghĩa ~75% sample variance of Y around its mean explained by fitted X relationship; không phải “75% chance model is correct” hay “75% return is guaranteed”.","trap":""},{"heading":"4. Correlation and R² in simple OLS","body":"Khi chỉ có 1 explanatory X cùng intercept, R²=rXY². Positive hoặc negative r có cùng R²; R² không cho biết sign of slope. Dùng r để đo signed linear association, R² để đo fraction of sample variation explained.","trap":""},{"heading":"5. Distinguishing SSE, SEE and coefficient SE","body":"SSE là tổng squared residuals; SEE (standard error of estimate) là √[SSE/(n−2)] có cùng units Y. Standard error of b1 hoặc b0 dùng để test coefficients, khác SEE và khác prediction forecast SE. Các đại lượng cùng chữ s nhưng ý nghĩa khác.","trap":""},{"heading":"6. Testing a population slope","body":"Null H₀:β1=B (thường B=0), alternative β1≠B, >B hoặc <B. t=(b1−B)/SE(b1) theo t_{n−2} dưới classical assumptions. Sign of t cùng sign of b1−B; chọn tail theo claim trước khi nhìn data.","trap":""},{"heading":"7. Standard error of slope","body":"SE(b1)=SEE/√Sxx. Sxx lớn hơn (ceteris paribus) làm slope estimate more precise; SEE lớn làm SE coefficient lớn. Sai số thường gặp: dùng sample sY thay cho SEE hoặc quên sqrt(Sxx).","trap":""},{"heading":"8. Testing the intercept","body":"Test H₀:β0=B0 dùng t=(b0−B0)/SE(b0), df=n−2. SE(b0)=SEE√[1/n+Xbar²/Sxx]. Intercept tại X=0 có thể không có ý nghĩa kinh tế; significance của intercept khác significance slope.","trap":""},{"heading":"9. Confidence interval for coefficient","body":"Two-sided (1−α) CI for β1: b1±tcrit(n−2)×SE(b1). Nếu B nằm ngoài CI, reject H₀:β1=B at matching two-sided α. Cần dùng df=n−2, không phải n−1; và không nhầm tcrit with normal z for tiny samples.","trap":""},{"heading":"10. One-sided versus two-sided tests","body":"Nếu economic question là beta >0, one-sided t applies; nếu chỉ “different from zero”, two-sided. F test of overall model (with one slope) tương đương two-sided t test for β1=0; F không có signed outcome và không thay thế one-sided t direction.","trap":""},{"heading":"11. Overall model significance with F","body":"H₀:β1=0 trong simple regression. F=(SSR/1)/(SSE/(n−2)) có F_{1,n−2} under assumptions, right-tailed rejection. F càng lớn nghĩa explained variation lớn so với residual mean square; p-value <α nghĩa evidence of nonzero population slope.","trap":""},{"heading":"12. t-squared and F identity","body":"Trong simple regression with intercept và cùng data/assumptions, F=t² đối với test H₀:β1=0. Ví dụ t=−3.0 => F=9 (không phải −9). Điều này hữu ích khi đề vừa cho slope t vừa cho ANOVA F.","trap":""},{"heading":"13. Correlation significance in regression","body":"H₀:ρXY=0: t=r√(n−2)/√(1−r²), df=n−2 (suitable joint-normal independent paired data). Trong simple linear OLS, t from correlation matches slope t under usual assumptions. Một sample r lớn vẫn có thể not significant nếu n nhỏ.","trap":""},{"heading":"14. Statistical and economic significance","body":"p=0.01 không nói magnitude b1 large, cũng không bảo đảm out-of-sample trading profit. Đọc magnitude + units + uncertainty + costs. Một statistically significant slope về monthly returns có thể rất nhỏ so với brokerage/trading impact.","trap":""},{"heading":"15. Indicator (dummy) regression interpretation","body":"X=D∈{0,1}; model Y=b0+b1D. Với D=0, fitted mean b0; với D=1, fitted mean b0+b1; slope b1 là DIFFERENCE between group means. Under usual independent homoskedastic assumptions, slope test tương ứng test of two group means. Đừng diễn giải “1-unit increase in a continuous quantity”.","trap":""},{"heading":"16. Regression output reading","body":"Trong table software: coefficient estimate, standard error, t-stat, p-value, R², F, sample size và residual df. Từ t=b1/SE tính missing coefficient hoặc SE. So p với α; kết luận “evidence of association”, không “model predicts with certainty”.","trap":""},{"heading":"17. Adjusted R² is a supplementary measure","body":"Adjusted R²=1−(SSE/(n−2))/(SST/(n−1)) cho simple regression; có thể âm. Đây là benchmark adjustment for df, không thay R² quy định của LOS. Không so R² giữa mô hình có transformed dependent variables mà thiếu điều chỉnh scale.","trap":""},{"heading":"18. Pitfalls: correlation, forecasts, coefficients","body":"R²=0.64 ⇒ |r|=0.80, sign phải lấy từ slope/r; correlation=0.8 không có nghĩa slope 0.8 trừ sX=sY. CI for β1 differs from PI for individual Y. Rejecting slope-zero does not validate independence/normality.","trap":""}],"formulas":[{"name":"Total sum of squares","expr":"SST=Σ(Yi−Ȳ)²","meaning":"Total sample variation of Y around mean.","conditions":""},{"name":"Explained sum of squares","expr":"SSR=Σ(Ŷi−Ȳ)²","meaning":"Explained variation by fitted regression line.","conditions":""},{"name":"Residual sum of squares","expr":"SSE=Σ(Yi−Ŷi)²","meaning":"Unexplained squared deviations.","conditions":""},{"name":"OLS sum-of-squares decomposition","expr":"SST=SSR+SSE","meaning":"Exact with OLS intercept; untransformed Y scale.","conditions":""},{"name":"R-squared","expr":"R²=SSR/SST=1−SSE/SST","meaning":"Fraction of in-sample total variation explained.","conditions":"SST>0; intercept for usual [0,1] bound."},{"name":"Simple regression relation","expr":"R²=r(X,Y)²","meaning":"Sign of r not recoverable from R².","conditions":"Exactly one explanatory X + intercept."},{"name":"SEE / residual standard error","expr":"SEE=√(SSE/(n−2))","meaning":"Residual dispersion in units of Y.","conditions":"n>2, model intercept+one slope."},{"name":"Slope standard error","expr":"SE(b1)=SEE/√Sxx","meaning":"Precision of slope estimate.","conditions":"Classical homoskedastic model."},{"name":"Intercept standard error","expr":"SE(b0)=SEE√[1/n+X̄²/Sxx]","meaning":"Precision of fitted intercept.","conditions":"Classical homoskedastic model."},{"name":"Slope t test","expr":"t=(b1−B1)/SE(b1), df=n−2","meaning":"Test H₀:β1=B1.","conditions":""},{"name":"Intercept t test","expr":"t=(b0−B0)/SE(b0), df=n−2","meaning":"Test H₀:β0=B0.","conditions":""},{"name":"Coefficient confidence interval","expr":"bⱼ ± t₍1−α/2,n−2₎ SE(bⱼ)","meaning":"Two-sided interval for β0 or β1.","conditions":"Classical inference assumptions."},{"name":"Slope-model F test","expr":"F=(SSR/1)/(SSE/(n−2))","meaning":"Tests H₀:β1=0; right-tailed F(1,n−2).","conditions":""},{"name":"t and F equivalence","expr":"F=t(b1 versus zero)²","meaning":"Two-sided slope-zero test vs overall F, simple OLS.","conditions":""},{"name":"Correlation significance test","expr":"t=r√(n−2)/√(1−r²), df=n−2","meaning":"Test null population linear correlation ρ=0.","conditions":""},{"name":"Adjusted R-squared (supplementary)","expr":"Adjusted R²=1−[SSE/(n−2)]/[SST/(n−1)]","meaning":"Df-adjusted fit; optional extension.","conditions":""},{"name":"Dummy slope interpretation","expr":"D∈{0,1}; Ŷ(D=1)−Ŷ(D=0)=b1","meaning":"Difference between group conditional fitted means.","conditions":""}],"examples":[{"question_en":"A simple OLS model has SST=200 and SSE=50. What is its R-squared?","steps_vi":["SSR=SST−SSE=150.","R²=1−50/200=.75."],"answer":"75%","check":""},{"question_en":"An OLS simple regression has correlation r=−0.70. What is R-squared?","steps_vi":["R²=r²=(−.70)²=.49.","Sign of slope is negative, while R² is nonnegative."],"answer":"49%","check":""},{"question_en":"The fitted slope is 1.20 with standard error 0.30. Test β1=0 using its t-statistic.","steps_vi":["t=(1.20−0)/.30=4.00.","Compare |4| with t critical for n−2 df and chosen α."],"answer":"t=4.00","check":""},{"question_en":"The estimated slope is −0.8, its standard error is 0.2, and n=22. What is df and t for testing zero slope?","steps_vi":["df=n−2=20.","t=−.8/.2=−4.0."],"answer":"df=20; t=−4.00","check":""},{"question_en":"A coefficient has b1=0.60, SE(b1)=0.20, and a two-sided t critical value of 2.1. Construct its CI.","steps_vi":["Margin=2.1×.20=.42.","CI=.60±.42."],"answer":"[0.18, 1.02]","check":""},{"question_en":"A regression with n=12 gives slope b1=2.0, SEE=3.0 and Sxx=36. Compute SE(b1).","steps_vi":["SE(b1)=SEE/√Sxx=3/6."],"answer":"0.50","check":""},{"question_en":"Suppose b0=4.2, SE(b0)=1.4, and H0: β0=0. Calculate t.","steps_vi":["t=(4.2−0)/1.4=3."],"answer":"3.00","check":""},{"question_en":"A sample has n=32 and correlation r=0.50. Calculate t for testing zero correlation.","steps_vi":["df=30.","t=.50√30/√(1−.25)=3.1623."],"answer":"3.1623","check":""},{"question_en":"The slope t-statistic in a simple regression is −2.5. What is the model F-statistic for H0: β1=0?","steps_vi":["With one slope and intercept, F=t².","F=(−2.5)²=6.25."],"answer":"6.25","check":""},{"question_en":"The F-statistic is 16 for a simple intercept regression and slope is negative. What is slope t-statistic for testing zero?","steps_vi":["F=t² and t sign follows slope sign.","t=−√16=−4."],"answer":"−4.00","check":""},{"question_en":"A dummy regression is Ŷ=5.4+1.8D where D=1 in event months. What is the event-month fitted mean?","steps_vi":["For D=1, fitted mean =5.4+1.8."],"answer":"7.20","check":""},{"question_en":"For Ŷ=5.4+1.8D, interpret b1 in relation to event/non-event month average values.","steps_vi":["Non-event D=0 fitted mean 5.4.","Event D=1 fitted mean 7.2, difference 1.8."],"answer":"Event-group mean is 1.8 units higher.","check":""},{"question_en":"A regression reports R2=0.81 and a positive slope. What is the sample correlation?","steps_vi":["|r|=√.81=.9.","Positive slope determines positive sign."],"answer":"+0.90","check":""},{"question_en":"For n=10, Sxx=25 and SEE=2, compute the standard error of an OLS slope.","steps_vi":["SE(b1)=2/√25."],"answer":"0.40","check":""},{"question_en":"A two-sided test has p-value 0.034 and α=0.05. What is the conclusion?","steps_vi":["p=.034<.05.","Reject the null of the coefficient value specified."],"answer":"Reject H₀.","check":""},{"question_en":"A two-sided slope test has t=−1.5 and t critical ±2.06. What is the decision?","steps_vi":["|−1.5|=1.5<2.06.","No rejection at given α."],"answer":"Fail to reject H₀.","check":""}],"questions":[{"stem_en":"In CFAI regression terminology, which sum of squares is unexplained?","options":["SSR","SSE","SST"],"correct":1,"why_vi":"SSE là sum of squares error; SSR regression explained.","trap_vi":""},{"stem_en":"An R-squared of 0.65 most directly means that:","options":["The model is correct with 65% probability.","The slope increases by 65%.","The fitted regression explains 65% of sample Y variation."],"correct":2,"why_vi":"R² là fraction of total variation explained in sample.","trap_vi":""},{"stem_en":"In an intercept simple OLS model, R-squared equals:","options":["Square of the sample correlation","Sample correlation","Slope divided by intercept"],"correct":0,"why_vi":"R²=r² for one regressor with intercept.","trap_vi":""},{"stem_en":"For a slope t-test, the denominator is:","options":["SEE directly","Standard error of estimated slope","Residual sum of squares"],"correct":1,"why_vi":"t=(b1−B1)/SE(b1).","trap_vi":""},{"stem_en":"Which degrees of freedom apply to a slope t-test in simple regression?","options":["n−1","n","n−2"],"correct":2,"why_vi":"Estimate 2 parameters → residual df=n−2.","trap_vi":""},{"stem_en":"For H0: β1=0 in simple intercept regression, which equality holds?","options":["F=t²","F=t","F=−t²"],"correct":0,"why_vi":"Omnibus F with 1 regressor equals squared two-sided slope t.","trap_vi":""},{"stem_en":"The overall F-test in simple regression is:","options":["A two-tailed F test","A right-tailed F test","A left-tailed F test"],"correct":1,"why_vi":"F≥0 và reject khi F lớn.","trap_vi":""},{"stem_en":"A regression has negative slope and R-squared 0.49. What is the implied correlation?","options":["+0.70","−0.49","−0.70"],"correct":2,"why_vi":"r sign=slope sign, |r|=√.49=.7.","trap_vi":""},{"stem_en":"If H0: β1=0 and the two-sided p-value is 0.40 at α=0.05, the correct decision is:","options":["Fail to reject H0","Reject H0","Accept the alternative as proven"],"correct":0,"why_vi":"p>.05 chưa đủ bằng chứng bác bỏ null.","trap_vi":""},{"stem_en":"A dummy-variable slope in Ŷ=b0+b1D is most directly interpreted as:","options":["Unexplained variance","Difference between groups D=1 and D=0","Standard error of the mean"],"correct":1,"why_vi":"Difference in fitted group means =b1.","trap_vi":""},{"stem_en":"Which statement about a high R-squared is accurate?","options":["It establishes model causality.","It eliminates structural breaks.","It does not ensure reliable out-of-sample predictions."],"correct":2,"why_vi":"In-sample fit khác forecast validity.","trap_vi":""},{"stem_en":"A 95% confidence interval for a slope excludes zero. Which test decision agrees?","options":["Reject a two-sided zero-slope null at 5%.","Fail to reject the zero-slope null at 5%.","The F-statistic must be negative."],"correct":0,"why_vi":"Matching CI/test equivalence under same assumptions.","trap_vi":""},{"stem_en":"An analyst uses tcrit=2.1, coefficient=0.4, and SE=0.1. Is zero inside its CI?","options":["Yes","No","Cannot determine because sample correlation is missing"],"correct":1,"why_vi":"CI .4±.21=[.19,.61], không chứa zero.","trap_vi":""},{"stem_en":"Which value can be negative in a standard simple-intercept regression?","options":["R-squared","F-statistic","Estimated slope"],"correct":2,"why_vi":"Slope sign unrestricted; R² và F không âm.","trap_vi":""},{"stem_en":"What does a p-value of 0.02 for a slope test mean?","options":["Under the null and assumptions, observed evidence is sufficiently extreme with probability 0.02.","The null has a 2% probability of being true.","The stock has a 98% probability of gaining."],"correct":0,"why_vi":"p-value conditional on H0, không phải posterior likelihood.","trap_vi":""},{"stem_en":"In an intercept simple regression, SST=250 and SSE=75. What is R-squared in percent?","options":["70.0%","175.0%","30.0%"],"correct":0,"why_vi":"1−75/250=.70 =70%.","trap_vi":""},{"stem_en":"A simple regression has r=−0.8. What is R-squared as a percentage?","options":["80.0%","64.0%","-64.0%"],"correct":1,"why_vi":"R²=(−.8)²=.64.","trap_vi":""},{"stem_en":"Slope estimate=2.4 and SE=0.6. What is t for H0: β1=0?","options":["1.80","4.00","3.00"],"correct":1,"why_vi":"t=2.4/.6=4.","trap_vi":""},{"stem_en":"For the slope-zero test, t=−3.5. What is the corresponding F-statistic?","options":["12.25","3.50","-12.25"],"correct":0,"why_vi":"F=t²=12.25.","trap_vi":""},{"stem_en":"Given SEE=3 and Sxx=100, what is SE(b1)?","options":["0.30","30.00","0.03"],"correct":0,"why_vi":"SE(b1)=3/10=.3.","trap_vi":""},{"stem_en":"A regression slope is 0.75 and its standard error is 0.25. What is the t-statistic for H0: β1=0.50?","options":["3.00","0.25","1.00"],"correct":2,"why_vi":"t=(.75−.5)/.25=1.","trap_vi":""},{"stem_en":"With b1=1.0 and SE=0.2, what is the upper limit of a two-sided CI with tcrit=2.0?","options":["1.20","0.60","1.40"],"correct":2,"why_vi":"1+2×.2=1.4.","trap_vi":""},{"stem_en":"In a dummy regression Ŷ=4.5−1.2D, what is the predicted group mean when D=1?","options":["4.50","3.30","-1.20"],"correct":1,"why_vi":"Ŷ=4.5−1.2=3.3.","trap_vi":""},{"stem_en":"If sample correlation r=0.6, sY=10 and sX=2, what is the regression slope?","options":["3.00","1.20","0.60"],"correct":0,"why_vi":"b1=r(sY/sX)=.6×5=3.","trap_vi":""}],"cards":[{"front_en":"How is SST defined?","back_vi":"Σ(Yi−Ybar)²; total Y sample variation."},{"front_en":"How is SSR defined in CFAI?","back_vi":"Σ(Yhat−Ybar)²; regression explained variation."},{"front_en":"How is SSE defined?","back_vi":"Σ(Y−Yhat)²; residual unexplained variation."},{"front_en":"OLS decomposition?","back_vi":"SST=SSR+SSE (with intercept)."},{"front_en":"How to calculate R-squared?","back_vi":"SSR/SST=1−SSE/SST."},{"front_en":"R-squared versus correlation in simple regression?","back_vi":"R²=r², sign of correlation from slope."},{"front_en":"Regression slope t-statistic?","back_vi":"(b1−B1)/SE(b1), df=n−2."},{"front_en":"Slope standard error?","back_vi":"SEE/√Sxx (classical model)."},{"front_en":"Intercept test t-statistic?","back_vi":"(b0−B0)/SE(b0), df=n−2."},{"front_en":"Two-sided coefficient confidence interval?","back_vi":"Estimate±tcrit×SE(estimate)."},{"front_en":"Overall F-test for simple regression?","back_vi":"H0: β1=0; F=MSR/MSE, right-tail."},{"front_en":"Slope t and overall F?","back_vi":"F=t² when testing slope=0 with intercept."},{"front_en":"Can F be negative?","back_vi":"No, F≥0."},{"front_en":"Does R² disclose direction?","back_vi":"No; r sign obtained from slope."},{"front_en":"What does dummy slope capture?","back_vi":"Fitted group difference D=1 minus D=0."},{"front_en":"Does high R² guarantee assumptions?","back_vi":"No."},{"front_en":"How to evaluate coefficient significance?","back_vi":"Compare |t| with tcrit or p with α, using correct tails."},{"front_en":"Standard error of intercept?","back_vi":"SEE√(1/n+Xbar²/Sxx)."},{"front_en":"Economic versus statistical significance?","back_vi":"Magnitude / business costs vs evidence under null test."},{"front_en":"What is a correlation t-test?","back_vi":"t=r√(n−2)/√(1−r²), df=n−2 under assumptions."}]},{"id":"CFA26-01-10-LOS04","letter":"10.d","title_en":"ANOVA, F-statistic and Standard Error of Estimate","outcome_en":"describe the use of analysis of variance (ANOVA) in regression analysis, interpret ANOVA results, and calculate and interpret the standard error of estimate in a simple linear regression","overview_vi":"Giải bảng ANOVA gồm SST/SSR/SSE, df, MSR/MSE, F, SEE, R² và variance Y; hoàn thành missing cells và hiểu hạn chế của kiểm định F trong suy luận về chất lượng mô hình.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"290–305 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"119–122, 128–129 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"432–438 (physical PDF)"}],"sections":[{"heading":"1. Purpose of ANOVA table","body":"Analysis of variance (ANOVA) đặt tổng biến thiên Y vào 3 hàng: regression explained, residual error, total. Bảng cho sum of squares, degrees of freedom, mean squares, F statistic và đôi khi p-value. Đọc đúng từng hàng và df là kỹ năng thường gặp trong output question.","trap":""},{"heading":"2. SST is total sample squared deviation","body":"SST=Σ(Yi−Ybar)² phản ánh dispersion của observed Y; df total=n−1. Sample variance of Y =SST/(n−1), nên có thể suy từ ANOVA nếu biết SST và total df. Đừng dùng residual df n−2 để tính sample variance Y.","trap":""},{"heading":"3. Regression sum of squares","body":"SSR=Σ(Ŷi−Ybar)², df regression=k=1 với simple regression. Mean square regression MSR=SSR/1=SSR. SSR lớn tương đối với SST có R² cao hơn, nhưng bản thân SSR phụ thuộc units/n nên không dùng để so hai data sets vô điều kiện.","trap":""},{"heading":"4. Error sum of squares","body":"SSE=Σ(Yi−Ŷi)², df error=n−k−1=n−2. Mean square error MSE=SSE/(n−2); đây là estimate của population error variance σ² trong classical model. SSE không phải MSE, và MSE không phải SEE.","trap":""},{"heading":"5. ANOVA degrees-of-freedom check","body":"Total df=n−1, Regression df=1, Error df=n−2. Tổng regression + error df=total df. Nếu bảng có residual df=18 thì n=20; biết total df=24 ⇒ n=25 và residual df=23. Khi k explanatory vars, error df=n−k−1 (mở rộng).","trap":""},{"heading":"6. Mean squares and F","body":"F=MSR/MSE=(SSR/1)/(SSE/(n−2)). Statistic không âm, under null slope-zero follow F distribution df1=1,df2=n−2. Reject right tail if F>F critical or p<α. Không tính F bằng SSE/SSR nếu không chia df.","trap":""},{"heading":"7. Standard error of estimate","body":"SEE=sₑ=√MSE=√[SSE/(n−2)] (same units as dependent Y). SEE tóm tắt typical unexplained residual dispersion in fitted line; không phải standard error of coefficient và không phải standard error of forecast.","trap":""},{"heading":"8. R-squared from ANOVA","body":"R²=SSR/SST=1−SSE/SST. Cần cùng response scale. Nếu output có SSR=90, SSE=30 ⇒ SST=120, R²=.75. R²≥0 và ≤1 với intercept OLS; values negative có thể xảy ra in non-intercept/informal out-of-sample definitions.","trap":""},{"heading":"9. ANOVA data consistency checks","body":"SST=SSR+SSE; n−1=1+(n−2); F≥0; SEE²=MSE; F=t² when one slope tests zero. Nếu bất kỳ identity nào không đúng vì rounding quá lớn hoặc t/F mismatch, kiểm tra input và assumptions.","trap":""},{"heading":"10. Inverting SEE and ANOVA fields","body":"Nếu biết SEE và n, SSE=SEE²(n−2). Nếu biết F, MSE, then SSR=F×MSE (simple model). Nếu biết SST và R², SSR=R²SST và SSE=(1−R²)SST. Dùng relationships để giải các ô còn trống.","trap":""},{"heading":"11. Sample size and model df from output","body":"Regression table có residual df=29 ⇒ n=31 (1 slope+intercept). Nếu MSE=4 và SSE=116 ⇒ residual df=29 ⇒ n=31. Không trừ n thêm một lần nữa khi table đã có df.","trap":""},{"heading":"12. F probability interpretation","body":"p-value of F là P(F_null≥Fobserved) trong classical test, không phải P(the model is true). F test chứng tỏ population slope có evidence khác zero; không xác nhận model well specified, normality hoặc ability to forecast accurately.","trap":""},{"heading":"13. Scale and units of ANOVA","body":"Nếu đổi Y từ percent points sang decimal, SST/SSR/SSE/MSE giảm 10,000 lần, SEE giảm 100 lần; R² và F không đổi. Nếu đổi đơn vị X, slope thay đổi nhưng model fitted Y, R² và F không đổi khi appropriately rescaled.","trap":""},{"heading":"14. Regression ANOVA and correlation link","body":"Simple intercept regression: F=[(n−2)R²]/(1−R²) nếu R²<1. Vì R²=r², có thể tính F từ sample correlation. R²=1 khiến residual MSE=0 và idealized F unbounded; tránh phép chia zero.","trap":""},{"heading":"15. Limits of comparing fit across models","body":"SEE so được khi dependent variable cùng units, cùng observation set; R² không tự kể forecast success. Khi dependent variable được log-transformed, R² nằm trên ln(Y) scale nên không so trực tiếp với model R² trên Y scale rồi kết luận mô hình nào dự báo Y tốt hơn.","trap":""},{"heading":"16. ANOVA solve-order exam method","body":"(1) Fill dfs from n. (2) SST=SSR+SSE. (3) MSR=SSR/1; MSE=SSE/(n−2). (4) F=MSR/MSE. (5) SEE=√MSE, R²=SSR/SST. (6) Compare F and p with critical rule. Luôn giữ nhiều chữ số tới bước cuối.","trap":""}],"formulas":[{"name":"Total sum of squares","expr":"SST=Σ(Y−Ybar)²","meaning":"Total variation; total df=n−1.","conditions":""},{"name":"Explained regression sum of squares","expr":"SSR=Σ(Ŷ−Ybar)²","meaning":"Explained variation; df regression=1.","conditions":""},{"name":"Unexplained error sum of squares","expr":"SSE=Σ(Y−Ŷ)²","meaning":"Residual variation; df error=n−2.","conditions":""},{"name":"ANOVA SS identity","expr":"SST=SSR+SSE","meaning":"OLS with intercept.","conditions":""},{"name":"ANOVA degrees of freedom","expr":"df_reg=1, df_err=n−2, df_total=n−1","meaning":"One predictor and intercept.","conditions":""},{"name":"Mean square regression","expr":"MSR=SSR/1","meaning":"Regression mean square in simple regression.","conditions":""},{"name":"Mean square error","expr":"MSE=SSE/(n−2)","meaning":"Residual mean square estimates σ² under classical assumptions.","conditions":""},{"name":"Regression overall F","expr":"F=MSR/MSE","meaning":"Right-tailed F distribution df(1,n−2) under H0.","conditions":""},{"name":"Standard error of estimate","expr":"SEE=√MSE=√[SSE/(n−2)]","meaning":"Residual scale in units Y.","conditions":""},{"name":"Y sample variance from ANOVA","expr":"sY²=SST/(n−1)","meaning":"Sample variance of dependent Y.","conditions":""},{"name":"ANOVA R-squared","expr":"R²=SSR/SST","meaning":"Explained fraction of Y variation.","conditions":""},{"name":"Inverse SSE from SEE","expr":"SSE=(SEE)²(n−2)","meaning":"Recover missing ANOVA cell.","conditions":""},{"name":"F from R-squared","expr":"F=(n−2)R²/(1−R²)","meaning":"Only simple regression with intercept, R²<1.","conditions":""},{"name":"Model SS from F","expr":"SSR=F×MSE","meaning":"Because MSR=SSR for 1 slope.","conditions":""},{"name":"ANOVA total DF identity","expr":"1+(n−2)=n−1","meaning":"Regression + error = total.","conditions":""}],"examples":[{"question_en":"For n=15, SSR=120 and SSE=80, fill the ANOVA degrees of freedom and SST.","steps_vi":["df regression=1; error=n−2=13; total=14.","SST=120+80=200."],"answer":"df: (1,13,14); SST=200.","check":""},{"question_en":"For n=12, SSE=50, compute MSE and SEE.","steps_vi":["Residual df=12−2=10.","MSE=50/10=5; SEE=√5=2.2361."],"answer":"MSE=5; SEE≈2.2361.","check":""},{"question_en":"Given SSR=60 and MSE=3, compute overall F for simple regression.","steps_vi":["MSR=SSR/1=60.","F=60/3=20."],"answer":"F=20.00","check":""},{"question_en":"An ANOVA table reports SSR=90, SSE=30. What is R-squared?","steps_vi":["SST=90+30=120.","R²=90/120=.75."],"answer":"75%","check":""},{"question_en":"For n=17 and SEE=2.5, determine SSE.","steps_vi":["Residual df=15.","SSE=SEE²×df_err=6.25×15=93.75."],"answer":"93.75","check":""},{"question_en":"An ANOVA table has total degrees of freedom=24. What is the sample size and error df?","steps_vi":["Total df=n−1=24 ⇒ n=25.","Error df=n−2=23."],"answer":"n=25; error df=23.","check":""},{"question_en":"A model has R2=0.60 with n=22. Compute the overall F-statistic.","steps_vi":["Residual df=20.","F=(n−2)R²/(1−R²)=20×.60/.40=30."],"answer":"F=30.00","check":""},{"question_en":"A model has SST=500 and R2=0.72. Calculate SSR and SSE.","steps_vi":["SSR=.72×500=360.","SSE=(1−.72)×500=140."],"answer":"SSR=360; SSE=140.","check":""},{"question_en":"An ANOVA table has SSR=100, SSE=50, and n=12. Calculate F.","steps_vi":["MSR=100; MSE=50/(12−2)=5.","F=100/5=20."],"answer":"F=20.00","check":""},{"question_en":"An analyst observes SEE=1.8. What is the implied residual MSE?","steps_vi":["SEE=√MSE.","MSE=1.8²=3.24."],"answer":"3.24","check":""},{"question_en":"In a simple regression, t for the slope is −2.2. Compute the regression ANOVA F.","steps_vi":["F=t² for testing zero slope.","F=(−2.2)²=4.84."],"answer":"4.84","check":""},{"question_en":"For n=16 and SST=120, calculate the sample variance of Y.","steps_vi":["Total df=n−1=15.","sY²=120/15=8."],"answer":"8.00","check":""},{"question_en":"An ANOVA table reports MSE=4 and error degrees of freedom 13. Find SSE and n.","steps_vi":["SSE=4×13=52.","n=error df+2=15."],"answer":"SSE=52; n=15.","check":""},{"question_en":"The overall F-statistic is 18 and MSE=2.5. Find SSR in simple regression.","steps_vi":["MSR=F×MSE=45.","Since df regression=1, SSR=45."],"answer":"45.00","check":""},{"question_en":"If a regression has R2=.40, what fraction of sample Y variation is not explained?","steps_vi":["SSE/SST=1−R²=1−.40=.60."],"answer":"60%","check":""}],"questions":[{"stem_en":"In ANOVA for simple intercept regression, the regression degrees of freedom is:","options":["1","n−1","n−2"],"correct":0,"why_vi":"One slope parameter ⇒ dfreg=1.","trap_vi":""},{"stem_en":"What is residual degrees of freedom for n=30 in simple regression?","options":["29","28","30"],"correct":1,"why_vi":"n−2=28.","trap_vi":""},{"stem_en":"Mean square error is:","options":["SST/(n−1)","SSR/1","SSE/(n−2)"],"correct":2,"why_vi":"MSE=unexplained SS divided by residual df.","trap_vi":""},{"stem_en":"Standard error of estimate is:","options":["Square root of MSE","Square of SSE","Regression coefficient divided by R-squared"],"correct":0,"why_vi":"SEE=√MSE.","trap_vi":""},{"stem_en":"In a simple ANOVA table, what is the numerator of F?","options":["MSE","MSR","SST"],"correct":1,"why_vi":"F=MSR/MSE.","trap_vi":""},{"stem_en":"SST equals:","options":["SSE−SSR","SSE/SSR","SSR+SSE"],"correct":2,"why_vi":"OLS with intercept decomposes total variation.","trap_vi":""},{"stem_en":"Which value has the same units as the dependent Y?","options":["SEE","MSE","SSE"],"correct":0,"why_vi":"SEE residual SD units Y; squared terms have Y².","trap_vi":""},{"stem_en":"A significant overall F test indicates evidence that:","options":["All regression assumptions hold.","Population slope differs from zero.","Predictions have zero error."],"correct":1,"why_vi":"F significance là evidence β1≠0 under assumptions.","trap_vi":""},{"stem_en":"Which quantity estimates error variance under classical regression assumptions?","options":["SEE","SSR","MSE"],"correct":2,"why_vi":"MSE=SSE/(n−2) estimates σ².","trap_vi":""},{"stem_en":"To recover sample variance of Y from ANOVA, use:","options":["SST/(n−1)","SST/(n−2)","SSE/(n−1)"],"correct":0,"why_vi":"Sample Y variance uses total variation and total df.","trap_vi":""},{"stem_en":"In simple intercept regression, F can be calculated from R2 and sample size as:","options":["R2/(n−2)","(n−2)R2/(1−R2)","(1−R2)/(n−2)"],"correct":1,"why_vi":"Derived from SSR and SSE ratios.","trap_vi":""},{"stem_en":"An ANOVA F statistic is necessarily:","options":["Negative when slope is negative","Between −1 and +1","Nonnegative"],"correct":2,"why_vi":"Both MSR/MSE nonnegative.","trap_vi":""},{"stem_en":"Why must the same dependent-variable scale be used when comparing SEE?","options":["SEE inherits the units of Y.","SEE is scale-free.","SEE never changes with Y units."],"correct":0,"why_vi":"SEE depends on Y units, so a transformed Y changes it.","trap_vi":""},{"stem_en":"If the total ANOVA df equals 49, the sample size is:","options":["49","50","51"],"correct":1,"why_vi":"n−1=49 → n=50.","trap_vi":""},{"stem_en":"Which field determines a right-tail F test denominator degrees of freedom?","options":["Total df","Regression df","Error df"],"correct":2,"why_vi":"denominator df = n−2.","trap_vi":""},{"stem_en":"A regression has n=20 and SSE=54. What is MSE?","options":["2.70","54.00","3.00"],"correct":2,"why_vi":"MSE=54/(20−2)=3.","trap_vi":""},{"stem_en":"For n=20 and SSE=54, what is SEE?","options":["3.000","1.732","7.348"],"correct":1,"why_vi":"SEE=√[54/18]=√3.","trap_vi":""},{"stem_en":"In simple ANOVA, SSR=40 and MSE=2. What is F?","options":["20.00","80.00","0.05"],"correct":0,"why_vi":"F=40/2=20.","trap_vi":""},{"stem_en":"SST=320 and SSE=80. What is R-squared as a percentage?","options":["75.0%","25.0%","240.0%"],"correct":0,"why_vi":"R²=1−80/320=.75.","trap_vi":""},{"stem_en":"Residual degrees of freedom=28. How many paired observations are in the regression?","options":["28","29","30"],"correct":2,"why_vi":"n=dferr+2=30.","trap_vi":""},{"stem_en":"SEE=2.5 and n=10. What is SSE?","options":["62.50","50.00","6.25"],"correct":1,"why_vi":"SSE=2.5²×(10−2)=50.","trap_vi":""},{"stem_en":"Given SSR=80 and SSE=20, what is SST?","options":["60.00","4.00","100.00"],"correct":2,"why_vi":"SST=SSR+SSE=100.","trap_vi":""},{"stem_en":"If the residual mean square MSE=5, what is SEE?","options":["25.000","2.236","5.000"],"correct":1,"why_vi":"SEE=√5.","trap_vi":""},{"stem_en":"A regression has n=12 and SST=88. What is sample variance of Y?","options":["8.00","7.33","11.00"],"correct":0,"why_vi":"sY²=88/(12−1)=8.","trap_vi":""},{"stem_en":"If n=18 and R-squared=0.5, what is the overall F-statistic?","options":["0.50","16.00","8.00"],"correct":1,"why_vi":"F=(n−2)R²/(1−R²)=16.","trap_vi":""}],"cards":[{"front_en":"What are ANOVA rows in simple regression?","back_vi":"Regression, Error, Total."},{"front_en":"ANOVA regression SS?","back_vi":"SSR explained variation."},{"front_en":"ANOVA error SS?","back_vi":"SSE unexplained variation."},{"front_en":"ANOVA total SS?","back_vi":"SST=SSR+SSE."},{"front_en":"Regression df for one predictor?","back_vi":"1."},{"front_en":"Residual error df for n observations?","back_vi":"n−2."},{"front_en":"Total df?","back_vi":"n−1."},{"front_en":"Mean square regression?","back_vi":"MSR=SSR/1=SSR."},{"front_en":"Mean square error?","back_vi":"MSE=SSE/(n−2)."},{"front_en":"F-statistic in ANOVA?","back_vi":"F=MSR/MSE."},{"front_en":"Which hypothesis does simple regression F test?","back_vi":"H0: β1=0."},{"front_en":"Standard error of estimate?","back_vi":"SEE=√MSE."},{"front_en":"MSE vs SEE units?","back_vi":"MSE in Y²; SEE in Y units."},{"front_en":"Regression R-squared from ANOVA?","back_vi":"SSR/SST."},{"front_en":"Sample variance of dependent variable from ANOVA?","back_vi":"SST/(n−1)."},{"front_en":"Recover SSE from SEE and n?","back_vi":"SSE=SEE²×(n−2)."},{"front_en":"Recover F from R² and n?","back_vi":"F=(n−2)R²/(1−R²)."},{"front_en":"ANOVA F test tail?","back_vi":"Right tail only."},{"front_en":"Does significant F guarantee correct residual assumptions?","back_vi":"Không."},{"front_en":"How to verify ANOVA table consistency?","back_vi":"SS additive, df additive, SEE²=MSE, F=t² in simple regression."}]},{"id":"CFA26-01-10-LOS05","letter":"10.e","title_en":"Point Forecasts and Prediction Intervals","outcome_en":"calculate and interpret the predicted value for the dependent variable, and a prediction interval for it, given an estimated linear regression model and a value for the independent variable","overview_vi":"Dự báo giá trị Y mới và khoảng dự báo t-based; tính standard error of forecast, phân biệt interval cho individual observation với conditional mean; kiểm tra độ rộng interval khi Xf xa mean, thay đổi confidence và vi phạm assumptions.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"305–310 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"124–125 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"439–442 (physical PDF)"}],"sections":[{"heading":"1. Prediction objective","body":"Hồi quy có thể dùng để estimate E(Y|Xf) và forecast một observed Y mới tại Xf. Trong LOS 10.e, trọng tâm là Ŷf=b0+b1Xf và **prediction interval** around an individual future Y, không chỉ coefficient CI hay mean-response CI.","trap":""},{"heading":"2. Point forecast from fitted coefficients","body":"Khi có b0,b1 và Xf, tính Ŷf=b0+b1Xf. Đảm bảo Xf cùng đơn vị với X sample; nếu X market return biểu diễn decimal hoặc percentage points, đổi đúng scale trước khi nhân slope.","trap":""},{"heading":"3. Meaning of the forecast error","body":"Observed future Y differs from Ŷf do residual disturbance ε_new và uncertainty trong ước lượng b0,b1. Vì vậy prediction interval cho một NEW observation rộng hơn confidence interval for conditional mean, do chứa “1+” trong variance.","trap":""},{"heading":"4. Standard error of estimate as starting point","body":"SEE=√[SSE/(n−2)] là residual dispersion trong Y units. Prediction standard error nhân SEE với uncertainty factor do n, Xf và Sxx. Nếu đề cung cấp s_f trực tiếp, không cần tính lại mà dùng tcritical×s_f.","trap":""},{"heading":"5. Standard error of individual forecast","body":"s_f=SEE√[1+1/n+(Xf−Xbar)²/Sxx], với Sxx=Σ(Xi−Xbar)². Term 1 là individual shock, 1/n là uncertainty in fitted intercept at center, leverage term tăng khi Xf xa Xbar. Assumes independent new error, constant variance and standard classical inference conditions.","trap":""},{"heading":"6. Prediction interval computation","body":"(1−α)% PI for individual future Y: Ŷf±t_{1−α/2,n−2}·s_f. Dùng two-sided t, df=n−2. Interval is *conditional on chosen Xf and model assumptions*, không bảo đảm kết quả luôn nằm trong khoảng.","trap":""},{"heading":"7. Mean-response confidence interval","body":"CI for E(Y|Xf) dùng s_mean=SEE√[1/n+(Xf−Xbar)²/Sxx], bỏ term 1. Do s_f²=s_mean²+SEE², PI individual rộng hơn mean CI cùng α. Nếu đề hỏi prediction interval cho Y mới, không tự thay mean-response formula.","trap":""},{"heading":"8. Why interval narrowest near Xbar","body":"Khi Xf=Xbar, distance term bằng 0, nên s_f minimized at SEE√(1+1/n). Xa Xbar làm leverage term tăng, interval rộng đối xứng hai phía. Điều này cũng cảnh báo uncertainty của extrapolation.","trap":""},{"heading":"9. Effect of sample size and spread","body":"Larger n giảm 1/n và thường tăng Sxx nếu X spread tương đương; s_f có lower limit near SEE do irreducible new observation error. Larger Sxx làm slope prediction more stable tại given distance, nhưng no free guarantee if data quality poor.","trap":""},{"heading":"10. Confidence level widens the interval","body":"Giữ s_f/df cố định, từ 90% PI sang 99% PI sẽ dùng tcrit lớn hơn và rộng hơn. Prediction interval 95% không có nghĩa 95% probability model đúng hoặc 95% stock return necessarily profitable.","trap":""},{"heading":"11. What if error assumptions fail?","body":"Nếu residual variance grows with X, constant SEE may understate uncertainty in high-X forecasts; autocorrelation ảnh hưởng variance và independence of new error, structural breaks làm coefficients unstable. Formula PI là conditional model result, không phải universal risk bound.","trap":""},{"heading":"12. Distinguish interpolation and extrapolation","body":"Ở Xf trong sample range, point forecast có support từ lịch sử nhiều hơn. Ngoài range, functional form có thể thay đổi và nominal t-based PI không capture model risk/extrapolation error. Cảnh giác với xfar beyond observed values.","trap":""},{"heading":"13. Using return units correctly","body":"Nếu Y là % returns, SEE, s_f và PI half-width cũng là percentage points; F, R² scale-free. Ví dụ Ŷf=8% và margin 3 pp ⇒ [5%,11%], không phải “8%±3% relative”.","trap":""},{"heading":"14. From forecast SE to PI without raw data","body":"Đề thường cho b0,b1, Xf, s_f, tcrit. Workflow: multiply slope, add intercept, margin=tcrit×s_f, subtract/add. Nếu đề cho SEE, n, Xbar, Sxx thì tính s_f trước. Đừng dùng coefficient SE(b1) để làm s_f.","trap":""},{"heading":"15. Direction of forecast error and interpretation","body":"Residual forecast error có thể là actual minus forecast; PI symmetric under normal model around Ŷ. PI width phản ánh uncertainty conditional on Xf, không phải probability distribution of Xf itself. Nếu Xf cũng được dự báo (uncertain), formula standard không bao phủ thêm uncertainty của X forecast.","trap":""},{"heading":"16. Individual realized return vs portfolio risk","body":"A 95% statistical prediction interval for one Y không trực tiếp bằng VaR hoặc expected shortfall và không đo tail risk khi heavy tails. Đừng biến PI trong regression thành guarantee về khả năng lỗ ở mức nào trong trading.","trap":""}],"formulas":[{"name":"Point forecast","expr":"Ŷf=b0+b1Xf","meaning":"Predicted dependent Y for specified Xf.","conditions":""},{"name":"Residual estimate variance","expr":"SEE²=SSE/(n−2)","meaning":"Estimated error variance of Y around fitted model.","conditions":""},{"name":"Centered X sum of squares","expr":"Sxx=Σ(Xi−Xbar)²","meaning":"Spread of observed regressors.","conditions":""},{"name":"Standard error of individual forecast","expr":"s_f=SEE√[1+1/n+(Xf−Xbar)²/Sxx]","meaning":"Includes irreducible individual error uncertainty.","conditions":""},{"name":"Two-sided prediction interval","expr":"PI = Ŷf ± t₍1−α/2,n−2₎·s_f","meaning":"Interval for a single future Y conditional on Xf.","conditions":""},{"name":"Mean response standard error","expr":"s_mean=SEE√[1/n+(Xf−Xbar)²/Sxx]","meaning":"For expected conditional mean E(Y|Xf), not individual Y.","conditions":""},{"name":"Mean response CI","expr":"CImean=Ŷf±tcrit·s_mean","meaning":"Narrower than individual PI at same α.","conditions":""},{"name":"PI vs CI variance","expr":"s_f²=s_mean²+SEE²","meaning":"Individual interval accounts for new disturbance.","conditions":""},{"name":"Forecast SE at mean X","expr":"Xf=Xbar ⇒ s_f=SEE√(1+1/n)","meaning":"Smallest PI SE for given estimated model.","conditions":""},{"name":"Half-width of prediction interval","expr":"halfwidth=tcrit·s_f","meaning":"PI=[Ŷf−halfwidth,Ŷf+halfwidth].","conditions":""},{"name":"Effect of moving Xf","expr":"leverage=(Xf−Xbar)²/Sxx","meaning":"Forecast SE widens as |Xf−Xbar| increases.","conditions":""}],"examples":[{"question_en":"For Ŷ=2+1.5X and Xf=6, calculate the point forecast.","steps_vi":["Ŷf=2+1.5×6=11."],"answer":"11.00","check":""},{"question_en":"A predicted value is 8%, the forecast standard error is 2%, and tcrit=2.1. Calculate the 95% prediction interval.","steps_vi":["Halfwidth=2.1×2%=4.2 percentage points.","PI=8%±4.2 pp."],"answer":"[3.8%, 12.2%]","check":""},{"question_en":"Given SEE=3, n=20, Xf=Xbar, find the forecast standard error.","steps_vi":["s_f=3√(1+1/20).","s_f≈3.0741."],"answer":"3.0741","check":""},{"question_en":"Given SEE=2, n=20, Xf=6, Xbar=5, and Sxx=100, calculate s_f.","steps_vi":["Squared factor=1+.05+1/100=1.06.","s_f=2√1.06≈2.0591."],"answer":"2.0591","check":""},{"question_en":"With b0=2, b1=1.5, Xf=6, sf=2.0591 and tcrit=2.101, construct the prediction interval.","steps_vi":["Ŷ=11.00.","Halfwidth≈2.101×2.0591≈4.326.","PI≈[6.674,15.326]."],"answer":"[6.67, 15.33] approximately.","check":""},{"question_en":"For SEE=2, n=20, Xf=6, Xbar=5, Sxx=100, compute standard error for mean response.","steps_vi":["s_mean=2√(.05+.01)=2√.06."],"answer":"0.4899","check":""},{"question_en":"At the same Xf, which interval is wider: mean CI or individual PI?","steps_vi":["s_f²=s_mean²+SEE², thus s_f>s_mean if SEE>0."],"answer":"Individual prediction interval.","check":""},{"question_en":"Given Yhat=12 and a prediction halfwidth of 4.5, determine lower and upper bounds.","steps_vi":["Lower=12−4.5=7.5.","Upper=12+4.5=16.5."],"answer":"[7.5, 16.5]","check":""},{"question_en":"A model has SEE=1.5, n=25, and Xf=Xbar. Compute minimum forecast standard error.","steps_vi":["s_f=1.5√(1+.04)=1.5297."],"answer":"1.5297","check":""},{"question_en":"Holding everything else fixed, Xf moves farther from Xbar. What happens to the prediction interval?","steps_vi":["Distance leverage term (Xf−Xbar)²/Sxx increases.","Forecast standard error and half-width increase."],"answer":"Prediction interval widens.","check":""},{"question_en":"With forecast standard error=2 and tcrit increasing from 1.7 to 2.7, by how much does interval halfwidth increase?","steps_vi":["Initial halfwidth=1.7×2=3.4.","New halfwidth=2.7×2=5.4; increase=2.0."],"answer":"2.00","check":""},{"question_en":"Why might a nominal 95% regression prediction interval be too narrow after a regime shift?","steps_vi":["New data may follow different intercept/slope or volatility.","Classical interval conditions assume model stability and suitable errors."],"answer":"Structural/model risk is not fully captured by nominal formula.","check":""},{"question_en":"For a fitted model with forecast Yhat=5 and sf=1.2, use tcrit=2.0 to find the prediction interval.","steps_vi":["Margin=2×1.2=2.4.","Lower=5−2.4=2.6; upper=7.4."],"answer":"[2.60, 7.40]","check":""},{"question_en":"Given SEE=2, n=10, Xf−Xbar=3 and Sxx=45, find forecast standard error.","steps_vi":["Factor=1+.1+9/45=1.3.","s_f=2√1.3≈2.28035."],"answer":"2.28035","check":""},{"question_en":"A market model predicts monthly stock return 1.5% with a 95% PI [−4.5%, 7.5%]. Does this guarantee positive return?","steps_vi":["Interval contains negative returns.","PI is a probabilistic model statement, not guarantee; individual Y can be outside interval too."],"answer":"No.","check":""},{"question_en":"For n=30, SEE=1, Xf=Xbar, calculate mean-response standard error.","steps_vi":["s_mean=1×√(1/30)."],"answer":"0.18257","check":""}],"questions":[{"stem_en":"Which interval is usually wider at the same X and confidence level?","options":["Mean-response confidence interval","Individual prediction interval","They must have identical width"],"correct":1,"why_vi":"PI adds individual shock term 1 under square root.","trap_vi":""},{"stem_en":"The term “1 +” in an individual forecast variance formula represents:","options":["The new observation disturbance variance","R-squared","The slope estimate"],"correct":0,"why_vi":"PI dự báo 1 observation nên bao gồm variance of new disturbance.","trap_vi":""},{"stem_en":"The prediction interval is generally narrowest when forecast X equals:","options":["The maximum X observation","Zero regardless of sample","Sample mean of X"],"correct":2,"why_vi":"Distance term minimized at Xf=Xbar.","trap_vi":""},{"stem_en":"Which degrees of freedom apply to the regression prediction interval t-critical value?","options":["n−1","n−2","n"],"correct":1,"why_vi":"Two fitted coefficients → residual df n−2.","trap_vi":""},{"stem_en":"Which quantity is multiplied by t-critical to build a prediction interval?","options":["Standard error of forecast","Standard error of slope only","R-squared"],"correct":0,"why_vi":"Halfwidth=tcrit×sf.","trap_vi":""},{"stem_en":"When Xf moves farther from Xbar, the individual forecast SE tends to:","options":["Fall","Remain equal to coefficient SE","Rise"],"correct":2,"why_vi":"Leverage term grows with squared distance.","trap_vi":""},{"stem_en":"A 99% prediction interval compared to a 90% interval, all else fixed, is:","options":["Narrower","Wider","Unchanged"],"correct":1,"why_vi":"Higher confidence ⇒ greater tcrit.","trap_vi":""},{"stem_en":"A regression forecast point estimate is:","options":["b0+b1Xf","Residual SSE","Sample correlation"],"correct":0,"why_vi":"Point forecast given Xf.","trap_vi":""},{"stem_en":"An individual prediction interval for a 1-year return is:","options":["A guarantee of returns","Always nonnegative","Conditional on the model and future X value"],"correct":2,"why_vi":"Nominal coverage requires model assumptions and conditional X.","trap_vi":""},{"stem_en":"Which interval uses the forecast SE without the added “1” term?","options":["PI for individual Y","CI for conditional mean Y","Risk-free confidence interval"],"correct":1,"why_vi":"Mean-response CI excludes new observation shock.","trap_vi":""},{"stem_en":"For an individual Y prediction interval, which statement is correct?","options":["It describes uncertainty of a single new response under assumptions.","It is the confidence interval for β1.","It is the probability that the null is true."],"correct":0,"why_vi":"Prediction interval differs from coefficient CI and hypothesis p-values.","trap_vi":""},{"stem_en":"Which regression property is most relevant when the new Xf lies outside observed sample values?","options":["Guaranteed accuracy","Lower forecast error","Extrapolation risk"],"correct":2,"why_vi":"Function outside sample may change.","trap_vi":""},{"stem_en":"If the forecast standard error is supplied, an analyst should:","options":["Calculate slope t instead","Multiply by the appropriate t critical and add/subtract from point forecast","Multiply by R2 for the PI"],"correct":1,"why_vi":"PI=point±tcrit×sf.","trap_vi":""},{"stem_en":"If residual variance increases at high X, constant-variance PI at high X may:","options":["Understate forecast uncertainty","Guarantee conservative coverage","Make R2 equal zero"],"correct":0,"why_vi":"Heteroskedasticity làm sf formula không thích ứng variance có điều kiện.","trap_vi":""},{"stem_en":"For s_f^2 and s_mean^2 at same Xf, which equality holds?","options":["sf²=smean²−SEE²","sf=smean","sf²=smean²+SEE²"],"correct":2,"why_vi":"Added individual disturbance variance=SEE².","trap_vi":""},{"stem_en":"For Ŷ=1.5+0.8X, Xf=10. What is the point forecast?","options":["9.50","8.00","11.50"],"correct":0,"why_vi":"1.5+.8×10=9.5.","trap_vi":""},{"stem_en":"A forecast equals 10, sf=2, tcrit=2.1. What is the prediction interval lower bound?","options":["5.80","14.20","7.90"],"correct":0,"why_vi":"10−2.1×2=5.8.","trap_vi":""},{"stem_en":"A forecast equals 10, sf=2, tcrit=2.1. What is the prediction interval upper bound?","options":["5.80","12.10","14.20"],"correct":2,"why_vi":"10+4.2=14.2.","trap_vi":""},{"stem_en":"Given SEE=2, n=20, Xf=Xbar, calculate sf.","options":["2.049","2.000","0.447"],"correct":0,"why_vi":"s_f=2√(1+1/20).","trap_vi":""},{"stem_en":"Given SEE=2, n=20, Xf=Xbar, calculate the mean-response SE.","options":["0.447","2.049","2.000"],"correct":0,"why_vi":"s_mean=2√(1/20).","trap_vi":""},{"stem_en":"For n=16, Xf−Xbar=4, Sxx=64, what is the leverage term inside forecast variance?","options":["0.062","0.250","4.000"],"correct":1,"why_vi":"Distance term=4²/64=.25.","trap_vi":""},{"stem_en":"The estimated forecast is 6, sf=1.5 and tcrit=2. What is the PI half-width?","options":["3.00","12.00","1.50"],"correct":0,"why_vi":"Halfwidth=2×1.5=3.","trap_vi":""},{"stem_en":"With SEE=1.0, n=10, Xf−Xbar=3, Sxx=30, calculate sf.","options":["1.183","1.400","0.632"],"correct":0,"why_vi":"sf=√(1+.1+9/30)=√1.4.","trap_vi":""}],"cards":[{"front_en":"Point forecast for simple regression?","back_vi":"Ŷf=b0+b1Xf."},{"front_en":"Individual prediction interval (PI)?","back_vi":"Ŷf±tcrit×sf."},{"front_en":"Regression forecast standard error sf?","back_vi":"SEE√[1+1/n+(Xf−Xbar)²/Sxx]."},{"front_en":"Mean-response standard error?","back_vi":"SEE√[1/n+(Xf−Xbar)²/Sxx]."},{"front_en":"Why is individual PI wider than mean CI?","back_vi":"PI includes new disturbance variance (“1+”)."},{"front_en":"Prediction interval df?","back_vi":"n−2."},{"front_en":"Where is forecast interval narrowest?","back_vi":"At Xf=Xbar."},{"front_en":"What widens forecast SE away from sample mean?","back_vi":"(Xf−Xbar)²/Sxx."},{"front_en":"What is the half-width of prediction interval?","back_vi":"tcrit×sf."},{"front_en":"Does PI guarantee actual Y?","back_vi":"No; nominal coverage conditional on model."},{"front_en":"A higher confidence level does what to PI?","back_vi":"Increases tcritical and width."},{"front_en":"Does larger n eliminate individual PI error?","back_vi":"No; irreducible residual shock remains."},{"front_en":"Why avoid Xf far outside sample?","back_vi":"Extrapolation risk and unreliable model form."},{"front_en":"Do Y and PI bounds share units?","back_vi":"Yes; all in Y units."},{"front_en":"Which uncertainty is missing if Xf itself is estimated?","back_vi":"Model assumes Xf given; uncertainty of Xf forecast not included."},{"front_en":"What happens when homoskedasticity fails?","back_vi":"Classical PI may have incorrect nominal coverage."},{"front_en":"Is a regression PI a VaR measure?","back_vi":"Not automatically; definitions and error tails differ."},{"front_en":"If sf is supplied, what is shortest PI calculation?","back_vi":"Calculate Ŷf then ± tcrit×sf."}]},{"id":"CFA26-01-10-LOS06","letter":"10.f","title_en":"Functional Forms of Simple Linear Regression","outcome_en":"describe different functional forms of simple linear regressions","overview_vi":"Hiểu level-level, log-lin, lin-log, log-log, chọn dạng hàm theo pattern/kinh tế, diễn giải percent-versus-unit chính xác và xấp xỉ, điều kiện log dương, back-transform và so sánh mô hình trên cùng response scale.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM10","pages":"311–317 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 10","pages":"126–128 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 10","pages":"442–444 (physical PDF)"}],"sections":[{"heading":"1. Why transform regression variables?","body":"Nếu scatterplot/residuals cho thấy Y và X liên hệ cong, có thể dùng log transforms để mô hình tuyến tính theo estimated coefficients trên transformed scale. Chọn functional form theo economic theory + diagnostic fit; không biến đổi đơn thuần để tạo R² cao.","trap":""},{"heading":"2. Level–level reference model","body":"Y=β0+β1X+ε: β1 units(Y) per 1 unit(X). Ví dụ earnings growth points theo advertising spend. Nếu Y và X là percentage points, tăng X 1 pp làm fitted Y tăng β1 pp; không tự hiểu β1 as elasticity.","trap":""},{"heading":"3. Log-lin or semilog model","body":"lnY=β0+β1X+ε (dependent variable logged, explanatory level). Một-unit increase X làm lnY tăng β1, Y tăng approximately 100β1% for small β1; exact percentage factor is [exp(β1)-1]×100%. Để forecast Y, naive exp(predicted lnY) is conditional median under lognormal assumptions, not automatically mean.","trap":""},{"heading":"4. Interpreting log-lin growth over multiple units","body":"Tăng X từ x0 lên x1 thay đổi predicted ratio Y1/Y0=exp[β1(x1−x0)]. Với β1=.05, X tăng 2 units ⇒ exact ratio exp(.10)≈1.1052 (10.52%). Khi β1 lớn, approximation 100×β1×ΔX có thể sai đáng kể.","trap":""},{"heading":"5. Lin-log model","body":"Y=β0+β1 lnX+ε (dependent variable level, X logged). Tăng X khoảng 1% → predicted Y đổi khoảng .01β1 Y units. Exact change from X0 to X1 is ΔŶ=β1 ln(X1/X0); β1 không phải percentage change in Y.","trap":""},{"heading":"6. Lin-log for diminishing marginal effect","body":"Derivative dY/dX=β1/X, nên với β1 dương, marginal absolute effect giảm khi X tăng. Ví dụ income vs firm size khi response tăng chậm dần theo firm size. Chỉ dùng log(X) nếu X>0.","trap":""},{"heading":"7. Log-log model","body":"lnY=β0+β1 lnX+ε. β1 là elasticity: X ↑1% ⇒ Y ↑ khoảng β1% cho biến đổi nhỏ; exact ratio Y1/Y0=(X1/X0)^β1. Vì slope là elasticity, không có units, khác level-level slope.","trap":""},{"heading":"8. Log-log elasticity and sign","body":"β1=1.4 → 1% X ↑ predicts approximately 1.4% Y ↑; β1=−0.5 → 1% X ↑ predicts approximately 0.5% Y ↓. 10% growth change exact using 1.1^β1−1, không nhất thiết đúng bằng β1×10%.","trap":""},{"heading":"9. Required domain of logarithms","body":"lnX chỉ xác định với X>0; lnY chỉ xác định với Y>0. Log return là ln(Pt/Pt−1) vì price ratio dương; không thể lấy ln of raw negative simple return hoặc ln of zero/negative earnings. Cần chọn economic transformations phù hợp.","trap":""},{"heading":"10. Interpreting intercept after log transformation","body":"Log-lin at X=0 gives lnY=β0, so predicted Y=expβ0 (assuming ε=0 conditional on transformed scale). Log-log at X=1 gives lnY=β0 so predicted Y=expβ0. Lin-log at X=1 gives Y=β0. Khi X=0 trong lnX, model undefined.","trap":""},{"heading":"11. How to forecast transformed dependent variable","body":"Từ lnYhat=b0+b1X (log-lin) hoặc lnYhat=b0+b1lnX (log-log), back-transform exp(lnYhat) để lấy fitted central level on multiplicative scale. Với lognormal residuals, mean E(Y|X)=exp(lnYhat+σ²/2) under assumptions; naively exponentiated line yields median, so note retransformation bias (extension).","trap":""},{"heading":"12. Comparing functional forms on the correct scale","body":"Không thể so raw R² của Y-level model với R² của lnY model và kết luận model nào dự báo Y tốt hơn, vì response scale khác. So on common target scale with suitable error metric, inspect residuals and economic theory; same-scale comparisons may use SEE with care.","trap":""},{"heading":"13. Selecting a model from residual diagnostics","body":"Level-level residual U-shape gợi nonlinear pattern, log-lin/lin-log/log-log có thể làm mean pattern straight hơn. Nhưng transformation không giải quyết tự động serial correlation, omitted factors hay nonconstant error variance. Chọn form dựa trên data properties và economic logic.","trap":""},{"heading":"14. Semilog vs log-log percentage interpretation","body":"Log-lin: percent Y for one unit X. Lin-log: level Y units for percent X. Log-log: percent Y for percent X (elasticity). Ghi rõ log nằm ở bên Y hay X; đây là lỗi dễ gặp nhất trong LOS 10.f.","trap":""},{"heading":"15. Reading regression equations with units","body":"lnRevenue=2+.04×Years ⇒ revenue grows ~4% per 1 year (exact ~4.081%). ProfitMargin=3+2lnAssets ⇒ assets +1% shifts profit margin ≈+.02 units. lnSales=1+1.5lnAdvertising ⇒ advertising +1% shifts sales ≈+1.5%.","trap":""},{"heading":"16. Transforming X and interpreting marginal effect","body":"Trong log-log dY/dX=β1Y/X; trong log-lin dY/dX=β1Y; trong lin-log dY/dX=β1/X; trong level-level dY/dX=β1. Các đạo hàm dùng local changes; exact large finite changes phải dùng exponent/log ratios.","trap":""},{"heading":"17. Model specification and practical caution","body":"Nếu data không dương, log not defined: không đơn giản bỏ missing/negative observations nếu selection bias. Nếu response Y price, dynamic time series cần thêm checks về nonstationarity, omitted variables và spurious trend; simple transformation chưa bảo đảm causal interpretation.","trap":""},{"heading":"18. Functional-form exam decision tree","body":"Quan sát dependent variable có ln không? Có: change Y percent (log-lin hoặc log-log). Quan sát explanatory X có ln không? Có: change X percent (lin-log hoặc log-log). Không log: level-level. Với tăng 1% X, dùng β1/100 in lin-log Y units; β1% in log-log Y percent.","trap":""}],"formulas":[{"name":"Level–level","expr":"Y=b0+b1X+ε","meaning":"b1: Y-units per one X-unit.","conditions":""},{"name":"Log-lin","expr":"lnY=b0+b1X+ε","meaning":"X +1 unit ⇒ Y about 100b1% change.","conditions":"Y>0."},{"name":"Exact log-lin percentage","expr":"100×(e^(b1·ΔX)−1)%","meaning":"Exact multiplicative Y change from ΔX.","conditions":"Y>0, assuming fitted transformed relation."},{"name":"Log-lin point back-transform","expr":"Ŷcentral=exp(b0+b1X)","meaning":"Predicted median/central level on transformed-error model, not always conditional mean.","conditions":""},{"name":"Lin-log","expr":"Y=b0+b1 lnX+ε","meaning":"X +1% ⇒ Y about b1/100 units.","conditions":"X>0."},{"name":"Exact lin-log level change","expr":"ΔŶ=b1 ln(Xnew/Xold)","meaning":"Level units Y, not percent Y.","conditions":"Xold,Xnew>0."},{"name":"Lin-log marginal derivative","expr":"dŶ/dX=b1/X","meaning":"Marginal effect varies with X.","conditions":""},{"name":"Log-log","expr":"lnY=b0+b1 lnX+ε","meaning":"b1 elasticity; X +1% ⇒ Y ~b1%.","conditions":"X>0,Y>0."},{"name":"Exact log-log percentage change","expr":"100×[(Xnew/Xold)^b1−1]%","meaning":"Exact multiplicative response to finite X change.","conditions":""},{"name":"Log-log level back-transform","expr":"Ŷcentral=exp(b0)·X^b1","meaning":"Power-law relationship on original scale.","conditions":""},{"name":"Log-log elasticity derivative","expr":"(dY/dX)×(X/Y)=b1","meaning":"Constant elasticity for power-law model.","conditions":""},{"name":"Level-level marginal effect","expr":"dŶ/dX=b1","meaning":"Constant level marginal slope.","conditions":""},{"name":"Log-lin marginal effect","expr":"dŶ/dX=b1·Ŷ","meaning":"Level marginal effect proportional to predicted Y.","conditions":""},{"name":"Simple compounding vs log","expr":"ln(1+Rsimple)=Rlog","meaning":"To take log of return factor, require 1+Rsimple>0.","conditions":""},{"name":"Lognormal back-transform mean (extension)","expr":"E(Y|X)=exp(μlogY+σ²/2)","meaning":"If conditional log-error is normal with constant σ²; naive expμ gives median.","conditions":""}],"examples":[{"question_en":"A level–level model is Yhat=3+0.8X. Interpret its slope.","steps_vi":["Each +1 unit of X raises predicted Y by 0.8 unit, not 0.8%."],"answer":"+0.8 unit Y per +1 unit X.","check":""},{"question_en":"In lnYhat=1+0.04X, what is approximate Y growth for a +1 unit change in X?","steps_vi":["Log-lin model: approximate percent change=100×.04."],"answer":"Approximately +4%.","check":""},{"question_en":"In lnYhat=1+0.04X, calculate exact Y growth for a +1 unit change in X.","steps_vi":["Exact change=100(exp(.04)−1).","exp(.04)≈1.04081."],"answer":"+4.0811% approximately.","check":""},{"question_en":"In Yhat=2+5lnX, X increases by approximately 1%. What is the approximate change in Y?","steps_vi":["Lin-log: ΔY≈b1×.01=5×.01."],"answer":"+0.05 units of Y.","check":""},{"question_en":"For Yhat=2+5lnX, X doubles. Calculate the exact predicted change in Y.","steps_vi":["ΔY=5ln(2)=5×.693147=3.4657."],"answer":"+3.4657 Y units.","check":""},{"question_en":"In lnYhat=3+1.2lnX, X increases by 1%. What is the approximate change in Y?","steps_vi":["Log-log elasticity b1=1.2.","Approx ΔY/Y=1.2×1%=1.2%."],"answer":"Approximately +1.2%.","check":""},{"question_en":"For a log-log model with elasticity 1.2, X grows by 10%. What is the exact predicted Y growth?","steps_vi":["Exact ratio=(1.10)^1.2.","Growth=100[(1.10)^1.2−1]≈12.1169%."],"answer":"Approximately +12.12%.","check":""},{"question_en":"For lnYhat=2+0.1X, X=3. Determine fitted central Y level ignoring retransformation-bias adjustment.","steps_vi":["lnYhat=2+.1×3=2.3.","Back-transform exp(2.3)=9.9742."],"answer":"9.9742","check":""},{"question_en":"For a log-log model lnYhat=0.5+0.75lnX and X=4, calculate central fitted Y.","steps_vi":["Yhat central=exp(.5)×4^.75.","≈1.64872×2.82843=4.6633."],"answer":"4.6633","check":""},{"question_en":"Which model fits a constant elasticity assumption?","steps_vi":["Elasticity is d lnY / d lnX.","Log-log uses linear lnY vs lnX with slope equal elasticity."],"answer":"Log–log model.","check":""},{"question_en":"What does b1=−2 in Yhat=5−2lnX imply for a 1% rise in X?","steps_vi":["Lin-log b1/100=−.02.","Y declines by approx 0.02 units, not 2%."],"answer":"Approximately −0.02 Y units.","check":""},{"question_en":"What does b1=−0.4 in lnYhat=2−0.4lnX imply for a 1% rise in X?","steps_vi":["Log-log elasticity −0.4."],"answer":"Approximately −0.4% in Y.","check":""},{"question_en":"A proposed regression uses ln(EPS) but some EPS values are negative. Is that functional form directly feasible?","steps_vi":["Natural log of nonpositive EPS is undefined.","Investigate target and transformation; do not silently drop negatives."],"answer":"No, not without a valid transformation/data treatment.","check":""},{"question_en":"Two models have R2=0.91 for lnY and R2=0.88 for Y. Can they be compared directly to choose the best Y-level forecast?","steps_vi":["Dependent scales differ.","Use a common-scale forecast evaluation and inspect residuals."],"answer":"No; raw R² values are on different Y scales.","check":""},{"question_en":"What is ln(1+0.08) for a simple return of 8%?","steps_vi":["Gross return factor 1.08>0.","Log return=ln(1.08)=.076961, about 7.6961%."],"answer":"0.076961 (7.6961%).","check":""},{"question_en":"In a log-lin model with b1=0.06, X increases by 2 units. Calculate exact Y percentage growth.","steps_vi":["Exact multiplicative ratio e^(.06×2)=e^.12.","Growth≈12.7497%."],"answer":"Approximately +12.75%.","check":""},{"question_en":"In a log-log model with b1=−0.5, X doubles. What is the exact predicted percentage change in Y?","steps_vi":["Ynew/Yold=2^−.5=1/√2≈.707107.","Percent change≈−29.2893%."],"answer":"Approximately −29.29%.","check":""},{"question_en":"A lin-log model has b1=4 and X grows from 20 to 22. Compute the exact change in fitted Y.","steps_vi":["ΔY=4 ln(22/20)=4ln1.1.","≈4×.0953102=.38124."],"answer":"+0.38124 Y units.","check":""}],"questions":[{"stem_en":"A model with ln(Y) as the dependent variable and X in levels is:","options":["Lin-log","Log-log","Log-lin"],"correct":2,"why_vi":"Y logged, X level ⇒ log-lin.","trap_vi":""},{"stem_en":"A model with Y in levels and ln(X) as explanatory variable is:","options":["Lin-log","Log-lin","Log-log"],"correct":0,"why_vi":"Y level and X logged ⇒ lin-log.","trap_vi":""},{"stem_en":"A model with both ln(Y) and ln(X) is:","options":["Level–level","Log–log","Lin–log"],"correct":1,"why_vi":"Both sides logged ⇒ elasticity interpretation.","trap_vi":""},{"stem_en":"In a log-lin model, the approximate effect of a one-unit X increase is:","options":["b1 units of Y","b1% change in X","100 × b1 percent change in Y"],"correct":2,"why_vi":"100×b1% approximate Y for +1 X unit.","trap_vi":""},{"stem_en":"In a lin-log model, a 1% increase in X changes predicted Y by approximately:","options":["b1/100 units of Y","100b1% of Y","b1% of Y"],"correct":0,"why_vi":"ΔY≈b1×.01, Y units.","trap_vi":""},{"stem_en":"In a log-log model, the slope is interpreted as:","options":["Standard error of the estimate","Constant elasticity of Y with respect to X","One unit of Y for one unit of X"],"correct":1,"why_vi":"β1 = dlnY/dlnX.","trap_vi":""},{"stem_en":"Which requirement applies to directly using ln(X)?","options":["X may equal zero","X must be negative","X must be positive"],"correct":2,"why_vi":"Natural log defined only for X>0 real.","trap_vi":""},{"stem_en":"Which functional form expresses a constant percentage response of Y to a one-unit change in X?","options":["Log-lin","Level-level","Lin-log"],"correct":0,"why_vi":"lnY linear in X gives multiplicative Y ratio per unit X.","trap_vi":""},{"stem_en":"The exact growth factor in Y for log-lin slope b1 and ΔX is:","options":["1+b1","exp(b1ΔX)","b1/ΔX"],"correct":1,"why_vi":"Y1/Y0=e^{b1ΔX}.","trap_vi":""},{"stem_en":"For log-log elasticity β1, exact Y growth factor when X increases 10% is:","options":["1+0.1β1 always exactly","exp(β1) always","(1.1)^β1"],"correct":2,"why_vi":"Power-law exact response.","trap_vi":""},{"stem_en":"Comparing R-squared of a regression for ln(Y) with one for Y, what is appropriate?","options":["Avoid direct raw R-squared ranking because response scales differ.","Select the higher number regardless of scale.","Assume coefficient sign resolves model choice."],"correct":0,"why_vi":"R² khác dependent scale không comparable directly.","trap_vi":""},{"stem_en":"What is the relationship between naive exp(lnYhat) and conditional mean Y under a lognormal-error model?","options":["Naive exp is always the mean.","Naive exp generally gives conditional median; mean needs variance adjustment.","They differ only if X=0."],"correct":1,"why_vi":"E(Y|X)=exp(μ+σ²/2), median=expμ if lognormal error.","trap_vi":""},{"stem_en":"In a lin-log model, which slope interpretation is wrong?","options":["X +1% changes fitted Y by about b1/100 units.","Y change depends on the ratio of new X to old X.","X +1% changes Y by b1 percent."],"correct":2,"why_vi":"Lin-log Y not logged, result in level Y units, not percentage Y.","trap_vi":""},{"stem_en":"For a log-lin model with b1=0.5, the exact one-unit Y growth is:","options":["exp(0.5)−1, not exactly 50%","Exactly 50% under all changes","0.5 unit Y"],"correct":0,"why_vi":"Exact change=64.87%, approximation 50% poor for large b1.","trap_vi":""},{"stem_en":"Which sign of a log-log coefficient implies negative elasticity?","options":["Positive coefficient","Negative coefficient","Intercept below zero"],"correct":1,"why_vi":"Elasticity sign equals slope sign.","trap_vi":""},{"stem_en":"In lnY=b0+0.03X, what is the approximate Y percentage increase for +1 X unit?","options":["30.00%","0.03%","3.00%"],"correct":2,"why_vi":"Log-lin approximation 100×.03=3%.","trap_vi":""},{"stem_en":"In lnY=b0+0.05X, what is the exact Y percentage increase for +1 X unit?","options":["5.13%","5.00%","1.05%"],"correct":0,"why_vi":"100(e^.05−1)=5.1271%.","trap_vi":""},{"stem_en":"In Y=b0+5lnX, what is the approximate Y-unit increase for +1% X?","options":["0.50","0.05","5.00"],"correct":1,"why_vi":"Lin-log ΔY≈5×.01=.05 units.","trap_vi":""},{"stem_en":"In lnY=b0+1.4lnX, how much does Y approximately rise for +1% X?","options":["14.00%","1.40%","0.01%"],"correct":1,"why_vi":"Log-log elasticity 1.4 ⇒ Y rises ≈1.4%.","trap_vi":""},{"stem_en":"In Y=b0+4lnX, X doubles. How many Y units does the fitted value change?","options":["8.000","4.000","2.773"],"correct":2,"why_vi":"ΔY=4 ln 2≈2.77259.","trap_vi":""},{"stem_en":"For log-log slope 2, X rises 10%. What is the exact Y percentage rise?","options":["10.0%","20.0%","21.0%"],"correct":2,"why_vi":"(1.1²−1)×100%=21%.","trap_vi":""},{"stem_en":"In log-log model with b1=−1, X doubles. What is the exact percentage change in Y?","options":["-50.0%","100.0%","-100.0%"],"correct":0,"why_vi":"Y ratio=2^(−1)=.5 ⇒ −50%.","trap_vi":""},{"stem_en":"In lnY=2+0.1X, X=0. Find central fitted Y=exp(lnYhat).","options":["1.105","7.389","2.000"],"correct":1,"why_vi":"e²≈7.389.","trap_vi":""},{"stem_en":"A simple return equals 10%. What is its continuously compounded log return in percent?","options":["9.531%","10.000%","11.000%"],"correct":0,"why_vi":"100ln(1.1)≈9.5310%.","trap_vi":""},{"stem_en":"In Y=2+3lnX, X increases from 1 to e. What is the change in predicted Y?","options":["8.15","3.00","1.10"],"correct":1,"why_vi":"ΔY=3ln(e/1)=3.","trap_vi":""}],"cards":[{"front_en":"Level-level equation and slope?","back_vi":"Y=b0+b1X; b1 Y units per X unit."},{"front_en":"Log-lin form?","back_vi":"lnY=b0+b1X."},{"front_en":"Log-lin slope approximate meaning?","back_vi":"X +1 unit ⇒ Y ≈100b1% change."},{"front_en":"Exact log-lin percentage change?","back_vi":"100(e^(b1ΔX)−1)%."},{"front_en":"Lin-log form?","back_vi":"Y=b0+b1lnX."},{"front_en":"Lin-log slope approximate meaning?","back_vi":"X +1% ⇒ Y changes ~b1/100 Y units."},{"front_en":"Exact lin-log change?","back_vi":"ΔY=b1 ln(Xnew/Xold)."},{"front_en":"Log-log form?","back_vi":"lnY=b0+b1lnX."},{"front_en":"Log-log slope?","back_vi":"Constant elasticity: X +1% ⇒ Y≈b1%."},{"front_en":"Exact log-log finite change?","back_vi":"100[(Xnew/Xold)^b1−1]%."},{"front_en":"When may X be logged?","back_vi":"X must be strictly positive."},{"front_en":"When may Y be logged?","back_vi":"Y must be strictly positive."},{"front_en":"Back-transform log-lin fitted central level?","back_vi":"exp(b0+b1X), not necessarily conditional arithmetic mean."},{"front_en":"Lognormal correction for E(Y|X) (extension)?","back_vi":"exp(μlogY+σ²/2)."},{"front_en":"Can raw R² compare Y vs lnY model?","back_vi":"Không trực tiếp; response scales differ."},{"front_en":"How to identify log-lin vs lin-log from equation?","back_vi":"Which side contains ln: Y only ⇒ log-lin, X only ⇒ lin-log."},{"front_en":"Why transform nonlinear relationships?","back_vi":"Make conditional relation linear on transformed scale; inspect residuals."},{"front_en":"Does log transformation automatically remove autocorrelation?","back_vi":"No."},{"front_en":"Log-log derivative elasticity?","back_vi":"(dY/dX)×(X/Y)=β1."},{"front_en":"What is ln(1+Rsimple)?","back_vi":"Continuously compounded log return for gross return 1+R>0."},{"front_en":"What is a common log-lin exam trap?","back_vi":"Using 100b1% as an exact change when b1 is large."},{"front_en":"What is a common lin-log exam trap?","back_vi":"Reporting b1/100 as percentage Y instead of Y units."}]}]},{"version":"2026.11.22-quant11-original-draft","module_id":"CFA26-01-11","module_title":"Introduction to Big Data Techniques","language":"Vietnamese explanations and original English questions","qa_status":"CFAI_2026_LOS_MAPPED_CONCEPTUAL_DRAFT_PENDING_FULL_ACADEMIC_REVIEW","disclaimer_vi":"Đây là bài giảng tự biên soạn từ nguồn CFAI 2026, Kaplan 2026 và SAPP Quant. Big Data chủ yếu kiểm tra khả năng mô tả và phân biệt thuật ngữ, không có nhiều công thức định lượng bắt buộc; các sơ đồ ghi nhớ đặt trong tab công thức được ghi nhãn conceptual. Chưa nghiệm thu học thuật độc lập toàn bộ.","los":[{"id":"CFA26-01-11-LOS01","letter":"11.a","title_en":"Fintech and Financial Data Collection","outcome_en":"describe aspects of “fintech” that are directly relevant for the gathering and analyzing of financial data","overview_vi":"Các công nghệ fintech dành cho nghiên cứu đầu tư, nguồn dữ liệu truyền thống/alternative từ individuals, business processes và sensors, data latency, sử dụng tín hiệu phù hợp, quyền truy cập và rủi ro look-ahead/privacy.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM11","pages":"335–340 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 11","pages":"132–133 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 11","pages":"454–457 (physical PDF)"}],"sections":[{"heading":"1. Fintech: scope of the term","body":"Fintech là ứng dụng tiến bộ công nghệ trong sản phẩm, dịch vụ và quy trình tài chính: dữ liệu, phân tích, thanh toán, quản lý tài sản, tư vấn, tín dụng, trading, risk controls. Trong Quant LOS 11.a, tập trung công nghệ thu thập và xử lý financial datasets, không phải toàn bộ lịch sử các start-ups fintech.","trap":""},{"heading":"2. From task automation to decision support","body":"Thế hệ công nghệ sớm tự động hóa data processing và tác vụ rule-based (if/then). Công cụ mới kết hợp AI/ML để xử lý quy mô dữ liệu lớn, tìm pattern, hỗ trợ hoặc tự động đưa ra quyết định. Không suy ra mọi hệ thống algorithmic trading đều là machine learning.","trap":""},{"heading":"3. Why data growth matters for investors","body":"Investment analysis dùng tăng trưởng mạnh dữ liệu truyền thống (price, volume, accounting, macro) và alternative data (sensors, web traffic, consumer behavior). Mục tiêu là nhận diện drivers, dự báo earnings, quản trị risk và cải thiện trade execution; thông tin lớn không tự động tạo alpha.","trap":""},{"heading":"4. Infrastructure: capture, storage and processing","body":"Digital feeds, APIs, networks, high-frequency processing, compute infrastructure và storage cho phép kết hợp datasets khác loại trong thời gian ngắn. Nếu input đến quá chậm so với market window, signal có thể hết giá trị trước khi strategy giao dịch.","trap":""},{"heading":"5. Direct relevance to quantitative investment research","body":"Quant researchers dùng batch/stream ingestion để dựng time series, factors, alternative indicators và backtest; data engineering/cleaning quyết định tính chính xác của downstream regression, model training và portfolio optimizers. Dữ liệu lỗi gây “garbage in, garbage out”.","trap":""},{"heading":"6. Growth in analytics capacity","body":"High-performance computing và chi phí lưu trữ giảm hỗ trợ phân tích nonlinear relationships, nhưng model complexity còn kéo theo overfitting, black-box risk và model governance. Không đánh đồng faster compute với higher forecast accuracy.","trap":""},{"heading":"7. Traditional financial market data","body":"Trade/quote, bid–ask, volume, security returns, financial statements, earnings announcements và government macro releases là dữ liệu quan trọng có cấu trúc hơn. Cần timestamp, adjustments (splits/corporate actions), survivorship logic và availability timing.","trap":""},{"heading":"8. Alternative data: generated outside standard reports","body":"Social media, online reviews, search terms, website traffic, geolocation, card transactions, satellite images và device sensors là ví dụ alternative data. Chúng có thể đo hoạt động kinh tế trước dữ liệu truyền thống nhưng liên quan privacy, licensing và sampling bias.","trap":""},{"heading":"9. Data sources: individuals","body":"Individuals có thể tạo social posts, news/reviews, search logs, user-generated location traces. Sentiment có thể phản ánh brand popularity nhưng posts không đồng đều population; sentiment bots và selection effects có thể gây nhiễu.","trap":""},{"heading":"10. Data sources: business processes","body":"Transaction records, e-commerce order flows, invoicing/logistics và corporate operations là “business exhaust” tạo ra trong quá trình hoạt động. Có thể hỗ trợ sales forecasting nhưng người bán dữ liệu phải có quyền phân phối, và coverage sample phải đại diện.","trap":""},{"heading":"11. Data sources: sensors and Internet of Things","body":"Sensors bao gồm satellite imagery, GPS/geolocation và IoT devices trên factories, trucks, smart buildings. Ví dụ shipping activity có thể là leading operational signal; image detection error, cloud cover và alternative interpretations phải được xem xét.","trap":""},{"heading":"12. Market data versus consumer data: timing","body":"High-frequency price updates rất nhạy latency; consumer spending data đôi khi đến theo ngày/tuần nhưng cung cấp trend. Cần phân biệt time observed, time reported và time truly accessible in research to avoid look-ahead bias.","trap":""},{"heading":"13. Text and multimedia capture","body":"NLP/text analytics xử lý filings, earnings calls và analyst notes. Computer vision xử lý satellite images và video. Khối lượng lớn unstructured data cần cleaning, encoding và model phù hợp trước khi đưa vào regressions/trading signals.","trap":""},{"heading":"14. New technologies reshape operating models","body":"Robo-advisory, trading automation, risk monitoring và digital products là ứng dụng fintech rộng; trong chương này, chức năng cốt lõi là cách công nghệ thay đổi financial data gathering/analysis. Không cần nhầm với việc công nghệ thay thế quy định đạo đức nghề nghiệp.","trap":""},{"heading":"15. Low latency versus high latency","body":"Latency là thời gian trễ giữa khi thông tin tạo ra và hệ thống có thể dùng. Lower latency hữu ích cho strategies dựa trên live quotes, nhưng không tất yếu cần cho long-horizon fundamental forecasts. Velocity (tốc độ dòng data) khác latency (độ trễ hệ thống).","trap":""},{"heading":"16. Limits: access, reliability and bias","body":"Một signal chỉ hữu ích nếu legitimate access, dữ liệu đủ sạch, có data coverage phù hợp và timestamp không gây leakage. Dữ liệu mới có thể rất predictive in sample nhưng bị sample-selection bias, availability lag hoặc noise ngoài sample.","trap":""},{"heading":"17. Privacy, legal and ethical boundaries","body":"Scraping/thu thập personal data không tự động hợp pháp khi dữ liệu xuất hiện trên web; cần quyền truy cập, consent, privacy rules và hợp đồng. Nội dung nội bộ/nhạy cảm không nên đăng công khai hoặc trộn vào source của GitHub learning site.","trap":""},{"heading":"18. Exam recognition checklist","body":"Fintech trong CFA Quant = technologies for gathering, accessing, processing và analyzing financial data; identify traditional vs alternative sources, latency, AI-enabled analysis, and advantages/limitations. Nhớ các nhóm individuals/business processes/sensors và không khẳng định alternative = always superior.","trap":""}],"formulas":[{"name":"Fintech scope — conceptual map","expr":"Fintech → data collection + processing + analytical tools + finance applications","meaning":"Sơ đồ khái niệm, không phải công thức định lượng.","conditions":""},{"name":"Alternative data source families","expr":"Individuals / business processes / sensors","meaning":"Ba nhóm nguồn alternative data được CFAI phân loại.","conditions":""},{"name":"Latency concept","expr":"latency = time usable − time event occurred","meaning":"Biểu diễn trực giác của độ trễ, không phải công thức tính bắt buộc của CFAI.","conditions":""},{"name":"Simple research chain","expr":"source → timestamp → cleanse → feature → model → decision","meaning":"Chuỗi tự học, bổ sung để tránh look-ahead bias, không phải nguyên văn source.","conditions":""}],"examples":[{"question_en":"A trading desk requires real-time bid–ask quotes to react within milliseconds. Which fintech feature matters most?","steps_vi":["Giá trị tín hiệu phụ thuộc vào tốc độ từ sự kiện thị trường đến lúc thực hiện lệnh.","Dòng dữ liệu có độ trễ thấp và xử lý nhanh quan trọng hơn báo cáo thường niên tĩnh đối với giao dịch cỡ mili giây."],"answer":"Low-latency data capture and processing.","check":""},{"question_en":"An analyst uses satellite pictures of retail parking lots to estimate foot traffic. Classify the dataset.","steps_vi":["Ảnh vệ tinh được tạo ra bởi hệ thống cảm biến từ xa.","Đây là dữ liệu thay thế (alternative data), có thể dùng làm chỉ báo gián tiếp cho hoạt động bán lẻ; không phải số doanh thu được công bố."],"answer":"Sensor-generated alternative data.","check":""},{"question_en":"A manager analyzes historical annual reports and reported net income. Is the source traditional or alternative?","steps_vi":["Báo cáo tài chính và hồ sơ công bố theo quy định thuộc nguồn dữ liệu doanh nghiệp truyền thống."],"answer":"Traditional financial/company data.","check":""},{"question_en":"A broker processes customer trades automatically using preset if–then rules. Does this alone establish machine learning?","steps_vi":["Tự động thực thi quy tắc if–then có thể chỉ là lập trình truyền thống.","Machine learning cần học mẫu quan hệ từ dữ liệu huấn luyện; không phải mọi thuật toán tự động đều là ML."],"answer":"No; it can be rule-based fintech.","check":""},{"question_en":"A provider sells anonymized credit-card transaction aggregates with different merchant coverage each year. What is a key risk?","steps_vi":["Phạm vi bao phủ thay đổi có thể tạo ra xu hướng giả, không phản ánh doanh thu thật của toàn ngành."],"answer":"Selection/coverage bias and data quality risk.","check":""},{"question_en":"The same investor reviews buy-side earnings reports and social media sentiment. Which is more likely unstructured alternative data?","steps_vi":["Báo cáo doanh nghiệp là nguồn công bố truyền thống; bài đăng mạng xã hội là văn bản do người dùng tạo, thường được xếp vào dữ liệu thay thế phi cấu trúc."],"answer":"Social media text.","check":""},{"question_en":"A logistics company shares vehicle GPS movement records. Which alternative-data family best fits?","steps_vi":["Thông tin vị trí GPS đến từ các cảm biến và hệ thống theo dõi chuyển động."],"answer":"Sensor / geolocation data.","check":""},{"question_en":"A strategy uses data released after the portfolio rebalancing date in its historical backtest. What is the research error?","steps_vi":["Backtest đã sử dụng thông tin chưa xuất hiện vào ngày tái cân bằng; đây là look-ahead bias."],"answer":"Look-ahead bias.","check":""},{"question_en":"A long-term valuation analyst receives monthly consumer spending summaries after 48 hours. Is millisecond latency essential?","steps_vi":["Quyết định đầu tư dài hạn thường ít nhạy với độ trễ tính bằng mili giây hơn giao dịch tần suất cao."],"answer":"Not necessarily.","check":""},{"question_en":"A website exposes user location data without consent. May an analyst freely monetize it for investments?","steps_vi":["Truy cập được dữ liệu trên mạng không đồng nghĩa có quyền khai thác không giới hạn.","Cần xem xét quyền riêng tư, sự đồng ý, giấy phép, quy định địa phương và các yêu cầu đạo đức CFA."],"answer":"No; rights and compliance must be verified.","check":""},{"question_en":"An equity analyst expects alternative data to guarantee excess returns. Evaluate the claim.","steps_vi":["Tín hiệu từ dữ liệu thay thế có thể nhiễu, thiên lệch, bị nhiều nhà đầu tư khai thác hoặc đã phản ánh vào giá.","Việc sở hữu dữ liệu không tự động chứng minh khả năng dự báo hay tạo lợi nhuận vượt trội."],"answer":"The claim is not justified.","check":""},{"question_en":"A team uses text analytics of earnings calls to detect management tone changes. Which technology is the likely tool?","steps_vi":["Ngôn ngữ phi cấu trúc trong earnings calls có thể được xử lý bằng natural language processing (NLP) và phân tích văn bản."],"answer":"Natural language processing.","check":""}],"questions":[{"stem_en":"In the context of CFA quantitative investment analysis, fintech primarily refers to:","options":["Technology-driven innovation in finance","Only cryptocurrency exchanges","Exclusively bank branches"],"correct":0,"why_vi":"Fintech bao trùm innovations về technology trong finance.","trap_vi":""},{"stem_en":"A satellite-derived shipping signal is an example of:","options":["A traditional regulatory filing","Sensor-based alternative data","A guaranteed stock-price forecast"],"correct":1,"why_vi":"Satellite imagery thuộc nhóm sensor-generated alternative data.","trap_vi":""},{"stem_en":"Which is most likely traditional financial data?","options":["Social media sentiment","Geolocation traces","Audited corporate financial statements"],"correct":2,"why_vi":"Financial statements là truyền thống.","trap_vi":""},{"stem_en":"Preset trading rules without model training are best described as:","options":["Rule-based automation","Proof of deep learning","Unsupervised clustering"],"correct":0,"why_vi":"Automated rules không tất yếu sử dụng ML.","trap_vi":""},{"stem_en":"Which alternative-data source belongs to the business-process category?","options":["Satellite images","Point-of-sale transaction records","Online personal reviews"],"correct":1,"why_vi":"Business-process exhaust bao gồm transaction records.","trap_vi":""},{"stem_en":"Which alternative-data source is generated by individuals?","options":["Smart building sensors","Satellite radar","Online product reviews"],"correct":2,"why_vi":"User-generated reviews thuộc individuals.","trap_vi":""},{"stem_en":"The key distinction between data velocity and system latency is:","options":["Velocity is data flow speed; latency is delay before data can be used.","Both measure data reliability.","Latency is the count of data columns."],"correct":0,"why_vi":"Velocity khác latency.","trap_vi":""},{"stem_en":"Which type of strategy most demands low latency?","options":["Annual fundamental model refresh","High-frequency execution using real-time prices","Long-term dividend forecast from yearly filings"],"correct":1,"why_vi":"HFT cần fast feed/execution.","trap_vi":""},{"stem_en":"Using data in a backtest before it was publicly available creates:","options":["Reduced overfitting","Automatic arbitrage","Look-ahead bias"],"correct":2,"why_vi":"Sai timing làm backtest quá lạc quan.","trap_vi":""},{"stem_en":"Which statement about alternative data is most accurate?","options":["It can supplement, but does not guarantee, superior investment forecasts.","It is always structured into relational tables.","It is always legally usable when found online."],"correct":0,"why_vi":"Data mới có thể thêm signal nhưng nhiều limitations.","trap_vi":""},{"stem_en":"Internet-of-Things data are most closely associated with:","options":["Government GDP revisions only","Networked sensor-equipped devices","Historical paper filing scans only"],"correct":1,"why_vi":"IoT là devices kết nối và thu thập/share information.","trap_vi":""},{"stem_en":"The quality challenge most directly related to changing merchant coverage is:","options":["Guaranteed normality","Perfect data independence","Selection/coverage bias"],"correct":2,"why_vi":"Coverage thay đổi có thể tạo spurious variation.","trap_vi":""},{"stem_en":"A data stream is delayed by 5 seconds. This delay is most directly described as:","options":["Latency","Volume","Variety"],"correct":0,"why_vi":"Latency là lag tới lúc usable.","trap_vi":""},{"stem_en":"Why might data curation matter before regression modeling?","options":["It replaces all hypotheses.","Dirty or missing data can distort estimated relationships.","It proves causal identification."],"correct":1,"why_vi":"Dữ liệu lỗi làm coefficients unreliable.","trap_vi":""},{"stem_en":"Which is an appropriate concern about scraped location data?","options":["It must always be publicly distributable.","It cannot be used in any finance context.","Privacy and licensing rights require verification."],"correct":2,"why_vi":"Publicly visible không đồng nghĩa được phép monetize.","trap_vi":""},{"stem_en":"A text-based earnings-call feature is best viewed as:","options":["A transformed input for investment analysis","A direct guaranteed profit","A risk-free asset"],"correct":0,"why_vi":"NLP tạo features, không bảo đảm alpha.","trap_vi":""},{"stem_en":"Which development has expanded the scale of fintech investment analytics?","options":["Higher data storage cost","Advances in computing and data availability","Eliminating the need for any judgment"],"correct":1,"why_vi":"Compute và data giúp xử lý models lớn hơn.","trap_vi":""},{"stem_en":"What is a major limitation of alternative consumer sentiment data?","options":["Always no timestamps","Always unbiased sampling","Potential self-selection and bot-driven distortion"],"correct":2,"why_vi":"Representation/noise có thể bias result.","trap_vi":""},{"stem_en":"A manager asks for a systematic low-latency feed. The key requirement is:","options":["Minimal delay from event to usable data","High historical R-squared regardless of release timing","Only manual annual reporting"],"correct":0,"why_vi":"Low latency focuses time delay.","trap_vi":""},{"stem_en":"Which statement best reflects the purpose of fintech within quant investing?","options":["Only replacing humans with software","Improving collection, processing and analysis of financial information","Eliminating statistical inference"],"correct":1,"why_vi":"Technology hỗ trợ workflow, không thay thế analysis.","trap_vi":""},{"stem_en":"A vendor measures real-time truck movements. Which group is the data source?","options":["Individuals / web reviews","Corporate annual reports","Sensors / geolocation"],"correct":2,"why_vi":"GPS sensor generated data.","trap_vi":""},{"stem_en":"If data are collected but not legally licensed for reuse, the analyst should:","options":["Resolve access/compliance rights before use","Assume all public data have unlimited reuse rights","Skip privacy evaluation for quantitative research"],"correct":0,"why_vi":"Cần licensing và ethical compliance.","trap_vi":""}],"cards":[{"front_en":"What does fintech mean in CFA Quant?","back_vi":"Technology-driven innovation in financial services and investment analytics."},{"front_en":"Rule-based automation vs ML?","back_vi":"Rule-based predefined rules; ML learns patterns from data."},{"front_en":"Traditional data examples?","back_vi":"Prices, volumes, financial statements, government releases."},{"front_en":"Alternative data examples?","back_vi":"Social posts, card transactions, satellites, sensors, search logs."},{"front_en":"Alternative data source families?","back_vi":"Individuals, business processes, sensors."},{"front_en":"What is the Internet of Things?","back_vi":"Networked devices and sensors that exchange data."},{"front_en":"What is data latency?","back_vi":"Delay before data can be used after generation."},{"front_en":"Which fintech workflows are latency-sensitive?","back_vi":"Real-time electronic / high-frequency trading."},{"front_en":"What is look-ahead bias?","back_vi":"Using information not available at research decision time."},{"front_en":"What is business exhaust data?","back_vi":"Operational transaction/activity records generated during business processes."},{"front_en":"Can alternative data guarantee alpha?","back_vi":"No; quality, access, timing and crowding matter."},{"front_en":"What is a sensor-data example?","back_vi":"Satellite images or GPS-derived movements."},{"front_en":"What is an individual-data example?","back_vi":"Social media review or web search traces."},{"front_en":"What is the privacy risk of scraped data?","back_vi":"Personal information can require consent and legal rights."},{"front_en":"Why does data curation matter?","back_vi":"Detect missing/error/outlier/selection issues before modeling."},{"front_en":"What tool analyzes language-heavy unstructured data?","back_vi":"NLP/text analytics."},{"front_en":"Which is traditional corporate information?","back_vi":"Published earnings and financial reports."},{"front_en":"Does faster computing ensure model accuracy?","back_vi":"No; biased or noisy data and overfitting remain."},{"front_en":"What is an ethical research first step?","back_vi":"Confirm lawful data access, permitted use and confidentiality."}]},{"id":"CFA26-01-11-LOS02","letter":"11.b","title_en":"Big Data, Artificial Intelligence and Machine Learning","outcome_en":"describe Big Data, artificial intelligence, and machine learning","overview_vi":"Big Data 3Vs + veracity; structured/semistructured/unstructured datasets; AI vs ML, supervised/unsupervised/deep learning, train/validate/test, overfitting/underfitting, black-box and data leakage risk.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM11","pages":"335–343 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 11","pages":"132–135 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 11","pages":"458–466 (physical PDF)"}],"sections":[{"heading":"1. Big Data is not merely a large spreadsheet","body":"Big Data mô tả datasets quy mô, tốc độ tạo, định dạng và sự phức tạp vượt khả năng thao tác truyền thống dễ dàng. Three Vs—volume, velocity, variety—là khung cốt lõi; veracity đôi khi được thêm khi dùng để suy luận hoặc dự báo.","trap":""},{"heading":"2. Volume","body":"Volume = số lượng records, kích cỡ data và số chiều lớn: hàng triệu trades, hàng tỷ device events, ảnh và transcripts. Volume lớn đặt nhu cầu storage, distributed processing, computing; lớn không đồng nghĩa informative hoặc đại diện.","trap":""},{"heading":"3. Velocity","body":"Velocity = tốc độ data được tạo, nhận, xử lý, có thể real-time hoặc near-real-time. Với finance, speed matter ở trading/market monitoring; feed nhanh không tự biến high-latency downstream models thành real-time systems.","trap":""},{"heading":"4. Variety and structure","body":"Variety = đa dạng sources và formats: structured tables, semi-structured HTML/JSON, unstructured text/audio/video/images. Analysts phải chọn database/parsers và feature extraction trước khi dùng same model.","trap":""},{"heading":"5. Fourth V: veracity","body":"Veracity = độ tin cậy, credibility, accuracy của sources: missing values, fake posts, bias, timestamp mismatch và inconsistent definitions. Big volumes có thể khuếch đại sai số hệ thống, nên veracity là điều kiện thiết yếu cho inference.","trap":""},{"heading":"6. Structured, semistructured and unstructured","body":"Structured rows/columns dễ query; semistructured có tags/keys nhưng không luôn bảng cố định; unstructured text/voice/images đòi specialized processing. Ví dụ SQL table vs HTML record vs earnings-call audio.","trap":""},{"heading":"7. Artificial intelligence is broader than ML","body":"AI = systems thực hiện tasks cần human-like intelligence; có thể là rule-based expert system hoặc learning systems. ML là tập con AI learning patterns từ examples. Không suy ra mọi AI đều dùng neural networks.","trap":""},{"heading":"8. Machine learning definition","body":"ML xây mô hình nhận dạng relationships trong data hoặc tạo dự báo mà không hard-code từng rule decision. Nó học từ input features và có thể labels; vẫn cần human judgment về cleaning, modeling và economic validity.","trap":""},{"heading":"9. Inputs, outputs, labels","body":"Input features X có thể prices, earnings, text sentiment; labeled output Y là target như next-day direction/forecasted return. Supervised learning học mapping từ X và known Y; unsupervised tìm structure khi không có target labels.","trap":""},{"heading":"10. Three-way data split","body":"Train set ước lượng model parameters; validation set chọn hyperparameters/model complexity; test set giữ ngoài training/tuning để đánh giá generalization. Nếu liên tục tune theo test, test không còn unseen. Với finance time series, tránh random split gây future information leakage.","trap":""},{"heading":"11. Supervised learning","body":"Dùng examples có correct outputs để classification hoặc regression: credit risk labels, forecast return, direction up/down. Decision trees, linear regression, neural models có thể là supervised khi training labels provided.","trap":""},{"heading":"12. Unsupervised learning","body":"Không có correct target labels; tìm clusters, hidden factors, anomaly structure. Ví dụ grouping stocks by observed balance-sheet characteristics thay vì sector labels được chỉ định từ trước. Cluster membership không phải dự báo return chắc chắn.","trap":""},{"heading":"13. Deep learning and neural networks","body":"Deep learning dùng nhiều layers của neural networks, progressive nonlinear representations, ứng dụng image, speech, text. Có thể dùng supervised hoặc unsupervised; do đó nó không phải một nhóm hoàn toàn mutually exclusive với hai nhóm còn lại.","trap":""},{"heading":"14. Overfitting: memorizing training noise","body":"Model quá phức tạp học data noise; training error thấp nhưng out-of-sample/test error tăng. Trong trading backtests có data snooping. Cần holdout/regularization/robust validation, không chọn model chỉ bằng backtest in-sample tốt.","trap":""},{"heading":"15. Underfitting: model cannot capture signal","body":"Model quá đơn giản bỏ sót relationship, thường training error và validation error đều cao. Không chữa underfitting bằng giảm complexity; cần richer features/model hoặc data treatment.","trap":""},{"heading":"16. Black-box and explainability","body":"Model ML complex có thể opaque, khó giải thích predictor importance, fairness, model failures hoặc feedback loop. Need governance and model monitoring dù backtest score cao. Explainability issues can be critical for portfolio constraints and client communications.","trap":""},{"heading":"17. Data bias and prediction leakage","body":"Selection bias, missing observations, survivorship bias, duplicate entities và feature values calculated after target event gây kết quả sai. Các lỗi này có thể vượt qua model sophistication; kỹ năng đọc data source và timestamp đặc biệt quan trọng.","trap":""},{"heading":"18. Training set versus test set performance","body":"If train accuracy 98% but test accuracy 55% for binary target near balanced base rate, potential overfitting or regime shift. Test performance is closer to model generalization, yet still depends on test sample design.","trap":""},{"heading":"19. More data does not automatically solve bias","body":"Nếu observations systematically exclude failed firms hoặc internet users, tăng n vẫn không bảo đảm unbiased estimator. Volume lớn giảm random noise trong một số trường hợp nhưng không chữa sample-selection bias.","trap":""},{"heading":"20. Exam technique for AI/ML terminology","body":"Big Data 3 Vs + veracity; AI broad, ML subset; supervised labeled, unsupervised unlabeled; deep neural layered (can be either); train/validation/test; overfit vs underfit. Nhấn mạnh generalization over memorizing patterns.","trap":""}],"formulas":[{"name":"Big Data three-V framework","expr":"Volume + Velocity + Variety","meaning":"Mnemonic framework, not a mathematical equation.","conditions":""},{"name":"Data reliability extension","expr":"Veracity = credibility + data quality + suitability","meaning":"Conceptual extension for inference and prediction.","conditions":""},{"name":"Learning taxonomy","expr":"AI ⊃ ML; deep learning uses multilayer neural networks","meaning":"Concept taxonomy; deep learning can be supervised or unsupervised.","conditions":""},{"name":"Model development workflow","expr":"Train → validate/tune → test on holdout","meaning":"Source-aligned process; avoid reusing test set for tuning.","conditions":""},{"name":"Generalization gap (supplementary)","expr":"gap = test error − training error","meaning":"Illustrative diagnostic, not a required CFAI calculation.","conditions":""}],"examples":[{"question_en":"A fund uses 400 million transaction records daily. Which Big Data characteristic is most prominent?","steps_vi":["Số lượng bản ghi và dung lượng dữ liệu lớn phản ánh chiều volume."],"answer":"Volume.","check":""},{"question_en":"A price stream publishes updates in milliseconds. Which characteristic is most relevant?","steps_vi":["Tốc độ tạo, truyền đến và xử lý dữ liệu phản ánh chiều velocity."],"answer":"Velocity.","check":""},{"question_en":"An analyst combines SQL tables, HTML pages, video footage and phone audio. Which characteristic is most prominent?","steps_vi":["Nhiều định dạng và mức độ cấu trúc khác nhau thể hiện variety."],"answer":"Variety.","check":""},{"question_en":"A data vendor has many records but duplicate and falsified entries. What characteristic is weak?","steps_vi":["Độ chính xác và mức độ đáng tin cậy của dữ liệu liên quan đến veracity."],"answer":"Veracity.","check":""},{"question_en":"A model predicts realized next-day return using historical labeled return outcomes. Is it supervised?","steps_vi":["Dữ liệu huấn luyện ghép các đặc trưng đầu vào với kết quả đã biết (labels/targets), vì vậy thuộc supervised learning."],"answer":"Supervised learning.","check":""},{"question_en":"An algorithm partitions firms into peer groups from balance-sheet patterns without target labels. Is it supervised?","steps_vi":["Không có biến mục tiêu đã gắn nhãn; thuật toán phát hiện các cụm tương đồng trong dữ liệu."],"answer":"Unsupervised learning.","check":""},{"question_en":"A multilayer neural network is trained on labeled satellite imagery to identify factory activity. Which descriptions apply?","steps_vi":["Kiến trúc gồm nhiều tầng biến đổi nên là deep learning.","Vì mô hình học trên ảnh có nhãn, đây đồng thời là supervised learning."],"answer":"Supervised deep learning.","check":""},{"question_en":"Training classification accuracy is 99% but unseen test accuracy is 52%. What is a likely concern?","steps_vi":["Khoảng cách lớn giữa hiệu suất tập huấn luyện và tập kiểm tra cho thấy mô hình có thể overfit hoặc chịu distribution shift."],"answer":"Overfitting / weak generalization.","check":""},{"question_en":"Training and test accuracy are both 50% for a balanced directional target. What might be the issue?","steps_vi":["Mô hình không khai thác được tín hiệu hữu ích; có thể underfitting, nhưng cũng có thể dữ liệu thực sự không có tín hiệu dự báo."],"answer":"Potential underfitting or uninformative features.","check":""},{"question_en":"A model is repeatedly tuned until test-set performance is optimal. Is the test still unbiased holdout?","steps_vi":["Việc lặp lại điều chỉnh theo kết quả tập test đã biến test thành dữ liệu dùng để phát triển mô hình, gây test leakage và selection bias."],"answer":"No; test leakage / selection bias.","check":""},{"question_en":"An equity model uses financial ratios updated 10 days after period-end but dates them at period-end in backtests. Identify the problem.","steps_vi":["Mô hình đã sử dụng dữ liệu chưa thể biết tại ngày ra quyết định, gây look-ahead data leakage."],"answer":"Look-ahead data leakage.","check":""},{"question_en":"A model groups stocks by sector labels already supplied. Is that unsupervised clustering?","steps_vi":["Nhãn ngành đã được cung cấp từ trước.","Việc đơn thuần phân loại theo các nhãn có sẵn không phải là phát hiện cụm từ dữ liệu chưa gắn nhãn."],"answer":"No; not necessarily unsupervised learning.","check":""},{"question_en":"What do many hidden neural-network layers enable?","steps_vi":["Nhiều hidden layers học các biểu diễn qua các phép biến đổi phi tuyến liên tiếp; đó là đặc điểm của deep learning."],"answer":"Deep learning.","check":""},{"question_en":"An AI investment model cannot explain why a security receives a strong positive score. Which issue is most relevant?","steps_vi":["Quyết định khó diễn giải làm tăng rủi ro black-box và gây trở ngại cho việc đánh giá, giám sát mô hình."],"answer":"Black-box / explainability risk.","check":""},{"question_en":"An analyst expects an ML algorithm to correct inaccurate labels automatically. Assess this assumption.","steps_vi":["Chất lượng mục tiêu huấn luyện ảnh hưởng trực tiếp đến những gì mô hình học.","Vẫn phải làm sạch và kiểm định dữ liệu; nhãn sai có thể khiến mô hình học sai quy luật."],"answer":"Not justified.","check":""}],"questions":[{"stem_en":"The three core Vs of Big Data are:","options":["Volume, Velocity, Variety","Variance, VaR, Value","Volume, Volatility, Valuation"],"correct":0,"why_vi":"Three Vs là volume/velocity/variety.","trap_vi":""},{"stem_en":"When Big Data are used for inference, veracity primarily refers to:","options":["Rate of data arrival","Credibility and accuracy of the data","Number of columns in a table"],"correct":1,"why_vi":"Veracity là reliability và quality.","trap_vi":""},{"stem_en":"A large number of observations is most closely associated with:","options":["Velocity","Variety","Volume"],"correct":2,"why_vi":"Volume measures amount of data.","trap_vi":""},{"stem_en":"Data arriving every millisecond is best described by:","options":["Velocity","Veracity","Variety"],"correct":0,"why_vi":"Velocity measures speed of generation/arrival.","trap_vi":""},{"stem_en":"Audio files combined with transaction tables primarily illustrate:","options":["High-latency data only","Variety","High accuracy"],"correct":1,"why_vi":"Different formats => variety.","trap_vi":""},{"stem_en":"Which is most likely structured data?","options":["A free-form video","An untranscribed conference call","A database table with fixed columns"],"correct":2,"why_vi":"Structured rows/columns are table data.","trap_vi":""},{"stem_en":"An HTML page with tags and data fields is usually:","options":["Semistructured","Strictly unstructured","A normal distribution"],"correct":0,"why_vi":"HTML tags define structure but not rigid relational schema.","trap_vi":""},{"stem_en":"AI is best described relative to ML as:","options":["A strict subset of supervised learning","A broader concept that includes ML","Identical to deep learning"],"correct":1,"why_vi":"AI broader than ML.","trap_vi":""},{"stem_en":"Which description best fits supervised learning?","options":["Clustering unlabeled observations","Only storing data","Learning with labeled input/output examples"],"correct":2,"why_vi":"Labels identify outcomes.","trap_vi":""},{"stem_en":"Which task is most naturally unsupervised?","options":["Group firms into clusters based on unlabeled financial features","Forecast known next-quarter EPS from labeled samples","Predict bond default flags using historical labels"],"correct":0,"why_vi":"Clustering without targets ⇒ unsupervised.","trap_vi":""},{"stem_en":"Deep learning most typically employs:","options":["Only linear OLS equations","Multi-layer neural networks","A database query without a model"],"correct":1,"why_vi":"Deep learning is layered nonlinear neural network method.","trap_vi":""},{"stem_en":"Can deep learning be supervised or unsupervised?","options":["No, only unsupervised","No, only supervised","Yes"],"correct":2,"why_vi":"CFAI explicitly allows both learning settings.","trap_vi":""},{"stem_en":"Which dataset is typically used to tune ML hyperparameters?","options":["Validation dataset","Test dataset exclusively","All future observations"],"correct":0,"why_vi":"Validation helps model tuning; test reserved.","trap_vi":""},{"stem_en":"Which dataset should estimate final generalization after tuning?","options":["Training set","Independent test set","Validation set used repeatedly to tune all results"],"correct":1,"why_vi":"Holdout test used after training/validation.","trap_vi":""},{"stem_en":"Train accuracy 98% and test accuracy 54% are most consistent with:","options":["Guaranteed skill","Perfect generalization","Possible overfitting"],"correct":2,"why_vi":"Large gap indicates out-of-sample degradation.","trap_vi":""},{"stem_en":"A model too simple to capture relationships is:","options":["Underfitted","Overfitted","Fully identified"],"correct":0,"why_vi":"Underfitting treats true patterns as noise.","trap_vi":""},{"stem_en":"A model that memorizes irrelevant training noise is:","options":["Unsupervised by definition","Overfitted","Guaranteed to forecast accurately"],"correct":1,"why_vi":"Overfitted captures noise and fails on new data.","trap_vi":""},{"stem_en":"Which issue is most related to a black-box model?","options":["Low data volume","Excessively high trading fees only","Opaque decisions that are hard to explain"],"correct":2,"why_vi":"Explainability/model governance.","trap_vi":""},{"stem_en":"Which data practice risks look-ahead bias?","options":["Using future outcomes as training features dated earlier","Strictly holdout future test windows","Recording actual data availability timestamps"],"correct":0,"why_vi":"Feature leakage uses unavailable data.","trap_vi":""},{"stem_en":"A 3-year historical dataset excludes all firms that later defaulted. What is the concern?","options":["Improved randomness","Survivorship bias","Perfect feature engineering"],"correct":1,"why_vi":"Excluded failures distort sample.","trap_vi":""},{"stem_en":"Which statement about large datasets is correct?","options":["Large n always removes selection bias.","Volume eliminates overfitting.","Large n does not necessarily fix biased collection."],"correct":2,"why_vi":"Systematic bias can persist with more data.","trap_vi":""},{"stem_en":"Machine learning generally aims to:","options":["Learn patterns to generalize beyond known examples","Manually encode all possible observations","Make all error terms normally distributed"],"correct":0,"why_vi":"ML finds patterns and applies to unseen data.","trap_vi":""},{"stem_en":"Why does human judgment still matter in ML?","options":["Models need no data understanding.","Data quality, objective design and interpretation require judgment.","Human analysts only enter database passwords."],"correct":1,"why_vi":"Input/labels/selection and economics require human checks.","trap_vi":""},{"stem_en":"A company wants to detect topic clusters in unlabeled text. The most likely approach is:","options":["Supervised return regression","Simple arithmetic mean only","Unsupervised learning"],"correct":2,"why_vi":"Clustering topics without given labels.","trap_vi":""}],"cards":[{"front_en":"What are Big Data 3Vs?","back_vi":"Volume, velocity and variety."},{"front_en":"What is the fourth V often considered in prediction?","back_vi":"Veracity — reliability/credibility."},{"front_en":"Volume vs velocity?","back_vi":"Amount of data vs speed of data generation/flow."},{"front_en":"Structured data example?","back_vi":"Fixed-column SQL table."},{"front_en":"Semistructured data example?","back_vi":"HTML or JSON with tags/keys."},{"front_en":"Unstructured data example?","back_vi":"Audio, video, plain text or images."},{"front_en":"Relation between AI and ML?","back_vi":"ML is a subset of AI."},{"front_en":"Supervised learning requires what?","back_vi":"Labeled input/output training examples."},{"front_en":"Unsupervised learning requires what?","back_vi":"Unlabeled inputs; discovers groups/structures."},{"front_en":"Deep learning uses what architecture?","back_vi":"Neural networks with many layers."},{"front_en":"Can deep learning use supervised learning?","back_vi":"Yes; also unsupervised forms."},{"front_en":"Training dataset role?","back_vi":"Fit patterns/parameters."},{"front_en":"Validation dataset role?","back_vi":"Tune model selection/hyperparameters."},{"front_en":"Test dataset role?","back_vi":"Evaluate unseen-data generalization."},{"front_en":"What is overfitting?","back_vi":"Model learns sample noise too precisely and generalizes poorly."},{"front_en":"What is underfitting?","back_vi":"Model too simplistic to capture genuine patterns."},{"front_en":"What is model black-box risk?","back_vi":"Complex decisions difficult to explain or audit."},{"front_en":"What is data leakage?","back_vi":"Information from future/target contaminates features or tuning."},{"front_en":"What is survivorship bias?","back_vi":"Training data exclude failed/disappeared entities."},{"front_en":"Does larger volume guarantee unbiased data?","back_vi":"No; sampling bias can persist."},{"front_en":"Which split should not be retuned on repeatedly?","back_vi":"Held-out test dataset."}]},{"id":"CFA26-01-11-LOS03","letter":"11.c","title_en":"Investment Applications of Data Science and Big Data","outcome_en":"describe applications of Big Data and Data Science to investment management","overview_vi":"Data processing stages (capture, curation, storage, search, transfer); visualization, tag clouds/mind maps, text analytics/NLP, image analytics, trading/risk/compliance; Python/R/Java/C++/VBA và SQL/SQLite/NoSQL.","source":[{"id":"CFA Institute Curriculum 2026 — Quantitative Methods, LM11","pages":"343–346 (physical PDF)"},{"id":"Kaplan SchweserNotes 2026 Book1 — Reading 11","pages":"134–136 (physical PDF)"},{"id":"SAPP Quant Slide Notes 2026 — Module 11","pages":"467–468 (physical PDF)"}],"sections":[{"heading":"1. What data science adds to investment management","body":"Data science kết hợp statistics, computer science, programming và domain knowledge để biến raw datasets thành actionable research insights. Investment use cases gồm forecasting returns/earnings, portfolio risk, trade execution, fraud/compliance và sentiment analysis.","trap":""},{"heading":"2. End-to-end data workflow","body":"Đầu vào data capture → curation → storage → search → transfer vào analytics; kết quả model training, diagnostics, interpretation và visualization. Một bottleneck trong ingest hoặc cleaning có thể khiến entire model unreliable, dù downstream machine learning sophistication cao.","trap":""},{"heading":"3. Capture","body":"Capture là thu thập dữ liệu và định dạng lại cho analysis; ví dụ price feed, API, satellite capture, OCR/transcripts. Low-latency capture cần thiết cho event trading; chọn batch capture khi timing không cần real-time.","trap":""},{"heading":"4. Curation","body":"Data curation bao gồm cleaning errors, missing values, duplicates, inconsistent identifiers, timestamps và suspicious outliers. Không thể tự động gán missing=0 trong mọi financial dataset; cần kiểm tra nghĩa business.","trap":""},{"heading":"5. Storage","body":"Storage là cách data được lưu, archive, truy cập với thiết kế database phù hợp. Structured relational data và unstructured video/transcripts có requirements khác; access controls, update frequencies và source lineage quan trọng cho audit.","trap":""},{"heading":"6. Search and query","body":"Search là truy xuất data thích hợp nhanh từ kho lớn; có thể dùng SQL cho bảng, search index/NLP cho text. Truy xuất nhầm timestamp hay identifier có thể tạo false correlation giữa company stock và third-party signal.","trap":""},{"heading":"7. Transfer","body":"Transfer là chuyển data từ nguồn/kho tới analytical engine hoặc execution system qua feeds, APIs và file pipelines. Data loss, delayed transmission và duplicate batch updates phải được quản lý để tránh stale models.","trap":""},{"heading":"8. Data visualization","body":"Charts, heat maps, tree/network graphics, tag clouds và interactive displays giúp quan sát distributions, missingness, clusters và relationships. Không lấy attractive visualization làm substitute for statistical evidence; axis choices có thể gây hiểu lầm.","trap":""},{"heading":"9. Tag clouds versus mind maps","body":"Tag cloud thay đổi font size theo frequency của words trong text; mind map biểu diễn link/relationships giữa concepts. Đây là hai visual khác mục đích: tần suất và quan hệ ý tưởng.","trap":""},{"heading":"10. Text analytics","body":"Text analytics trích thông tin từ unstructured written/oral content: filings, research, transcripts, news, social posts. Lexical analysis, frequency, pattern matching và automated information retrieval có thể tạo model features, nhưng negation/sarcasm/domain meaning gây khó.","trap":""},{"heading":"11. Natural language processing (NLP)","body":"NLP liên kết computer science, AI và linguistics để xử lý ngôn ngữ tự nhiên. Trong finance: sentiment analysis, topic extraction, translation, speech-to-text, name/entity recognition và regulatory monitoring of communications.","trap":""},{"heading":"12. Sentiment scores and investment forecasts","body":"Một analyst giữ recommendation Buy nhưng dùng từ ngữ thận trọng hơn; NLP có thể phát hiện sentiment decline trước rating change. Để trở thành tradeable signal, cần kiểm soát timing, neutral language context và khả năng dự báo out-of-sample.","trap":""},{"heading":"13. Satellite and image analytics","body":"Computer vision đọc satellite imagery of parking lots, ships, manufacturing sites, crops; estimates business activity. Data availability/cloud/lighting/seasonality có thể làm proxies nhiễu, và observed activity không đồng nghĩa reported profit.","trap":""},{"heading":"14. Risk and compliance applications","body":"Monitor credit/fraud signals, aggregate exposures, detect suspicious communications or outlier trades, review financial reports. Dữ liệu nhạy cảm phải có quyền dùng phù hợp; high recall vs false alarms là trade-off application-specific (ngoài trọng tâm tính toán LOS).","trap":""},{"heading":"15. Portfolio and trading applications","body":"Data science hỗ trợ factor discovery, portfolio allocation/risk estimation, transaction cost estimation và algorithmic order execution. Hiệu quả thực tế phụ thuộc net costs, turnover, constraints và robust validation, không chỉ machine-learning accuracy.","trap":""},{"heading":"16. Common programming tools: Python and R","body":"Python thích hợp data engineering, numerical computing, ML; R mạnh về statistical analysis and modeling. Đây là công cụ phục vụ analytics, không phải cách chứng minh phương pháp sẽ có predictive performance.","trap":""},{"heading":"17. Other programming tools: Java, C/C++, Excel VBA","body":"Java hỗ trợ ứng dụng platforms; C/C++ thuận tiện optimize latency/speed trong trading/compute-intensive code; Excel VBA làm automation spreadsheet tasks. Công cụ có trade-off về development cost, speed và integration.","trap":""},{"heading":"18. SQL vs SQLite vs NoSQL","body":"SQL query language và relational databases dùng structured rows/columns; SQLite là embedded relational engine không cần server riêng; NoSQL là broad family linh hoạt cho structured/unstructured-like documents (source CFAI nhấn unstructured use). Không tự động coi NoSQL luôn “không có schema” hoặc nhanh hơn SQL trong mọi workload.","trap":""},{"heading":"19. Ethical and operational governance","body":"Data licensing, intellectual property, privacy, cybersecurity, reproducibility và model explainability ảnh hưởng investment data use. Khi dùng vendor data phải phân biệt rights for personal research, redistribution và public GitHub publishing.","trap":""},{"heading":"20. CFA exam application checklist","body":"Match each business task to capture/curation/storage/search/transfer; identify visualization tools; classify text analytics vs NLP; match satellite to images, compliance to monitoring; recognize Python/R/C++/VBA and SQL/SQLite/NoSQL use cases.","trap":""}],"formulas":[{"name":"Data management stages — conceptual","expr":"Capture → Curation → Storage → Search → Transfer","meaning":"Source-derived data science process, not a calculation formula.","conditions":""},{"name":"Visual tool distinction","expr":"Tag cloud → word frequency; mind map → concept relationships","meaning":"Concept map for deciding visual type.","conditions":""},{"name":"Analytics input-to-decision pipeline","expr":"data → features → model → validation → interpretation → decision","meaning":"Pedagogical synthesis; extension beyond a prescribed exam equation.","conditions":""},{"name":"Technology roles","expr":"SQL/SQLite → relational tables; NoSQL → flexible data stores","meaning":"Conceptual association; no single tool is optimal for all data.","conditions":""}],"examples":[{"question_en":"A quantitative team collects prices from three exchanges and standardizes timestamps and currencies. Which stages are involved?","steps_vi":["Đầu tiên thu nhận dữ liệu từ các sàn giao dịch (capture); sau đó chuẩn hóa múi giờ, thời điểm ghi nhận và đơn vị tiền tệ (curation)."],"answer":"Capture and curation.","check":""},{"question_en":"A vendor database has duplicate customer records that inflate transaction counts. What should the team perform?","steps_vi":["Cần phát hiện và loại bỏ bản ghi trùng, đồng thời thống nhất mã nhận diện khách hàng/doanh nghiệp."],"answer":"Data curation / cleaning.","check":""},{"question_en":"A research system needs fast retrieval of a company’s quarterly revenue observations. What database action is most relevant?","steps_vi":["Hệ thống thực hiện search/query để truy xuất các bản ghi có mã doanh nghiệp và kỳ báo cáo phù hợp."],"answer":"Search/query.","check":""},{"question_en":"A team moves a market-price feed to its execution engine. Identify the stage.","steps_vi":["Dữ liệu được chuyển từ feed hoặc kho lưu trữ sang bộ máy thực thi thuật toán; đó là giai đoạn transfer."],"answer":"Transfer.","check":""},{"question_en":"An investment deck displays a chart where word font sizes indicate term frequencies in earnings calls. Name the visualization.","steps_vi":["Kích thước chữ thể hiện tần suất xuất hiện của từ, không biểu diễn quan hệ nhân quả hoặc cấu trúc ngữ nghĩa."],"answer":"Tag cloud.","check":""},{"question_en":"A diagram highlights links between inflation, interest rates, equity prices and currency values. Which tool fits best?","steps_vi":["Sơ đồ này thể hiện mối liên hệ giữa các khái niệm chứ không chỉ tần suất từ, nên phù hợp với mind map hoặc network diagram."],"answer":"Mind map / network diagram.","check":""},{"question_en":"A model assigns a score to earnings-call optimism using transcript language. What technique is most directly used?","steps_vi":["Trích xuất mức độ lạc quan/bi quan từ transcript là ứng dụng NLP và phân tích cảm xúc văn bản."],"answer":"NLP / text analytics.","check":""},{"question_en":"A trading surveillance engine reviews employee chat messages for violations. Which application does this illustrate?","steps_vi":["NLP có thể phân loại thông điệp, phát hiện tín hiệu bất thường và hỗ trợ giám sát tuân thủ."],"answer":"NLP for compliance.","check":""},{"question_en":"Satellite imagery is used to estimate agricultural yields. Which pipeline likely applies?","steps_vi":["Ảnh cần được thu thập, làm sạch rồi trích xuất đặc trưng bằng computer vision/image analytics trước khi lập dự báo."],"answer":"Image analytics / computer vision.","check":""},{"question_en":"An analyst wants exploratory statistics and financial modeling using a mature statistical programming environment. Which language is a common fit?","steps_vi":["R là môi trường ngôn ngữ phổ biến lâu năm trong thống kê ứng dụng và có nhiều thư viện phân tích."],"answer":"R.","check":""},{"question_en":"A high-frequency trading project prioritizes optimized execution speed in compiled code. Which language family is commonly relevant?","steps_vi":["C/C++ thường được chọn cho các hệ thống cần hiệu suất và độ trễ tính toán thấp."],"answer":"C/C++.","check":""},{"question_en":"An office analyst automates regular Excel report updates using macros. Which tool is appropriate?","steps_vi":["VBA giúp tự động hóa thao tác lặp lại, báo cáo và macro trong Microsoft Excel."],"answer":"Excel VBA.","check":""},{"question_en":"A mobile application needs a lightweight embedded relational database without separate database server. Which is a suitable choice?","steps_vi":["SQLite là cơ sở dữ liệu quan hệ nhúng, có thể dùng mà không cần máy chủ database độc lập."],"answer":"SQLite.","check":""},{"question_en":"A team stores heterogeneous unstructured documents and needs a flexible non-relational data system. Which family can be suitable?","steps_vi":["Họ cơ sở dữ liệu NoSQL có thể phù hợp với dữ liệu tài liệu/khóa–giá trị không đồng nhất và cấu trúc linh hoạt; lựa chọn còn tùy bài toán."],"answer":"NoSQL.","check":""},{"question_en":"A large relational warehouse stores rows of issuer, date, and return data. Which query language is commonly used?","steps_vi":["SQL là ngôn ngữ truy vấn thường dùng với dữ liệu có cấu trúc trong cơ sở dữ liệu quan hệ."],"answer":"SQL.","check":""},{"question_en":"A finance model shows excellent in-sample accuracy using social-media sentiment but loses money after trading costs. What is the key lesson?","steps_vi":["Khả năng khớp dữ liệu trong mẫu không bảo đảm lợi nhuận ròng sau chi phí.","Phải đánh giá ngoài mẫu, tính giao dịch và các giả định triển khai thực tế."],"answer":"Predictive in-sample fit does not guarantee net returns.","check":""}],"questions":[{"stem_en":"Which activity is an example of data curation?","options":["Cleaning duplicate and inaccurate records","Transferring data over a feed","Displaying a word cloud"],"correct":0,"why_vi":"Curation tập trung data quality.","trap_vi":""},{"stem_en":"What does data capture involve?","options":["Building model residual plots only","Collecting and transforming source data into usable form","Issuing a company dividend"],"correct":1,"why_vi":"Capture = gather/format incoming data.","trap_vi":""},{"stem_en":"In data science, storage primarily concerns:","options":["Prediction model p-values","Visual font choices","How data are recorded, archived and accessed"],"correct":2,"why_vi":"Storage handles records and access architecture.","trap_vi":""},{"stem_en":"Which stage retrieves selected records from a large database?","options":["Search","Transfer","Curation only"],"correct":0,"why_vi":"Search queries appropriate subset.","trap_vi":""},{"stem_en":"Which stage moves an exchange price feed to an algorithmic trading tool?","options":["Storage","Transfer","Tagging"],"correct":1,"why_vi":"Transfer transports to analytical tool.","trap_vi":""},{"stem_en":"A tag cloud typically encodes:","options":["Causal relationship strength","Forecast volatility","Frequency of words through display size"],"correct":2,"why_vi":"Word cloud font size reflects frequency.","trap_vi":""},{"stem_en":"A mind map is primarily used to display:","options":["Relationships between concepts","Relative word frequency only","A Student-t p-value"],"correct":0,"why_vi":"Mind map shows links.","trap_vi":""},{"stem_en":"Analyzing the sentiment of an earnings-call transcript is most likely:","options":["SQL administration only","Natural language processing","Sensor calibration"],"correct":1,"why_vi":"NLP processes language and sentiment.","trap_vi":""},{"stem_en":"NLP is most directly concerned with:","options":["Only numeric covariance matrices","Only satellite pixel counts","Understanding and processing human language"],"correct":2,"why_vi":"Natural language spans text/voice.","trap_vi":""},{"stem_en":"Which dataset is most naturally analyzed with image recognition?","options":["Satellite images of shipping activity","Textual central-bank minutes only","A printed ANOVA F ratio"],"correct":0,"why_vi":"Computer vision processes images.","trap_vi":""},{"stem_en":"Which tool has a long-standing focus on statistical analysis?","options":["Excel cell formatting only","R","SQL as an operating system"],"correct":1,"why_vi":"R supports statistics/ML.","trap_vi":""},{"stem_en":"Which language family is associated with performance-sensitive algorithmic trading systems?","options":["VBA alone","HTML only","C/C++"],"correct":2,"why_vi":"C/C++ compiled performance.","trap_vi":""},{"stem_en":"Excel VBA is mainly useful for:","options":["Automating spreadsheet macros and report tasks","Replacing all exchange regulators","Designing relational schemas only"],"correct":0,"why_vi":"VBA spreadsheet automation.","trap_vi":""},{"stem_en":"Which database is commonly embedded without a separate server?","options":["Enterprise SQL Server only","SQLite","Only cloud NoSQL"],"correct":1,"why_vi":"SQLite embedded database.","trap_vi":""},{"stem_en":"A database with structured rows and columns is commonly queried using:","options":["Speech recognition","A satellite image parser","SQL"],"correct":2,"why_vi":"SQL relational structured queries.","trap_vi":""},{"stem_en":"NoSQL systems are frequently selected for:","options":["Flexible non-relational data organization","Only fixed Excel cell references","Rendering a t-distribution chart only"],"correct":0,"why_vi":"NoSQL broad flexible data systems.","trap_vi":""},{"stem_en":"An ML model’s text sentiment score is best viewed as:","options":["Guaranteed excess return","A potential feature needing validation","A legally protected trade signal by default"],"correct":1,"why_vi":"Sentiment features need evidence and legality.","trap_vi":""},{"stem_en":"Which application fits NLP-based compliance monitoring?","options":["Estimating a stock split adjustment only","Counting parking lot vehicles only","Reviewing electronic communications for suspicious content"],"correct":2,"why_vi":"Language monitoring is NLP usage.","trap_vi":""},{"stem_en":"Which is a correct caution regarding satellite foot-traffic estimates?","options":["Image quality and context can distort the operational proxy.","Images directly reveal audited net income.","Satellite data guarantee better earnings forecasts."],"correct":0,"why_vi":"Proxy signal may be noisy and not equivalent to profit.","trap_vi":""},{"stem_en":"Why are data lineage and timestamps important?","options":["They prove an AI model is causal.","They help audit information availability and prevent look-ahead bias.","They eliminate legal licensing requirements."],"correct":1,"why_vi":"Track when data were truly available.","trap_vi":""},{"stem_en":"Which pair is correctly matched?","options":["Tag cloud — relational SQL query","NoSQL — only physically printed tables","Python — data science and analytical programming"],"correct":2,"why_vi":"Python broadly used in financial data science.","trap_vi":""},{"stem_en":"An automated text translation engine is most directly linked to:","options":["Natural language processing","ANOVA residual decomposition","Sharpe ratio"],"correct":0,"why_vi":"Translation is NLP.","trap_vi":""},{"stem_en":"An analyst wants to compare data from two vendors with different firm identifiers. Which step should happen before forecasting?","options":["Ignore identifiers","Data curation/entity mapping","Assume more observations resolve the mismatch"],"correct":1,"why_vi":"Entity resolution and source cleaning essential.","trap_vi":""},{"stem_en":"Which of the following is not a guarantee of machine-learning use in investing?","options":["A model can support risk analysis.","Text analytics can create signals.","Higher model accuracy always yields positive net trading profits."],"correct":2,"why_vi":"Transaction costs, capacity, risk and regime changes matter.","trap_vi":""}],"cards":[{"front_en":"What is data science in investment management?","back_vi":"Computer science + statistics + domain expertise to extract insights from data."},{"front_en":"Five CFAI data processing stages?","back_vi":"Capture, curation, storage, search, transfer."},{"front_en":"What is capture?","back_vi":"Collect/transform source data into usable form."},{"front_en":"What is curation?","back_vi":"Clean errors, missing data and inconsistency."},{"front_en":"What is storage?","back_vi":"Record, archive and access datasets."},{"front_en":"What is search?","back_vi":"Query and locate requested data."},{"front_en":"What is transfer?","back_vi":"Move source data/feed to analytical application."},{"front_en":"What does a tag cloud show?","back_vi":"Word frequency via relative word size."},{"front_en":"What does a mind map show?","back_vi":"Relationships across concepts."},{"front_en":"Text analytics example?","back_vi":"Sentiment analysis of earnings-call transcript."},{"front_en":"NLP tasks in finance?","back_vi":"Sentiment, speech recognition, topic extraction, translation, compliance."},{"front_en":"What is computer vision used for?","back_vi":"Feature extraction from satellite/image data."},{"front_en":"Python use case?","back_vi":"Data science, ML and financial analytics."},{"front_en":"R use case?","back_vi":"Statistical modeling and analysis."},{"front_en":"Java use case?","back_vi":"Portable applications and platforms."},{"front_en":"C/C++ use case?","back_vi":"Optimized low-latency code / algorithmic trading."},{"front_en":"Excel VBA use case?","back_vi":"Automating spreadsheet reports/macros."},{"front_en":"SQL use case?","back_vi":"Querying structured relational tables."},{"front_en":"SQLite use case?","back_vi":"Embedded relational database without separate server."},{"front_en":"NoSQL use case?","back_vi":"Flexible stores for document/unstructured-like data."},{"front_en":"NLP compliance example?","back_vi":"Screening electronic communications for problematic language."},{"front_en":"Why is source licensing important?","back_vi":"Legal rights and ethics restrict access/distribution of data."}]}]}];
